// recomp_runtime.c — runtime support for the PPC→C recomp output.
// Implements RECOMP_* helpers, the source-backed Diab tagged-varargs glue, and
// re-exports the Diab prologue families as no-ops (the generated C manages its
// own stack). Link this with the generated game_recomp.c and host shims.
//
// FP helpers (FMADDS etc) live in ppc_ctx.h; this TU provides the out-of-line
// stubs and the selector trampoline used by the generated bl sites.

// glibc declares Dl_info/dladdr only under _GNU_SOURCE; gnu11 alone does not
// define it. Must precede every system header.
#if !defined(_WIN32) && !defined(_GNU_SOURCE)
#define _GNU_SOURCE
#endif

#include "ppc_ctx.h"
#include "recomp_helpers.h"
#include "recomp_host.h"
#include "guest_kernel.h"
#include "diagnostic_gate.h"
#include "diagnostic_input.h"
#include "guest_module.h"
#include "m2_cport_bits.h"
#include "device_command_contract.h"
#include "te_command_contract.h"
#include "dsp_template_catalog.h"
#include "dsp_template_loader.h"
#include "shim_abi.h"
#if !defined(_WIN32)
#include <dlfcn.h>
#endif
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <setjmp.h>
#include <string.h>
#include <time.h>
#include <limits.h>
#include <math.h>

#define M2_TIME_BASE_TICKS_PER_SECOND 8333333ull

// UI_MercInit (0x37598..0x375a0) installs this original width. Race
// trackIterate's rear-view pass subsequently leaves the shared CloseData at
// 128, while UI_ShowMerc only refreshes its height. Scope the presentation
// correction to that UI draw; never change the race camera or simulation.
uint32_t m2_menu_preview_clip_begin(PPCContext *c, uint32_t close) {
    if (!c || !c->mem || close == 0u || close > RECOMP_M2_RAM_LIMIT - 0x68u)
        return 0u;
    const uint32_t saved = rd32(c, close + 0x64u);
    const char *reference = getenv("M2_MENU_PREVIEW_CLIP_FIX");
    if (!reference || strcmp(reference, "0") != 0)
        wr32(c, close + 0x64u, rd32(c, 0x13ac04u));
    return saved;
}

void m2_menu_preview_clip_end(PPCContext *c, uint32_t close, uint32_t saved) {
    if (c && c->mem && close != 0u && close <= RECOMP_M2_RAM_LIMIT - 0x68u)
        wr32(c, close + 0x64u, saved);
}

// Opt-in player-car AI controller selection. This deliberately overrides only
// complexSim's transient branch input: the original AI routines still produce
// the controls, and the guest-owned race-state selector is never modified.
static atomic_int g_player_ai_enabled = ATOMIC_VAR_INIT(-1);

static int player_ai_enabled(void) {
    int enabled = atomic_load_explicit(&g_player_ai_enabled,
                                       memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_PLAYER_AI");
    const int detected = value != NULL && strcmp(value, "1") == 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_player_ai_enabled, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

uint32_t m2_player_ai_controller_selector(uint32_t guest_selector) {
    return player_ai_enabled() ? 1u : guest_selector;
}

// Opt-in player-car appearance variant. This overrides only the transient
// MS_buildcar/MS_rebuildcar variant argument for the player's own car; the
// guest still resolves the model from its own car-body table, and physics,
// opponent selection and the track-init/unload bookkeeping keep the original
// body index. -2 = not read yet, -1 = no override, 0-2 = override value.
static atomic_int g_player_car_variant_override = ATOMIC_VAR_INIT(-2);

static int player_car_variant_override(void) {
    int override_value = atomic_load_explicit(&g_player_car_variant_override,
                                              memory_order_acquire);
    if (override_value >= -1)
        return override_value;

    const char *value = getenv("M2_PLAYER_CAR_VARIANT");
    int detected = -1;
    if (value != NULL && (strcmp(value, "1") == 0 || strcmp(value, "2") == 0))
        detected = value[0] - '0';
    int expected = -2;
    if (!atomic_compare_exchange_strong_explicit(
            &g_player_car_variant_override, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

uint32_t m2_player_car_variant(uint32_t guest_variant, uint32_t entry_variant1,
                               uint32_t entry_variant2) {
    const int override_value = player_car_variant_override();
    if (override_value == 1 && entry_variant1 != 0)
        return 1u;
    if (override_value == 2 && entry_variant2 != 0)
        return 2u;
    return guest_variant;
}

// Opt-in skidpad engine-sound rebind. This refreshes only the audio binding
// when the player's engine index changes in-session: the two engine-sound
// channels are rebound from the already-built per-engine sample structures.
// Simulation, car model, opponents, race rules and timing are untouched.
// Exact "1" is on; every other value preserves the stale entry-time binding.
static atomic_int g_skidpad_engine_fix = ATOMIC_VAR_INIT(-1);

static int skidpad_engine_fix_enabled_cached(void) {
    int enabled = atomic_load_explicit(&g_skidpad_engine_fix,
                                       memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_SKIDPAD_ENGINE_FIX");
    const int detected = value != NULL && strcmp(value, "1") == 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_skidpad_engine_fix, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

int m2_skidpad_engine_fix_enabled(void) {
    return skidpad_engine_fix_enabled_cached();
}

extern unsigned g_recomp_text_base, g_recomp_data_base, g_recomp_bss_base;
extern void (*recomp_lookup(unsigned guest))(PPCContext *);

void m2_skidpad_engine_rebind(PPCContext *c) {
    if (!skidpad_engine_fix_enabled_cached())
        return;
    if (!c || !c->mem)
        return;
    // Save the guest register window: the helper runs between two original
    // guest calls (after createNewCar, before updateSkidpadSprites) and must
    // not disturb the racePhase frame. Memory writes to the two channel
    // records persist; registers are restored.
    uint32_t saved_gpr[32], saved_lr, saved_ctr, saved_cr, saved_xer, saved_pc;
    memcpy(saved_gpr, c->gpr, sizeof(saved_gpr));
    saved_lr = c->lr;
    saved_ctr = c->ctr;
    saved_cr = c->cr;
    saved_xer = c->xer;
    saved_pc = c->pc;

    // UI_GetEngine source (state.c 0x31874): .data+0x7998 holds the active
    // configuration pointer; byte 1 is the engine (extsb, 0-3 valid).
    const uint32_t config_ptr_ea = g_recomp_data_base + 0x7998u;
    if (config_ptr_ea > RECOMP_GUEST_MEM - 4u)
        goto restore;
    const uint32_t config = rd32(c, config_ptr_ea);
    if (config == 0 || config + 1u >= RECOMP_GUEST_MEM)
        goto restore;
    const int32_t engine = (int32_t)(int8_t)rd8(c, config + 1u);
    if (engine < 0 || engine > 3)
        goto restore;

    // Per-engine Up/Down sample Item slots built at track entry (trackInit_2
    // 0x17c00-0x17c8c; selected at 0x17c90): .bss offsets from the lifted
    // spans, independently pinned by m2_skidpad_engine_binding words.
    static const uint32_t kUpOff[4] = {0xb9cu, 0xba4u, 0xb8cu, 0xb94u};
    static const uint32_t kDownOff[4] = {0xba0u, 0xba8u, 0xb90u, 0xb98u};
    const uint32_t want_up = rd32(c, g_recomp_bss_base + kUpOff[engine]);
    const uint32_t want_down = rd32(c, g_recomp_bss_base + kDownOff[engine]);
    if (want_up == 0 || want_down == 0)
        goto restore;

    // Race data pointer (BSS+0x3a54) and the two 28-byte two-stage channel
    // records at gdp+0x20e8 / gdp+0x2104. Sample fields at +0x20f0/+0x210c,
    // attachment Items at +0x20ec/+0x2108, instruments at +0x20e8/+0x2104.
    const uint32_t gdp_ptr_ea = g_recomp_bss_base + 0x3a54u;
    if (gdp_ptr_ea > RECOMP_GUEST_MEM - 4u)
        goto restore;
    const uint32_t gdp = rd32(c, gdp_ptr_ea);
    if (gdp == 0 || gdp > RECOMP_GUEST_MEM - 0x2110u)
        goto restore;
    const uint32_t cur_up = rd32(c, gdp + 0x20f0u);
    const uint32_t cur_down = rd32(c, gdp + 0x210cu);
    if (cur_up == want_up && cur_down == want_down)
        goto restore;

    void (*create_attachment)(PPCContext *) = recomp_lookup(0x173394u);
    if (!create_attachment)
        goto restore;

    static const uint32_t kInstOff[2] = {0x20e8u, 0x2104u};
    static const uint32_t kAttOff[2] = {0x20ecu, 0x2108u};
    static const uint32_t kSampleOff[2] = {0x20f0u, 0x210cu};
    const uint32_t want[2] = {want_up, want_down};
    const uint32_t cur[2] = {cur_up, cur_down};
    for (int i = 0; i < 2; ++i) {
        if (cur[i] == want[i])
            continue;
        const uint32_t instrument = rd32(c, gdp + kInstOff[i]);
        const uint32_t old_att = rd32(c, gdp + kAttOff[i]);
        const uint32_t old_sample = cur[i];
        if (instrument == 0 || want[i] == 0)
            continue;
        // Stop the channel (retires the stale voice; the per-frame
        // sndSet2StageEng restarts it with its own knobs, so no knob is
        // authored here). Then delete the stale attachment and create the
        // replacement on the same sampler, as proven by m2_audio_items_test.
        c->gpr[3] = instrument;
        c->gpr[4] = 0u;
        c->pc = 0x2f38cu;
        recomp_call_selector(c, 6, 67, 0x2f38c);
        if (old_att != 0) {
            c->gpr[3] = old_att;
            c->pc = 0x2f38cu;
            recomp_call_selector(c, 1, 164, 0x2f38c);
        }
        c->gpr[3] = instrument;
        c->gpr[4] = want[i];
        c->gpr[5] = 0u;
        c->lr = 0x2f38cu;
        create_attachment(c);
        const uint32_t new_att = c->gpr[3];
        if (new_att != 0) {
            wr32(c, gdp + kSampleOff[i], want[i]);
            wr32(c, gdp + kAttOff[i], new_att);
        } else if (old_sample != 0) {
            // Host allocation failure: best-effort restore of the previous
            // binding so the channel keeps its stale voice instead of going
            // silent with a dangling attachment.
            c->gpr[3] = instrument;
            c->gpr[4] = old_sample;
            c->gpr[5] = 0u;
            c->lr = 0x2f38cu;
            create_attachment(c);
            const uint32_t restored = c->gpr[3];
            if (restored != 0)
                wr32(c, gdp + kAttOff[i], restored);
        }
    }

restore:
    memcpy(c->gpr, saved_gpr, sizeof(saved_gpr));
    c->lr = saved_lr;
    c->ctr = saved_ctr;
    c->cr = saved_cr;
    c->xer = saved_xer;
    c->pc = saved_pc;
}

// Optional enhancements: restore unfinished credits.
// When M2_RESTORE_CREDITS=1, intercepts the main-menu Credits option (State 13)
// and runs the unfinished credits routine (credits.c, guest 0x0103a4..0x01068c)
// with the highscore font instead of the placeholder credits.mov video player.
// Default, 0, or any other value preserves authentic behavior.
static atomic_int g_restore_credits = ATOMIC_VAR_INIT(-1);

static int restore_credits_enabled_cached(void) {
    int enabled = atomic_load_explicit(&g_restore_credits, memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_RESTORE_CREDITS");
    const int detected = value != NULL && strcmp(value, "1") == 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_restore_credits, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

int m2_restore_credits_enabled(void) {
    return restore_credits_enabled_cached();
}

// Font descriptors are 5916 bytes: the base sprite, metrics at +0x90..+0x98,
// then 40 glyph sprite records at +0x9c (0x90 each) chained through their
// +4 next field. A copy keeps the source's texture but must rebase those
// links, or TwoD_DrawText on the copy would walk into the source's sprites
// and draw their stale positions.
#define M2_FONT_SIZE 5916u
static int copy_guest_font(PPCContext *c, uint32_t dst, uint32_t src) {
    if (src == 0u || src > RECOMP_GUEST_MEM - M2_FONT_SIZE ||
        dst > RECOMP_GUEST_MEM - M2_FONT_SIZE)
        return 0;
    memcpy(c->mem + dst, c->mem + src, M2_FONT_SIZE);
    for (uint32_t i = 0; i < 40u; ++i) {
        const uint32_t link_ea = dst + 0x9cu + i * 0x90u + 4u;
        const uint32_t link = rd32(c, link_ea);
        if (link >= src && link < src + M2_FONT_SIZE)
            wr32(c, link_ea, link - src + dst);
    }
    return 1;
}

static int s_credits_active = 0;
static uint32_t s_credits_frame_count = 0;
static uint32_t s_credits_prev_actions = 0;
void m2_credits_state_reset(void) {
    s_credits_active = 0;
    s_credits_frame_count = 0;
    s_credits_prev_actions = 0;
    atomic_store_explicit(&g_restore_credits, -1, memory_order_release);
}

void m2_credits_text_blend_rearm(PPCContext *c) {
    if (!restore_credits_enabled_cached() || !c || !c->mem)
        return;
    // TwoD_DrawSprites' cached texture (StateDriver resets it to -1 at
    // 0x316bc each frame). Clearing it makes the first line sprite re-arm
    // the font's texture and blend state after TextDestBlendInit.
    wr32(c, g_recomp_bss_base + 0x98d8u, 0xffffffffu);
}

int m2_credits_state_step(PPCContext *c) {
    if (!restore_credits_enabled_cached())
        return 0;
    if (!c || !c->mem)
        return 0;

    const uint32_t gdp_ptr_ea = g_recomp_bss_base + 0x3a54u;
    if (gdp_ptr_ea > RECOMP_GUEST_MEM - 4u)
        return 0;
    const uint32_t gdp = rd32(c, gdp_ptr_ea);
    if (gdp == 0 || gdp > RECOMP_GUEST_MEM - 0x688u - 5916u)
        return 0;

    // StateDriver's input record lives at r1+8 and record+0x14 holds this
    // frame's translated button word. GDP+0x68 is the control-port device
    // pointer passed to GetCPortData, not buttons. Sample it before calling
    // guest code, whose frames may reuse the stack around r1.
    uint32_t actions = 0;
    if (c->gpr[1] >= 0x20u && c->gpr[1] <= RECOMP_GUEST_MEM - 0x20u) {
        actions = rd32(c, c->gpr[1] + 0x1cu);
    }

    // 1. Entry / Initialization
    if (!s_credits_active) {
        // Fix font: credits_fill_line and TwoD_DrawText require an initialized Font
        // at gdp + 0x688. If char_width_table at gdp + 0x688 + 0x94 is NULL, copy
        // highscorefont (or lcdfont) which was loaded by UI_LoadArt.
        if (rd32(c, gdp + 0x688u + 0x94u) == 0u) {
            uint32_t hs_font = rd32(c, g_recomp_bss_base + 0x97d0u);
            if (hs_font == 0u || hs_font > RECOMP_GUEST_MEM - M2_FONT_SIZE) {
                hs_font = rd32(c, g_recomp_bss_base + 0x97d4u);
            }
            copy_guest_font(c, gdp + 0x688u, hs_font);
        }

        void (*credits_init)(PPCContext *) = recomp_lookup(0x1103a4u);
        if (credits_init) {
            credits_init(c);
        }
        s_credits_active = 1;
        s_credits_frame_count = 0;
        s_credits_prev_actions = 0xffffffffu;  // treat entry-held buttons as old
    }

    // 2. Draw background (main menu still)
    const uint32_t gdp_gs = rd32(c, gdp);
    uint32_t mainstill = rd32(c, g_recomp_bss_base + 0x9638u);
    void (*draw_bg)(PPCContext *) = recomp_lookup(0x137870u); // UI_DrawBackground
    if (draw_bg && mainstill != 0u) {
        c->gpr[3] = mainstill;
        draw_bg(c);
    }
    // Every UI screen follows its background with CLT_SetSrcToCurrentDest
    // (e.g. 0x38154..0x38160). TextDestBlendInit enables destination blending
    // but never sets DBSRCBASEADDR, so without this the text blends against
    // whichever buffer was last selected, flickering on alternate frames.
    void (*set_src_to_dest)(PPCContext *) = recomp_lookup(0x171d74u);
    if (set_src_to_dest && gdp_gs != 0u) {
        c->gpr[3] = gdp_gs;
        set_src_to_dest(c);
    }

    // 3. Step credits scroll
    int iterate_res = 1;
    void (*credits_iterate)(PPCContext *) = recomp_lookup(0x1103f8u);
    if (credits_iterate) {
        credits_iterate(c);
        iterate_res = (int)c->gpr[3];
    }

    // 4. Input check (skip)
    // Only a newly pressed button skips, so the press that selected Credits
    // (or any held button) cannot end the roll on its own.
    const uint32_t pressed = actions & ~s_credits_prev_actions;
    s_credits_prev_actions = actions;
    s_credits_frame_count++;

    // Allow skip after 30 frames grace period (0.5s debounce), or when complete
    const int want_exit = (iterate_res == 0) ||
        (s_credits_frame_count >= 30u && pressed != 0u);

    if (want_exit) {
        void (*credits_teardown)(PPCContext *) = recomp_lookup(0x11068cu);
        if (credits_teardown) {
            credits_teardown(c);
        }
        s_credits_active = 0;
        s_credits_frame_count = 0;

        // Transition back to the Main Menu (State 27), as the original
        // State 13 handler does after its movie (0x30e74..0x30e98).
        wr32(c, g_recomp_bss_base + 0x653cu, 27u);  // state = 27
        wr32(c, g_recomp_bss_base + 0x6544u, 13u);  // oldstate = 13
        wr32(c, g_recomp_bss_base + 0x654cu, 1u);   // clearScreen = 1
        wr32(c, g_recomp_bss_base + 0x7854u, 1u);   // refresh
    } else {
        // Keep state = 13
        wr32(c, g_recomp_bss_base + 0x653cu, 13u);
    }

    return 1;
}

// Optional enhancements: restore the unused post-race summary screen.
// UI_DrawBestTimes (ui.c 0x379cc) has no caller. It draws the player's race
// time (racers+0x38), best lap (+0x34), average speed, laps (+0x04) and
// finishing place (+0x14), with a 0/1/2 layout argument matching the
// win/lose/DNF index StateDriver computes at 0x311dc..0x31210 and keeps in
// r25 for the result movie. When M2_RESTORE_BEST_TIMES=1 the result handler
// (0x3136c) arms the screen and the first post-race high-score state
// (secondary 31 or 32) shows it until a new button press. Its art was never
// loaded by the shipped game: finishStill takes the track's high-score still,
// fLcd a copy of the menu LCD font, and fHelv the disc's helv42.font ordinal
// strip (0-9, st/nd/rd/th). Default, 0, or any other value preserves the
// original results flow.
static atomic_int g_restore_best_times = ATOMIC_VAR_INIT(-1);

static int restore_best_times_enabled_cached(void) {
    int enabled = atomic_load_explicit(&g_restore_best_times, memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_RESTORE_BEST_TIMES");
    const int detected = value != NULL && strcmp(value, "1") == 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_restore_best_times, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

int m2_restore_best_times_enabled(void) {
    return restore_best_times_enabled_cached();
}

#define M2_BT_FINISH_STILL 0x6758u  // .bss finishStill (still descriptor slot)
#define M2_BT_FHELV        0x67f8u  // .bss fHelv (font descriptor)
#define M2_BT_FLCD         0x7f18u  // .bss fLcd (font descriptor)
#define M2_BT_HELV_IDX     0xab78u  // .data fHelv_idx (9 bytes)
#define M2_BT_HELV_CS      0xab81u  // .data fHelv_cs (16 bytes)
#define M2_BT_RACERS       0x3a60u  // .bss racers, stride 0x124
#define M2_BT_RACER_BEST   0x34u    // racers[0] best lap (GetMinSecHund raw)
#define M2_BT_TIME_FMT     0x3b0adu // .text "%02d:%02d.%02d"

// helv42.font is a 27x448 strip of 14 cells, 32 rows each: 0-9, then
// st/nd/rd/th. TwoD_DrawText walks (skip, count) pairs; a pair covers the
// `count` characters after `skip` more, numbering glyphs consecutively.
// '0'..'9' -> 0..9 and 'a'..'d' (UI_DrawBestTimes' ordinal suffixes) -> 10..13.
// Every other character advances one cell width. The original 17-glyph tables
// (space, '.', 0-9, ':', st..th) describe a texture that is not on the disc,
// so they are saved and put back when the screen closes.
static const uint8_t k_bt_helv_idx[] = {47u, 10u, 39u, 4u, 0xffu};
static const uint8_t k_bt_helv_cs[] = {
    26u, 26u, 26u, 26u, 26u, 26u, 26u, 26u, 26u, 26u, 27u, 27u, 27u, 27u,
};
static const char k_bt_helv_path[] = "data/font/helv42.font";

static int s_bt_armed = 0;
static int s_bt_active = 0;
static int s_bt_helv_loaded = 0;
static int s_bt_labels_logged = 0;
static uint32_t s_bt_outcome = 0;
static uint32_t s_bt_frame_count = 0;
static uint32_t s_bt_prev_actions = 0;
static uint8_t s_bt_saved_idx[9];
static uint8_t s_bt_saved_cs[16];

void m2_best_times_state_reset(void) {
    s_bt_armed = 0;
    s_bt_active = 0;
    s_bt_helv_loaded = 0;
    s_bt_labels_logged = 0;
    s_bt_outcome = 0;
    s_bt_frame_count = 0;
    s_bt_prev_actions = 0;
    atomic_store_explicit(&g_restore_best_times, -1, memory_order_release);
}

void m2_best_times_arm(PPCContext *c) {
    if (!restore_best_times_enabled_cached() || !c)
        return;
    // r25 is StateDriver's outcome index (0 win, 1 lose, 2 DNF), the same
    // value it passed to hs_calcresults and uses to pick the result movie.
    if (c->gpr[25] > 2u)
        return;
    s_bt_outcome = c->gpr[25];
    s_bt_armed = 1;
    // StateDriver's common tail enters attract mode when its idle counter r18
    // reaches 15000 and the phase is 1. The result handler sets phase 1 in
    // this same frame, so a long unattended race would otherwise overwrite
    // the just-selected secondary 31/32 with phase 5/state 29 before the
    // summary handler ever runs. Zero the counter with the arm.
    c->gpr[18] = 0;
}

// TwoD_LoadFont_memcall(font, name, cellw, cellh, perrow, idx, cs, memcall)
// with the name in a scratch frame below the caller's stack, which callees
// never touch. TwoD_LoadFont's default memcall is the kernel AllocMem import
// slot (1:2 at 0x3f1000), which no shipped path calls through and the recomp
// does not dispatch. MS_MyAlloc (0x23a40) is the game allocator trackInit_2
// hands TwoD_LoadSprite_memcall: it allocates in the current mem zone (1, the
// menu zone, after the result handler's UI_LoadArt), which track loads free
// wholesale, so the font is never freed through TwoD_FreeFont.
static int best_times_load_helv(PPCContext *c, uint32_t font) {
    void (*load_font)(PPCContext *) = recomp_lookup(0x14e8a0u);
    const uint32_t saved_sp = c->gpr[1];
    if (!load_font || saved_sp < 0x1000u)
        return 0;
    const uint32_t idx = g_recomp_data_base + M2_BT_HELV_IDX;
    const uint32_t cs = g_recomp_data_base + M2_BT_HELV_CS;
    memcpy(s_bt_saved_idx, c->mem + idx, sizeof(s_bt_saved_idx));
    memcpy(s_bt_saved_cs, c->mem + cs, sizeof(s_bt_saved_cs));
    memcpy(c->mem + idx, k_bt_helv_idx, sizeof(k_bt_helv_idx));
    memcpy(c->mem + cs, k_bt_helv_cs, sizeof(k_bt_helv_cs));

    const uint32_t frame = saved_sp - 0x80u;
    wr32(c, frame, saved_sp);
    memcpy(c->mem + frame + 0x40u, k_bt_helv_path, sizeof(k_bt_helv_path));
    c->gpr[1] = frame;
    c->gpr[3] = font;
    c->gpr[4] = frame + 0x40u;
    c->gpr[5] = 27u;
    c->gpr[6] = 32u;
    c->gpr[7] = 1u;
    c->gpr[8] = idx;
    c->gpr[9] = cs;
    c->gpr[10] = g_recomp_text_base + 0x23a40u;  // MS_MyAlloc
    load_font(c);
    c->gpr[1] = saved_sp;
    if ((int32_t)c->gpr[3] >= 0)
        return 1;

    memcpy(c->mem + idx, s_bt_saved_idx, sizeof(s_bt_saved_idx));
    memcpy(c->mem + cs, s_bt_saved_cs, sizeof(s_bt_saved_cs));
    return 0;
}

static void best_times_close(PPCContext *c) {
    if (s_bt_helv_loaded) {
        memcpy(c->mem + g_recomp_data_base + M2_BT_HELV_IDX,
               s_bt_saved_idx, sizeof(s_bt_saved_idx));
        memcpy(c->mem + g_recomp_data_base + M2_BT_HELV_CS,
               s_bt_saved_cs, sizeof(s_bt_saved_cs));
    }
    // Leave the never-loaded slots as the shipped game has them: zero.
    memset(c->mem + g_recomp_bss_base + M2_BT_FHELV, 0, M2_FONT_SIZE);
    memset(c->mem + g_recomp_bss_base + M2_BT_FLCD, 0, M2_FONT_SIZE);
    memset(c->mem + g_recomp_bss_base + M2_BT_FINISH_STILL, 0, 16u);
    s_bt_armed = 0;
    s_bt_active = 0;
    s_bt_helv_loaded = 0;
    s_bt_labels_logged = 0;
    s_bt_frame_count = 0;
}

static int best_times_open(PPCContext *c) {
    // finishStill: the per-track still UI_DrawHighScores_postRace draws
    // (HSstills + track * 12), so the summary leads into the table.
    const uint32_t hs_stills = rd32(c, g_recomp_bss_base + 0x97ccu);
    void (*get_track)(PPCContext *) = recomp_lookup(0x131718u);
    if (hs_stills == 0u || !get_track)
        return 0;
    get_track(c);
    const uint32_t track = c->gpr[3];
    if (track > 15u || hs_stills > RECOMP_GUEST_MEM - 12u * 16u)
        return 0;
    const uint32_t still = g_recomp_bss_base + M2_BT_FINISH_STILL;
    memcpy(c->mem + still, c->mem + hs_stills + track * 12u, 12u);
    wr32(c, still + 12u, 0u);

    // fLcd: the menu's LCD font (highscorefont if absent).
    uint32_t lcd = rd32(c, g_recomp_bss_base + 0x97d4u);
    if (lcd == 0u || lcd > RECOMP_GUEST_MEM - M2_FONT_SIZE)
        lcd = rd32(c, g_recomp_bss_base + 0x97d0u);
    if (!copy_guest_font(c, g_recomp_bss_base + M2_BT_FLCD, lcd)) {
        memset(c->mem + still, 0, 16u);
        return 0;
    }

    // fHelv: the ordinal strip, or the LCD copy if the file will not load
    // (places then read as a digit plus a letter instead of 1st/2nd/...).
    const uint32_t helv = g_recomp_bss_base + M2_BT_FHELV;
    s_bt_helv_loaded = best_times_load_helv(c, helv);
    if (!s_bt_helv_loaded)
        copy_guest_font(c, helv, lcd);
    fprintf(stderr, "[best-times] layout=%u track=%u place font=%s\n",
            s_bt_outcome, track, s_bt_helv_loaded ? "helv42.font" : "lcd fallback");
    return 1;
}

// True when `font` maps `ch` to one of its 40 glyph slots. The two menu fonts
// cover different character sets (the high-score font has letters, the LCD
// font has the time punctuation), so the label path can fall back to the other
// loaded font if the slot order on a disc differs.
static int best_times_font_maps(PPCContext *c, uint32_t font, int ch) {
    if (font == 0u || font > RECOMP_GUEST_MEM - M2_FONT_SIZE)
        return 0;
    const uint32_t idx = rd32(c, font + 0x94u);
    const uint32_t cs = rd32(c, font + 0x98u);
    if (idx == 0u || cs == 0u || idx > RECOMP_GUEST_MEM - 512u ||
        cs > RECOMP_GUEST_MEM - 64u)
        return 0;
    int32_t start = 0, first = 0;
    for (uint32_t pair = 0; pair < 128u; ++pair) {
        const uint32_t skip = rd8(c, idx + pair * 2u);
        if (skip == 0xffu)
            break;
        start += (int32_t)skip;
        const int32_t count = (int32_t)rd8(c, idx + pair * 2u + 1u);
        if (start + count >= ch) {
            const int32_t glyph = first + (ch - start) - 1;
            return glyph >= 0 && glyph < 40;
        }
        first += count;
        start += count;
    }
    return 0;
}

// The labels are words, so they need the high-score font; fall back to the
// LCD slot only if the two font slots are swapped and that one happens to
// carry the letter table. A glyph slot with a zero texture id means the font
// descriptor exists but its sprites were never built, so prefer the other.
static int best_times_font_drawable(PPCContext *c, uint32_t font) {
    return best_times_font_maps(c, font, 'A') &&
           best_times_font_maps(c, font, '0') &&
           rd32(c, font + 0x9cu + 0x4cu) != 0u;
}

static uint32_t best_times_label_font(PPCContext *c) {
    const uint32_t hs = rd32(c, g_recomp_bss_base + 0x97d0u);
    if (best_times_font_drawable(c, hs))
        return hs;
    const uint32_t lcd = rd32(c, g_recomp_bss_base + 0x97d4u);
    if (best_times_font_drawable(c, lcd))
        return lcd;
    return 0u;
}

// Width TwoD_DrawText advances for `text` in `font`: (skip, count) pairs map
// a character to a glyph whose width is cs[glyph]; any other character
// advances the cell width at +0x90.
static uint32_t best_times_text_width(PPCContext *c, uint32_t font, const char *text) {
    if (font == 0u || font > RECOMP_GUEST_MEM - M2_FONT_SIZE)
        return 0u;
    const uint32_t idx = rd32(c, font + 0x94u);
    const uint32_t cs = rd32(c, font + 0x98u);
    const uint32_t cell = rd8(c, font + 0x90u);
    if (idx == 0u || cs == 0u || idx > RECOMP_GUEST_MEM - 512u)
        return 0u;
    uint32_t width = 0u;
    for (const char *p = text; *p; ++p) {
        const int32_t ch = (uint8_t)*p;
        int32_t start = 0, first = 0, glyph = -1;
        for (uint32_t pair = 0; pair < 128u; ++pair) {
            const uint32_t skip = rd8(c, idx + pair * 2u);
            if (skip == 0xffu)
                break;
            start += (int32_t)skip;
            const int32_t count = (int32_t)rd8(c, idx + pair * 2u + 1u);
            if (start + count >= ch) {
                glyph = first + (ch - start) - 1;
                break;
            }
            first += count;
            start += count;
        }
        width += glyph >= 0 ? rd8(c, cs + (uint32_t)glyph) : cell;
    }
    return width;
}

// The values sit on fixed coordinates meant for labels painted into the
// missing finishStill art. Name each line with the menu font beside its
// value: left of the right-hand columns (layouts 0 and 2), right of the
// left-hand column (layout 1). Each row keeps its own value x because
// UI_DrawBestTimes moves the average-speed column out by 10 px.
static void best_times_draw_labels(PPCContext *c, uint32_t gs) {
    struct label { float value_x; float y; const char *text; };
    static const struct label k_win[] = {
        {381.0f, 113.0f, "RACE TIME"},
        {381.0f, 178.0f, "BEST LAP"},
        {391.0f, 240.0f, "AVG MPH"},
    };
    static const struct label k_lose[] = {
        {25.0f, 96.0f, "PLACE"}, {25.0f, 156.0f, "RACE TIME"},
        {25.0f, 222.0f, "BEST LAP"}, {35.0f, 283.0f, "AVG MPH"},
    };
    static const struct label k_dnf[] = {
        {354.0f, 105.0f, "LAPS"}, {354.0f, 170.0f, "BEST LAP"},
    };
    const struct label *rows = k_win;
    size_t count = sizeof(k_win) / sizeof(k_win[0]);
    if (s_bt_outcome == 1u) {
        rows = k_lose;
        count = sizeof(k_lose) / sizeof(k_lose[0]);
    } else if (s_bt_outcome == 2u) {
        rows = k_dnf;
        count = sizeof(k_dnf) / sizeof(k_dnf[0]);
    }

    const uint32_t font = best_times_label_font(c);
    void (*draw_text)(PPCContext *) = recomp_lookup(0x14e9f8u);
    const uint32_t saved_sp = c->gpr[1];
    if (!draw_text || gs == 0u || font == 0u || saved_sp < 0x1000u)
        return;

    // A broken/zero idx or cs used to place the labels off-screen or give
    // them zero width. Keep the fallback inside the 576x432 canvas.
    uint32_t value_width = best_times_text_width(
        c, g_recomp_bss_base + M2_BT_FLCD, "00:00.00");
    if (value_width == 0u || value_width > 160u)
        value_width = 96u;
    const float gap = 24.0f;
    const float column = 25.0f + (float)value_width + gap;

    if (!s_bt_labels_logged) {
        s_bt_labels_logged = 1;
        fprintf(stderr, "[best-times] labels font=%#x texture=%#x column=%.0f\n",
                font, rd32(c, font + 0x4cu), column);
    }

    for (size_t i = 0; i < count; ++i) {
        const size_t len = strlen(rows[i].text);
        uint32_t label_width = best_times_text_width(c, font, rows[i].text);
        if (label_width == 0u || label_width > 200u)
            label_width = 80u;
        float x = s_bt_outcome == 1u
            ? column
            : rows[i].value_x - gap - (float)label_width;
        if (x < 0.0f)
            x = 0.0f;
        if (x > 520.0f)
            x = 520.0f;
        const uint32_t frame = saved_sp - 0x80u;
        wr32(c, frame, saved_sp);
        memcpy(c->mem + frame + 0x40u, rows[i].text, len + 1u);
        c->gpr[1] = frame;
        c->gpr[3] = gs;
        c->gpr[4] = font;
        c->gpr[5] = frame + 0x40u;
        c->fpr[1] = x;
        c->fpr[2] = rows[i].y;
        draw_text(c);
        c->gpr[1] = saved_sp;
    }
}

// Called from UI_DrawBestTimes right after its UI_DrawBackground call
// (guest 0x379fc). The shipped post-race screen follows its background with
// CLT_SetSrcToCurrentDest (0x395b4) before drawing text; mirror that here so
// the text's destination blend reads this frame's back buffer.
void m2_best_times_background_done(PPCContext *c) {
    if (!restore_best_times_enabled_cached() || !s_bt_active || !c || !c->mem)
        return;
    const uint32_t gdp = rd32(c, g_recomp_bss_base + 0x3a54u);
    if (gdp == 0u || gdp > RECOMP_GUEST_MEM - 4u)
        return;
    const uint32_t gs = rd32(c, gdp);
    void (*set_src_to_dest)(PPCContext *) = recomp_lookup(0x171d74u);
    if (set_src_to_dest && gs != 0u) {
        c->gpr[3] = gs;
        set_src_to_dest(c);
    }
}

// Called at guest 0x37b60, after UI_DrawBestTimes has loaded the DNF lap
// count into r12 and before it tests it. The dormant layout 2 formats the
// lap count twice and never fills the y=170 line; if the lap count is
// nonzero it draws the uninitialized r1+0x14 buffer there. Replace that
// buffer with the player's best lap so the host's BEST LAP label has a value,
// and force r12 nonzero so the guest skips its "0" fallback copy.
void m2_best_times_dnf_fill(PPCContext *c) {
    if (!restore_best_times_enabled_cached() || !s_bt_active ||
        s_bt_outcome != 2u || !c || !c->mem)
        return;
    const uint32_t saved_sp = c->gpr[1];
    void (*get_msh)(PPCContext *) = recomp_lookup(0x1149a8u);
    if (!get_msh || saved_sp < 0x1000u)
        return;
    const uint32_t frame = saved_sp - 0x80u;
    const uint32_t minutes_ea = frame + 0x10u;
    const uint32_t seconds_ea = frame + 0x14u;
    const uint32_t hundredths_ea = frame + 0x18u;
    wr32(c, frame, saved_sp);
    c->gpr[1] = frame;
    c->gpr[3] = rd32(c, g_recomp_bss_base + M2_BT_RACERS + M2_BT_RACER_BEST);
    c->gpr[4] = minutes_ea;
    c->gpr[5] = seconds_ea;
    c->gpr[6] = hundredths_ea;
    get_msh(c);
    c->gpr[1] = saved_sp;

    c->gpr[3] = saved_sp + 0x14u;                    // UI_DrawBestTimes buffer
    c->gpr[4] = g_recomp_text_base + M2_BT_TIME_FMT;
    c->gpr[5] = rd32(c, minutes_ea);
    c->gpr[6] = rd32(c, seconds_ea);
    c->gpr[7] = rd32(c, hundredths_ea);
    recomp_call_selector(c, 1, 324, 0x37b60u);       // sprintf
    c->gpr[1] = saved_sp;
    c->gpr[12] = 1u;
}

int m2_best_times_state_step(PPCContext *c) {
    if (!restore_best_times_enabled_cached() || !c || !c->mem)
        return 0;
    if (!s_bt_armed)
        return 0;

    const uint32_t gdp_ptr_ea = g_recomp_bss_base + 0x3a54u;
    const uint32_t gdp = rd32(c, gdp_ptr_ea);
    if (gdp == 0 || gdp > RECOMP_GUEST_MEM - 4u)
        return 0;

    // Same input record m2_credits_state_step samples: StateDriver's r1+8,
    // record+0x14 = this frame's translated button word.
    uint32_t actions = 0;
    if (c->gpr[1] >= 0x20u && c->gpr[1] <= RECOMP_GUEST_MEM - 0x20u)
        actions = rd32(c, c->gpr[1] + 0x1cu);

    if (!s_bt_active) {
        if (!best_times_open(c)) {
            // Missing art: fall through to the original high-score screen.
            s_bt_armed = 0;
            return 0;
        }
        s_bt_active = 1;
        s_bt_frame_count = 0;
        s_bt_prev_actions = 0xffffffffu;  // the button that ended the race is old
    }

    const uint32_t pressed = actions & ~s_bt_prev_actions;
    s_bt_prev_actions = actions;
    s_bt_frame_count++;
    if (s_bt_frame_count >= 30u && pressed != 0u) {
        best_times_close(c);
        // Clear once more for the high-score screen that resumes next frame;
        // consuming this frame keeps the press from also dismissing it.
        wr32(c, g_recomp_bss_base + 0x654cu, 1u);
        return 1;
    }

    // Select the blender source before the text, as every shipped UI
    // screen does after its background (see m2_credits_state_step).
    const uint32_t gdp_gs = rd32(c, gdp);
    void (*set_src_to_dest)(PPCContext *) = recomp_lookup(0x171d74u);
    if (set_src_to_dest && gdp_gs != 0u) {
        c->gpr[3] = gdp_gs;
        set_src_to_dest(c);
    }
    void (*draw_best_times)(PPCContext *) = recomp_lookup(0x1379ccu);
    if (draw_best_times) {
        c->gpr[3] = 0u;
        c->gpr[4] = s_bt_outcome;
        draw_best_times(c);
    }
    best_times_draw_labels(c, gdp_gs);
    return 1;
}

// Optional enhancements: restore the unused drafting/slipstream effect.
// HandleDrafting (ai.c 0x6d44) has no caller. It targets the next car up the
// road (RankOppPositions, ascending centerline point, wrapping) and, when the
// player is within 2 centerline points, 60 ft behind and 6 ft either side of
// it, adds k * target world velocity (body+0xd8) to the player record's Vwind
// (record+0x48..0x50); k is 0.5 within 10 ft and falls off linearly to 0.
// sim_cmd_go copies the record into the sim each frame and aerofn subtracts
// Vwind from the airflow, reducing drag and lift. The shipped game never
// resets Vwind after track init, so the helper zeroes it each frame before
// the call, and it skips the call when there are no opponents, where
// RankOppPositions makes the player its own target. Hooked once per frame in
// CarSimFunction (0xae74) before the player record goes to the sim at 0xae7c.
// Default, 0, or any other value preserves the original physics.
static atomic_int g_restore_drafting = ATOMIC_VAR_INIT(-1);

static int restore_drafting_enabled_cached(void) {
    int enabled = atomic_load_explicit(&g_restore_drafting, memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_RESTORE_DRAFTING");
    const int detected = value != NULL && strcmp(value, "1") == 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_restore_drafting, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

int m2_restore_drafting_enabled(void) {
    return restore_drafting_enabled_cached();
}

void m2_drafting_state_reset(void) {
    atomic_store_explicit(&g_restore_drafting, -1, memory_order_release);
}

#define M2_DRAFT_RECORD   0x6754u  // .data player control record (0x60 bytes)
#define M2_DRAFT_VWIND    0x48u    // record Vwind[0..2]
#define M2_DRAFT_RACERS   0x3a60u  // .bss racers, stride 0x124
#define M2_DRAFT_NDRONES  0x62a4u  // .bss numDrones
#define M2_RACER_STRIDE   0x124u

// The sim pointer chain HandleDrafting dereferences for one racer:
// racer+0x8c simcomm, simcomm+0x3d4 carsim, carsim[0] body.
static int drafting_racer_ready(PPCContext *c, uint32_t racer) {
    const uint32_t simcomm = rd32(c, racer + 0x8cu);
    if (simcomm == 0u || simcomm > RECOMP_GUEST_MEM - 0x3d8u)
        return 0;
    const uint32_t carsim = rd32(c, simcomm + 0x3d4u);
    if (carsim == 0u || carsim > RECOMP_GUEST_MEM - 4u)
        return 0;
    const uint32_t body = rd32(c, carsim);
    return body != 0u && body <= RECOMP_GUEST_MEM - 0xe4u;
}

void m2_drafting_step(PPCContext *c) {
    if (!restore_drafting_enabled_cached() || !c || !c->mem)
        return;

    const uint32_t vwind = g_recomp_data_base + M2_DRAFT_RECORD + M2_DRAFT_VWIND;
    for (uint32_t i = 0; i < 3u; ++i)
        wr32(c, vwind + 4u * i, 0u);

    const int32_t drones = (int32_t)rd32(c, g_recomp_bss_base + M2_DRAFT_NDRONES);
    if (drones <= 0)
        return;
    const uint32_t racers = g_recomp_bss_base + M2_DRAFT_RACERS;
    if (!drafting_racer_ready(c, racers))
        return;
    void (*handle_drafting)(PPCContext *) = recomp_lookup(0x106d44u);
    if (!handle_drafting)
        return;

    // HandleDrafting clobbers the volatile registers; CarSimFunction reloads
    // r3/r4/r10 right after the hook, but keep the whole frame intact anyway.
    uint32_t saved_gpr[32];
    float saved_fpr[32];
    memcpy(saved_gpr, c->gpr, sizeof(saved_gpr));
    memcpy(saved_fpr, c->fpr, sizeof(saved_fpr));
    const uint32_t saved_lr = c->lr, saved_ctr = c->ctr, saved_cr = c->cr;
    const uint32_t saved_xer = c->xer, saved_pc = c->pc;

    // HandleDrafting ranks first, so the target is only known afterwards;
    // the ranking itself is side-effect free (UpdateBits repeats it), so
    // rank, check the target, and only then run HandleDrafting.
    void (*rank)(PPCContext *) = recomp_lookup(0x1036f4u);
    if (rank) {
        c->gpr[3] = racers;
        c->lr = 0xae74u;
        rank(c);
        const uint32_t target = rd32(c, racers + 0x5cu);
        if (target >= 1u && target <= (uint32_t)drones &&
            drafting_racer_ready(c, racers + target * M2_RACER_STRIDE)) {
            c->lr = 0xae74u;
            handle_drafting(c);
        }
    }

    memcpy(c->gpr, saved_gpr, sizeof(saved_gpr));
    memcpy(c->fpr, saved_fpr, sizeof(saved_fpr));
    c->lr = saved_lr;
    c->ctr = saved_ctr;
    c->cr = saved_cr;
    c->xer = saved_xer;
    c->pc = saved_pc;
}

// Optional enhancements: unlock the secret track (activatesecrettrack,
// state.c 0x2e578). activatesecrettrack writes 6 to configraceNumSub[0]
// (.data+0x78f8, 0x17d968), which is the modulo limit doButtonMenu reads for
// the Track row of the Configure Race menu (0x17d980). Default is 5 (tracks
// 0..4); 6 exposes index 5 (Psychedelia / leary). Default, 0, or any other
// value leaves 0x17d968 untouched until unlocked in-game on the Skid Pad.
static atomic_int g_unlock_secret_track = ATOMIC_VAR_INIT(-1);

static int unlock_secret_track_enabled_cached(void) {
    int enabled = atomic_load_explicit(&g_unlock_secret_track, memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_UNLOCK_SECRET_TRACK");
    const int detected = value != NULL && strcmp(value, "1") == 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_unlock_secret_track, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

int m2_unlock_secret_track_enabled(void) {
    return unlock_secret_track_enabled_cached();
}

void m2_unlock_secret_track_state_reset(void) {
    atomic_store_explicit(&g_unlock_secret_track, -1, memory_order_release);
}

void m2_unlock_secret_track_step(PPCContext *c) {
    if (!unlock_secret_track_enabled_cached() || !c || !c->mem)
        return;

    void (*activate)(PPCContext *) = recomp_lookup(0x12e578u);
    if (!activate)
        return;

    const uint32_t saved_r11 = c->gpr[11];
    const uint32_t saved_r12 = c->gpr[12];
    const uint32_t saved_lr = c->lr;
    const uint32_t saved_pc = c->pc;

    activate(c);

    c->gpr[11] = saved_r11;
    c->gpr[12] = saved_r12;
    c->lr = saved_lr;
    c->pc = saved_pc;
}

// Default-on fix: the Laguna phantom heap overrun. With no phantom on the
// MicroCard, repRestorePhantom (replay2.c 0x27250) opens the disc's
// tracks/<track>/ra_<track>_phantom.dat, takes fi_ByteCount from
// GetRawFileInfo (FileInfo+0x08, stack 0x14(r1)) and reads that many bytes
// into the 0x11978-byte buffer it allocated at 0x2727c. Every shipped file is
// 63,080 bytes except Laguna's, which is 1,354,716: a 3,288-frame phantom
// followed by an unrelated pose/control recording of the same drive. The read
// overruns ~1.28 MB of heap (the engine 3D-sound objects first), and the race
// faults in M_Draw. The hook runs at 0x2735c with r4 = buffer and r5 =
// fi_ByteCount; it bounds the read to the buffer and rewrites the stack copy
// that 0x27360 compares against, so the routine still takes its own success
// path (cursor 0x648c reset, file closed). The bounded bytes hold Laguna's
// whole phantom (0x38 header + 3,288 frames = 0x3398), and repGetPhantomFrame
// stops at the header's frame count. Files that fit are untouched. Default,
// unset, or any value other than "0" applies the bound; "0" keeps the
// original overrun.
#define M2_PHANTOM_RESTORE_BUFFER 0x11978u  // repRestorePhantom mem_alloc size

static atomic_int g_laguna_phantom_fix = ATOMIC_VAR_INIT(-1);

static int laguna_phantom_fix_enabled_cached(void) {
    int enabled = atomic_load_explicit(&g_laguna_phantom_fix, memory_order_acquire);
    if (enabled >= 0)
        return enabled;

    const char *value = getenv("M2_LAGUNA_PHANTOM_FIX");
    const int detected = value == NULL || strcmp(value, "0") != 0;
    int expected = -1;
    if (!atomic_compare_exchange_strong_explicit(
            &g_laguna_phantom_fix, &expected, detected,
            memory_order_release, memory_order_acquire))
        return expected;
    return detected;
}

int m2_laguna_phantom_fix_enabled(void) {
    return laguna_phantom_fix_enabled_cached();
}

void m2_laguna_phantom_fix_state_reset(void) {
    atomic_store_explicit(&g_laguna_phantom_fix, -1, memory_order_release);
}

void m2_phantom_restore_read_step(PPCContext *c) {
    if (!laguna_phantom_fix_enabled_cached() || !c || !c->mem)
        return;
    if (c->gpr[5] <= M2_PHANTOM_RESTORE_BUFFER)
        return;
    c->gpr[5] = M2_PHANTOM_RESTORE_BUFFER;
    wr32(c, c->gpr[1] + 0x14u, M2_PHANTOM_RESTORE_BUFFER);
}

// ---- Observed selector dispatch (selector_observed.h) ---------------------
// One relaxed atomic fetch_or per dispatch into a fixed 10x1024 table: no
// lock, no allocation, no I/O, and monotonic by construction (bit 0 = the pair
// was reached, bit 1 = a typed route served it), so a later handled note is
// never downgraded by an earlier unhandled one. Observation only: it feeds
// folio_print_report() and nothing else.
#define M2_SELECTOR_OBS_SEEN 1u
#define M2_SELECTOR_OBS_HANDLED 2u
static _Atomic unsigned char g_selector_observed[M2_FOLIO_COUNT * 1024u];

void m2_selector_note(uint32_t folio, uint32_t ordinal, int handled) {
    if (folio < M2_FOLIO_COUNT && ordinal < 1024u) {
        atomic_fetch_or_explicit(
            &g_selector_observed[folio * 1024u + ordinal],
            handled ? (unsigned char)(M2_SELECTOR_OBS_SEEN | M2_SELECTOR_OBS_HANDLED)
                    : (unsigned char)M2_SELECTOR_OBS_SEEN,
            memory_order_relaxed);
    }
}

// Read-only view of the record for folio_print_report(). Counts every
// distinct pair seen so far at each level, so the report can print what it
// measured rather than only what it predicted.
int m2_selector_observed(uint32_t folio, uint32_t ordinal,
                               uint32_t* out_handled,
                               uint32_t* out_unhandled) {
    uint32_t handled = 0, unhandled = 0;
    int result = -1;

    if (folio < M2_FOLIO_COUNT && ordinal < 1024u) {
        const unsigned char bits = atomic_load_explicit(
            &g_selector_observed[folio * 1024u + ordinal], memory_order_relaxed);
        result = (bits & M2_SELECTOR_OBS_HANDLED) ? 1
              : (bits & M2_SELECTOR_OBS_SEEN) ? 0
                                              : -1;
    }
    for (size_t i = 0; i < sizeof(g_selector_observed); ++i) {
        const unsigned char bits =
            atomic_load_explicit(&g_selector_observed[i], memory_order_relaxed);
        if (bits & M2_SELECTOR_OBS_HANDLED)
            handled++;
        else if (bits & M2_SELECTOR_OBS_SEEN)
            unhandled++;
    }
    if (out_handled) *out_handled = handled;
    if (out_unhandled) *out_unhandled = unhandled;
    return result;
}

