// The production call shape selects the source ViewType enum value 6. The
// graphics folio adds the NTSC projector bits while resolving the ViewType.
#define GK_VIEWTYPE_16_640        5u
#define GK_VIEWTYPE_16_640_LACE   6u
#define GK_VIEWTYPE_PROJTYPE_NTSC 0x10000000u
