// distinct (type, name_ea) → handle mappings so repeated FindItem probes
// return stable handles instead of always the last CreateItemVA dummy.
#define GK_FIND_REG 32
static uint32_t g_last_generic_item = 0;
static struct { uint32_t type, name, handle; } g_find_reg[GK_FIND_REG];

