// Opt-in bounded movie-path trace (`M2_MPEG_TRACE=1`): device-visible
// mpegvideo WRITE/READ/CONTROL traffic plus the folio call sequence from the
// VideoPlayer entry window, so the FMV streaming/decoder path can be
// recovered and tested without the broad state2 input census.
static int gk_mpeg_trace_enabled(void) {
    static int enabled = -1;
    if (enabled == -1) {
        const char* e = getenv("M2_MPEG_TRACE");
        enabled = e && (e[0] == '1' || e[0] == 'y' || e[0] == 'Y');
    }
    return enabled;
}

// VideoPlayer's first selector after MemSetZone(2) is the stable host
// boundary for resetting a stale temporary media-zone cursor. The definition
// lives with the guest-entry diagnostics below; keep this declaration here so
// the lifecycle correction does not depend on an optional trace hook.
static void gk_prepare_video_media_zone(PPCContext* cpu);

// Movie-path selector window trace (declared in recomp_helpers.h). One shared
// trigger (first selector call inside VideoPlayer) and one bounded budget
// across every generated translation unit. Returns 1 while the call belongs
// to the traced window so the header wrapper logs the matching return.
int m2_mpeg_sel_trace_call(PPCContext* c, uint32_t folio, uint32_t ord,
                           uint32_t pc) {
    if (pc == 0x03c2f0u)
        gk_prepare_video_media_zone(c);
    if (!gk_mpeg_trace_enabled()) return 0;
    static int window_active = 0;
    static uint32_t window_end = 0;
    static uint32_t window_n = 0;
    uint32_t frame = 0;
    if (c && c->mem && M2_GUEST_FRAME_COUNTER_EA <= RECOMP_GUEST_MEM - 4u)
        frame = rd32(c, M2_GUEST_FRAME_COUNTER_EA);
    if (pc == 0x03c2f0u) {
        window_active = 1;
        window_end = frame + 30u;
        window_n = 0;
    }
    if (!window_active) return 0;
    if (frame > window_end || window_n >= 3000u) {
        window_active = 0;
        return 0;
    }
    if (pc == 0x06ab4cu && ord == 171u) return 0;   // CreateMsgItem pool flood
    ++window_n;
    fprintf(stderr,
            "[mpeg-sel] n=%u call folio=%u ord=%u pc=%#x r3=%#x r4=%#x\n",
            window_n, folio, ord, pc, c->gpr[3], c->gpr[4]);
    return 1;
}

void m2_mpeg_sel_trace_ret(uint32_t ord, uint32_t pc, uint32_t r3) {
    fprintf(stderr, "[mpeg-sel] ret ord=%u pc=%#x r3=%#x\n", ord, pc, r3);
}

