static int gk_carsim_signal_diag_site(uint32_t pc) {
    return pc == 0x18d0cu || pc == 0x18ea4u || pc == 0x18ed4u ||
           pc == 0x18eccu || pc == 0x3110cu || pc == 0xb7c8u;
}

static uint32_t g_carsim_signal_diag_count;

static int gk_carsim_signal_diag_should_emit(uint32_t pc) {
    if (!gk_carsim_signal_diag_enabled() ||
        !gk_carsim_signal_diag_site(pc))
        return 0;
    // The track-init task polls this site while waiting for CarSimThread to
    // terminate. Keep that hot loop bounded, but leave enough diagnostic
    // budget for CarSimThread's own wait site to appear in the same run.
    if (pc == 0x18ed4u)
        return g_carsim_signal_diag_count < 16u;
    return g_carsim_signal_diag_count < 128u;
}

static uint32_t gk_diag_word(uint32_t ea) {
    if (!g_gk.cpu || !g_gk.cpu->mem || ea >= RECOMP_GUEST_MEM ||
        RECOMP_GUEST_MEM - ea < 4u)
        return 0;
    return rd32(g_gk.cpu, ea);
}

