static uint32_t gk_make_handle(uint32_t type, uint32_t slot, uint32_t gen) {
    return ((gen << M2K_HANDLE_GEN_SHIFT) & M2K_HANDLE_GEN_MASK) |
           ((slot << M2K_HANDLE_SLOT_SHIFT) & M2K_HANDLE_SLOT_MASK) |
           (type & M2K_HANDLE_TYPE_MASK);
}

#define GK_HANDLE_GEN_MAX (M2K_HANDLE_GEN_MASK >> M2K_HANDLE_GEN_SHIFT)

static uint32_t gk_next_item_generation(void) {
    // The public handle carries 20 generation bits. Keep zero reserved for
    // invalid handles and wrap only after the representable range is spent.
    if (g_gk.item_gen == 0 || g_gk.item_gen >= GK_HANDLE_GEN_MAX)
        g_gk.item_gen = 1;
    else
        ++g_gk.item_gen;
    return g_gk.item_gen;
}

static int gk_bound(void) { return g_gk.kctx && g_gk.cpu && g_gk.cpu->mem; }

void m2_guest_kernel_note_boundary(void) {
    if (g_gk.kctx) m2k_task_note_kernel_boundary(g_gk.kctx);
}

// Selector identity for the kernel-lock attribution diagnostic. The pair
// counts are only maintained while M2_KERNEL_LOCK_DIAG is enabled, so the
// production path is the same lock note with no extra bookkeeping.
#define M2K_LOCK_DIAG_PAIRS 256u
typedef struct m2k_lock_diag_pair {
    uint32_t folio;
    uint32_t ordinal;
    uint64_t count;
} m2k_lock_diag_pair;
static m2k_lock_diag_pair g_lock_diag_pairs[M2K_LOCK_DIAG_PAIRS];
static uint64_t g_lock_diag_pair_total;

// The lifted call sites route the image's C-library helpers (memmove, memset,
// __itof, __utof) through the selector path because the host implements them
// as shims. The original image linked them as ordinary functions: they perform
// no kernel state transition and no scheduler-visible side effect, so they
// must not carry the kernel-boundary note (lock, quantum check, boundary
// sequence, wakeup). A race attribution put these four ordinals at
// ~77% of all selector dispatches and ~90% of the kernel-lock wait. Every
// other folio selector keeps the note: folio calls are real kernel entries.
// M2_KERNEL_NOTE_LIBRARY_ALL=1 restores the note for every selector as a
// falsification control.
static int g_note_library_all = -1;  // -1 unchecked, 0 skip helpers, 1 note all

int m2_selector_is_library_helper(uint32_t folio, uint32_t ordinal) {
    if (folio != M2_FOLIO_KERNEL) return 0;
    return ordinal == M2_KSEL_MEMMOVE || ordinal == M2_KSEL_MEMSET ||
           ordinal == M2_KSEL_ITOF || ordinal == M2_KSEL_UTOF;
}

void m2_guest_kernel_note_boundary_sel(uint32_t folio, uint32_t ordinal) {
    if (m2_kernel_lock_diag_enabled()) {
        const uint32_t key = (folio << 16u) ^ ordinal;
        uint32_t base = (uint32_t)((key * 2654435761u) & (M2K_LOCK_DIAG_PAIRS - 1u));
        for (uint32_t probe = 0; probe < M2K_LOCK_DIAG_PAIRS; ++probe) {
            m2k_lock_diag_pair* pair =
                &g_lock_diag_pairs[(base + probe) & (M2K_LOCK_DIAG_PAIRS - 1u)];
            if ((pair->count == 0u && pair->folio == 0u && pair->ordinal == 0u) ||
                (pair->folio == folio && pair->ordinal == ordinal)) {
                pair->folio = folio;
                pair->ordinal = ordinal;
                ++pair->count;
                break;
            }
        }
        ++g_lock_diag_pair_total;
    }
    if (g_note_library_all < 0)
        g_note_library_all = getenv("M2_KERNEL_NOTE_LIBRARY_ALL") ? 1 : 0;
    if (!g_note_library_all && m2_selector_is_library_helper(folio, ordinal))
        return;
    m2_guest_kernel_note_boundary();
}

void m2_kernel_lock_diag_dump_pairs(void) {
    if (!m2_kernel_lock_diag_enabled()) return;
    fprintf(stderr, "[kernel-lock] selector-pairs total=%llu\n",
            (unsigned long long)g_lock_diag_pair_total);
    for (int rank = 0; rank < 16; ++rank) {
        m2k_lock_diag_pair* best = NULL;
        for (uint32_t i = 0; i < M2K_LOCK_DIAG_PAIRS; ++i) {
            m2k_lock_diag_pair* pair = &g_lock_diag_pairs[i];
            if (!pair->count) continue;
            if (!best || pair->count > best->count) best = pair;
        }
        if (!best) break;
        fprintf(stderr,
                "[kernel-lock] pair[%d] folio=%u ordinal=%u count=%llu\n",
                rank, best->folio, best->ordinal,
                (unsigned long long)best->count);
        best->count = 0;
    }
}

static PPCContext* gk_current_cpu(void) {
    return g_gk_active_cpu ? g_gk_active_cpu : g_gk.cpu;
}

// Selector dispatch scopes the caller's registers through g_gk_active_cpu.
// Focused harnesses may use a register-only caller while the bound context owns
// guest RAM; production task contexts carry the same shared mem pointer. Keep
// register ownership and memory ownership distinct so a register-only caller
// cannot turn a valid guest read into an OOB-shadow read.
static PPCContext* gk_current_memory_cpu(void) {
    PPCContext* cpu = gk_current_cpu();
    return (cpu && cpu->mem) ? cpu : g_gk.cpu;
}

// Probe-only view of the context currently executing guest kernel/worker
// code.  The normal context accessor returns the main guest context, which is
// insufficient while an opt-in MPIO dispatch runs CarSimFunction on a local
// worker context sharing the same guest RAM.
PPCContext* m2_guest_active_ctx_for_trace(void) {
    return gk_current_cpu();
}

static uint32_t gk_diag_word_ctx(PPCContext* cpu, uint32_t ea) {
    if (!cpu || !cpu->mem || ea >= RECOMP_GUEST_MEM ||
        RECOMP_GUEST_MEM - ea < 4u)
        return 0;
    return rd32(cpu, ea);
}

static uint32_t gk_diag_byte_ctx(PPCContext* cpu, uint32_t ea) {
    if (!cpu || !cpu->mem || ea >= RECOMP_GUEST_MEM)
        return 0;
    return rd8(cpu, ea);
}

static void gk_record_guest_host_write(uint32_t ea, uint32_t size,
                                       uint32_t writer_pc) {
    if (!m2_provenance_active || !gk_bound() || size == 0) return;
    PPCContext* cpu = gk_current_memory_cpu();
    if (!cpu || !cpu->mem) return;
    uint32_t frame_seq = 0;
    if (M2_GUEST_FRAME_COUNTER_EA <= RECOMP_GUEST_MEM - 4u)
        frame_seq = rd32(cpu, M2_GUEST_FRAME_COUNTER_EA);
    m2_provenance_record_host_write(cpu->mem, ea, size,
                                    writer_pc ? writer_pc : cpu->pc,
                                    cpu->lr, frame_seq);
}

static void gk_record_guest_host_copy(uint32_t dst_ea, uint32_t src_ea,
                                      uint32_t size, uint32_t operation_pc) {
    if (!m2_provenance_active || !gk_bound() || size == 0) return;
    PPCContext* cpu = gk_current_memory_cpu();
    if (!cpu || !cpu->mem) return;
    uint32_t frame_seq = 0;
    if (M2_GUEST_FRAME_COUNTER_EA <= RECOMP_GUEST_MEM - 4u)
        frame_seq = rd32(cpu, M2_GUEST_FRAME_COUNTER_EA);
    m2_provenance_record_copy_from_guest(
        cpu->mem, dst_ea, src_ea, size,
        operation_pc ? operation_pc : cpu->pc, cpu->lr, frame_seq);
}

