static void gk_remove_audio_attachments(uint32_t item) {
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
            continue;
        if (attachment->attachment_next == item)
            attachment->attachment_next = 0;
        if (attachment->attachment_master != item &&
            attachment->attachment_slave != item)
            continue;
        const uint32_t slave_item = attachment->attachment_slave;
        const int owns_promoted_delay =
            item == attachment->attachment_master &&
            gk_live_item(slave_item) != NULL &&
            gk_live_item(slave_item)->sample_delay_owned;
        uint32_t attachment_item = gk_make_handle(
            GK_TYPE_ITEM_VA, i, attachment->generation);
        gk_DeleteItem(attachment_item);
        if (owns_promoted_delay) {
            int still_referenced = 0;
            for (uint32_t j = 0; j < GK_MAX_ITEMS; ++j) {
                const gk_item *other = &g_gk.items[j];
                if (!other->used ||
                    other->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
                    continue;
                if (other->attachment_slave == slave_item) {
                    still_referenced = 1;
                    break;
                }
            }
            if (!still_referenced)
                gk_DeleteItem(slave_item);
        }
    }
}

// CheckItem (kernel 29): resolve an Item to its guest Node representation and
// verify the source subsystem/node type bytes at Node+8/+9. Supported substrate
// handles are materialized by gk_LookupItem; raw guest EAs remain valid only if
// their caller-provided Node header matches the requested type.
static uint32_t gk_CheckItemNode(uint32_t item, uint32_t subsystem_type,
                                 uint32_t node_type) {
    if (!gk_bound() || item == 0) return 0;
    const uint32_t type = m2k_handle_type(item);
    uint32_t node_ea = item;
    if (type == GK_TYPE_ITEM_VA || type == M2K_TYPE_MSGPORT ||
        m2k_is_message_handle(item) ||
        type == M2K_TYPE_IOREQ || type == M2K_TYPE_TASK) {
        if (!gk_item_handle_is_live(item)) return 0;
        node_ea = gk_LookupItem(item);
        // A local generic Item has no materialized Node yet; do not report the
        // handle itself as a Node and thereby create a false positive.
        if (node_ea == 0 || node_ea == item) return 0;
    }
    if (node_ea > RECOMP_GUEST_MEM - 0x24u) return 0;
    if (rd8(g_gk.cpu, node_ea + 0x08u) != (uint8_t)subsystem_type ||
        rd8(g_gk.cpu, node_ea + 0x09u) != (uint8_t)node_type)
        return 0;
    return node_ea;
}

// One-argument validity view for host-side consumers of
// m2_kernel_dispatch. Guest calls never use this slot;
// recomp_call_kernel_dispatch uses the exact Node-returning CheckItemNode ABI.
static uint32_t gk_CheckItem(uint32_t item) {
    if (!gk_bound() || item == 0) return 1;
    const uint32_t type = m2k_handle_type(item);
    if (type == GK_TYPE_ITEM_VA || type == M2K_TYPE_MSGPORT ||
        m2k_is_message_handle(item) ||
        type == M2K_TYPE_IOREQ || type == M2K_TYPE_TASK)
        return gk_item_handle_is_live(item) ? 0 : 1;
    return item < RECOMP_GUEST_MEM ? 0 : 1;
}

 // ---- List/Node + TagList kernel helpers (28/36/1) --------------------------
 // Bounded guest-string compare matching Portfolio FindNamedNode's
 // case-insensitive name comparison. Returns 0 on equal.
 static int gk_guest_strcasecmp(uint32_t a, uint32_t b) {
     for (int i = 0; i < 256; i++) {
         if (a >= RECOMP_GUEST_MEM || b >= RECOMP_GUEST_MEM) return -1;
         uint8_t ca = rd8(g_gk.cpu, a), cb = rd8(g_gk.cpu, b);
         if (ca >= (uint8_t)'A' && ca <= (uint8_t)'Z')
             ca = (uint8_t)(ca + ((uint8_t)'a' - (uint8_t)'A'));
         if (cb >= (uint8_t)'A' && cb <= (uint8_t)'Z')
             cb = (uint8_t)(cb + ((uint8_t)'a' - (uint8_t)'A'));
         a++; b++;
         if (ca != cb) return (int)ca - (int)cb;
         if (ca == 0) return 0;
     }
     return -1;
 }

 // FindNamedNode (kernel 36): Portfolio `Node* FindNamedNode(const List* list,
 // const char* name)`. The generated spFindMarkerName window passes
 // `sound + 0x1c`, which is the complete 16-byte List, not its head field.
 // Portfolio stops at the l_Filler sentinel. Invalid or cyclic guest links
 // fail closed after a bounded walk.
static uint32_t gk_FindNamedNode(uint32_t list, uint32_t name) {
    if (!gk_bound() || list == 0 || name == 0 ||
        list > RECOMP_GUEST_MEM - 16u || name >= RECOMP_GUEST_MEM)
        return 0;

    const uint32_t filler = list + 8u;  // &l_Filler / empty-list sentinel
    uint32_t node = rd32(g_gk.cpu, list + 4u);  // l_Head
    for (int i = 0; i < 4096; i++) {
        if (node == filler) return 0;
        if (node == 0 || node > RECOMP_GUEST_MEM - 20u) return 0;

        const uint32_t name_ptr = rd32(g_gk.cpu, node + 16u);  // Node.n_Name
        if (name_ptr != 0 && name_ptr < RECOMP_GUEST_MEM) {
            const int cmp = gk_guest_strcasecmp(name_ptr, name);
            if (cmp == 0) return node;
        }

         node = rd32(g_gk.cpu, node);  // Node.n_Next
     }
     return 0;
 }

 // UniversalInsertNode (kernel 28): Portfolio
 // `void UniversalInsertNode(List*, Node*, bool (*)(Node*, Node*))`. The
 // source sound-player call passes CmpMarkers in r5; resolve that guest
 // callback and insert before the first node for which it returns true.
static void gk_UniversalInsertNode(uint32_t list, uint32_t node,
                                   uint32_t compare) {
     if (!gk_bound() || list == 0 || node == 0 || compare == 0 ||
         list > RECOMP_GUEST_MEM - 16u || node > RECOMP_GUEST_MEM - 8u)
         return;

    RecompFn comparator = gk_lookup_callback(compare);
    if (!comparator) return;

    PPCContext* cpu = g_gk.cpu;
    const uint32_t filler = list + 8u;
    uint32_t current = rd32(cpu, list + 4u);  // l_Head
    for (int i = 0; i < 4096; i++) {
        if (current == filler) {
            // ADDTAIL(list, node): insert before the l_Filler sentinel.
            const uint32_t pred = rd32(cpu, list + 12u);  // l_Tail
            if (pred == 0 || pred > RECOMP_GUEST_MEM - 8u) return;
             wr32(cpu, node + 0u, filler);
            wr32(cpu, node + 4u, pred);
            wr32(cpu, pred + 0u, node);
            wr32(cpu, filler + 4u, node);
            return;
        }
        if (current == 0 || current > RECOMP_GUEST_MEM - 8u) return;

        cpu->gpr[3] = node;
        cpu->gpr[4] = current;
        comparator(cpu);
        if (cpu->gpr[3] != 0) {
            const uint32_t pred = rd32(cpu, current + 4u);
            if (pred == 0 || pred > RECOMP_GUEST_MEM - 8u) return;
            wr32(cpu, node + 0u, current);
            wr32(cpu, node + 4u, pred);
            wr32(cpu, pred + 0u, node);
            wr32(cpu, current + 4u, node);
            return;
        }
         current = rd32(cpu, current + 0u);
     }
 }

 // FindTagArg (kernel 1): Portfolio
 // `TagArg *FindTagArg(const TagArg *tagList, uint32 tag)`. The vendor
 // implementation walks through NextTagArg(), skips TAG_NOP, follows TAG_JUMP,
 // and returns the last matching TagArg pair. There is no third output
 // argument; GetTagArg@0x73d9c loads ta_Arg from +4 of the returned pair.
 static uint32_t gk_FindTagArg(uint32_t taglist, uint32_t tag) {
     if (!gk_bound()) return 0;
     uint32_t p = taglist;
     uint32_t result = 0;
     for (uint32_t i = 0; i < 4096u; ++i) {
         if (p == 0 || p > RECOMP_GUEST_MEM - 8u) return result;
         const uint32_t t = rd32(g_gk.cpu, p);
         const uint32_t v = rd32(g_gk.cpu, p + 4u);
         if (t == M2_TAG_END) return result;
         if (t == 0xffffffffu /* TAG_NOP */) {
             p += 8u;
             continue;
         }
         if (t == M2_TAG_JUMP) {
             p = v;
             continue;
         }
         if (t == tag) result = p;
         p += 8u;
     }
     return result;
 }

 // ---- GetMemInfo / UnimportByName (kernel 16/100) --------------------------
 // GetMemInfo (kernel 16): Portfolio `void GetMemInfo(MemInfo *info,
 // uint32 infoSize, uint32 memFlags)`. The source record is
 // {taskPages, taskBytes, freePages, largestFreePageSpan, systemPages,
 // systemBytes, otherPages}; it is not the similarly named six-field layout
 // used by older host notes. The compatibility page pool gives each allocation
 // task family a 4 KiB page pool while allowing sub-page hole reuse. All
 // currently modeled CreateThread workers share the launcher's pool, matching
 // task.c; a future CreateTask implementation can supply another pool owner.
 // The handler applies the source's zero-fill/truncated-copy rule and leaves
 // the guest return register untouched because the source function is void.
 static void gk_GetMemInfo(uint32_t info, uint32_t size, uint32_t sel) {
     if (!gk_bound() || !g_gk.cpu || !g_gk.cpu->mem || info == 0 || size == 0 ||
         info > RECOMP_GUEST_MEM || size > RECOMP_GUEST_MEM - info)
         return;

     const m2k_item_t current = gk_heap_current_page_pool();
     uint32_t task_bytes = 0u;
     pthread_mutex_lock(&gk_heap_lock);
     for (uint32_t i = 0; i < g_gk.heap_block_count; ++i) {
         const gk_heap_block *block = &g_gk.heap_blocks[i];
         if (block->owner == current) task_bytes += block->size;
     }

     uint32_t task_pages = 0u;
     uint32_t other_pages = 0u;
     uint32_t free_pages = 0u;
     uint32_t largest_pages = 0u;
     uint32_t run_pages = 0u;
     for (uint32_t page = 0; page < GK_HEAP_PAGE_COUNT; ++page) {
         if (g_gk.heap_owned_pages[page] == 0u) {
             ++free_pages;
             ++run_pages;
             if (run_pages > largest_pages) largest_pages = run_pages;
         } else {
             run_pages = 0u;
             ++task_pages;
         }
     }
     pthread_mutex_unlock(&gk_heap_lock);
     const uint32_t values[7] = {
         task_pages, task_bytes, free_pages,
         largest_pages * GK_HEAP_PAGE_SIZE, 0u, 0u, other_pages
     };
     const uint32_t record_size = 7u * sizeof(uint32_t);

     // Vendor GetMemInfo first clears an over-sized caller buffer, then copies
     // the bounded local record. A non-normal flag returns the zeroed local
     // record without querying a page pool.
     if (size > record_size)
         memset(g_gk.cpu->mem + info, 0, size);
     if (sel != 0)
         memset(g_gk.cpu->mem + info, 0, size < record_size ? size : record_size);
     else {
         const uint32_t copy_size = size < record_size ? size : record_size;
         for (uint32_t off = 0; off < copy_size; off += sizeof(uint32_t)) {
             if (off + sizeof(uint32_t) <= copy_size)
                 wr32(g_gk.cpu, info + off, values[off / sizeof(uint32_t)]);
             else {
                 // The source uses memcpy, so preserve a partial final word
                 // in big-endian byte order for malformed sizes.
                 uint32_t word = values[off / sizeof(uint32_t)];
                 for (uint32_t i = 0; off + i < copy_size; ++i)
                     g_gk.cpu->mem[info + off + i] =
                         (uint8_t)(word >> (24u - i * 8u));
             }
         }
     }
     gk_record_guest_host_write(info, size < record_size ? size : record_size,
                                g_gk_selector_pc);
 }

// UnimportByName (kernel 100): Portfolio
// `Err UnimportByName(Item module, const char *name)` (libs/loader/api.c ->
// AskDaemon(DAEMON_UNIMPORTBYNAME) -> daemon.c:DaemonUnimportByName). The four
// image call sites are its own Close*Folio wrappers (game_text_10.c
// FN_CloseAudioFolio@0x73220, FN_CloseAudioPatchFolio@0x73254,
// FN_CloseGraphicsFolio@0x7328c, FN_CloseIFFFolio@0x732c4): r3 = the
// FindCurrentModule Item and r4 = the name EA, spelled "audio", "audiopatch",
// "graphics", "iff" at 0x17324c/0x173280/0x1732b8/0x1732f0. Vendor order:
//   1. !IsMemReadable(name, 1)          -> LOADER_ERR_BADPTR
//   2. LookupItem(importer)             -> the module's LoaderInfo
//   3. FindImportIndex(li, name)        -> scan the module's *static* import
//                                          list, else LOADER_ERR_NOTFOUND
//   4. FindImport(li, impIndex, FALSE)  -> the loaded exporter Item, else
//                                          LOADER_ERR_NOTFOUND
//   5. automatic import (no IMPORT_NOW) -> CloseModuleTree(clientTask,
//                                          exporter); its Err is returned.
// Host model: the module's import list is the image's own resolved import set
// (the same bounded table gk_ImportByName#103 resolves), and the host serves
// those folios natively instead of loading exporter modules. Step 4 therefore
// always resolves for a listed native folio. Automatic imports have no host
// tree to close; IMPORT_NOW imports remain linked. Both yield host success 0
// (the vendor can return a positive exporter Item for IMPORT_NOW), and
// the loader's negative verdict otherwise — never a blanket success. Name
// comparison is ASCII case-insensitive, matching the vendor loader's
// FindImportIndex `strcasecmp` contract.
static uint32_t gk_UnimportByName(uint32_t module_item, uint32_t name_ea) {
    if (!gk_bound()) return M2M_ERR_BAD_ITEM;
    if (module_item != gk_current_module_item())
        return M2M_ERR_BAD_ITEM;

    char name[GK_MAX_NAME_LEN];
    const int32_t rc = m2m_copy_guest_string_ctx(g_gk.cpu, name_ea, name,
                                                 sizeof(name));
    if (rc == M2M_ERR_FAULT) return M2M_ERR_FAULT;
    if (rc < 0) return M2M_ERR_RANGE;   // no NUL within the bounded copy

    for (uint32_t i = 0; i < GK_IMPORT_COUNT; ++i) {
        if ((g_imports[i].module_mask & (1u << gk_current_module_slot())) != 0 &&
            gk_host_strcasecmp(name, g_imports[i].name) == 0)
            return M2K_OK;   // listed import: FindImport resolves, close is a no-op
    }
    return M2M_ERR_NAME;     // FindImportIndex: not in the module's import list
}


// ---- DebugPutStr / DebugPutChar (kernel 118/120) --------------------------
// Opera debug-console output. DebugPutStr(r3 = guest NUL-terminated string EA)
// emits the string to stderr; DebugPutChar(r3 = char byte) emits one char. Both
// are void on the guest side (callers discard the result and advance a pointer),
// so a host stderr sink is a faithful debug proxy.
static void gk_DebugPutStr(uint32_t str_ea) {
    if (!gk_bound() || str_ea == 0 || str_ea >= RECOMP_GUEST_MEM) return;
    char buf[256];
    if (m2m_copy_guest_string_ctx(g_gk.cpu, str_ea, buf, sizeof(buf)) >= 0)
        fputs(buf, stderr);
}
static void gk_DebugPutChar(uint32_t c) {
    if (!gk_bound()) return;
    fputc((int)(c & 0xffu), stderr);
}



// ---- CreateDeviceStackList (kernel 67) ---------------------------------------
// Portfolio OS device stack enumeration:
//   Err CreateDeviceStackList(List **listOut, const DeviceStackDesc *desc);
// Takes r3=listOut EA (pointer to List* in guest RAM), r4=desc EA (pointer to
// array of 16-byte DeviceStackDesc records terminated by 0 in word 0).
// Allocates a 16-byte List structure on the guest heap, initializes it as empty:
//   *(list_ea + 0) = 0 (l_Anchor)
//   *(list_ea + 4) = list_ea + 8 (l_Head points to &l_Tail, matching ISEMPTYLIST)
//   *(list_ea + 8) = 0 (l_Tail is NULL)
//   *(list_ea + 12) = list_ea + 4 (l_TailPred points to &l_Head)
// Writes list_ea to *listOut via wr32(cpu, listOut_ea, list_ea), and returns 0.
// Fail-closed on unbound kernel, invalid EA, or OOM.
static int32_t gk_CreateDeviceStackList(uint32_t listOut_ea, uint32_t desc_ea) {
    (void)desc_ea;
    if (!gk_bound()) return -1;
    if (listOut_ea < 0x10000 || listOut_ea > RECOMP_GUEST_MEM - 4) return -1;

    // Allocate 16-byte List struct + 64-byte DeviceStack node
    uint32_t list_ea =
        (uint32_t)(uintptr_t)gk_heap_alloc(80, "device_stack_list");
    if (!list_ea || list_ea > RECOMP_GUEST_MEM - 80) {
        return (int32_t)0xd57b9006u; // ER_NoMem
    }

    uint32_t node_ea = list_ea + 16;
    PPCContext* cpu = g_gk.cpu;
    // 3DO List struct
    wr32(cpu, list_ea + 0, 0);
    wr32(cpu, list_ea + 4, node_ea);         // l_Head -> first node
    wr32(cpu, list_ea + 8, 0);               // l_Tail -> NULL
    wr32(cpu, list_ea + 12, node_ea);        // l_TailPred -> last node

    // 3DO Node & DeviceStack fields
    wr32(cpu, node_ea + 0, list_ea + 8);     // n_Next -> &l_Tail (end of list)
    wr32(cpu, node_ea + 4, list_ea + 4);     // n_Prev -> &l_Head
    wr32(cpu, node_ea + 8, 0);
    wr32(cpu, node_ea + 12, 0);
    wr32(cpu, node_ea + 16, 0);
    wr32(cpu, node_ea + 20, 0);
    wr32(cpu, node_ea + 24, node_ea);        // device node ptr / handle @ 0x18
    wr32(cpu, node_ea + 28, 0);
    wr32(cpu, node_ea + 32, 0);
    wr32(cpu, node_ea + 36, node_ea);        // device node ptr / handle @ 0x24

    wr32(cpu, listOut_ea, list_ea);
    if (gk_state2_input_diag_enabled())
        fprintf(stderr,
                "[gk_CreateDeviceStackList] pc=%#x listOut_ea=%#x -> "
                "list_ea=%#x node_ea=%#x\n",
                g_gk_selector_pc, listOut_ea, list_ea, node_ea);
    return 0;
}

// ---- DeleteDeviceStackList (kernel 68) --------------------------------------
// Portfolio OS device stack teardown:
//   Err DeleteDeviceStackList(struct List *list);
// Takes r3=list_ea (the List* that CreateDeviceStackList#67 wrote into *listOut).
// The compatibility creator uses one 80-byte List+node allocation. Deletion
// returns that exact block and reports 0; all 8 generated call sites discard
// the return value. Fail-closed on
// unbound kernel, null EA, or an EA outside the bound guest RAM (the List struct
// occupies 16 bytes, so a valid pointer must leave room for it).
static int32_t gk_DeleteDeviceStackList(uint32_t list_ea) {
    if (!gk_bound()) return -1;
    if (list_ea == 0 || list_ea > RECOMP_GUEST_MEM - 16) return -1;
    gk_FreeMem((void *)(uintptr_t)list_ea, 80);
    return 0;
}

// ---- OpenDeviceStack (kernel 69) ------------------------------------------
// Portfolio OS device stack open: Err OpenDeviceStack(struct DeviceStack *ds);
// r3 = ds_ea, the device-stack node EA each caller loads as *(list_ea+4) from the
// List created by CreateDeviceStackList#67. Returns 0 (Err success) so the 5
// generated call sites proceed down their device-setup success paths:
//   - FMVOpenVideo 0x652a0:  cmpwi r31,0; blt  -> success continues to video open
//   - CreateMPIOReq 0x738a8 / 0x73a84: cmpwi r31,0; bge -> success calls ord 170
//   - OpenTEDevice 0x73f68: stores the result and returns it as its own Err
//   - MPS_InitMPEGStill 0x20278: stores the result to an out-param (*r29)
// Our guest heap (and device model) has no real hardware device, so the
// device-open side effect (marking the DeviceStack open) is a platform service
// not modeled this slice — analogous to #67/#68, which perform no real I/O.
// Only EA-bound validation is observable; null / out-of-bounds / unbound -> -1.
static int32_t gk_OpenDeviceStack(uint32_t ds_ea) {
    if (!gk_bound()) return -1;
    if (ds_ea == 0 || ds_ea > RECOMP_GUEST_MEM - 4) return -1;
    if (gk_state2_input_diag_enabled())
        fprintf(stderr, "[gk_OpenDeviceStack] pc=%#x ds_ea=%#x\n",
                g_gk_selector_pc, ds_ea);
    return 0;
}

// ---- CloseDeviceStack (kernel 70) -----------------------------------------
// Portfolio OS device stack close: Err CloseDeviceStack(struct DeviceStack *ds);
// the inverse of OpenDeviceStack#69. r3 = ds_ea, the device-stack node EA each
// of the 7 generated call sites loads (see m2fn_CloseDeviceStack_t in
// recomp_helpers.h for the exact per-site provenance). Returns 0 (Err success)
// so the teardown paths proceed; 6 of 7 call sites discard the return, and
// MPS_TeardownMPEGStill 0x20a58 propagates it as its own Err. Our guest heap
// and device model have no real hardware device, so the device-close side
// effect (marking the DeviceStack closed) is a platform service not modeled
// this slice — analogous to #67/#68/#69, which perform no real I/O. Only
// EA-bound validation is observable; null / out-of-bounds / unbound -> -1. The
// node itself is not freed here (that is DeleteDeviceStackList#68's contract).
static int32_t gk_CloseDeviceStack(uint32_t ds_ea) {
    if (!gk_bound()) return -1;
    if (ds_ea == 0 || ds_ea > RECOMP_GUEST_MEM - 4) return -1;
    return 0;
}

// ---- libc-flavoured memory services (kernel 33 memset / kernel 31 memmove) ----
// Both write inside the bound host guest-RAM window and clip the requested byte
// range to [0, RECOMP_GUEST_MEM) so a malformed size/EA can never write past
// the image. Writes go through the CPU's shared mem pointer (same RAM the
// generated code reads), so the guest sees the change. Per C/3DO semantics
// both return the original dst guest EA in r3 even though most generated
// sites discard r3 and rely only on the side-effect. When unbound, both fail
// closed (NULL return, no write).
static void* gk_memset(void* dst, int32_t c, uint32_t n) {
    if (!gk_bound()) return NULL;
    uint32_t ea = (uint32_t)(uintptr_t)dst;
    uint32_t len = (uint32_t)n;
    if (ea >= RECOMP_GUEST_MEM) len = 0;
    else if (len > RECOMP_GUEST_MEM - ea) len = RECOMP_GUEST_MEM - ea;
    if (len) {
        m2_trace_light_host_write("kernel-memset-before", ea, len);
        memset(g_gk.cpu->mem + ea, (unsigned char)c, (size_t)len);
        m2_trace_light_host_write("kernel-memset-after", ea, len);
        gk_record_guest_host_write(ea, len, g_gk.cpu ? g_gk.cpu->pc : 0);
    }
    return (void*)(uintptr_t)ea;
}
static void* gk_memmove(void* dst, const void* src, uint32_t n) {
    if (!gk_bound()) return NULL;
    uint32_t dea = (uint32_t)(uintptr_t)dst;
    uint32_t sea = (uint32_t)(uintptr_t)src;
    // Effective bytes = intersection of the source's and dest's in-bounds
    // ranges, so we never read past src or write past dst. host memmove then
    // preserves overlap semantics on the shared guest RAM buffer.
    uint32_t src_avail = (sea >= RECOMP_GUEST_MEM) ? 0u : RECOMP_GUEST_MEM - sea;
    uint32_t dst_avail = (dea >= RECOMP_GUEST_MEM) ? 0u : RECOMP_GUEST_MEM - dea;
    uint32_t len = (uint32_t)n;
    if (len > src_avail) len = src_avail;
    if (len > dst_avail) len = dst_avail;
    if (len && sea < RECOMP_GUEST_MEM && dea < RECOMP_GUEST_MEM) {
        m2_trace_light_host_write("kernel-memmove-before", dea, len);
        memmove(g_gk.cpu->mem + dea, g_gk.cpu->mem + sea, (size_t)len);
        m2_trace_light_host_write("kernel-memmove-after", dea, len);
        gk_record_guest_host_copy(dea, sea, len,
                                  g_gk.cpu ? g_gk.cpu->pc : 0);
    }
    return (void*)(uintptr_t)dea;
}

// ---- filesystem directory window (folio 4: 32/33/34) ------------------------
// Pinned by the FindMicroCard lift (microcard.c 0x1faa8; layout constants
// mirror shims/filesystem_folio.h): ord 32 OpenDirPath(path_ea) -> dir
// handle or 0, ord 33 ReadDir(dir, entry_ea) -> >=0 entry (attr u32 @+0, name
// @+36) / <0 end, ord 34 CloseDir(dir) -> m2_err_t. Directory handles are
// 32-bit-clean guest tokens (never host pointers). Real disc-FS enumeration is
// bridged to the host through weak m2_host_dir_* accessors (strong defs in
// host/core/filesystem_shim.cpp); with no bridge present (standalone/weak
// builds) the handlers fail closed deterministically (not-found / end).

// Pinned M2_DIRENT entry layout (mirrors filesystem_folio.h).
#define M2_DIRENT_ATTR_OFF 0u
#define M2_DIRENT_NAME_OFF 36u
#define M2_DIRENT_NAME_CAP 48u   // bytes incl. NUL terminator
#define M2_DIRENT_ATTR_IS_DIRECTORY (1u << 0)   // FILE_IS_DIRECTORY
#define M2_DIRENT_ATTR_USER_STORAGE (1u << 9)   // FILE_USER_STORAGE_PLACE

#define GK_MAX_DIRS 8u
typedef struct gk_dir_slot {
    uint8_t  used;
    uint32_t guest_handle;   // guest-visible token (GK_TYPE_DIR)
    uint32_t host_token;     // opaque host enumeration token
} gk_dir_slot;
static gk_dir_slot g_dir_slots[GK_MAX_DIRS];
static uint32_t g_dir_gen = 0;

// Weak host bridges (strong defs in host/core/filesystem_shim.cpp; resolve to
// NULL in standalone/weak builds and are null-checked here).
uint32_t m2_host_dir_open(const char* guest_path) __attribute__((weak));
int      m2_host_dir_next(uint32_t host_token, char* name_out,
                          uint32_t name_cap) __attribute__((weak));
void     m2_host_dir_close(uint32_t host_token) __attribute__((weak));

static uint32_t gk_OpenDirPath(uint32_t path_ea) {
    if (!gk_bound() || !m2_host_dir_open) return 0u;
    char path[GK_MAX_NAME_LEN];
    int32_t rc = m2m_copy_guest_string_ctx(g_gk.cpu, path_ea, path, sizeof(path));
    if (rc == M2M_ERR_FAULT || rc < 0) return 0u;   // not a clean in-bounds path
    uint32_t host_tok = m2_host_dir_open(path);
    if (host_tok == 0) return 0u;   // open failed / not a directory
    for (unsigned i = 0; i < GK_MAX_DIRS; ++i) {
        if (g_dir_slots[i].used) continue;
        g_dir_slots[i].used = 1;
        g_dir_slots[i].host_token = host_tok;
        g_dir_slots[i].guest_handle = gk_make_handle(GK_TYPE_DIR, i, ++g_dir_gen);
        return g_dir_slots[i].guest_handle;
    }
    m2_host_dir_close(host_tok);    // table full -> close + fail closed
    return 0u;
}

// Reads one entry into guest RAM at entry_ea using the pinned M2_DIRENT layout.
static int32_t gk_ReadDir(uint32_t dir, uint32_t entry_ea) {
    if (!gk_bound() || !m2_host_dir_next) return -1;
    uint32_t slot = m2k_handle_slot(dir);   // (dir & SLOT_MASK) >> SLOT_SHIFT
    if (slot >= GK_MAX_DIRS || !g_dir_slots[slot].used ||
        g_dir_slots[slot].guest_handle != dir)
        return -1;   // stale/closed handle -> end (fail closed)
    char name[GK_MAX_NAME_LEN];
    int n = m2_host_dir_next(g_dir_slots[slot].host_token, name, sizeof(name));
    if (n <= 0) return -1;   // host reports end / error
    if (!g_gk.cpu || !g_gk.cpu->mem) return -1;
    // Bounded guest-RAM write (clip the 48-byte entry to image bounds).
    if (entry_ea > RECOMP_GUEST_MEM ||
        entry_ea + (M2_DIRENT_NAME_OFF + M2_DIRENT_NAME_CAP) > RECOMP_GUEST_MEM)
        return -1;
    wr32(g_gk.cpu, entry_ea + M2_DIRENT_ATTR_OFF,
         M2_DIRENT_ATTR_IS_DIRECTORY | M2_DIRENT_ATTR_USER_STORAGE);
    memset(g_gk.cpu->mem + entry_ea + 4, 0,
           M2_DIRENT_NAME_OFF - M2_DIRENT_ATTR_OFF - 4);
    gk_record_guest_host_write(
        entry_ea + 4, M2_DIRENT_NAME_OFF - M2_DIRENT_ATTR_OFF - 4,
        g_gk_selector_pc);
    size_t nl = (name[0] ? strlen(name) : 0);
    if (nl > M2_DIRENT_NAME_CAP - 1) nl = M2_DIRENT_NAME_CAP - 1;
    memcpy(g_gk.cpu->mem + entry_ea + M2_DIRENT_NAME_OFF, name, nl + 1);
    gk_record_guest_host_write(entry_ea + M2_DIRENT_NAME_OFF,
                               (uint32_t)(nl + 1), g_gk_selector_pc);
    return 0;
}

static int32_t gk_CloseDir(uint32_t dir) {
    if (!gk_bound() || !m2_host_dir_close) return -1;
    uint32_t slot = m2k_handle_slot(dir);   // (dir & SLOT_MASK) >> SLOT_SHIFT
    if (slot >= GK_MAX_DIRS || !g_dir_slots[slot].used ||
        g_dir_slots[slot].guest_handle != dir)
        return -1;   // stale/closed handle
    m2_host_dir_close(g_dir_slots[slot].host_token);
    g_dir_slots[slot].used = 0;
    g_dir_slots[slot].guest_handle = 0;
    g_dir_slots[slot].host_token = 0;
    return 0;
}

// ---- filesystem raw-file window (folio 4: 35 OpenRawFile / 36 CloseRawFile /
// 37 ReadRawFile / 38 WriteRawFile / 39 SeekRawFile / 40 GetRawFileInfo) ----
//
// Pinned by the readinmemimage@0x1f638 + readinmemimage_prealloc@0x1f4c8 call
// shape (generated game_text_02.c) cross-checked against the
// M2/Portfolio OS FileInfo struct (ws_root/src/includes/file/fileio.h:75):
//   35 OpenRawFile(out_handle_ea, path_ea, mode=FILEOPEN_READ(=0))
//      -> Err in gpr[3] (>=0 success), *out_handle_ea = guest RawFile token.
//   36 CloseRawFile(handle) -> Err in gpr[3]; 8 sites discard the return.
//   37 ReadRawFile(handle, buf_ea, count) -> int32 bytes-read (>=0) or <0 error.
//   40 GetRawFileInfo(handle, info_ea, info_size=0x28)
//      -> Err in gpr[3]; writes a 0x28-byte FileInfo struct. Field +0x08 is
//         fi_ByteCount (total file size in bytes) — used by readinmemimage as
//         the third-alloc size `extra = fi_ByteCount - payload - 4`.
//   38 WriteRawFile(handle, buf_ea, count) -> bytes-written or <0 (pinned by
//      writeRepNode@0x267a4, 20 sites; return discarded by all callers).
//   39 SeekRawFile(handle, offset, whence) -> previous cursor position / <0
//      (pinned by file/rawfile.c and the freopen site 0x7497c (handle,0,2);
//      that caller checks only the negative-error branch).
//
// Real disc-FS access is bridged through weak m2_host_raw_* accessors (strong
// defs in host/core/filesystem_shim.cpp); the guest handle is a 32-bit-clean
// GK_TYPE_RAW token (slot|generation), never a host pointer, so a stale or
// reused handle fails closed after close/reopen. With no bridge present
// (standalone/weak build) the handlers return 0 and 4:37/40 leave their
// guest-RAM buffers unchanged — preserving the prior fail-closed behavior.

#define GK_MAX_RAWS 8u
#define GK_RAW_BLOCK_SIZE 2048u
typedef struct gk_raw_slot {
    uint8_t  used;
    uint8_t  writable;       // Portfolio rf_Writable: which FileOpenModes the
                            // open mode set (rawfile.c:220-247). WriteRawFile
                            // refuses a read-only RawFile with
                            // FILE_ERR_BADMODE (rawfile.c:570-571).
    uint32_t guest_handle;   // guest-visible token (GK_TYPE_RAW)
    uint32_t host_token;     // opaque host raw-file token (m2_host_raw_open result)
    uint32_t file_size;      // cached file size (mirrors the FileInfo fi_ByteCount)
} gk_raw_slot;
static gk_raw_slot g_raw_slots[GK_MAX_RAWS];
static uint32_t g_raw_gen = 0;

// File Items use the same host-side read-only open service as the already
// recovered RawFile window, but keep an independent guest Item table. This
// preserves the Portfolio distinction between an Item returned by OpenFile
// and a RawFile* returned through an out-parameter; both values remain
// fixed-width guest tokens and never expose host pointers.
#define GK_MAX_FILES 32u
static gk_file_slot g_file_slots[GK_MAX_FILES];
static uint32_t g_file_gen;

// Both guest file tables are process-wide while folio-4 selectors execute on
// the calling guest task pthread. One guard covers allocation/reservation and
// release of the File and RawFile slots. Release paths take this lock before
// the host shim's raw-pool mutex and no host path acquires it, so the order is
// one-way and the two pools cannot form a cycle. An open reserves its guest
// slot, drops this lock for the host open, then reacquires it to publish the
// handle.
static pthread_mutex_t g_fs_pool_lock = PTHREAD_MUTEX_INITIALIZER;

static gk_file_slot *gk_file_find(uint32_t handle) {
    if (handle == 0 || m2k_handle_type(handle) != GK_TYPE_FILE) return NULL;
    uint32_t slot = m2k_handle_slot(handle);
    if (slot >= GK_MAX_FILES) return NULL;
    gk_file_slot *file = &g_file_slots[slot];
    if (!file->used || file->guest_handle != handle) return NULL;
    return file;
}

// CreateAlias(path_ea) -> Err (log-only). Sole game site is closenodelete
// @0x741d8 (r3 = r31+0x19 string EA; r4 stale, return ignored — next insn
// checks r30, not r3). Portfolio CreateAlias(existing, alias) takes two paths,
// but only one string EA is live here, so the handler validates the single
// bounded guest string and reports success without side effects.
static int32_t gk_CreateAlias(uint32_t path_ea) {
    if (!gk_bound()) return M2K_ERR_BAD_ITEM;
    char path[GK_MAX_NAME_LEN];
    if (m2m_copy_guest_string_ctx(g_gk.cpu, path_ea, path, sizeof(path)) < 0)
        return M2K_ERR_BAD_ITEM;
    return M2K_OK;
}

// OpenFile(path) -> Item. The original File Folio returns a negative Err on
// failure; successful Items are positive handles. The path is copied from
// guest RAM before the existing raw host bridge is called.
static int32_t gk_OpenFile(uint32_t path_ea) {
    if (!gk_bound() || !m2_host_raw_open) return M2K_ERR_BAD_ITEM;

    char path[GK_MAX_NAME_LEN];
    if (m2m_copy_guest_string_ctx(g_gk.cpu, path_ea, path, sizeof(path)) < 0)
        return M2K_ERR_BAD_ITEM;

    uint32_t host_token = m2_host_raw_open(path);
    if (host_token == 0) {
        if (gk_audio_start_diag_enabled()) {
            static uint32_t miss_count;
            if (miss_count < 32u) {
                fprintf(stderr, "[audio-file] open path='%s' host=0 rc=%d\n",
                        path, M2K_ERR_BAD_ITEM);
                ++miss_count;
            }
        }
        return M2K_ERR_BAD_ITEM;
    }

    pthread_mutex_lock(&g_fs_pool_lock);
    for (uint32_t i = 0; i < GK_MAX_FILES; ++i) {
        if (g_file_slots[i].used) continue;
        g_file_slots[i].used = 1;
        g_file_slots[i].host_token = host_token;
        g_file_slots[i].guest_handle =
            gk_make_handle(GK_TYPE_FILE, i, ++g_file_gen);
        if (gk_audio_start_diag_enabled()) {
            static uint32_t open_count;
            if (open_count < 32u) {
                fprintf(stderr,
                        "[audio-file] open path='%s' host=%#x item=%#x slot=%u rc=0\n",
                        path, host_token, g_file_slots[i].guest_handle, i);
                ++open_count;
            }
        }
        pthread_mutex_unlock(&g_fs_pool_lock);
        return (int32_t)g_file_slots[i].guest_handle;
    }
    pthread_mutex_unlock(&g_fs_pool_lock);

    if (m2_host_raw_close) m2_host_raw_close(host_token);
    if (gk_audio_start_diag_enabled()) {
        static uint32_t full_count;
        if (full_count < 32u) {
            fprintf(stderr,
                    "[audio-file] open path='%s' host=%#x rc=%d reason=no-slot\n",
                    path, host_token, M2K_ERR_NO_SLOT);
            ++full_count;
        }
    }
    return M2K_ERR_NO_SLOT;
}

// CloseFile(Item) -> Err. Closing invalidates the guest token immediately;
// generation matching prevents a stale token from closing a later file.
static int32_t gk_CloseFile(uint32_t handle) {
    if (!gk_bound()) return M2K_ERR_BAD_ITEM;
    pthread_mutex_lock(&g_fs_pool_lock);
    gk_file_slot *file = gk_file_find(handle);
    if (!file) {
        pthread_mutex_unlock(&g_fs_pool_lock);
        return M2K_ERR_BAD_ITEM;
    }
    if (m2_host_raw_close) m2_host_raw_close(file->host_token);
    file->used = 0;
    file->guest_handle = 0;
    file->host_token = 0;
    pthread_mutex_unlock(&g_fs_pool_lock);
    return M2K_OK;
}

static void gk_close_all_files(void) {
    pthread_mutex_lock(&g_fs_pool_lock);
    if (m2_host_raw_close) {
        for (uint32_t i = 0; i < GK_MAX_FILES; ++i) {
            if (g_file_slots[i].used)
                m2_host_raw_close(g_file_slots[i].host_token);
        }
    }
    memset(g_file_slots, 0, sizeof(g_file_slots));
    g_file_gen = 0;
    pthread_mutex_unlock(&g_fs_pool_lock);
}
// Weak default for the mode-aware host open. host/core/filesystem_shim.cpp
// supplies the production definition; a standalone link, or a focused gate
// that only overrides the read accessors, keeps the historic behaviour:
// FILEOPEN_READ still resolves through m2_host_raw_open, and a write mode has
// no provider, so it fails closed rather than reporting a create it never did.
__attribute__((weak)) uint32_t m2_host_raw_open_mode(const char* guest_path,
                                                    uint32_t mode) {
    if (mode != M2_FILEOPEN_READ) return 0u;
    return m2_host_raw_open ? m2_host_raw_open(guest_path) : 0u;
}


static uint32_t gk_OpenRawFile(uint32_t out_handle_ea, uint32_t path_ea,
                              uint32_t mode) {
    if (!gk_bound() || out_handle_ea == 0 ||
        out_handle_ea > RECOMP_GUEST_MEM - 4u) {
        // out_handle_ea must fit a 4-byte handle write; no path on unbound
        // kernel -> 0 in gpr[3] (M2_ERR code 0) so the guest bge-not-taken
        // path at 0x1f668 fires.
        return (uint32_t)-1;   // negative -> caller takes the bge-not-taken path
    }
    // FileOpenModes is a bounded vendor enum (fileio.h:31-42); rawfile.c's
    // internalOpenRawFile switch has no default, so an out-of-range mode
    // leaves the file unopened. Refuse it the same way.
    if (mode > M2_FILEOPEN_READWRITE_EXISTING) return (uint32_t)-1;
    char path[GK_MAX_NAME_LEN];
    int32_t rc = m2m_copy_guest_string_ctx(g_gk.cpu, path_ea, path, sizeof(path));
    if (rc == M2M_ERR_FAULT || rc < 0) {
        return (uint32_t)-1;   // not a clean NUL-terminated in-bounds path
    }
    // Reserve a guest slot before the host open. A *_NEW mode removes an
    // existing file on the host, so discovering a full eight-slot table only
    // after m2_host_raw_open_mode() would truncate the save and then fail.
    pthread_mutex_lock(&g_fs_pool_lock);
    int slot = -1;
    for (uint32_t i = 0; i < GK_MAX_RAWS; ++i) {
        if (g_raw_slots[i].used) continue;
        slot = (int)i;
        g_raw_slots[i].used = 1;   // reservation; release below on failure
        break;
    }
    pthread_mutex_unlock(&g_fs_pool_lock);
    if (slot < 0) {
        return (uint32_t)-1;   // guest table full: no host-side side effects
    }
    // FILEOPEN_READ keeps the historic read-only accessor so every existing
    // bridge override (m2recomp gates, standalone harness) is unchanged; a
    // write mode needs a provider that can actually create the file.
    uint32_t host_tok = 0;
    if (mode == M2_FILEOPEN_READ) {
        if (!m2_host_raw_open) host_tok = 0;
        else host_tok = m2_host_raw_open(path);
    } else if (m2_host_raw_open_mode) {
        host_tok = m2_host_raw_open_mode(path, mode);
    }
    if (host_tok == 0) {
        pthread_mutex_lock(&g_fs_pool_lock);
        g_raw_slots[slot].used = 0;
        pthread_mutex_unlock(&g_fs_pool_lock);
        return (uint32_t)-1;   // open failed (no file / bridge absent)
    }
    pthread_mutex_lock(&g_fs_pool_lock);
    g_raw_slots[slot].host_token = host_tok;
    g_raw_slots[slot].file_size =
        m2_host_raw_size ? m2_host_raw_size(host_tok) : 0u;
    // rawfile.c:277-284 sets rf_Writable for exactly five modes:
    // WRITE, WRITE_NEW, READWRITE, READWRITE_NEW and READWRITE_EXISTING.
    // WRITE_EXISTING and READ are left read-only, which is what makes the
    // folio 4:38 refusal in gk_WriteRawFile discriminable rather than a
    // blanket "always refuse".
    g_raw_slots[slot].writable =
        (mode == M2_FILEOPEN_WRITE || mode == M2_FILEOPEN_WRITE_NEW ||
         mode == M2_FILEOPEN_READWRITE ||
         mode == M2_FILEOPEN_READWRITE_NEW ||
         mode == M2_FILEOPEN_READWRITE_EXISTING) ? 1u : 0u;
    g_raw_slots[slot].guest_handle =
        gk_make_handle(GK_TYPE_RAW, (uint32_t)slot, ++g_raw_gen);
    // M2 contract: write the guest RawFile* (== our 32-bit token) to
    // *out_handle_ea. The token IS the guest-visible handle, so the
    // later GetRawFileInfo / ReadRawFile / CloseRawFile calls consume
    // it directly.
    wr32(g_gk.cpu, out_handle_ea, g_raw_slots[slot].guest_handle);
    pthread_mutex_unlock(&g_fs_pool_lock);
    return 0;   // success (>=0)
}

static int32_t gk_CloseRawFile(uint32_t handle) {
    if (!gk_bound() || handle == 0) return -1;
    uint32_t slot = m2k_handle_slot(handle);
    // Serialize with the reservation in gk_OpenRawFile: a close must not free
    // a slot in the middle of another task's check-then-open sequence.
    pthread_mutex_lock(&g_fs_pool_lock);
    if (slot >= GK_MAX_RAWS || !g_raw_slots[slot].used ||
        g_raw_slots[slot].guest_handle != handle) {
        pthread_mutex_unlock(&g_fs_pool_lock);
        return -1;   // stale/closed -> fail closed
    }
    if (m2_host_raw_close) m2_host_raw_close(g_raw_slots[slot].host_token);
    g_raw_slots[slot].used = 0;
    g_raw_slots[slot].guest_handle = 0;
    g_raw_slots[slot].host_token = 0;
    g_raw_slots[slot].file_size = 0;
    g_raw_slots[slot].writable = 0;
    pthread_mutex_unlock(&g_fs_pool_lock);
    return 0;   // success
}

static int32_t gk_ReadRawFile(uint32_t handle, uint32_t buf_ea, uint32_t count,
                              uint32_t op_pc) {
    if (!gk_bound() || !m2_host_raw_read) return -1;
    if (handle == 0) return -1;
    uint32_t slot = m2k_handle_slot(handle);
    if (slot >= GK_MAX_RAWS || !g_raw_slots[slot].used ||
        g_raw_slots[slot].guest_handle != handle) {
        return -1;   // stale/closed
    }
    if (buf_ea >= RECOMP_GUEST_MEM) return -1;
    if (count == 0) return 0;
    uint32_t avail = RECOMP_GUEST_MEM - buf_ea;
    if (count > avail) count = avail;
    m2_trace_light_host_write("raw-read-before", buf_ea, count);
    int32_t n = m2_host_raw_read(g_raw_slots[slot].host_token,
                                 g_gk.cpu->mem + buf_ea, count);
    m2_trace_light_host_write("raw-read-after", buf_ea, count);
    if (n > 0 && (uint32_t)n <= count) {
        if (gk_mpeg_trace_enabled()) {
            static uint32_t mpeg_raw_n;
            if (mpeg_raw_n < 64u) {
                fprintf(stderr,
                        "[mpeg-raw] n=%u buf=%#x got=%d first=%#x\n",
                        mpeg_raw_n + 1u, buf_ea, n,
                        (uint32_t)n >= 4u ? rd32(g_gk.cpu, buf_ea) : 0u);
                ++mpeg_raw_n;
            }
        }
        // Bounded diagnostic for the bulk-fread provenance gap (area-table
        // case): the record call below should always fire here. Gate on
        // M2_PROV_FREAD_TRACE so normal runs stay quiet.
        const char* trace_env = getenv("M2_PROV_FREAD_TRACE");
        if (trace_env && (trace_env[0] == '1' || trace_env[0] == 'y' ||
                          trace_env[0] == 'Y')) {
            PPCContext* trace_cpu = gk_current_cpu();
            fprintf(stderr,
                    "[prov-fread] buf=%#x n=%d active=%d bound=%d "
                    "cpu=%p mem=%p\n",
                    buf_ea, n, (int)m2_provenance_active, gk_bound(),
                    (void*)trace_cpu,
                    (void*)(trace_cpu ? trace_cpu->mem : NULL));
        }
        gk_record_guest_host_write(buf_ea, (uint32_t)n,
                                   // Folio-4 dispatch never sets
                                   // g_gk_selector_pc (only the folio-1
                                   // kernel path does), so file-read records
                                   // may carry a stale kernel pc (e.g.
                                   // allocator sites 0x6dd54/0x260a4). Thread
                                   // the guest BL site through instead: the
                                   // bulk-fread record then attributes to
                                   // 0x1f740, matching the lifted
                                   // readinmemimage call.
                                   op_pc ? op_pc : g_gk_selector_pc);
    }
    if (count >= 0x1000u && m2_light_host_write_overlaps(buf_ea, count))
        m2_trace_light_host_image();
    return n;   // host byte count (>=0) or negative on error
}

// folio 4:38 WriteRawFile(handle, buf_ea, count) -> bytes-written (>=0) or <0.
// Pinned by writeRepNode@0x267a4 (20 sites; r3=handle in r30, r4=buffer field,
// r5=byte-count field; paired readRepNode uses 37). Return is discarded by all
// observed callers, so the load-bearing contract is bounded validation + host
// forwarding. The production disc view is read-only: with no write bridge (or
// a read-only host file) the handler fails closed negative without touching
// guest RAM.
static int32_t gk_WriteRawFile(uint32_t handle, uint32_t buf_ea, uint32_t count) {
    if (!gk_bound()) return -1;
    if (handle == 0) return -1;
    uint32_t slot = m2k_handle_slot(handle);
    if (slot >= GK_MAX_RAWS || !g_raw_slots[slot].used ||
        g_raw_slots[slot].guest_handle != handle) {
        return -1;   // stale/closed
    }
    // rawfile.c:570-571 — `if (!file->rf_Writable) return FILE_ERR_BADMODE;`
    // comes before the count checks, so a write through a FILEOPEN_READ
    // handle is refused whatever the buffer is. The host bridge produces no
    // Portfolio ER_FSYS code, and every lifted caller only branches on the
    // sign, so the boundary reports a plain negative.
    if (!g_raw_slots[slot].writable) return -1;
    if (count == 0) return 0;
    if (buf_ea >= RECOMP_GUEST_MEM) return -1;
    if (count > RECOMP_GUEST_MEM - buf_ea) return -1;
    if (!m2_host_raw_write) return -1;   // read-only / standalone: fail closed
    return m2_host_raw_write(g_raw_slots[slot].host_token,
                             g_gk.cpu->mem + buf_ea, count);
}

// folio 4:39 SeekRawFile(handle, offset, whence) -> previous cursor position
// / <0 error. Pinned by file/rawfile.c and freopen@0x74840 site 0x7497c
// (r3=handle, r4=0 offset, r5=2 whence; return checked via or./blt
// negative-error branch). The host bridge performs the source clamp and
// returns the old position; otherwise it fails closed negative (guest takes
// its error path, which stores the code and returns 0 — the authentic failure
// shape).
static int32_t gk_SeekRawFile(uint32_t handle, int32_t offset, int32_t whence) {
    if (!gk_bound()) return -1;
    if (handle == 0) return -1;
    uint32_t slot = m2k_handle_slot(handle);
    if (slot >= GK_MAX_RAWS || !g_raw_slots[slot].used ||
        g_raw_slots[slot].guest_handle != handle) {
        return -1;   // stale/closed
    }
    if (whence < 0 || whence > 2) return -1;
    if (!m2_host_raw_seek) return -1;
    return m2_host_raw_seek(g_raw_slots[slot].host_token, offset, whence);
}

static int32_t gk_GetRawFileInfo(uint32_t handle, uint32_t info_ea,
                                 uint32_t info_size) {
    if (!gk_bound()) return -1;
    if (handle == 0) return -1;
    uint32_t slot = m2k_handle_slot(handle);
    if (slot >= GK_MAX_RAWS || !g_raw_slots[slot].used ||
        g_raw_slots[slot].guest_handle != handle) {
        return -1;   // stale/closed
    }
    // Pinned FileInfo layout (shims/filesystem_folio.h +
    // ws_root/src/includes/file/fileio.h:75) — 0x28 = 40 bytes. The lifted
    // readinmemimage uses +0x08 (fi_ByteCount), while M2ReadQMFFile also uses
    // +0x0c/+0x10 (fi_BlockCount/fi_BlockSize); fill the whole struct so
    // other consumers (texload.c parse_utf_file at 0x4f6a8) see a
    // well-formed record.
    if (info_ea == 0 || info_size == 0) return 0;
    if (info_ea >= RECOMP_GUEST_MEM) return -1;
    uint32_t want = info_size < 0x28u ? info_size : 0x28u;
    if (want > RECOMP_GUEST_MEM - info_ea) {
        want = RECOMP_GUEST_MEM - info_ea;
    }
    // Zero the requested window so unwritten fields are deterministic.
    memset(g_gk.cpu->mem + info_ea, 0, want);
    gk_record_guest_host_write(info_ea, want, g_gk_selector_pc);
    if (want >= 0x04u) {
        // +0x00 fi_File (Item / RawFile*) — the guest RawFile* is our
        // guest_handle token, so the file folio records the slot|gen word.
        wr32(g_gk.cpu, info_ea + 0x00, g_raw_slots[slot].guest_handle);
    }
    if (want >= 0x08u) {
        // +0x04 fi_FileType — unknown to the recomp runtime; leave 0.
    }
    if (want >= 0x0cu) {
        // +0x08 fi_ByteCount — total file size in bytes. readinmemimage
        // uses this as the third-alloc size `extra = fi_ByteCount - payload - 4`.
        wr32(g_gk.cpu, info_ea + 0x08, g_raw_slots[slot].file_size);
    }
    if (want >= 0x10u) {
        // +0x0c fi_BlockCount — OperaFS stores each file as whole 2048-byte
        // blocks; M2ReadQMFFile uses this together with fi_BlockSize to size
        // its guest buffer before reading fi_ByteCount bytes.
        wr32(g_gk.cpu, info_ea + 0x0c,
             g_raw_slots[slot].file_size / GK_RAW_BLOCK_SIZE +
             (g_raw_slots[slot].file_size % GK_RAW_BLOCK_SIZE != 0));
    }
    if (want >= 0x14u) {
        // +0x10 fi_BlockSize — fixed by the disc's OperaFS volume metadata.
        wr32(g_gk.cpu, info_ea + 0x10, GK_RAW_BLOCK_SIZE);
    }
    return 0;   // success
}

// ---- folio 4:7 ChangeDirectory (folios/file/linkexec.x EXPORTS 7) ----------
//
// Item ChangeDirectory (const char *path)   (folios/file/autodocs.c:269-302)
// "Changes the current task's working directory ... returns the item number
//  for the directory" / "Returns the item number of the new directory or a
//  negative error code for failure."
//
// internalChangeDirectory (folios/file/open.c:1402-1432) is
//   FindFile(startingDir, path, UpdateCurrentDirectory) -> File*;
//   if found and !(fi_Flags & FILE_IS_DIRECTORY) -> NotADirectory error;
//   if found -> fftd_CurrentDirectory = theDirectory; return fi.n_Item;
//   else     -> fftd_ErrorCode.
//
// The current directory is task data in the source (fftd_CurrentDirectory per
// FileFolioTaskData), so the host keeps one bounded path per guest task.
// FindFile's path grammar that the disc actually uses, reproduced here:
//   '/'         -> back to the volume root (open.c:466-476)
//   "."         -> skip (open.c:614-616)
//   ".."        -> parent directory, clamped at the root (open.c:617-622)
//   any other   -> one directory level, matched case-insensitively
// "$alias", "{a|b}" alternatives and "^" are NOT modeled. They stay ordinary
// component bytes here, so a path that uses them does not resolve and the call
// fails closed rather than silently taking a different branch. The disc
// launcher uses none of them.
// ".." is folded lexically because the M2 file folio has no symlink node: a
// File's parent is the only way up, so the composed path is the whole state.
#define GK_CWD_MAX 256u   /* FILESYSTEM_MAX_PATH_LEN (file/filesystem.h:87) */
#define GK_CWD_SLOTS 8u

// Weak host bridge (strong definition in host/core/filesystem_shim.cpp; NULL in
// a standalone/weak build, where ChangeDirectory then fails closed).
// Returns 0 when the guest path names nothing on the mounted volume, 1 for a
// regular file, 2 for a directory — FindFile's "found a node" plus the
// FILE_IS_DIRECTORY test that internalChangeDirectory performs.
int m2_host_path_kind(const char* guest_path) __attribute__((weak));

typedef struct gk_cwd_slot {
    uint8_t  used;
    uint32_t guest_handle;   // GK_TYPE_DIR Item for this directory
    char     path[GK_CWD_MAX];
} gk_cwd_slot;
static gk_cwd_slot g_cwd_slots[GK_CWD_SLOTS];
static uint32_t g_cwd_gen;

// One current directory per guest task, plus a no-task slot the host boot
// thread shares. Deliberately separate from the Item table above: these are
// the per-task data (fftd_CurrentDirectory), those are the File nodes the
// calls hand back.
static char g_cwd_paths[M2K_MAX_TASKS + 1u][GK_CWD_MAX];

// The task's own current directory, defaulting to the volume root. Index 0 is
// reserved for callers with no current guest task, which is how the host boot
// thread and the synchronous fallback reach this state.
static char* gk_cwd_slot_for_current_task(void) {
    uint32_t slot = 0;
    if (gk_bound()) {
        const m2k_item_t task = m2k_current_task_item(g_gk.kctx);
        if (task != M2K_ITEM_NONE && m2k_handle_slot(task) < M2K_MAX_TASKS)
            slot = m2k_handle_slot(task) + 1u;
    }
    return g_cwd_paths[slot];
}

// FindFile's component walk over a bounded guest path, composing the result
// into `out`. Returns 0 on success, -1 when the composed path does not fit.
static int gk_cwd_resolve(const char* base, const char* path, char* out,
                          uint32_t out_cap) {
    char work[GK_CWD_MAX];
    if (path[0] == '/') {
        work[0] = '\0';       // absolute: FindFile restarts at ff_Root
    } else {
        uint32_t n = 0;
        while (base[n] != '\0' && n + 1u < out_cap) { work[n] = base[n]; ++n; }
        if (base[n] != '\0') return -1;
        work[n] = '\0';
    }
    const char* p = path;
    while (*p != '\0') {
        if (*p == '/') { ++p; continue; }
        const char* start = p;
        while (*p != '\0' && *p != '/') ++p;
        const size_t len = (size_t)(p - start);
        if (len == 1u && start[0] == '.') continue;
        if (len == 2u && start[0] == '.' && start[1] == '.') {
            size_t cut = 0;                       // clamp at the volume root
            for (size_t i = 0; work[i] != '\0'; ++i)
                if (work[i] == '/') cut = i;
            work[cut] = '\0';
            continue;
        }
        size_t at = 0;
        while (work[at] != '\0') ++at;
        if (at + 1u + len + 1u > out_cap) return -1;
        work[at] = '/';
        for (size_t i = 0; i < len; ++i) work[at + 1u + i] = start[i];
        work[at + 1u + len] = '\0';
    }
    uint32_t n = 0;
    while (work[n] != '\0' && n + 1u < out_cap) { out[n] = work[n]; ++n; }
    if (work[n] != '\0') return -1;
    out[n] = '\0';
    return 0;
}

// Host file bridges use the guest caller's directory, not the process cwd.
// An unset directory preserves the direct-boot asset-root convention.
int m2_guest_resolve_file_path(const char* path, char* out, uint32_t capacity) {
    if (!path || !out || capacity == 0) return -1;
    const char* base = gk_cwd_slot_for_current_task();
    if (path[0] == '/' || base[0] == '\0') {
        if (strlen(path) >= capacity) return -1;
        memcpy(out, path, strlen(path) + 1u);
        return 0;
    }
    return gk_cwd_resolve(base, path, out, capacity);
}

// One Item per distinct directory, so a repeated ChangeDirectory to the same
// node returns the same value — the source returns the cached File node's
// n_Item, not a fresh one.
static uint32_t gk_cwd_item_for(const char* path) {
    for (uint32_t i = 0; i < GK_CWD_SLOTS; ++i) {
        if (g_cwd_slots[i].used && strcmp(g_cwd_slots[i].path, path) == 0)
            return g_cwd_slots[i].guest_handle;
    }
    for (uint32_t i = 0; i < GK_CWD_SLOTS; ++i) {
        if (g_cwd_slots[i].used) continue;
        g_cwd_slots[i].used = 1;
        snprintf(g_cwd_slots[i].path, sizeof(g_cwd_slots[i].path), "%s", path);
        g_cwd_slots[i].guest_handle = gk_make_handle(GK_TYPE_DIR, i, ++g_cwd_gen);
        return g_cwd_slots[i].guest_handle;
    }
    return 0;   // directory table full: no Item to hand back
}

static int32_t gk_ChangeDirectory(uint32_t path_ea) {
    if (!gk_bound() || !m2_host_path_kind) return M2K_ERR_BAD_ITEM;
    char path[GK_CWD_MAX];
    if (m2m_copy_guest_string_ctx(g_gk.cpu, path_ea, path, sizeof(path)) < 0 ||
        path[0] == '\0')
        return M2K_ERR_BAD_ITEM;
    char composed[GK_CWD_MAX];
    if (gk_cwd_resolve(gk_cwd_slot_for_current_task(), path, composed,
                       sizeof(composed)) != 0)
        return M2K_ERR_BAD_ITEM;
    const int kind = m2_host_path_kind(composed);
    if (kind == 0) return M2K_ERR_BAD_ITEM;        // FindFile found nothing
    if (kind != 2) return M2K_ERR_STATE;          // found, FILE_IS_DIRECTORY clear
    const uint32_t item = gk_cwd_item_for(composed);
    if (item == 0) return M2K_ERR_NO_SLOT;
    char* current = gk_cwd_slot_for_current_task();
    snprintf(current, GK_CWD_MAX, "%s", composed);
    return (int32_t)item;
}

// Typed folio-4 (filesystem) dispatch — OpenFile/CloseFile, directory
// enumeration, and the raw-file windows. Marshals the generated register
// window into the pinned contracts (see filesystem_folio.h / SoundPlayer,
// FindMicroCard, and readinmemimage lifts) and lands the int32 result in
// c->gpr[3]. Returns 1 when handled; 0 lets recomp_call_selector fall through
// to its fail-closed path.
static int recomp_call_fs_dispatch_impl(PPCContext* c, uint32_t ordinal,
                                        uint32_t pc) {
    (void)pc;
    if (!c) return 0;
    switch (ordinal) {
    case 0: /* OpenFile(path_ea) -> File Item or negative Err */
        c->gpr[3] = (uint32_t)gk_OpenFile(c->gpr[3]);
        return 1;
    case 1: /* CloseFile(file_item) -> Err */
        c->gpr[3] = (uint32_t)gk_CloseFile(c->gpr[3]);
        return 1;
    case 7: /* ChangeDirectory(path_ea) -> directory Item or negative Err */
        c->gpr[3] = (uint32_t)gk_ChangeDirectory(c->gpr[3]);
        return 1;
    case 10: /* CreateAlias(path_ea) -> Err (log-only; return ignored) */
        c->gpr[3] = (uint32_t)gk_CreateAlias(c->gpr[3]);
        return 1;
    case 32: /* OpenDirectoryPath(path_ea) -> dir handle or 0 */
        c->gpr[3] = gk_OpenDirPath(c->gpr[3]);
        return 1;
    case 33: /* ReadDirectory(dir_handle, entry_ea) -> >=0 entry / <0 end */
        c->gpr[3] = (uint32_t)gk_ReadDir(c->gpr[3], c->gpr[4]);
        return 1;
    case 34: /* CloseDirectory(dir_handle) -> m2_err_t */
        c->gpr[3] = (uint32_t)gk_CloseDir(c->gpr[3]);
        return 1;
    case 35: /* OpenRawFile(out_handle_ea, path_ea, mode) */
        c->gpr[3] = gk_OpenRawFile(c->gpr[3], c->gpr[4], c->gpr[5]);
        return 1;
    case 36: /* CloseRawFile(handle) */
        c->gpr[3] = (uint32_t)gk_CloseRawFile(c->gpr[3]);
        return 1;
    case 37: /* ReadRawFile(handle, buf_ea, count) */
        c->gpr[3] = (uint32_t)gk_ReadRawFile(c->gpr[3], c->gpr[4], c->gpr[5],
                                             pc);
        return 1;
    case 38: /* WriteRawFile(handle, buf_ea, count) */
        c->gpr[3] = (uint32_t)gk_WriteRawFile(c->gpr[3], c->gpr[4], c->gpr[5]);
        return 1;
    case 39: /* SeekRawFile(handle, offset, whence=0/1/2) */
        c->gpr[3] = (uint32_t)gk_SeekRawFile(c->gpr[3], (int32_t)c->gpr[4],
                                             (int32_t)c->gpr[5]);
        return 1;
    case 40: /* GetRawFileInfo(handle, info_ea, info_size=0x28) */
        c->gpr[3] = (uint32_t)gk_GetRawFileInfo(c->gpr[3], c->gpr[4], c->gpr[5]);
        return 1;
    default:
        return 0;
    }
}

// Public entry point.  Notes the (folio, ordinal) dispatch in the observed
// record (selector_observed.h) and returns the dispatch's handled flag
// unchanged.
int recomp_call_fs_dispatch(PPCContext* c, uint32_t ordinal, uint32_t pc) {
    const int handled = recomp_call_fs_dispatch_impl(c, ordinal, pc);
    m2_selector_note(M2_FOLIO_FILESYSTEM, ordinal, handled);
    return handled;
}

// ---- IFF parser engine (folio 2) --------------------------------------------
//
// Source contract: Portfolio-OS `src/mac/libs/iff/iff.c` (the released
// Portfolio source), the implementation linked into System.m2's iff module.
// The read path is
// implemented here so the game's own IFF callbacks execute unchanged and every
// IFF selector used by `driving/game` is a real parser service:
//
//   #1 DeleteIFFParser    #2 ParseIFF            #3 ReadChunk
//   #7 RegisterPropChunks #10 FindPropChunk      #13 GetCurrentContext
//   #15 AllocContextInfo  #16 FreeContextInfo    #17 FindContextInfo
//   #18 StoreContextInfo  #20 InstallEntryHandler
//   #21 InstallExitHandler #22 SeekChunk         #23 GetIFFOffset
//   #24 CreateIFFParserVA
//
// Records are 32-bit guest EAs in the NO_64_BIT_SCALARS layout the lifted image
// was built against, never host pointers:
//   ContextNode 52 B: type@+8 id@+12 sizeHi@+16 size@+20 offsetHi@+24 offset@+28
//                     List@+32 currentSizeHi@+44 currentSize@+48
//   ContextInfo 36 B: dataSizeHi@+8 dataSize@+12 data@+16 id@+20 type@+24
//                     ident@+28 purgeCB@+32; ci_Data = &ci[1]
//   PropChunk    12 B: dataSizeHi@+0 dataSize@+4 data@+8
// File bytes come from the host raw-file bridge: absolute reads through
// m2_host_raw_read_at when the host provides it, else a bounded in-memory
// prefix for standalone harnesses.  Write mode (WriteChunk/PushChunkW) has no
// `driving/game` call sites and stays fail-closed.

#define GK_IFF_MAX_PARSERS 8u
#define GK_IFF_MAX_DEPTH 16u
#define GK_IFF_MAX_INFO 128u
#define GK_IFF_MAX_PROP_TYPES 32u
#define GK_IFF_PREFIX_CAP (1u << 20)
#define GK_IFF_TAG_FILE 10u

// Error codes are MakeErr(ER_FOLI, ER_IFF, svr, ER_E_SSTM, class, err) per
// kernel/operror.h: object 'F'=42 @25, id 'IF'=0xb6a @13, severity @11,
// class @8, err @0.  Values match the constants the lifted callers compare
// against (e.g. IFF_PARSE_EOF 0xd56d410a in ScanAIFF 0x6fd60).
#define GK_IFF_ERR_NOMEM        ((int32_t)0xD56D5006u)  // severe, standard, NoMem
#define GK_IFF_ERR_BADPTR       ((int32_t)0xD56D5009u)  // severe, standard, BadPtr
#define GK_IFF_ERR_NOTSUPPORTED ((int32_t)0xD56D5010u)  // severe, standard, NotSupported
#define GK_IFF_ERR_NOSCOPE      ((int32_t)0xD56D5101u)  // severe, nonstandard, 1
#define GK_IFF_ERR_PREMATURE_EOF ((int32_t)0xD56D5102u)
#define GK_IFF_ERR_MANGLED      ((int32_t)0xD56D5103u)
#define GK_IFF_ERR_SYNTAX       ((int32_t)0xD56D5104u)
#define GK_IFF_ERR_NOTIFF       ((int32_t)0xD56D5105u)
#define GK_IFF_ERR_NOOPENTYPE   ((int32_t)0xD56D5106u)
#define GK_IFF_ERR_BADLOCATION  ((int32_t)0xD56D5107u)
#define GK_IFF_ERR_TOOBIG       ((int32_t)0xD56D5108u)
#define GK_IFF_ERR_BADMODE      ((int32_t)0xD56D5109u)
#define GK_IFF_PARSE_EOF        ((int32_t)0xD56D410Au)  // info, nonstandard, 10
#define GK_IFF_PARSE_EOC        ((int32_t)0xD56D410Bu)  // info, nonstandard, 11
// The host raw-file bridge produces no Portfolio ER_FSYS code; an open failure
// collapses to a plain fail-closed -1 (the lifted callers only branch on <0).
#define GK_IFF_ERR_HOST_OPEN    ((int32_t)-1)

#define GK_IFF_ID_FORM 0x464f524du
#define GK_IFF_ID_LIST 0x4c495354u
#define GK_IFF_ID_CAT  0x43415420u
#define GK_IFF_ID_PROP 0x50524f50u
#define GK_IFF_ID_NULL 0x20202020u
#define GK_IFF_ID_PROPCHUNK 0x70726f70u     // 'prop'
#define GK_IFF_ID_ENTRYHANDLER 0x656e6864u  // 'enhd'
#define GK_IFF_ID_EXITHANDLER 0x65786864u   // 'exhd'

#define GK_IFF_SIZE_64BIT 0xfffffffdu
#define GK_IFF_SIZE_RESERVED 0xfffffff0u

#define GK_IFF_CN_SIZE 52u
#define GK_IFF_CN_TYPE 8u
#define GK_IFF_CN_ID 12u
#define GK_IFF_CI_SIZE 36u
#define GK_IFF_PROPCHUNK_SIZE 12u

#define GK_IFF_KIND_GUEST 0u
#define GK_IFF_KIND_PROPERTY 1u

typedef struct gk_iff_node {
    uint8_t used;
    uint8_t is_master;
    uint32_t ea;            // guest ContextNode EA
    uint32_t type, id;
    uint64_t size, offset, current_size;
    int32_t info_head;      // head of attached ContextInfo list (global pool)
} gk_iff_node;

typedef struct gk_iff_info {
    uint8_t used;
    uint8_t kind;           // GK_IFF_KIND_*
    int32_t state;          // owning parser slot, -1 when unattached
    int32_t node;           // attached node index, -1 when unattached
    int32_t next;           // next info in the owning node's list
    uint32_t ea;            // guest ContextInfo EA
    uint32_t type, id, ident;
    uint32_t data_ea;
    uint32_t data_size;
    uint32_t purge_cb;      // guest purge callback EA or 0
} gk_iff_info;

typedef struct gk_iff_state {
    uint8_t used;
    uint8_t new_io;         // iff_NewIO: first chunk not yet pushed
    uint8_t paused;         // iff_Paused: deferred PopChunk pending
    uint32_t parser_ea;
    uint32_t host_token;
    uint32_t file_size;
    uint8_t *prefix;        // fallback image when read_at is unavailable
    uint32_t prefix_size;
    uint64_t stream_pos;
    uint32_t depth;         // node count; nodes[0] is the embedded master
    gk_iff_node nodes[GK_IFF_MAX_DEPTH];
    char file_name[GK_MAX_NAME_LEN];
} gk_iff_state;

static gk_iff_state g_iff_states[GK_IFF_MAX_PARSERS];
static gk_iff_info g_iff_infos[GK_IFF_MAX_INFO];

static gk_iff_state *gk_iff_find(uint32_t parser_ea) {
    if (parser_ea == 0) return NULL;
    for (uint32_t i = 0; i < GK_IFF_MAX_PARSERS; ++i) {
        if (g_iff_states[i].used && g_iff_states[i].parser_ea == parser_ea)
            return &g_iff_states[i];
    }
    return NULL;
}

static int32_t gk_iff_state_index(const gk_iff_state *s) {
    for (uint32_t i = 0; i < GK_IFF_MAX_PARSERS; ++i) {
        if (&g_iff_states[i] == s) return (int32_t)i;
    }
    return -1;
}

static uint32_t gk_iff_be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

// GoodID/GoodType: characters in [0x20, 0x7e], no leading spaces except
// ID_NULL.  The M2 is big-endian, so byte 0 of the packed ID is its top byte.
static int gk_iff_good_id(uint32_t id) {
    if ((uint8_t)(id >> 24) == ' ') return id == GK_IFF_ID_NULL;
    for (uint32_t i = 0; i < 4u; ++i) {
        uint8_t ch = (uint8_t)(id >> (24u - 8u * i));
        if (ch < ' ' || ch > '~') return 0;
    }
    return 1;
}

static int gk_iff_good_type(uint32_t type) {
    if (!gk_iff_good_id(type)) return 0;
    for (uint32_t i = 0; i < 4u; ++i) {
        uint8_t ch = (uint8_t)(type >> (24u - 8u * i));
        if (!((ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') ||
              ch == ' '))
            return 0;
    }
    return 1;
}

static int gk_iff_is_generic_id(uint32_t id) {
    return id == GK_IFF_ID_FORM || id == GK_IFF_ID_CAT ||
           id == GK_IFF_ID_LIST || id == GK_IFF_ID_PROP;
}

static int gk_iff_is_container_id(uint32_t id) {
    // iff.c: ((id & '\0\0\0{') == '\0\0\0{')
    return (id & 0x0000007bu) == 0x0000007bu;
}

static gk_iff_node *gk_iff_current_node(gk_iff_state *s) {
    if (!s || s->depth < 2u) return NULL;
    return &s->nodes[s->depth - 1u];
}

static void gk_iff_sync_node(gk_iff_node *n) {
    PPCContext *cpu = g_gk.cpu;
    if (!cpu || !n || n->ea == 0) return;
    wr32(cpu, n->ea + GK_IFF_CN_TYPE, n->type);
    wr32(cpu, n->ea + GK_IFF_CN_ID, n->id);
    wr32(cpu, n->ea + 16u, (uint32_t)(n->size >> 32));
    wr32(cpu, n->ea + 20u, (uint32_t)n->size);
    wr32(cpu, n->ea + 24u, (uint32_t)(n->offset >> 32));
    wr32(cpu, n->ea + 28u, (uint32_t)n->offset);
    wr32(cpu, n->ea + 44u, (uint32_t)(n->current_size >> 32));
    wr32(cpu, n->ea + 48u, (uint32_t)n->current_size);
}

// ---- stream over the host raw-file bridge -----------------------------------

static int32_t gk_iff_read_raw(gk_iff_state *s, void *dst, uint32_t n) {
    if (!s || (n != 0 && !dst)) return -1;
    if (n == 0) return 0;
    if (m2_host_raw_read_at_present && m2_host_raw_read_at) {
        if (s->stream_pos > s->file_size) return 0;
        uint64_t avail = (uint64_t)s->file_size - s->stream_pos;
        uint32_t want = n;
        if (avail < want) want = (uint32_t)avail;
        if (want == 0) return 0;
        int32_t got = m2_host_raw_read_at(s->host_token, s->stream_pos, dst, want);
        if (got < 0) return -1;
        s->stream_pos += (uint32_t)got;
        return got;
    }
    if (s->prefix != NULL) {
        if (s->stream_pos >= s->prefix_size) return 0;
        uint32_t avail = s->prefix_size - (uint32_t)s->stream_pos;
        uint32_t want = n < avail ? n : avail;
        memcpy(dst, s->prefix + (uint32_t)s->stream_pos, want);
        s->stream_pos += want;
        return (int32_t)want;
    }
    return -1;
}

// IFFSeek -> FileSeek -> SeekRawFile: relative seek clamped to the file
// bounds, returning the PREVIOUS cursor position (fileio.h SeekRawFile
// contract), or negative on failure.  SeekChunk compares the movement it
// observed against the requested delta, so this return contract is load
// bearing; GetIFFOffset(iff) = IFFSeek(iff, 0) yields the current position.
static int32_t gk_iff_seek_raw(gk_iff_state *s, int32_t delta) {
    if (!s) return -1;
    uint64_t prev = s->stream_pos < s->file_size ? s->stream_pos : s->file_size;
    int64_t target = (int64_t)prev + delta;
    if (target < 0) target = 0;
    if ((uint64_t)target > s->file_size) target = (int64_t)s->file_size;
    s->stream_pos = (uint64_t)target;
    return prev > (uint64_t)INT32_MAX ? -1 : (int32_t)prev;
}

// ---- ContextInfo pool --------------------------------------------------------

static int32_t gk_iff_info_by_ea(uint32_t ea) {
    if (ea == 0) return -1;
    for (uint32_t i = 0; i < GK_IFF_MAX_INFO; ++i) {
        if (g_iff_infos[i].used && g_iff_infos[i].ea == ea) return (int32_t)i;
    }
    return -1;
}

static void gk_iff_detach_info(gk_iff_info *ci) {
    if (!ci || ci->state < 0 || ci->node < 0) {
        if (ci) { ci->state = -1; ci->node = -1; ci->next = -1; }
        return;
    }
    gk_iff_state *s = &g_iff_states[ci->state];
    gk_iff_node *n = &s->nodes[ci->node];
    int32_t cur = n->info_head, prev = -1;
    while (cur >= 0) {
        if (cur == (int32_t)(ci - g_iff_infos)) {
            if (prev < 0) n->info_head = ci->next;
            else g_iff_infos[prev].next = ci->next;
            break;
        }
        prev = cur;
        cur = g_iff_infos[cur].next;
    }
    ci->state = -1;
    ci->node = -1;
    ci->next = -1;
}

// iff:16 FreeContextInfo(ContextInfo *ci) — M2 SDK src/folios/iff/iff.c:1628:
//
//   void FreeContextInfo(ContextInfo *ci) {
//       if (ci) {
//           FreeMem(ci, sizeof(ContextInfo) + ci->ci_DataSize);
//       }
//   }
//
// The release is the whole point of the routine: unlike RemoveContextInfo
// (#25, unlink only) it owns the guest block, and the vendor's size term
// `ci->ci_DataSize` is read back OUT OF THE STRUCTURE at free time, not from
// the caller's argument. That is why the size is taken from the guest words at
// ci+8/ci+12 (the NO_64_BIT_SCALARS ci_DataSizeHi/ci_DataSize pair that
// gk_iff_alloc_info wrote at #15) rather than from the host record: a guest
// that rewrote the field would ask FreeMem for a different size, exactly as on
// the hardware. gk_FreeMem only releases a record whose requested size matches,
// so a rewritten field leaves the block live instead of releasing a stranger's
// memory - the same outcome the vendor's MemFree size check produces.
//
// Order: unlink from the host list first (the guest EA becomes invalid the
// moment FreeMem returns, so no list may still point at it), then release, then
// clear the slot. The slot lookup is keyed on `used`, which the memset clears,
// so a second FreeContextInfo on the same EA finds nothing and does not free a
// second time. PurgeContextInfo's guest callback reaches this same routine
// through #16, which is what keeps the purge path and the explicit free path
// from releasing twice.
static void gk_iff_free_info(uint32_t ea) {
    int32_t idx = gk_iff_info_by_ea(ea);
    if (idx < 0) return;                 // `if (ci)` + not ours: already freed
    gk_iff_info *ci = &g_iff_infos[idx];
    const uint32_t block_ea = ci->ea;
    PPCContext *cpu = gk_current_memory_cpu();
    uint64_t total = 0;
    if (cpu && cpu->mem) {
        const uint64_t data_size =
            ((uint64_t)rd32(cpu, block_ea + 8u) << 32) |
            (uint64_t)rd32(cpu, block_ea + 12u);
        total = (uint64_t)GK_IFF_CI_SIZE + data_size;
    } else {
        total = (uint64_t)GK_IFF_CI_SIZE + ci->data_size;
    }
    gk_iff_detach_info(ci);
    // FreeMem's size argument is a signed 32-bit int; a block larger than that
    // cannot have been requested by the 32-bit AllocContextInfo either.
    if (total <= (uint64_t)INT32_MAX) {
        gk_FreeMem((void *)(uintptr_t)block_ea, (int32_t)total);
    }
    memset(&g_iff_infos[idx], 0, sizeof(g_iff_infos[idx]));
    g_iff_infos[idx].state = -1;
    g_iff_infos[idx].node = -1;
    g_iff_infos[idx].next = -1;
}

// iff:25 RemoveContextInfo(ContextInfo *ci) — M2 SDK src/folios/iff/iff.c:1563:
//
//   void RemoveContextInfo(ContextInfo *ci) {
//       if (ci->ci.n_Next) { RemNode((Node *)ci); ci->ci.n_Next = NULL; }
//   }
//
// Unlink ONLY. The structure stays allocated and the caller still owns the
// free: FindContextInfo does not return it (its list membership is gone)
// while FreeContextInfo (#16) remains the owner of the release. The `if`
// guard makes a structure that is not in a list a NOP, which is what an
// already-unlinked or freshly-allocated ContextInfo is. The source's
// `ci->ci.n_Next = NULL` writes the guest-visible Node link word at ci+0; this
// host does not model those link words (gk_iff_alloc_info zeroes them once
// and no attach/detach path updates them, exactly as gk_iff_free_info
// assumes), so list membership is tracked in the host table only and the
// redundant guest write is omitted.
static void gk_iff_remove_info(uint32_t ea) {
    int32_t idx = gk_iff_info_by_ea(ea);
    if (idx < 0) return;                 // unknown EA: nothing is in a list
    gk_iff_info *ci = &g_iff_infos[idx];
    if (ci->state < 0 || ci->node < 0) return;   // `if (ci->ci.n_Next)` NOP
    gk_iff_detach_info(ci);
}

static int32_t gk_iff_invoke_guest(uint32_t fn_ea, uint32_t a3, uint32_t a4) {
    if (fn_ea == 0 || !gk_bound()) return GK_IFF_ERR_BADPTR;
    RecompFn fn = gk_lookup_callback(fn_ea);
    if (!fn) return GK_IFF_ERR_BADPTR;
    PPCContext *cpu = gk_current_memory_cpu();
    cpu->gpr[3] = a3;
    cpu->gpr[4] = a4;
    fn(cpu);
    return (int32_t)cpu->gpr[3];
}

// PurgeContextInfo: run the guest purge callback when one is installed,
// otherwise FreeContextInfo (iff.c).  The callback is responsible for
// releasing the ContextInfo itself (PurgeDataChunk calls #16).
static void gk_iff_purge_info(int32_t idx) {
    if (idx < 0 || !g_iff_infos[idx].used) return;
    gk_iff_info *ci = &g_iff_infos[idx];
    uint32_t parser_ea = (ci->state >= 0) ? g_iff_states[ci->state].parser_ea : 0;
    uint32_t ci_ea = ci->ea;
    uint32_t cb = ci->purge_cb;
    gk_iff_detach_info(ci);
    if (cb != 0) {
        (void)gk_iff_invoke_guest(cb, parser_ea, ci_ea);
    } else {
        gk_iff_free_info(ci_ea);
    }
}

static uint32_t gk_iff_alloc_info(uint32_t type, uint32_t id, uint32_t ident,
                                  uint32_t data_size, uint32_t purge_cb,
                                  uint8_t kind) {
    if (!gk_bound()) return 0;
    if (data_size > UINT32_MAX - GK_IFF_CI_SIZE) return 0;
    int32_t idx = -1;
    for (uint32_t i = 0; i < GK_IFF_MAX_INFO; ++i) {
        if (!g_iff_infos[i].used) { idx = (int32_t)i; break; }
    }
    if (idx < 0) return 0;
    void *p = gk_heap_alloc(GK_IFF_CI_SIZE + data_size, "iff_context_info");
    if (!p) return 0;
    uint32_t ea = (uint32_t)(uintptr_t)p;
    gk_iff_info *ci = &g_iff_infos[idx];
    memset(ci, 0, sizeof(*ci));
    ci->used = 1;
    ci->kind = kind;
    ci->state = -1;
    ci->node = -1;
    ci->next = -1;
    ci->ea = ea;
    ci->type = type;
    ci->id = id;
    ci->ident = ident;
    ci->data_ea = ea + GK_IFF_CI_SIZE;
    ci->data_size = data_size;
    ci->purge_cb = purge_cb;
    PPCContext *cpu = g_gk.cpu;
    wr32(cpu, ea + 0u, 0u);
    wr32(cpu, ea + 4u, 0u);
    wr32(cpu, ea + 8u, 0u);
    wr32(cpu, ea + 12u, data_size);
    wr32(cpu, ea + 16u, ci->data_ea);
    wr32(cpu, ea + 20u, id);
    wr32(cpu, ea + 24u, type);
    wr32(cpu, ea + 28u, ident);
    wr32(cpu, ea + 32u, purge_cb);
    return ea;
}

static int32_t gk_iff_find_info(const gk_iff_state *s, uint32_t type, uint32_t id,
                                uint32_t ident) {
    if (!s) return -1;
    for (int32_t node = (int32_t)s->depth - 1; node >= 0; --node) {
        for (int32_t cur = s->nodes[node].info_head; cur >= 0;
             cur = g_iff_infos[cur].next) {
            if (g_iff_infos[cur].type == type && g_iff_infos[cur].id == id &&
                g_iff_infos[cur].ident == ident)
                return cur;
        }
    }
    return -1;
}

// AttachContextInfo: purge any duplicate identity in the target context and
// link the new info at its head.
static void gk_iff_attach_info(gk_iff_state *s, int32_t node_idx, int32_t ci_idx) {
    if (!s || node_idx < 0 || ci_idx < 0) return;
    gk_iff_node *n = &s->nodes[node_idx];
    gk_iff_info *add = &g_iff_infos[ci_idx];
    int32_t prev = -1, cur = n->info_head;
    while (cur >= 0) {
        gk_iff_info *ci = &g_iff_infos[cur];
        int32_t next = ci->next;
        if (ci->ident == add->ident && ci->id == add->id && ci->type == add->type) {
            if (prev < 0) n->info_head = next;
            else g_iff_infos[prev].next = next;
            // Already unlinked above; keep owner state so the guest purge
            // callback still receives the parser EA, then purge/free.
            ci->next = -1;
            gk_iff_purge_info(cur);
            break;
        }
        prev = cur;
        cur = next;
    }
    add->state = gk_iff_state_index(s);
    add->node = node_idx;
    add->next = n->info_head;
    n->info_head = ci_idx;
}

// FindPropContext: topmost FORM or LIST below the current context (iff.c).
static int32_t gk_iff_prop_node(const gk_iff_state *s) {
    if (!s) return -1;
    for (int32_t node = (int32_t)s->depth - 2; node >= 1; --node) {
        uint32_t id = s->nodes[node].id;
        if (id == GK_IFF_ID_FORM || id == GK_IFF_ID_LIST) return node;
    }
    return -1;
}

static int32_t gk_iff_store_context_info(gk_iff_state *s, uint32_t ci_ea,
                                         uint32_t pos) {
    int32_t idx = gk_iff_info_by_ea(ci_ea);
    if (idx < 0) return GK_IFF_ERR_BADPTR;
    int32_t node;
    switch (pos) {
    case 0:  // IFF_CIL_BOTTOM: default (master) context
        node = 0;
        break;
    case 1:  // IFF_CIL_TOP: current context
        node = (int32_t)s->depth - 1;
        break;
    case 2:  // IFF_CIL_PROP: topmost FORM or LIST
        node = gk_iff_prop_node(s);
        if (node < 0) return GK_IFF_ERR_NOSCOPE;
        break;
    default:
        return GK_IFF_ERR_BADLOCATION;
    }
    gk_iff_attach_info(s, node, idx);
    return 0;
}

// ---- chunk data IO -----------------------------------------------------------

static int32_t gk_iff_clamp_chunk_read(gk_iff_state *s, uint32_t *num_bytes) {
    gk_iff_node *top = gk_iff_current_node(s);
    if (!top) return GK_IFF_PARSE_EOF;
    // iff.c declares maxBytes as uint32, truncating the 64-bit difference.
    uint32_t max_bytes = (uint32_t)(top->size - top->offset);
    if (*num_bytes > max_bytes) *num_bytes = max_bytes;
    return 0;
}

static int32_t gk_iff_read_chunk_raw(gk_iff_state *s, void *dst, uint32_t num_bytes) {
    uint32_t want = num_bytes;
    int32_t err = gk_iff_clamp_chunk_read(s, &want);
    if (err < 0) return err;
    int32_t result = gk_iff_read_raw(s, dst, want);
    if (result != (int32_t)want) {
        if (result >= 0) result = GK_IFF_ERR_PREMATURE_EOF;
    } else {
        gk_iff_node *top = gk_iff_current_node(s);
        top->offset += (uint32_t)result;
        gk_iff_sync_node(top);
    }
    return result;
}

static int32_t gk_iff_read_chunk_guest(gk_iff_state *s, uint32_t buf_ea,
                                       uint32_t num_bytes) {
    uint32_t want = num_bytes;
    int32_t err = gk_iff_clamp_chunk_read(s, &want);
    if (err < 0) return err;
    if (want != 0 &&
        (buf_ea == 0 || buf_ea > RECOMP_GUEST_MEM || want > RECOMP_GUEST_MEM - buf_ea))
        return GK_IFF_ERR_BADPTR;
    return gk_iff_read_chunk_raw(s, g_gk.cpu->mem + buf_ea, num_bytes);
}

// BufferChunk: read exactly size bytes into a guest buffer, 0 on success.
static int32_t gk_iff_buffer_chunk(gk_iff_state *s, uint32_t buf_ea,
                                   uint32_t size) {
    int32_t result = gk_iff_read_chunk_raw(s, g_gk.cpu->mem + buf_ea, size);
    if (result != (int32_t)size) {
        if (result >= 0) result = GK_IFF_ERR_PREMATURE_EOF;
        return result;
    }
    return 0;
}

// SeekChunk (iff.c): clip position to the current chunk and move the stream.
static int32_t gk_iff_seek_chunk(gk_iff_state *s, int32_t position, int32_t mode) {
    gk_iff_node *top = gk_iff_current_node(s);
    if (!top) return GK_IFF_PARSE_EOF;
    uint64_t base;
    switch (mode) {
    case 0: base = 0; break;
    case 1: base = top->offset; break;
    case 2: base = top->size; break;
    default: return GK_IFF_ERR_BADMODE;
    }
    uint64_t new_offset;
    if (position >= 0) {
        uint64_t pos = (uint32_t)position;
        if (pos < top->size - base) new_offset = base + pos;
        else new_offset = top->size;
    } else {
        uint64_t pos = (uint64_t)(-(int64_t)position);
        if (pos < base) new_offset = base - pos;
        else new_offset = 0;
    }
    int32_t seek_offset = (int32_t)(new_offset - top->offset);
    int32_t old_pos = gk_iff_seek_raw(s, seek_offset);
    if (old_pos < 0) return old_pos;
    int32_t new_pos = gk_iff_seek_raw(s, 0);
    if (new_pos < 0) return new_pos;
    if (new_pos - old_pos != seek_offset) return GK_IFF_ERR_PREMATURE_EOF;
    top->offset = new_offset;
    gk_iff_sync_node(top);
    return 0;
}

// ---- parse engine ------------------------------------------------------------

static int32_t gk_iff_free_top_node(gk_iff_state *s) {
    if (!s || s->depth < 2u) return GK_IFF_PARSE_EOF;
    gk_iff_node *n = &s->nodes[s->depth - 1u];
    int32_t cur = n->info_head;
    while (cur >= 0) {
        int32_t next = g_iff_infos[cur].next;
        gk_iff_detach_info(&g_iff_infos[cur]);
        gk_iff_purge_info(cur);
        cur = next;
    }
    memset(n, 0, sizeof(*n));
    s->depth--;
    return 0;
}

// PushChunkR: read the next chunk header and push its context.
static int32_t gk_iff_push_chunk_r(gk_iff_state *s, int first_chunk) {
    gk_iff_node *top = gk_iff_current_node(s);
    if (!top && !first_chunk) return GK_IFF_PARSE_EOF;
    uint32_t type = top ? top->type : 0u;
    uint8_t hdr[8];
    uint32_t id;
    uint64_t size;
    if (first_chunk) {
        int32_t err = gk_iff_read_raw(s, hdr, 8u);
        if (err != 8) return err >= 0 ? GK_IFF_ERR_NOTIFF : err;
        id = gk_iff_be32(hdr);
        size = gk_iff_be32(hdr + 4u);
        if (size == GK_IFF_SIZE_64BIT) {
            uint8_t ext[8];
            err = gk_iff_read_raw(s, ext, 8u);
            if (err != 8) return err >= 0 ? GK_IFF_ERR_NOTIFF : err;
            size = ((uint64_t)gk_iff_be32(ext) << 32) | gk_iff_be32(ext + 4u);
        } else if ((uint32_t)size >= GK_IFF_SIZE_RESERVED) {
            return GK_IFF_ERR_MANGLED;
        }
    } else {
        int32_t err = gk_iff_read_chunk_raw(s, hdr, 8u);
        if (err != 8) return err >= 0 ? GK_IFF_ERR_PREMATURE_EOF : err;
        id = gk_iff_be32(hdr);
        size = gk_iff_be32(hdr + 4u);
        if (size == GK_IFF_SIZE_64BIT) {
            uint8_t ext[8];
            err = gk_iff_read_chunk_raw(s, ext, 8u);
            if (err != 8) return err >= 0 ? GK_IFF_ERR_PREMATURE_EOF : err;
            size = ((uint64_t)gk_iff_be32(ext) << 32) | gk_iff_be32(ext + 4u);
        } else if ((uint32_t)size >= GK_IFF_SIZE_RESERVED) {
            return GK_IFF_ERR_MANGLED;
        }
        if (size > top->size - top->offset) return GK_IFF_ERR_MANGLED;
    }
    if (!gk_iff_good_id(id)) {
        return s->new_io ? GK_IFF_ERR_NOTIFF : GK_IFF_ERR_SYNTAX;
    }
    if (s->depth >= GK_IFF_MAX_DEPTH) return GK_IFF_ERR_NOMEM;
    void *rec = gk_heap_alloc(GK_IFF_CN_SIZE, "iff_context_node");
    if (!rec) return GK_IFF_ERR_NOMEM;
    gk_iff_node *n = &s->nodes[s->depth];
    memset(n, 0, sizeof(*n));
    n->used = 1;
    n->ea = (uint32_t)(uintptr_t)rec;
    n->type = type;
    n->id = id;
    n->size = size;
    n->offset = 0;
    n->current_size = size;
    n->info_head = -1;
    s->depth++;
    gk_iff_sync_node(n);
    return 0;
}

// PopChunkR: skip unread bytes, free the top context and its local infos.
static int32_t gk_iff_pop_chunk_r(gk_iff_state *s) {
    gk_iff_node *top = gk_iff_current_node(s);
    if (!top) return GK_IFF_PARSE_EOF;
    uint64_t rsize = (top->size + 1u) & ~(uint64_t)1u;
    if (top->offset < rsize) {
        int32_t err = gk_iff_seek_raw(s, (int32_t)(rsize - top->offset));
        if (err < 0) return err;
    }
    gk_iff_free_top_node(s);
    gk_iff_node *n = gk_iff_current_node(s);
    if (n) {
        n->offset += rsize;
        gk_iff_sync_node(n);
    }
    return 0;
}

// ReadGenericType: read the 4-byte container type into the current context.
static int32_t gk_iff_read_generic_type(gk_iff_state *s) {
    gk_iff_node *top = gk_iff_current_node(s);
    if (!top) return GK_IFF_PARSE_EOF;
    uint8_t word[4];
    int32_t result = gk_iff_read_chunk_raw(s, word, 4u);
    if (result == 4) {
        top->type = gk_iff_be32(word);
        gk_iff_sync_node(top);
        if (gk_iff_good_type(top->type)) return 0;
        return GK_IFF_ERR_MANGLED;
    }
    if (result >= 0) result = GK_IFF_ERR_PREMATURE_EOF;
    return result;
}

// HandlePropertyChunk (iff.c): materialize the chunk into a PropChunk
// ContextInfo stored in the topmost FORM/LIST context.
static int32_t gk_iff_handle_property(gk_iff_state *s) {
    gk_iff_node *top = gk_iff_current_node(s);
    if (!top) return GK_IFF_PARSE_EOF;
    if (top->size > (uint64_t)(UINT32_MAX - GK_IFF_PROPCHUNK_SIZE))
        return GK_IFF_ERR_TOOBIG;
    uint32_t size = (uint32_t)top->size;
    uint32_t ci_ea = gk_iff_alloc_info(top->type, top->id, GK_IFF_ID_PROPCHUNK,
                                       size + GK_IFF_PROPCHUNK_SIZE, 0u,
                                       GK_IFF_KIND_PROPERTY);
    if (!ci_ea) return GK_IFF_ERR_NOMEM;
    int32_t idx = gk_iff_info_by_ea(ci_ea);
    uint32_t data_ea = g_iff_infos[idx].data_ea;
    PPCContext *cpu = g_gk.cpu;
    wr32(cpu, data_ea + 0u, 0u);
    wr32(cpu, data_ea + 4u, size);
    wr32(cpu, data_ea + 8u, data_ea + GK_IFF_PROPCHUNK_SIZE);
    int32_t err = gk_iff_buffer_chunk(s, data_ea + GK_IFF_PROPCHUNK_SIZE, size);
    if (err >= 0) err = gk_iff_store_context_info(s, ci_ea, 2u);
    if (err < 0) gk_iff_free_info(ci_ea);
    return err >= 0 ? 1 : err;
}

// NextState (iff.c): advance one complete chunk-context transition.
static int32_t gk_iff_next_state(gk_iff_state *s) {
    gk_iff_node *top;
    if (s->new_io) {
        int32_t err = gk_iff_push_chunk_r(s, 1);
        s->new_io = 0;
        s->paused = 0;
        if (err < 0) return err;
        top = gk_iff_current_node(s);
        if (top->id != GK_IFF_ID_FORM && top->id != GK_IFF_ID_CAT &&
            top->id != GK_IFF_ID_LIST && !gk_iff_is_container_id(top->id))
            return GK_IFF_ERR_NOTIFF;
        if (top->size & 1u) return GK_IFF_ERR_MANGLED;
        return gk_iff_read_generic_type(s);
    }
    if (s->paused) {
        int32_t err = gk_iff_pop_chunk_r(s);
        if (err < 0) return err;
        s->paused = 0;
    }
    top = gk_iff_current_node(s);
    if (!top) return GK_IFF_PARSE_EOF;
    uint32_t topid = top->id;
    if (gk_iff_is_generic_id(topid) || gk_iff_is_container_id(topid)) {
        if (top->offset < top->size) {
            int32_t err = gk_iff_push_chunk_r(s, 0);
            if (err < 0) return err;
            top = gk_iff_current_node(s);
            if (!gk_iff_is_generic_id(top->id)) {
                if (topid != GK_IFF_ID_FORM && topid != GK_IFF_ID_PROP &&
                    !gk_iff_is_container_id(topid))
                    return GK_IFF_ERR_SYNTAX;
                return 0;
            }
            if (top->id == GK_IFF_ID_PROP && topid != GK_IFF_ID_LIST)
                return GK_IFF_ERR_SYNTAX;
            return gk_iff_read_generic_type(s);
        } else if (top->offset != top->size) {
            return GK_IFF_ERR_MANGLED;
        }
    }
    s->paused = 1;
    return GK_IFF_PARSE_EOC;
}

// ParseIFF (iff.c): drive NextState and dispatch entry/exit handlers.
static int32_t gk_iff_parse(gk_iff_state *s, int32_t control) {
    if (control < 0 || control > 2) return GK_IFF_ERR_BADMODE;
    for (;;) {
        int32_t eoc = gk_iff_next_state(s);
        if (eoc < 0 && eoc != GK_IFF_PARSE_EOC) return eoc;
        if (control == 2) return eoc;
        gk_iff_node *top = gk_iff_current_node(s);
        if (!top) return GK_IFF_PARSE_EOF;
        int32_t ci = gk_iff_find_info(s, top->type, top->id,
                                      eoc == GK_IFF_PARSE_EOC
                                          ? GK_IFF_ID_EXITHANDLER
                                          : GK_IFF_ID_ENTRYHANDLER);
        if (ci >= 0) {
            gk_iff_info *info = &g_iff_infos[ci];
            int32_t err;
            if (info->kind == GK_IFF_KIND_PROPERTY) {
                err = gk_iff_handle_property(s);
            } else {
                err = gk_iff_invoke_guest(
                    rd32(g_gk.cpu, info->data_ea + 0u), s->parser_ea,
                    rd32(g_gk.cpu, info->data_ea + 4u));
            }
            if (err != 1) return err;
        }
        if (control == 1) return eoc;
    }
}

// InstallHandler (iff.c): create a handler ContextInfo and store it.
static int32_t gk_iff_install_handler(gk_iff_state *s, uint32_t type, uint32_t id,
                                      uint32_t ident, uint32_t pos, uint32_t cb_ea,
                                      uint32_t userdata, uint8_t kind) {
    uint32_t ci_ea = gk_iff_alloc_info(type, id, ident, 8u, 0u, kind);
    if (!ci_ea) return GK_IFF_ERR_NOMEM;
    int32_t idx = gk_iff_info_by_ea(ci_ea);
    wr32(g_gk.cpu, g_iff_infos[idx].data_ea + 0u, cb_ea);
    wr32(g_gk.cpu, g_iff_infos[idx].data_ea + 4u, userdata);
    int32_t err = gk_iff_store_context_info(s, ci_ea, pos);
    if (err < 0) gk_iff_free_info(ci_ea);
    return err;
}

// RegisterPropChunks (iff.c): install HandlePropertyChunk for every
// {Type,ID} pair in the guest IFFTypeID array terminated by Type==0.
static int32_t gk_iff_register_prop_chunks(gk_iff_state *s, uint32_t typeids_ea) {
    if (typeids_ea == 0 || typeids_ea > RECOMP_GUEST_MEM - 8u)
        return GK_IFF_ERR_BADPTR;
    for (uint32_t i = 0; i < GK_IFF_MAX_PROP_TYPES; ++i) {
        uint32_t ea = typeids_ea + i * 8u;
        if (ea > RECOMP_GUEST_MEM - 8u) return GK_IFF_ERR_BADPTR;
        uint32_t type = rd32(g_gk.cpu, ea);
        uint32_t id = rd32(g_gk.cpu, ea + 4u);
        if (type == 0u) return 0;
        int32_t err = gk_iff_install_handler(s, type, id, GK_IFF_ID_ENTRYHANDLER,
                                             1u, 0u, 0u, GK_IFF_KIND_PROPERTY);
        if (err < 0) return err;
    }
    return 0;
}

// ---- parser lifecycle --------------------------------------------------------

static int32_t gk_iff_load_prefix(gk_iff_state *s) {
    if (!m2_host_raw_read) return -1;
    uint32_t cap = s->file_size < GK_IFF_PREFIX_CAP ? s->file_size
                                                    : GK_IFF_PREFIX_CAP;
    if (cap == 0) return 0;
    uint8_t *buf = (uint8_t *)malloc(cap);
    if (!buf) return -1;
    uint32_t done = 0;
    while (done < cap) {
        int32_t got = m2_host_raw_read(s->host_token, buf + done, cap - done);
        if (got <= 0 || (uint32_t)got > cap - done) {
            free(buf);
            return -1;
        }
        done += (uint32_t)got;
    }
    s->prefix = buf;
    s->prefix_size = cap;
    return 0;
}

static int32_t gk_iff_create(PPCContext *cpu, uint32_t out_ea, uint32_t write_mode,
                             uint32_t tag, uint32_t file_name_ea,
                             uint32_t terminator) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem || out_ea == 0 ||
        out_ea > RECOMP_GUEST_MEM - 4u)
        return GK_IFF_ERR_BADPTR;
    // Write mode has no `driving/game` call sites; the read engine above is
    // the source-backed contract in use.
    if (write_mode != 0u) return GK_IFF_ERR_NOTSUPPORTED;
    if (tag != GK_IFF_TAG_FILE || terminator != 0u) return GK_IFF_ERR_BADPTR;
    if (!m2_host_raw_open || !m2_host_raw_size) return GK_IFF_ERR_NOTSUPPORTED;

    gk_iff_state *s = NULL;
    for (uint32_t i = 0; i < GK_IFF_MAX_PARSERS; ++i) {
        if (!g_iff_states[i].used) { s = &g_iff_states[i]; break; }
    }
    if (!s) return GK_IFF_ERR_NOMEM;
    memset(s, 0, sizeof(*s));
    s->nodes[0].info_head = -1;
    if (m2m_copy_guest_string_ctx(cpu, file_name_ea, s->file_name,
                                  sizeof(s->file_name)) < 0)
        return GK_IFF_ERR_BADPTR;

    uint32_t token = m2_host_raw_open(s->file_name);
    if (token == 0) return GK_IFF_ERR_HOST_OPEN;
    s->host_token = token;
    s->file_size = m2_host_raw_size(token);
    s->stream_pos = 0;
    s->new_io = 1;
    s->depth = 1;
    s->nodes[0].used = 1;
    s->nodes[0].is_master = 1;
    s->nodes[0].id = 0;
    s->nodes[0].info_head = -1;

    if (!(m2_host_raw_read_at_present && m2_host_raw_read_at) &&
        gk_iff_load_prefix(s) != 0) {
        if (m2_host_raw_close) m2_host_raw_close(token);
        memset(s, 0, sizeof(*s));
        return GK_IFF_ERR_HOST_OPEN;
    }
    void *parser = gk_heap_alloc(16u, "iff_parser");
    void *master = gk_heap_alloc(GK_IFF_CN_SIZE, "iff_master_context");
    if (!parser || !master) {
        free(s->prefix);
        if (m2_host_raw_close) m2_host_raw_close(token);
        memset(s, 0, sizeof(*s));
        return GK_IFF_ERR_NOMEM;
    }
    s->nodes[0].ea = (uint32_t)(uintptr_t)master;
    s->parser_ea = (uint32_t)(uintptr_t)parser;
    gk_iff_sync_node(&s->nodes[0]);
    s->used = 1;
    wr32(cpu, out_ea, s->parser_ea);
    return 0;
}

static int32_t gk_iff_delete(gk_iff_state *s) {
    int32_t result = 0;
    while (gk_iff_current_node(s)) {
        result = gk_iff_pop_chunk_r(s);
        if (result < 0) {
            while (gk_iff_current_node(s)) gk_iff_free_top_node(s);
        }
    }
    int32_t cur = s->nodes[0].info_head;
    while (cur >= 0) {
        int32_t next = g_iff_infos[cur].next;
        gk_iff_detach_info(&g_iff_infos[cur]);
        gk_iff_purge_info(cur);
        cur = next;
    }
    s->nodes[0].info_head = -1;
    if (s->host_token && m2_host_raw_close) m2_host_raw_close(s->host_token);
    free(s->prefix);
    memset(s, 0, sizeof(*s));
    return result;
}

static int recomp_call_iff_dispatch_impl(PPCContext *c, uint32_t ordinal,
                                         uint32_t pc) {
    (void)pc;
    if (!c) return 0;

    switch (ordinal) {
    case 1: {  // DeleteIFFParser(iff)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        c->gpr[3] = s ? (uint32_t)gk_iff_delete(s)
                      : (uint32_t)GK_IFF_ERR_BADPTR;
        return 1;
    }
    case 2: {  // ParseIFF(iff, control)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        int32_t rc = s ? gk_iff_parse(s, (int32_t)c->gpr[4])
                       : GK_IFF_ERR_BADPTR;
        // Bounded audio-path diagnostic (M2_AUDIO_START_DIAG): preserves the
        // old narrow parser's [audio-iff] path/rc observability.
        if (gk_audio_start_diag_enabled()) {
            static uint32_t parse_count;
            if (parse_count < 32u) {
                fprintf(stderr, "[audio-iff] path='%s' mode=%u rc=%d\n",
                        s ? s->file_name : "", c->gpr[4], rc);
                ++parse_count;
            }
        }
        c->gpr[3] = (uint32_t)rc;
        return 1;
    }
    case 3: {  // ReadChunk(iff, buffer, numBytes)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        c->gpr[3] = s ? (uint32_t)gk_iff_read_chunk_guest(s, c->gpr[4], c->gpr[5])
                      : (uint32_t)GK_IFF_ERR_BADPTR;
        return 1;
    }
    case 7: {  // RegisterPropChunks(iff, typeids)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        c->gpr[3] = s ? (uint32_t)gk_iff_register_prop_chunks(s, c->gpr[4])
                      : (uint32_t)GK_IFF_ERR_BADPTR;
        return 1;
    }
    case 10: {  // FindPropChunk(iff, type, id)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        uint32_t result = 0;
        if (s) {
            int32_t idx = gk_iff_find_info(s, c->gpr[4], c->gpr[5],
                                           GK_IFF_ID_PROPCHUNK);
            if (idx >= 0) result = g_iff_infos[idx].data_ea;
        }
        c->gpr[3] = result;
        return 1;
    }
    case 13: {  // GetCurrentContext(iff)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        gk_iff_node *top = gk_iff_current_node(s);
        c->gpr[3] = top ? top->ea : 0u;
        return 1;
    }
    case 15: {  // AllocContextInfo(type, id, ident, dataSize, purgeCB)
        c->gpr[3] = gk_iff_alloc_info(c->gpr[3], c->gpr[4], c->gpr[5],
                                      c->gpr[6], c->gpr[7], GK_IFF_KIND_GUEST);
        return 1;
    }
    case 16: {  // FreeContextInfo(ci)
        gk_iff_free_info(c->gpr[3]);
        c->gpr[3] = 0u;
        return 1;
    }
    case 17: {  // FindContextInfo(iff, type, id, ident)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        uint32_t result = 0;
        if (s) {
            int32_t idx = gk_iff_find_info(s, c->gpr[4], c->gpr[5], c->gpr[6]);
            if (idx >= 0) result = g_iff_infos[idx].ea;
        }
        c->gpr[3] = result;
        return 1;
    }
    case 25: {  // RemoveContextInfo(ci) — unlink only, no free (iff.c:1563)
        gk_iff_remove_info(c->gpr[3]);
        c->gpr[3] = 0u;
        return 1;
    }
    case 18: {  // StoreContextInfo(iff, ci, location)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        c->gpr[3] = s ? (uint32_t)gk_iff_store_context_info(s, c->gpr[4],
                                                            c->gpr[5])
                      : (uint32_t)GK_IFF_ERR_BADPTR;
        return 1;
    }
    case 20:  // InstallEntryHandler(iff, type, id, location, cb, userData)
    case 21: {  // InstallExitHandler(iff, type, id, location, cb, userData)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        if (!s) {
            c->gpr[3] = (uint32_t)GK_IFF_ERR_BADPTR;
            return 1;
        }
        uint32_t ident = ordinal == 20u ? GK_IFF_ID_ENTRYHANDLER
                                        : GK_IFF_ID_EXITHANDLER;
        c->gpr[3] = (uint32_t)gk_iff_install_handler(
            s, c->gpr[4], c->gpr[5], ident, c->gpr[6], c->gpr[7], c->gpr[8],
            GK_IFF_KIND_GUEST);
        return 1;
    }
    case 22: {  // SeekChunk(iff, position, mode)
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        c->gpr[3] = s ? (uint32_t)gk_iff_seek_chunk(s, (int32_t)c->gpr[4],
                                                    (int32_t)c->gpr[5])
                      : (uint32_t)GK_IFF_ERR_BADPTR;
        return 1;
    }
    case 23: {  // GetIFFOffset(iff) -> int64 in r3:r4
        gk_iff_state *s = gk_iff_find(c->gpr[3]);
        uint64_t offset = s ? s->stream_pos : 0u;
        c->gpr[3] = (uint32_t)(offset >> 32);
        c->gpr[4] = (uint32_t)offset;
        return 1;
    }
    case 24:  // CreateIFFParserVA(&iff, writeMode, IFF_TAG_FILE, file, TAG_END)
        c->gpr[3] = (uint32_t)gk_iff_create(c, c->gpr[3], c->gpr[4], c->gpr[5],
                                            c->gpr[6], c->gpr[7]);
        return 1;
    default:
        return 0;
    }
}

// Public entry point; see the filesystem dispatch wrapper
// (selector_observed.h).
int recomp_call_iff_dispatch(PPCContext *c, uint32_t ordinal, uint32_t pc) {
    // Entry/exit/purge handlers execute synchronously on the calling task's
    // PPC registers and stack, with shared RAM; never on the boot context.
    PPCContext *previous_cpu = g_gk_active_cpu;
    g_gk_active_cpu = c;
    const int handled = recomp_call_iff_dispatch_impl(c, ordinal, pc);
    g_gk_active_cpu = previous_cpu;
    m2_selector_note(M2_FOLIO_IFF, ordinal, handled);
    return handled;
}

// ---- StateDriver window (kernel 17/163) -------------------------------------
// Generated-evidence semantics only (see m2fn_ScavengeMem_t / m2fn_FindItem_t
// in recomp_helpers.h): no backing store or record layout is established for
// this slice, so both handlers stay pointer-free.

static int32_t gk_IsMasterCPU(void) {
    // kernel:105 IsMasterCPU — no args, pure predicate over the source's CPU id
    // (cpu.s: mfsr r3,SR14; cmpwi r3,0; master id 0 => 1, else 0). The host
    // models the master CPU of the M2's dual-CPU pair, so SR14 reads
    // M2_MODEL_CPU_SR14 and the predicate answers 1. All 4 generated windows
    // pass zero regs and cmpwi r3,0 with no guest-RAM traffic.
    (void)gk_bound();
    return m2_cpu_sr14_is_master(M2_MODEL_CPU_SR14);
}

static int32_t gk_ScavengeMem(uint32_t arg) {
    (void)arg;   // no source argument; dispatch's incoming word is ignored
    if (!gk_bound()) return M2K_ERR_BAD_ITEM;
    uint32_t released_pages = 0u;
    pthread_mutex_lock(&gk_heap_lock);
    for (uint32_t page = 0; page < GK_HEAP_PAGE_COUNT; ++page) {
        if (g_gk.heap_owned_pages[page] == 0u) continue;
        const uint32_t page_start = GK_HEAP_BASE + page * GK_HEAP_PAGE_SIZE;
        const uint32_t page_end = page_start + GK_HEAP_PAGE_SIZE;
        int live = 0;
        for (uint32_t i = 0; i < g_gk.heap_block_count; ++i) {
            const gk_heap_block *block = &g_gk.heap_blocks[i];
            if (block->ea < page_end && page_start < block->ea + block->size) {
                live = 1;
                break;
            }
        }
        if (!live) {
            g_gk.heap_owned_pages[page] = 0u;
            ++released_pages;
        }
    }
    pthread_mutex_unlock(&gk_heap_lock);
    return (int32_t)(released_pages * GK_HEAP_PAGE_SIZE);
}

// GetCacheInfo per kernel/cache.h: void GetCacheInfo(CacheInfo *info, uint32 infoSize)
// CacheInfo is 7 x uint32 (28 bytes): Flags, ICacheSize, ICacheLineSize, ICacheSetSize, DCacheSize, DCacheLineSize, DCacheSetSize.
// All 4 sites (GS_Create 0x1b45c, M_Init 0x5f62c/0x5f96c, etc.) call with info_ea = r1+8 (stack carve) and info_size = 28 (0x1c), so handler must fill with bounded wr32 BE and handle null/OOB/malformed size.
// Spinlock.c uses DCacheLineSize (offset 20) to round AllocMemAligned, so that field must be 32 (PPC602 line size) for correct allocation.
static void gk_GetCacheInfo(uint32_t info_ea, uint32_t info_size) {
    if (!gk_bound() || info_ea == 0 || info_size == 0) return;
    // Bounds: info_ea must be within guest RAM for the requested size; if not, log and fail closed (no write).
    if (info_ea + 4 > RECOMP_GUEST_MEM || !g_gk.cpu || !g_gk.cpu->mem) {
        fprintf(stderr, "[gk] GetCacheInfo fault: info_ea=%#x size=%u OOB\n", info_ea, info_size);
        return;
    }
    // Truncate to struct size (28) and to guest RAM.
    uint32_t max_write = info_size < 28u ? info_size : 28u;
    if (info_ea + max_write > RECOMP_GUEST_MEM) max_write = RECOMP_GUEST_MEM - info_ea;
    // Plausible PPC602 values — match kernel/cache.h CacheInfo layout and spinlock expectation.
    const uint32_t flags = (1u << 1) | (1u << 3); // CACHE_INSTR_ENABLED | CACHE_DATA_ENABLED
    const uint32_t vals[7] = {
        flags,          // cinfo_Flags
        8192u,          // cinfo_ICacheSize
        32u,            // cinfo_ICacheLineSize
        2u,             // cinfo_ICacheSetSize
        8192u,          // cinfo_DCacheSize
        32u,            // cinfo_DCacheLineSize — critical for AllocMemAligned
        2u              // cinfo_DCacheSetSize
    };
    for (uint32_t i = 0; i < 7; ++i) {
        uint32_t off = i * 4u;
        if (off + 4u > max_write) break;
        wr32(g_gk.cpu, info_ea + off, vals[i]);
    }
    // Throttled log for boot-trace diagnosis (first 4 calls)
    {
        static int _gci_cnt = 0;
        if (_gci_cnt < 4) {
            fprintf(stderr, "[gk] GetCacheInfo info_ea=%#x size=%u -> filled CacheInfo (DLine=32)\n", info_ea, info_size);
            _gci_cnt++;
        }
    }
}

