static uint32_t gk_mint_item(const char *kind, uint32_t ctype,
                             uint32_t name_ea, uint32_t tag_count,
                             int remember_as_generic) {
    GK_AUDIO_GRAPH_GUARD();
    if (!gk_bound() || ctype == 0) return M2K_ITEM_NONE;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        if (g_gk.items[i].used) continue;
        memset(&g_gk.items[i], 0, sizeof(g_gk.items[i]));
        g_gk.items[i].used = 1;
        g_gk.items[i].generation = gk_next_item_generation();
        g_gk.items[i].ctype = ctype;
        g_gk.items[i].name_ea = name_ea;
        g_gk.items[i].tag_count = tag_count;
        g_gk.items[i].template_item = 0;
        g_gk.items[i].calc_rate_divider = 0;
        g_gk.items[i].priority = 0;
        g_gk.items[i].mixer_spec = 0;
        if (ctype == GK_AUDIO_SAMPLE_CTYPE) {
            g_gk.items[i].sample_rate = 44100.0f;
            g_gk.items[i].sample_channels = 1u;
            g_gk.items[i].sample_bits = 16u;
            g_gk.items[i].sample_compression_ratio = 1u;
            g_gk.items[i].sample_sustain_begin = -1;
            g_gk.items[i].sample_sustain_end = -1;
            g_gk.items[i].sample_release_begin = -1;
            g_gk.items[i].sample_release_end = -1;
            g_gk.items[i].sample_low_note = 0;
            g_gk.items[i].sample_high_note = 127;
            g_gk.items[i].sample_low_velocity = 0;
            g_gk.items[i].sample_high_velocity = 127;
        }
        if (ctype == GK_AUDIO_ENVELOPE_CTYPE) {
            g_gk.items[i].envelope_sustain_begin = -1;
            g_gk.items[i].envelope_sustain_end = -1;
            g_gk.items[i].envelope_release_begin = -1;
            g_gk.items[i].envelope_release_end = -1;
            g_gk.items[i].envelope_release_jump = -1;
            g_gk.items[i].envelope_signal_type = 0u;
        }
        g_gk.items[i].audio_start_time_scale = 1.0f;
        g_gk.items[i].audio_release_time_scale = 1.0f;
        if (ctype == GK_AUDIO_CUE_CTYPE) {
            pthread_mutex_lock(&g_audio_timer_lock);
            g_gk.items[i].cue_owner = m2k_current_task_item(g_gk.kctx);
            int32_t bit = m2k_alloc_signal(g_gk.kctx, -1);
            if (bit < 0) {
                g_gk.items[i].used = 0;
                pthread_mutex_unlock(&g_audio_timer_lock);
                return M2K_ITEM_NONE;
            }
            g_gk.items[i].cue_signal_mask = 1u << bit;
            pthread_mutex_unlock(&g_audio_timer_lock);
        }
        if (ctype == GK_AUDIO_CLOCK_CTYPE) {
            // Vendor internalCreateAudioClock (audio_timer.c:1728-1730):
            // aclk_Duration = (dspp_SampleRate / AF_DEFAULT_CLOCK_RATE) + 0.5,
            // and AF_DEFAULT_CLOCK_RATE is 44100.0/184.0 (includes/audio/
            // audio.h:144), so a fresh clock ticks every 184 sample frames.
            g_gk.items[i].clock_duration = GK_AUDIO_GLOBAL_CLOCK_DURATION;
        }
        if (ctype == GK_AUDIO_TEMPLATE_CTYPE && name_ea != 0)
            (void)gk_copy_audio_name(g_gk.cpu, name_ea,
                                     g_gk.items[i].audio_name);
        uint32_t h = gk_make_handle(GK_TYPE_ITEM_VA, i,
                                    g_gk.items[i].generation);
        if (name_ea != 0) {
            for (int j = 0; j < GK_FIND_REG; ++j) {
                if (g_find_reg[j].handle == 0) {
                    g_find_reg[j] = (typeof(g_find_reg[0])){ctype, name_ea, h};
                    break;
                }
            }
        }
        if (remember_as_generic) m2_set_last_generic_item(h);
        gk_mix_graph_touch();
        static int _item_cnt = 0;
        if (_item_cnt < 20) {
            fprintf(stderr, "[gk] %s ctype=%#x name=%#x tags=%u -> %#x\n",
                    kind ? kind : "item", ctype, name_ea, tag_count, h);
            ++_item_cnt;
        }
        return h;
    }
    fprintf(stderr, "[gk] %s OOM: ctype=%#x\n",
            kind ? kind : "item", ctype);
    return M2K_ITEM_NONE;
}

// Configure the Bitmap fields used by the recovered gstate and M_Support
// callers.  This is the source-shaped subset of graphics/bitmap.c's tag
// processor: dimensions, format, clip/origin, buffer, capability flags, and
// co-alignment.  The full graphics folio still owns validation that depends on
// a real display/device buffer, so this bridge publishes only bounded guest
// metadata and rejects malformed values.
static int gk_configure_bitmap_item(gk_item *bitmap,
                                    const uint32_t tags[][2],
                                    uint32_t tag_count) {
    if (!bitmap || bitmap->ctype != GK_GRAPHICS_BITMAP_CTYPE)
        return 0;

    uint32_t width = 320u;
    uint32_t height = 240u;
    uint32_t x_origin = 0u;
    uint32_t y_origin = 0u;
    uint32_t clip_width = width;
    uint32_t clip_height = height;
    uint32_t buffer = 0u;
    uint32_t type = GK_BMTYPE_16;
    uint32_t flags = 0u;
    uint32_t coalign_item = 0u;
    int reset_clip = 1;

    for (uint32_t i = 0; i < tag_count; ++i) {
        const uint32_t tag = tags[i][0];
        const uint32_t value = tags[i][1];
        switch (tag) {
        case M2_TAG_END:
            i = tag_count;
            break;
        case 1u: // TAG_ITEM_NAME, already validated and retained by mint
        case 2u: // TAG_ITEM_PRI
        case 3u: // TAG_ITEM_VERSION
        case 4u: // TAG_ITEM_REVISION
        case 5u: // TAG_ITEM_UNIQUE_NAME
        case 6u: // reserved item tag
        case 7u:
        case 8u:
        case 9u:
            break;
        case GK_BMTAG_WIDTH:
            width = value;
            break;
        case GK_BMTAG_HEIGHT:
            height = value;
            break;
        case GK_BMTAG_TYPE:
            type = value;
            break;
        case GK_BMTAG_CLIP_WIDTH:
            clip_width = value;
            reset_clip = 0;
            break;
        case GK_BMTAG_CLIP_HEIGHT:
            clip_height = value;
            reset_clip = 0;
            break;
        case GK_BMTAG_X_ORIGIN:
            x_origin = value;
            reset_clip = 0;
            break;
        case GK_BMTAG_Y_ORIGIN:
            y_origin = value;
            reset_clip = 0;
            break;
        case GK_BMTAG_BUFFER:
            buffer = value;
            break;
        case GK_BMTAG_DISPLAYABLE:
            if (value) flags |= GK_BMF_DISPLAYABLE;
            else flags &= ~GK_BMF_DISPLAYABLE;
            break;
        case GK_BMTAG_RENDERABLE:
            if (value) flags |= GK_BMF_RENDERABLE;
            else flags &= ~GK_BMF_RENDERABLE;
            break;
        case GK_BMTAG_MPEGABLE:
            if (value) flags |= GK_BMF_MPEGABLE;
            else flags &= ~GK_BMF_MPEGABLE;
            break;
        case GK_BMTAG_BUMPDIMS:
            if (value) flags |= GK_BMF_BUMPDIMS;
            else flags &= ~GK_BMF_BUMPDIMS;
            break;
        case GK_BMTAG_COALIGN:
            if (value != 0u) {
                gk_item *coalign = gk_live_item(value);
                if (!coalign || coalign->ctype != GK_GRAPHICS_BITMAP_CTYPE)
                    return 0;
            }
            coalign_item = value;
            break;
        case GK_BMTAG_RESET_CLIP:
            if (value) reset_clip = 1;
            break;
        default:
            return 0;
        }
    }

    if (type < GK_BMTYPE_16 || type > GK_BMTYPE_16_ZBUFFER)
        return 0;
    // The recovered Bitmap type table permits display/render/MPEG for the
    // two framebuffer formats, but a z-buffer is renderable only.
    const uint32_t allowed_flags = type == GK_BMTYPE_16_ZBUFFER
        ? GK_BMF_RENDERABLE | GK_BMF_BUMPDIMS
        : GK_BMF_DISPLAYABLE | GK_BMF_RENDERABLE |
          GK_BMF_MPEGABLE | GK_BMF_BUMPDIMS;
    if (flags & ~allowed_flags)
        return 0;

    if (reset_clip) {
        x_origin = 0u;
        y_origin = 0u;
        clip_width = width;
        clip_height = height;
    }
    if (x_origin > width || y_origin > height ||
        clip_width > width - x_origin ||
        clip_height > height - y_origin)
        return 0;

    const uint64_t pixel_size = type == GK_BMTYPE_32 ? 4u : 2u;
    const uint64_t buffer_size = (uint64_t)width * height * pixel_size;
    if (buffer_size > UINT32_MAX)
        return 0;
    if (buffer != 0u && buffer >= RECOMP_GUEST_MEM)
        return 0;

    bitmap->bitmap_width = width;
    bitmap->bitmap_height = height;
    bitmap->bitmap_x_origin = x_origin;
    bitmap->bitmap_y_origin = y_origin;
    bitmap->bitmap_clip_width = clip_width;
    bitmap->bitmap_clip_height = clip_height;
    bitmap->bitmap_buffer_size = (uint32_t)buffer_size;
    bitmap->bitmap_buf_mem_type = 0u;       // MEMTYPE_NORMAL
    bitmap->bitmap_buf_mem_care_bits = 0u;
    bitmap->bitmap_buf_mem_state_bits = 0u;
    bitmap->bitmap_buffer = buffer;
    bitmap->bitmap_type = type;
    bitmap->bitmap_flags = flags;
    bitmap->bitmap_coalign_item = coalign_item;
    return 1;
}

// Configure NTSC VIEWTYPE_16_640 and VIEWTYPE_16_640_LACE Views backed by a displayable
// BMTYPE_16 Bitmap. The tag numbers and dimension rules are from graphics/view.c;
// unsupported projector/view combinations remain rejected instead of becoming
// a guessed host viewport.
static int gk_configure_view_item(gk_item *view,
                                  const uint32_t tags[][2],
                                  uint32_t tag_count) {
    if (!view || view->ctype != GK_GRAPHICS_VIEW_CTYPE)
        return 0;

    int32_t left = 0;
    int32_t top = 0;
    int32_t width = -1;
    int32_t height = -1;
    int32_t pixel_width = -1;
    int32_t pixel_height = -1;
    int32_t win_left = 0;
    int32_t win_top = 0;
    int32_t type = -1;
    int width_mode = 0;  // 1 = physical width tag, 2 = pixel width tag
    int height_mode = 0;
    uint32_t bitmap_item = 0;
    uint32_t render_signal = 0;
    uint32_t display_signal = 0;
    uint32_t signal_task = 0;
    uint32_t avg_mode0 = 0;
    uint32_t avg_mode1 = 0;

    for (uint32_t i = 0; i < tag_count; ++i) {
        const uint32_t tag = tags[i][0];
        const uint32_t value = tags[i][1];
        switch (tag) {
        case 1u: // TAG_ITEM_NAME, already validated by CreateItemVA
        case 2u: // TAG_ITEM_PRI
        case 3u: // TAG_ITEM_VERSION
        case 4u: // TAG_ITEM_REVISION
        case 5u: // TAG_ITEM_UNIQUE_NAME
        case 6u:
        case 7u:
        case 8u:
        case 9u:
            break;
        case GK_VIEWTAG_VIEWTYPE:
            type = (int32_t)value;
            break;
        case GK_VIEWTAG_WIDTH:
            width = (int32_t)value;
            width_mode = 1;
            break;
        case GK_VIEWTAG_HEIGHT:
            height = (int32_t)value;
            height_mode = 1;
            break;
        case GK_VIEWTAG_PIXELWIDTH:
            pixel_width = (int32_t)value;
            width_mode = 2;
            break;
        case GK_VIEWTAG_PIXELHEIGHT:
            pixel_height = (int32_t)value;
            height_mode = 2;
            break;
        case GK_VIEWTAG_TOPEDGE:
            top = (int32_t)value;
            break;
        case GK_VIEWTAG_LEFTEDGE:
            left = (int32_t)value;
            break;
        case GK_VIEWTAG_WINTOPEDGE:
            win_top = (int32_t)value;
            break;
        case GK_VIEWTAG_WINLEFTEDGE:
            win_left = (int32_t)value;
            break;
        case GK_VIEWTAG_BITMAP:
            bitmap_item = value;
            break;
        case GK_VIEWTAG_AVGMODE:
            if (value & 0x00010000u)
                avg_mode1 = value & 3u;
            else
                avg_mode0 = value & 3u;
            break;
        case GK_VIEWTAG_RENDERSIGNAL:
            render_signal = value;
            break;
        case GK_VIEWTAG_DISPLAYSIGNAL:
            display_signal = value;
            break;
        case GK_VIEWTAG_SIGNALTASK:
            signal_task = value;
            break;
        case GK_VIEWTAG_FIELDSTALL_BM:
        case GK_VIEWTAG_FIELDSTALL_VIEW:
        case GK_VIEWTAG_BESILENT:
            // These fields are forwarded to projector/interrupt machinery in
            // the original folio; no guest-visible host state is recovered yet.
            break;
        default:
            return 0;
        }
    }

    if (type != (int32_t)GK_VIEWTYPE_16_640 && type != (int32_t)GK_VIEWTYPE_16_640_LACE)
        return 0;
    if (bitmap_item == 0u)
        return 0;
    gk_item *bitmap = gk_live_item(bitmap_item);
    if (!bitmap || bitmap->ctype != GK_GRAPHICS_BITMAP_CTYPE ||
        (bitmap->bitmap_flags & GK_BMF_DISPLAYABLE) == 0u ||
        bitmap->bitmap_type != GK_BMTYPE_16)
        return 0;

    const int32_t pixel_y = type == (int32_t)GK_VIEWTYPE_16_640 ? 2 : 1;
    // NTSC non-interlaced 640 views have two display rows per pixel;
    // VIEWTYPE_16_640_LACE has one display coordinate per pixel in the NTSC
    // database. Match view.c's mutually-exclusive physical/pixel dimensions,
    // then fill unspecified dimensions from the attached Bitmap.
    if (width_mode == 2)
        width = pixel_width;
    else if (width_mode == 1)
        pixel_width = width;
    else if (pixel_width < 0 && width < 0)
        pixel_width = (int32_t)bitmap->bitmap_width;
    if (height_mode == 2 && (pixel_height < 0 || pixel_height > 480 / pixel_y))
        return 0;
    if (height_mode == 2)
        height = pixel_height * pixel_y;
    else if (height_mode == 1)
        pixel_height = height / pixel_y + (height % pixel_y != 0);
    else if (pixel_height < 0 && height < 0)
        pixel_height = (int32_t)bitmap->bitmap_height;

    if (width < 0 && pixel_width >= 0)
        width = pixel_width;
    if (height < 0 && pixel_height >= 0)
        height = pixel_height * pixel_y;

    if (pixel_width < 0 || pixel_height < 0 || width < 0 || height < 0 ||
        pixel_width > 640 || pixel_height > 480 / pixel_y || pixel_width == 0 ||
        pixel_height == 0 || win_left < 0 || win_top < 0)
        return 0;
    if ((uint64_t)pixel_width + (uint32_t)win_left > bitmap->bitmap_width ||
        (uint64_t)pixel_height + (uint32_t)win_top > bitmap->bitmap_height)
        return 0;

    view->view_left = left;
    view->view_top = top;
    view->view_width = width;
    view->view_height = height;
    view->view_pixel_width = pixel_width;
    view->view_pixel_height = pixel_height;
    view->view_win_left = win_left;
    view->view_win_top = win_top;
    view->view_type = (int32_t)(GK_VIEWTYPE_PROJTYPE_NTSC |
                                (uint32_t)type);
    view->view_flags = 0u;
    view->view_bitmap_item = bitmap_item;
    view->view_render_signal = render_signal;
    view->view_display_signal = display_signal;
    view->view_signal_task = signal_task;
    view->view_avg_mode0 = avg_mode0;
    view->view_avg_mode1 = avg_mode1;
    return 1;
}

// ---- Graphics folio view-list window (public vectors 3/5) -----------------
//
// Recovered from the released Portfolio source:
//   * folios/graphics/view.c:797  SuperAddViewToViewList(viewItem,
//     viewListItem) — the folio entry behind the public AddViewToViewList
//     library wrapper (syscall_glue.s: GRAPHICSFOLIO+1 -> swifuncs[1]).
//   * folios/graphics/view.c:1003 SuperRemoveView(viewItem) — public
//     RemoveView (syscall_glue.s: GRAPHICSFOLIO+2 -> swifuncs[2]).
//
// Contract applied here:
//   * A nonzero viewListItem must resolve to a graphics ViewList or Projector
//     Item; zero selects the default Projector's view list. The recovered
//     image creates neither ViewList nor Projector Items (only graphics Items
//     are one View via kernel CreateItemVA and the single AddViewToViewList
//     site passes viewListItem = 0), so any nonzero target fails closed with
//     GFX_ERR_BADITEM exactly as the source rejects non-ViewList/Projector
//     targets.
//   * viewItem must resolve to a live graphics View (the model has no
//     ViewList node), else GFX_ERR_BADITEM.
//   * An attached View cannot be re-added: GFX_ERR_VIEWINUSE.
//   * RemoveView accepts only a View and treats an already-detached node as a
//     successful no-op (view.c removeview returns 0).
//   * deleteview() (view.c:663) detaches before destruction; gk_DeleteItem
//     clears the membership flag for the reclaimed slot.
// The default Projector's ViewList anchor and its front-to-back ordering are
// not modeled: the host display path consumes the TE view Item directly, and
// no guest code reads the View's n_Next/n_Prev after look-up, so those
// guest-visible words stay zero rather than naming a fabricated anchor.
#include "guest_display.h"

static uint32_t g_display_rgba[M2_DISPLAY_WIDTH * M2_DISPLAY_HEIGHT];
static uint64_t g_display_generation;
static uint64_t g_display_content_hash;
static uint32_t g_display_view, g_display_task, g_display_signals;
static int g_display_uses_te_target;
static uint32_t g_display_te_target;
static uint32_t g_display_bitmap_buffer;

static uint64_t gk_display_hash(void) {
    const uint8_t *bytes = (const uint8_t *)g_display_rgba;
    uint64_t hash = 1469598103934665603ull;
    for (size_t i = 0; i < sizeof(g_display_rgba); ++i) {
        hash ^= bytes[i];
        hash *= 1099511628211ull;
    }
    return hash;
}

static void gk_display_clear(uint32_t view) {
    pthread_mutex_lock(&g_display_lock);
    if (!view || view == g_display_view) {
        g_display_view = g_display_task = g_display_signals = 0;
        g_display_uses_te_target = 0;
        g_display_te_target = 0;
        g_display_bitmap_buffer = 0;
        g_display_content_hash = 0;
        ++g_display_generation;
    }
    pthread_mutex_unlock(&g_display_lock);
}

uint32_t m2_guest_display_te_target(void) {
    pthread_mutex_lock(&g_display_lock);
    const uint32_t target = g_display_uses_te_target ? g_display_te_target : 0;
    pthread_mutex_unlock(&g_display_lock);
    return target;
}

// The guest's movie-mode word is not cleared by the Configure Race stop path:
// it remains a view/overlay configuration value while the stream workers are
// torn down.  Use the two source-owned stream workers as the lifecycle edge so
// a later preview launch can clear and re-seed the host overlay copy.
static int gk_video_stream_task_live(void) {
    static const uint32_t stream_entries[] = {
        0x692a0u, // DataStreamThread
        0x6a388u, // DataAcqThread
    };
    for (uint32_t i = 0; i < M2K_MAX_TASKS; ++i) {
        const gk_thread_spec *spec = &g_gk.specs[i];
        if (!spec->busy || spec->task == M2K_ITEM_NONE) continue;
        const uint32_t entry = spec->entry_ea >= GK_RELOC_TEXT_BASE
                                   ? spec->entry_ea - GK_RELOC_TEXT_BASE
                                   : spec->entry_ea;
        for (size_t j = 0; j < sizeof(stream_entries) / sizeof(stream_entries[0]); ++j) {
            if (entry == stream_entries[j] && !gk_task_terminal(spec->task))
                return 1;
        }
    }
    return 0;
}

int m2_guest_video_overlay_targets(uint32_t *view_base, uint32_t *draw_base) {
    if (!view_base || !draw_base) return 0;
    uint32_t draw = 0;
    gk_item *fb = gk_live_item(g_gk.te_framebuffer_item);
    if (fb && fb->ctype == GK_GRAPHICS_BITMAP_CTYPE)
        draw = fb->bitmap_buffer;
    pthread_mutex_lock(&g_display_lock);
    uint32_t view = g_display_bitmap_buffer;
    const int configured = g_display_uses_te_target ||
                           (g_gk.cpu && rd32(g_gk.cpu, 0x18aa7cu) != 0);
    pthread_mutex_unlock(&g_display_lock);
    const int active = configured && gk_video_stream_task_live();
    if (active && draw && (!view || view == draw) && fb) {
        for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
            const gk_item *candidate = &g_gk.items[i];
            if (!candidate->used || candidate->ctype != GK_GRAPHICS_BITMAP_CTYPE ||
                candidate->bitmap_type != 1u ||
                candidate->bitmap_buffer_size != fb->bitmap_buffer_size ||
                candidate->bitmap_buffer == draw)
                continue;
            const uint32_t distance = candidate->bitmap_buffer > draw
                ? candidate->bitmap_buffer - draw
                : draw - candidate->bitmap_buffer;
            if (distance == fb->bitmap_buffer_size + 2048u) {
                view = candidate->bitmap_buffer;
                break;
            }
        }
    }
    if (!active || !view || !draw) return 0;
    *view_base = view;
    *draw_base = draw;
    return 1;
}

int m2_guest_video_overlay_active(void) {
    return g_gk.cpu && rd32(g_gk.cpu, 0x18aa7cu) != 0 &&
           gk_video_stream_task_live();
}

int m2_guest_display_copy(uint32_t *rgba, size_t pixels, uint64_t *generation) {
    return m2_guest_display_copy_hashed(rgba, pixels, generation, NULL);
}

int m2_guest_display_copy_hashed(uint32_t *rgba, size_t pixels,
                                 uint64_t *generation, uint64_t *content_hash) {
    if (!rgba || pixels < M2_DISPLAY_WIDTH * M2_DISPLAY_HEIGHT || !generation)
        return 0;
    pthread_mutex_lock(&g_display_lock);
    // A View selecting the active TE destination scans out the host-rendered
    // target. Its guest-RAM backing is intentionally not kept coherent, so a
    // RAM snapshot would cover the rendered image with stale pixels.
    const int active = g_display_view != 0 && !g_display_uses_te_target;
    if (active) memcpy(rgba, g_display_rgba, sizeof(g_display_rgba));
    *generation = g_display_generation;
    if (content_hash) *content_hash = active ? g_display_content_hash : 0;
    pthread_mutex_unlock(&g_display_lock);
    return active;
}

void m2_guest_display_presented(uint64_t generation) {
    pthread_mutex_lock(&g_display_lock);
    if (gk_bound() && generation == g_display_generation && g_display_task) {
        for (uint32_t bit = 0; bit < 32; ++bit)
            if (g_display_signals & (1u << bit))
                (void)m2k_send_signal(g_gk.kctx, g_display_task, bit);
        g_display_signals = 0;
    }
    pthread_mutex_unlock(&g_display_lock);
}

// presented_target names the guest framebuffer the presented pixels came from,
// or 0 when a direct Bitmap/Projector image owned scanout instead of the
// addressed TE target. The released driver has no image identity to compare:
// it waits on the View display callback and resumes on the next presented
// field whatever the View holds (driver.c:456-479, OnScreenHandler), and
// io_Error is reserved for the missing-binding identities. Withholding the
// fence on a mismatch would therefore deadlock a guest that can never be told
// "not yet", so a disagreement is recorded as an explicit ownership refusal
// and still releases the edge.
void m2_guest_te_display_presented(uint32_t presented_target) {
    pthread_mutex_lock(&g_display_lock);
    if (g_te_display_presented < g_te_display_published) {
        if (presented_target == 0 || presented_target != g_te_display_target) {
            ++g_te_display_refusals;
            if (gk_graphics_io_trace_enabled()) {
                static uint32_t refusal_emitted;
                if (refusal_emitted < gk_graphics_io_trace_max()) {
                    fprintf(stderr,
                            "[te-ack] refused te_target=%#x presented=%#x "
                            "direct=%d\n",
                            g_te_display_target, presented_target,
                            presented_target == 0);
                    ++refusal_emitted;
                }
            }
        }
        ++g_te_display_presented;
        pthread_cond_broadcast(&g_te_display_cond);
    }
    pthread_mutex_unlock(&g_display_lock);
}

uint64_t m2_guest_te_display_refusals(void) {
    pthread_mutex_lock(&g_display_lock);
    const uint64_t refusals = g_te_display_refusals;
    pthread_mutex_unlock(&g_display_lock);
    return refusals;
}

// view.c modifyview copies the old View, validates its replacement Bitmap,
// then asks the projector to display it. A View is not a Bitmap, and must not
// be rejected by the Bitmap-only ModifyGraphicsItem path. This is the direct
// RGB555 framebuffer route (including MPEG DMA). A View selecting the active
// TE destination instead leaves scanout on that renderer-owned target.
static uint32_t gk_modify_view_bitmap(PPCContext *c, uint32_t item,
                                       gk_item *view, uint32_t tags) {
    uint32_t bitmap_item = view->view_bitmap_item;
    int silent = 0, ended = tags == 0;
    for (uint32_t i = 0; !ended && i < 32; ++i) {
        if (tags > RECOMP_GUEST_MEM - 8u) return 0xd55b9002u; // BADTAGARG
        const uint32_t tag = rd32(c, tags), value = rd32(c, tags + 4u);
        tags += 8u;
        switch (tag) {
        case M2_TAG_END: ended = 1; break;
        case GK_VIEWTAG_BITMAP: bitmap_item = value; break;
        case GK_VIEWTAG_BESILENT: silent = value != 0; break;
        case GK_VIEWTAG_FIELDSTALL_BM:
        case GK_VIEWTAG_FIELDSTALL_VIEW:
            // The recovered full-height interlaced View requests line zero.
            // Presentation/notifications are serviced at the host field boundary.
            if (value != 0u) return 0xd55b9003u; // BADTAGARGVAL
            break;
        default: return 0xd55b9002u; // GFX_ERR_BADTAGARG
        }
    }
    if (!ended) return 0xd55b9002u;
    const gk_item *bm = gk_live_item(bitmap_item);
    if (!bm || bm->ctype != GK_GRAPHICS_BITMAP_CTYPE ||
        !(bm->bitmap_flags & GK_BMF_DISPLAYABLE) || bm->bitmap_type != GK_BMTYPE_16)
        return 0xd55b9104u; // GFX_ERR_BADBITMAP
    if (view->view_win_left < 0 || view->view_win_top < 0 ||
        (uint64_t)view->view_pixel_width + view->view_win_left > bm->bitmap_width ||
        (uint64_t)view->view_pixel_height + view->view_win_top > bm->bitmap_height)
        return 0xd55b9102u; // GFX_ERR_BADDIMS
    if (!bm->bitmap_buffer || bm->bitmap_buffer_size > RECOMP_GUEST_MEM ||
        bm->bitmap_buffer > RECOMP_GUEST_MEM - bm->bitmap_buffer_size)
        return 0xd55b9104u;

    // VideoPlayer stores its nonzero overlay-mode argument at gMpwi
    // (0x18aa7c). In that mode StreamEventFunc composites into the normal TE
    // display buffers and advances the View to the completed sibling while
    // GS_SetDestBuffer selects the other sibling for the next callback. Full
    // screen movies pass zero and continue to scan out decoded guest RAM.
    const int uses_te_target = rd32(c, 0x18aa7cu) != 0;
    pthread_mutex_lock(&g_display_lock);
    if (!uses_te_target) {
        for (size_t i = 0; i < M2_DISPLAY_WIDTH * M2_DISPLAY_HEIGHT; ++i)
            g_display_rgba[i] = 0xff000000u;
        for (int32_t y = 0; y < view->view_pixel_height; ++y) {
            const int32_t pixel_y = (view->view_type & 0xffff) == GK_VIEWTYPE_16_640 ? 2 : 1;
            const int32_t dy = y * pixel_y + view->view_top;
            if (dy < 0 || dy >= (int32_t)M2_DISPLAY_HEIGHT) continue;
            for (int32_t x = 0; x < view->view_pixel_width; ++x) {
                const int32_t dx = x + view->view_left;
                if (dx < 0 || dx >= (int32_t)M2_DISPLAY_WIDTH) continue;
                const uint32_t ea = bm->bitmap_buffer + 2u *
                    ((y + view->view_win_top) * bm->bitmap_width + x + view->view_win_left);
                const uint16_t pixel = rd16(c, ea);
                const uint32_t r = (pixel >> 10u) & 31u;
                const uint32_t g = (pixel >> 5u) & 31u;
                const uint32_t b = pixel & 31u;
                const uint32_t rgba = 0xff000000u |
                    ((r << 3u) | (r >> 2u)) |
                    (((g << 3u) | (g >> 2u)) << 8u) |
                    (((b << 3u) | (b >> 2u)) << 16u);
                for (int32_t row=0; row<pixel_y; ++row) {
                    if (dy+row < (int32_t)M2_DISPLAY_HEIGHT)
                        g_display_rgba[(dy+row) * M2_DISPLAY_WIDTH + dx] = rgba;
                }
            }
        }
    }
    // Detached Views are not copied to the host scanout. Avoid hashing the
    // guest bitmap in that path (State 3 keeps its TE target authoritative).
    g_display_content_hash =
        view->viewlist_attached && !uses_te_target ? gk_display_hash() : 0;
    view->view_bitmap_item = bitmap_item;
    gk_publish_view_bitmap_attachment(item, view);
    g_display_view = view->viewlist_attached ? item : 0;
    g_display_uses_te_target = uses_te_target;
    g_display_te_target = uses_te_target ? bm->bitmap_buffer : 0;
    g_display_bitmap_buffer = bm->bitmap_buffer;
    g_display_task = view->view_signal_task;
    g_display_signals = silent ? 0 : view->view_render_signal | view->view_display_signal;
    ++g_display_generation;
    pthread_mutex_unlock(&g_display_lock);
    return item;
}

static uint32_t gk_graphics_viewlist_add(uint32_t view_item,
                                         uint32_t view_list_item) {
    // SuperAddViewToViewList: default Projector when viewListItem is zero.
    if (view_list_item != 0)
        return GK_GFX_ERR_BADITEM;

    gk_item *view = gk_live_item(view_item);
    if (!view || view->ctype != GK_GRAPHICS_VIEW_CTYPE)
        return GK_GFX_ERR_BADITEM;

    // view.c AddHead() links the node; an already-linked node is VIEWINUSE.
    if (view->viewlist_attached)
        return GK_GFX_ERR_VIEWINUSE;
    view->viewlist_attached = 1;
    return M2K_OK;
}

static uint32_t gk_graphics_viewlist_remove(uint32_t view_item) {
    // SuperRemoveView validates the Item before removeview().
    gk_item *view = gk_live_item(view_item);
    if (!view || view->ctype != GK_GRAPHICS_VIEW_CTYPE)
        return GK_GFX_ERR_BADITEM;

    // removeview(): only touches the node when n_Next is set; a detached View
    // is still a successful removal (the source returns 0 either way).
    view->viewlist_attached = 0;
    gk_display_clear(view_item);
    return M2K_OK;
}

// ---- folio 3:17 QueryGraphics (folios/graphics/linkexec.x EXPORTS 17) -------
//
// Err QueryGraphics (const struct TagArg *args)  (folios/graphics/query.c:88)
//   err = WaitForProjectorLoader();  if (err < 0) return err;
//   if (!(state = ta)) return (err);
//   while (ta = NextTagArg(&state)) { if ((err = iqg(ta->ta_Tag,
//                                                    ta->ta_Arg)) < 0) break; }
//   return err;
// iqg (query.c:57-81) accepts only QUERYGFXTAG_DEFAULTPROJECTOR (1), which
// writes GBASE(gb_DefaultProjector)->p.n_Item into *ret; every other tag
// returns GFX_ERR_BADTAGARG.
//
// imsa_shell.c calls QueryGraphics(NULL) as its graphics-folio context probe
// (LaunchMe.m2 0x18, `li r3,0` immediately before), which is the NULL-list arm
// and returns 0.
//
// QUERYGFXTAG_DEFAULTPROJECTOR is refused here rather than answered: this
// boundary never creates a Projector Item, so there is no source-backed
// gb_DefaultProjector to report and a made-up Item number would be invented
// game state. The refusal uses the vendor's own error identity.
#define GK_GFX_ERR_BADPTR 0xD55B9009u // ER_BadPtr (kernel/operror.h:171)
#define GK_GFX_ERR_BADTAGARG 0xD55B9002u  // ER_BadTagArg (operror.h:172)
#define GK_GFX_QUERYGFTAG_DEFAULTPROJECTOR 1u

static uint32_t gk_QueryGraphics(uint32_t ta_ea) {
    // WaitForProjectorLoader(): there is no projector-loader task on this
    // boundary, so the equivalent precondition is a live folio binding.
    if (!gk_bound() || !g_gk.cpu || !g_gk.cpu->mem)
        return GK_GFX_ERR_BADITEM;
    if (ta_ea == 0) return M2K_OK;   // `if (!(state = ta)) return (err);`
    for (uint32_t i = 0; i < 32u; ++i) {   // same bound as the task tag list
        const uint32_t at = ta_ea + i * 8u;
        if (at < ta_ea || at > RECOMP_GUEST_MEM - 8u)
            return GK_GFX_ERR_BADPTR;
        const uint32_t tag = rd32(g_gk.cpu, at);
        if (tag == 0) return M2K_OK;       // TAG_END: no tag failed
        const uint32_t arg = rd32(g_gk.cpu, at + 4u);
        if (tag != GK_GFX_QUERYGFTAG_DEFAULTPROJECTOR)
            return GK_GFX_ERR_BADTAGARG;   // iqg default:
        if (arg == 0 || arg > RECOMP_GUEST_MEM - 4u)
            return GK_GFX_ERR_BADPTR;      // iqg BUILD_PARANOIA IsMemWritable
        return GK_GFX_ERR_BADTAGARG;       // no Projector Item exists here
    }
    return GK_GFX_ERR_BADTAGARG;           // no TAG_END within the bound
}

// The recovered game allocates Bitmap objects first, then attaches their
// guest buffers through ModifyGraphicsItemVA(item, BMTAG_BUFFER, buffer,
// TAG_END). Keep this boundary deliberately narrow: the source folio routes
// by ItemNode type, and a numeric tag 0x11 is also used by View. Unknown item
// types, malformed tag lists, and unsupported tags therefore return a
// negative result without changing the existing Bitmap state.
static int recomp_call_graphics_dispatch_impl(PPCContext *c, uint32_t ordinal,
                                             uint32_t pc) {
    switch (ordinal) {
    case 1: {
    if (!c)
        return 1;
    const uint32_t item = c->gpr[3];
    c->gpr[3] = (uint32_t)M2K_ERR_BAD_ITEM;
    if (!gk_bound() || !c->mem || c->mem != g_gk.cpu->mem)
        return 1;

    gk_item *bitmap = gk_live_item(item);
    if (bitmap && bitmap->ctype == GK_GRAPHICS_VIEW_CTYPE) {
        c->gpr[3] = gk_modify_view_bitmap(c, item, bitmap, c->gpr[4]);
        return 1;
    }
    if (!bitmap || bitmap->ctype != GK_GRAPHICS_BITMAP_CTYPE)
        return 1;

    const uint32_t taglist_ea = c->gpr[4];
    if (taglist_ea > RECOMP_GUEST_MEM - 8u)
        return 1;
    if (rd32(c, taglist_ea) != GK_BMTAG_BUFFER ||
        rd32(c, taglist_ea + 8u) != M2_TAG_END)
        return 1;

    const uint32_t buffer = rd32(c, taglist_ea + 4u);
    if (buffer != 0u &&
        ((buffer & 3u) != 0u || buffer >= RECOMP_GUEST_MEM ||
         bitmap->bitmap_buffer_size > RECOMP_GUEST_MEM - buffer))
        return 1;

    // bitmap.c resets the memory care/state bits before rerunning the
    // enabled capability checks. The current source call shape has
    // DISPLAYABLE|RENDERABLE, which requires four-byte buffer alignment and
    // publishes care=3/state=0; MPEGABLE's source contract requires care=31.
    uint32_t care_bits = 0u;
    if (bitmap->bitmap_flags & GK_BMF_MPEGABLE)
        care_bits = 31u;
    else if (bitmap->bitmap_flags & (GK_BMF_DISPLAYABLE | GK_BMF_RENDERABLE))
        care_bits = 3u;

    bitmap->bitmap_buf_mem_care_bits = care_bits;
    bitmap->bitmap_buf_mem_state_bits = 0u;
    bitmap->bitmap_buffer = buffer;
    gk_publish_bitmap_object(item, bitmap);
    c->gpr[3] = item;

    // Publish every bitmap buffer span (all care paths). The display
    // carves are MPEGABLE in the recovered allocation, so a care filter
    // would drop them; the bridge resolves the strip targets via the
    // framebuffer/view items instead of the care bits. A zero buffer is
    // published too: the guest has released this allocation, and the
    // bridge has to drop the span it recorded for the item, or later
    // DB-source reads would keep addressing the obsolete renderer target.
    if (m2_guest_graphics_bitmap_buffer_c)
        m2_guest_graphics_bitmap_buffer_c(item, buffer,
                                          bitmap->bitmap_buffer_size);

    if (gk_state2_input_diag_enabled()) {
        static unsigned diag_count;
        if (diag_count < 64u) {
            fprintf(stderr,
                    "[gk-input] ModifyGraphicsItemVA pc=%#x item=%#x "
                    "tag=%#x buffer=%#x -> %#x\n",
                    pc, item, GK_BMTAG_BUFFER, buffer, item);
            ++diag_count;
        }
    }
    return 1;
    }
    case 3: // AddViewToViewList(viewItem, viewListItem) -> Err
        if (!c)
            return 1;
        if (!gk_bound() || !c->mem || c->mem != g_gk.cpu->mem)
            c->gpr[3] = GK_GFX_ERR_BADITEM;
        else
            c->gpr[3] = gk_graphics_viewlist_add(c->gpr[3], c->gpr[4]);
        return 1;
    case 5: // RemoveView(viewItem) -> Err
        if (!c)
            return 1;
        if (!gk_bound() || !c->mem || c->mem != g_gk.cpu->mem)
            c->gpr[3] = GK_GFX_ERR_BADITEM;
        else
            c->gpr[3] = gk_graphics_viewlist_remove(c->gpr[3]);
        return 1;
    case 17: // QueryGraphics(args_ea) -> Err
        if (!c)
            return 1;
        if (!gk_bound() || !c->mem || c->mem != g_gk.cpu->mem)
            c->gpr[3] = GK_GFX_ERR_BADITEM;
        else
            c->gpr[3] = gk_QueryGraphics(c->gpr[3]);
        return 1;
    default:
        return 0;
    }
}

// Public entry point; see the filesystem dispatch wrapper
// (selector_observed.h).
int recomp_call_graphics_dispatch(PPCContext *c, uint32_t ordinal,
                                  uint32_t pc) {
    const int handled = recomp_call_graphics_dispatch_impl(c, ordinal, pc);
    m2_selector_note(M2_FOLIO_GRAPHICS, ordinal, handled);
    return handled;
}

static char gk_audio_fold(char c) {
    return (c >= 'a' && c <= 'z') ? (char)(c - ('a' - 'A')) : c;
}

static int gk_audio_name_equal(const char *a, const char *b) {
    if (!a || !b) return 0;
    for (uint32_t i = 0; i < GK_MAX_NAME_LEN; ++i) {
        const char ca = gk_audio_fold(a[i]);
        const char cb = gk_audio_fold(b[i]);
        if (ca != cb) return 0;
        if (ca == '\0') return 1;
    }
    return 0;
}

static const m2_dsp_template_def *gk_find_dsp_template(const char *name) {
    if (!name || name[0] == '\0') return NULL;
    // Prefer the on-disc filename. This keeps the legitimate
    // timesplus_noclip.dsp entry distinct even though its NAME chunk declares
    // the same name as timesplus.dsp.
    for (size_t i = 0; i < M2_DSP_TEMPLATE_CATALOG_COUNT; ++i) {
        if (gk_audio_name_equal(name, m2_dsp_template_catalog[i].file_name))
            return &m2_dsp_template_catalog[i];
    }
    for (size_t i = 0; i < M2_DSP_TEMPLATE_CATALOG_COUNT; ++i) {
        if (m2_dsp_template_catalog[i].declared_name &&
            gk_audio_name_equal(name, m2_dsp_template_catalog[i].declared_name))
            return &m2_dsp_template_catalog[i];
    }
    return NULL;
}

// Copy a guest-owned audio filename into bounded host metadata. The caller
// still owns the original EA; no guest pointer escapes this function.
static int32_t gk_copy_audio_name(PPCContext *cpu, uint32_t name_ea,
                                  char out[GK_MAX_NAME_LEN]) {
    // Audio selectors can run in a guest task context.  Task contexts copy
    // the shared guest-RAM pointer but are not the boot context bound to the
    // kernel pool, so pointer identity is not part of the guest ABI.
    if (!out) return M2K_ERR_BAD_ITEM;
    memset(out, 0, GK_MAX_NAME_LEN);
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem || name_ea == 0 ||
        name_ea >= RECOMP_GUEST_MEM)
        return M2K_ERR_BAD_ITEM;
    int32_t rc = m2m_copy_guest_string_ctx(cpu, name_ea, out,
                                           GK_MAX_NAME_LEN);
    if (rc == M2M_ERR_FAULT || rc < 0 || out[0] == '\0')
        return M2K_ERR_BAD_ITEM;
    return M2K_OK;
}

static int32_t gk_validate_audio_template_name(PPCContext *cpu,
                                               uint32_t name_ea) {
    char name[GK_MAX_NAME_LEN];
    int32_t valid = gk_copy_audio_name(cpu, name_ea, name);
    if (valid < 0) return valid;
    if (!gk_find_dsp_template(name)) return M2_AUDIO_ERR_NAME_MISSING;
    return M2K_OK;
}

static int32_t gk_audio_require_no_tags(PPCContext *cpu,
                                        uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (taglist_ea == 0) return M2K_OK;
    if (taglist_ea > RECOMP_GUEST_MEM - 4u ||
        rd32(cpu, taglist_ea) != M2_TAG_END)
        return M2_AUDIO_ERR_BAD_TAG;
    return M2K_OK;
}

static int32_t gk_mint_audio_template(uint32_t name_ea) {
    uint32_t template_item = gk_mint_item(
        "audio template", GK_AUDIO_TEMPLATE_CTYPE, name_ea, 3, 0);
    if (template_item == M2K_ITEM_NONE) return M2K_ERR_NO_SLOT;
    return (int32_t)template_item;
}

// CreateMixerTemplate accepts only TAG_ITEM_NAME in its optional tag list.
// Keep the list walk bounded and use the calling task's shared guest image;
// the returned Item still contains no guest or host pointer.
static int32_t gk_audio_mixer_name(PPCContext *cpu, uint32_t taglist_ea,
                                   uint32_t *name_ea_out,
                                   uint32_t *tag_count_out) {
    if (!name_ea_out || !tag_count_out || !gk_bound() || !cpu ||
        cpu->mem != g_gk.cpu->mem)
        return M2K_ERR_BAD_ITEM;
    *name_ea_out = 0;
    *tag_count_out = 0;
    if (taglist_ea == 0) return M2K_OK;

    for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
        uint32_t ea = taglist_ea + i * 8u;
        if (taglist_ea > RECOMP_GUEST_MEM - 8u ||
            ea > RECOMP_GUEST_MEM - 8u)
            return M2K_ERR_BAD_ITEM;
        uint32_t tag = rd32(cpu, ea);
        uint32_t value = rd32(cpu, ea + 4u);
        if (tag == M2_TAG_END) return M2K_OK;
        if (tag != 1u /* TAG_ITEM_NAME */ ||
            gk_copy_audio_name(cpu, value, (char[GK_MAX_NAME_LEN]){0}) < 0)
            return M2K_ERR_BAD_ITEM;
        *name_ea_out = value;
        ++*tag_count_out;
    }
    return M2K_ERR_BAD_ITEM;
}

// M2 CreateMixerTemplate(6:8) validates the packed MixerSpec before building
// a template. The metadata retained here is exactly the resource shape made
// by dsppCreateMixerTemplate: Input[numIn], Output[numOut] (or imported
// gMixer when line-out is set), Gain[numIn*numOut], and optional Amplitude.
// DSP code generation and playback remain outside this Item boundary.
int32_t m2_guest_audio_create_mixer_template(PPCContext *cpu,
                                             uint32_t mixer_spec,
                                             uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2K_ERR_BAD_ITEM;

    const uint32_t num_inputs = (mixer_spec >> 24) & 0xffu;
    const uint32_t num_outputs = (mixer_spec >> 16) & 0xffu;
    const uint32_t flags = mixer_spec & 0xffffu;
    if (num_inputs < 1u || num_inputs > 32u ||
        num_outputs < 1u || num_outputs > 8u ||
        (flags & ~0x3u) != 0u ||
        ((flags & 0x2u) != 0u && num_outputs != 2u))
        return M2K_ERR_BAD_ITEM;

    uint32_t name_ea = 0;
    uint32_t tag_count = 0;
    if (gk_audio_mixer_name(cpu, taglist_ea, &name_ea, &tag_count) < 0)
        return M2K_ERR_BAD_ITEM;

    uint32_t template_item = gk_mint_item(
        "audio mixer template", GK_AUDIO_TEMPLATE_CTYPE, name_ea,
        tag_count + 1u, 0);
    if (template_item == M2K_ITEM_NONE) return M2K_ERR_NO_SLOT;
    gk_item *live = gk_live_item(template_item);
    if (!live) {
        gk_DeleteItem(template_item);
        return M2K_ERR_BAD_ITEM;
    }
    live->mixer_spec = mixer_spec;
    // R1/R3 capture: classify the live graph's submix nodes (kind + shape).
    // Bounded (16) behind the existing audio start gate; no behavior change.
    if (gk_audio_start_diag_enabled()) {
        static uint32_t mixer_count = 0;
        if (mixer_count < 16u) {
            ++mixer_count;
            fprintf(stderr,
                    "[audio-template] n=%u kind=mixer item=%#x spec=%#x "
                    "in=%u out=%u flags=%#x\n",
                    mixer_count, template_item, mixer_spec, num_inputs,
                    num_outputs, flags);
        }
    }
    return (int32_t)template_item;
}

// LoadInsTemplate accepts only a NULL or empty tag list and returns a local
// catalog-backed template Item. DSP template loading and resource execution
// remain outside this fixed-width ownership boundary.
int32_t m2_guest_audio_load_ins_template(PPCContext *cpu, uint32_t name_ea,
                                         uint32_t taglist_ea) {
    int32_t valid = gk_validate_audio_template_name(cpu, name_ea);
    if (valid < 0) return valid;
    valid = gk_audio_require_no_tags(cpu, taglist_ea);
    if (valid < 0) return valid;
    return gk_mint_audio_template(name_ea);
}

static int gk_audio_clock_diag_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_AUDIO_CLOCK_DIAG");
        enabled = e && *e && *e != '0';
        checked = 1;
    }
    return enabled;
}

static void gk_log_audio_clock(PPCContext *cpu, const char *source,
                               uint32_t frames, uint32_t audio_time) {
    static uint32_t pump_count = 0;
    static uint32_t time_count = 0;
    static uint32_t frame_count = 0;
    if (!gk_audio_clock_diag_enabled() || !source) return;
    uint32_t *count = source[0] == 'p' ? &pump_count
                                      : source[0] == 't' ? &time_count
                                                         : &frame_count;
    if (*count >= 64u) return;
    ++*count;
    uint32_t guest_frame = 0;
    if (cpu && cpu->mem && M2_GUEST_FRAME_COUNTER_EA <= RECOMP_GUEST_MEM - 4u)
        guest_frame = rd32(cpu, M2_GUEST_FRAME_COUNTER_EA);
    fprintf(stderr,
            "[audio-clock] source=%s n=%u rendered_frames=%u audio_time=%u "
            "guest_frame=%u\n",
            source, *count, frames, audio_time, guest_frame);
}

// GetAudioTime reads the original AF_GLOBAL_CLOCK. Its clock advances from
// DSP sample frames using the default 184-frame duration. The local host
// mixer exposes the same 44.1 kHz rendered-frame unit; when no mixer is
// present, gk_audio_clock_read supplies the host frame-boundary fallback used
// by the timer daemon so guest clock reads and Cue delivery share one timebase.
uint32_t m2_guest_audio_get_audio_time(PPCContext *cpu) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return 0;
    const uint32_t rendered_frames = m2_host_audio_frame_count();
    const uint64_t clock_frames =
        gk_audio_clock_read(rendered_frames, 0);
    const uint32_t audio_time =
        (uint32_t)(clock_frames / GK_AUDIO_GLOBAL_CLOCK_DURATION);
    gk_log_audio_clock(cpu, "audio_time", (uint32_t)clock_frames,
                       audio_time);
    return audio_time;
}

// Standalone adapters retain their explicitly supplied sample time.
__attribute__((weak)) uint32_t m2_host_audio_clock_frame_count(void) {
    return m2_host_audio_frame_count();
}

// GetAudioFrameCount reads DSPX_FRAME_UP_COUNTER, a continuously advancing
// sample clock. The interactive host supplies 44.1 kHz monotonic time from
// the first device callback. Completed callback blocks remain the separate
// output-production counter: returning those here can give two moving-car
// updates identical timestamps, causing Calc3DSoundDoppler to return zero
// and sndSetEng to release/restart the opponent engine every few frames.
uint32_t m2_guest_audio_get_audio_frame_count(PPCContext *cpu) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return 0;
    const uint32_t sample_frames = m2_host_audio_clock_frame_count();
    const uint64_t clock_frames =
        sample_frames != 0u ? sample_frames : gk_audio_clock_read(0u, 0);
    gk_log_audio_clock(cpu, "frame_count", (uint32_t)clock_frames,
                       (uint32_t)(clock_frames /
                                  GK_AUDIO_GLOBAL_CLOCK_DURATION));
    return (uint32_t)clock_frames;
}

int32_t m2_guest_audio_load_instrument(PPCContext *cpu, uint32_t name_ea,
                                       uint32_t calc_rate_divider,
                                       uint32_t priority) {
    int32_t valid = gk_validate_audio_template_name(cpu, name_ea);
    if (valid < 0) return valid;

    const uint32_t divider = calc_rate_divider & 0xffu;
    const uint32_t effective_divider = divider == 0 ? 1u : divider;
    const uint32_t effective_priority = priority & 0xffu;
    if ((effective_divider != 1u && effective_divider != 2u &&
         effective_divider != 8u) || effective_priority > 200u)
        return M2K_ERR_BAD_ITEM;

    // LoadInsTemplate() creates a named AUDIO_TEMPLATE_NODE, then the
    // convenience call creates an AUDIO_INSTRUMENT_NODE referring to it.
    int32_t template_result = gk_mint_audio_template(name_ea);
    if (template_result < 0) return template_result;
    uint32_t template_item = (uint32_t)template_result;

    uint32_t instrument = gk_mint_item(
        "audio instrument", GK_AUDIO_INSTRUMENT_CTYPE, 0, 3, 0);
    if (instrument == M2K_ITEM_NONE) {
        gk_DeleteItem(template_item);
        return M2K_ERR_NO_SLOT;
    }

    gk_item *live = gk_live_item(instrument);
    if (!live) {
        gk_DeleteItem(instrument);
        gk_DeleteItem(template_item);
        return M2K_ERR_BAD_ITEM;
    }
    live->template_item = template_item;
    live->calc_rate_divider = effective_divider;
    live->priority = effective_priority;
    // R2-full probe (2): AF_TAG_CALCRATE_DIVIDE census — log the effective
    // divider with the template name. Observation only; default-off gate.
    if (gk_audio_calcrate_diag_enabled()) {
        char cname[GK_MAX_NAME_LEN];
        cname[0] = '\0';
        (void)gk_copy_audio_name(cpu, name_ea, cname);
        gk_log_audio_calcrate(instrument, cname, effective_divider,
                              effective_priority);
    }
    return (int32_t)instrument;
}

int32_t m2_guest_audio_unload_instrument(uint32_t instrument) {
    if (!gk_bound()) return M2K_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        live->template_item == M2K_ITEM_NONE)
        return M2K_ERR_BAD_ITEM;

    uint32_t template_item = live->template_item;
    gk_item *template_live = gk_live_item(template_item);
    if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE)
        return M2K_ERR_BAD_ITEM;

    // UnloadInstrument() is DeleteItem(instrument) followed by
    // UnloadInsTemplate(template), both returning an Err status.
    gk_log_audio_lifecycle("unload", NULL, instrument, M2K_OK,
                           live->audio_started);
    gk_DeleteItem(instrument);
    gk_DeleteItem(template_item);
    return M2K_OK;
}

// audio_instr.c internalDeleteAudioIns calls DisconnectRemaining before
// releasing DSP resources. Restore surviving consumers as well as removing
// the graph record, so a patched operand/MOVE cannot read a freed allocation.
static void gk_remove_audio_connections(uint32_t item) {
    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i) {
        gk_audio_connection *connection = &g_gk.connections[i];
        if (connection->used &&
            (connection->src_item == item || connection->dst_item == item)) {
            gk_item *dst = gk_live_item(connection->dst_item);
            if (connection->dst_item != item && dst && dst->audio_dsp_sim) {
                dspp_sim *sim = (dspp_sim *)dst->audio_dsp_sim;
                const dspp_resource *port = gk_dsp_find_resource(sim, connection->dst_name);
                if (port)
                    dspp_sim_disconnect(sim, port->name,
                                        (uint32_t)connection->dst_part);
            }
            memset(connection, 0, sizeof(*connection));
        }
    }
    // Generated-mixer hop teardown: with the item's connections gone, its
    // output-word reservation (if any) has no carrier left; free it. Mixer
    // nodes are the only reservation owners.
    gk_mixnode_release_words(item);
    gk_mix_graph_touch();
}

static int32_t gk_find_audio_port(gk_item *instrument, const char *name,
                                  uint8_t *type_out, uint32_t *parts_out) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        !type_out || !parts_out)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *template_live = gk_live_item(instrument->template_item);
    if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;

    if (template_live->patch_index > 0 &&
        template_live->patch_index <= GK_MAX_PATCH_TEMPLATES) {
        const gk_patch_template *pt =
            &g_gk_patches[template_live->patch_index - 1];
        if (!pt->used) return M2_AUDIO_ERR_BAD_ITEM;
        for (uint32_t i = 0; i < pt->resource_count; ++i) {
            if (gk_audio_name_equal(name, pt->resources[i].name)) {
                *type_out = pt->resources[i].type;
                *parts_out = pt->resources[i].parts;
                return M2K_OK;
            }
        }
        return M2_AUDIO_ERR_NAME_MISSING;
    }

    if (template_live->mixer_spec != 0) {
        const uint32_t inputs = (template_live->mixer_spec >> 24) & 0xffu;
        const uint32_t outputs = (template_live->mixer_spec >> 16) & 0xffu;
        const uint32_t flags = template_live->mixer_spec & 0xffffu;
        if (gk_audio_name_equal(name, "Input")) {
            *type_out = M2_DSP_RESOURCE_INPUT;
            *parts_out = inputs;
            return M2K_OK;
        }
        if (gk_audio_name_equal(name, "Gain")) {
            *type_out = M2_DSP_RESOURCE_KNOB;
            *parts_out = inputs * outputs;
            return M2K_OK;
        }
        if ((flags & 0x01u) != 0u &&
            gk_audio_name_equal(name, "Amplitude")) {
            *type_out = M2_DSP_RESOURCE_KNOB;
            *parts_out = 1;
            return M2K_OK;
        }
        if ((flags & 0x02u) != 0u &&
            gk_audio_name_equal(name, "gMixer")) {
            // dspp_mixer.c declares this imported resource VARIABLE when the
            // line-out option is selected, so it is not a connectable output.
            *type_out = M2_DSP_RESOURCE_VARIABLE;
            *parts_out = outputs;
            return M2K_OK;
        }
        if ((flags & 0x02u) == 0u &&
            gk_audio_name_equal(name, "Output")) {
            *type_out = M2_DSP_RESOURCE_OUTPUT;
            *parts_out = outputs;
            return M2K_OK;
        }
        return M2_AUDIO_ERR_NAME_MISSING;
    }

    const m2_dsp_template_def *template_def =
        gk_find_dsp_template(template_live->audio_name);
    if (!template_def) return M2_AUDIO_ERR_NAME_MISSING;
    for (uint32_t i = 0; i < template_def->resource_count; ++i) {
        const m2_dsp_resource_def *resource =
            &m2_dsp_resource_catalog[template_def->resource_offset + i];
        if (gk_audio_name_equal(name, resource->name)) {
            *type_out = resource->type;
            *parts_out = resource->parts;
            return M2K_OK;
        }
    }
    return M2_AUDIO_ERR_NAME_MISSING;
}

// ---- DSPP live-sim sync (connect + knob execution boundary) ------------------
//
// The guest-owned connection table above is the record; these helpers apply it
// to the host-owned dspp_sim code images through the loader's
// dsppConnectInstrumentParts equivalent (dspp_sim_connect), BIND+RBASE
// destinations through its dsppConnectWithMove equivalent
// (dspp_sim_connect_move, a per-frame copy applied at each tick entry), and
// feed SetKnobPart floats into sim data words through the vendor's
// dsppSetKnob conversion (ConvertFP_SF15 + signal-type clip). Source-backed
// contracts: dspp_instr.c, dspp_knobs.c, dspp_signals.c (RawLimits),
// dspp_template.h.
//
// Runtime-created sims bind to one M2-wide DSP data space, matching the
// dspp_resources_bulldog allocator and dsppImportResource's owner address.
// A cross-instrument patch therefore reads the exporting instrument's live
// word; BIND+RBASE MOVE copies use the same shared address. FIFO-channel and
// trigger resource allocations also use the shared hardware tables, while the
// bounded per-channel FIFO execution state remains on each simulator after
// channels are uniquely allocated. Standalone loader tests may still use
// private sims. Other DSPI registers and imported resources remain explicit
// boundaries (line_out's gMixer import stays EXTERNALREF because no nanokernel
// exporter is loaded).
static const dspp_resource *gk_dsp_find_resource(dspp_sim *sim,
                                                 const char *name) {
    if (!sim || !name) return NULL;
    const dspp_template *res = dspp_sim_resources(sim);
    if (!res) return NULL;
    for (uint32_t i = 0; i < res->resource_count; ++i) {
        if (gk_audio_name_equal(res->resources[i].name, name))
            return &res->resources[i];
    }
    return NULL;
}

static void gk_log_dspp_connect(const gk_audio_connection *cn, uint16_t operand,
                                int applied) {
    static uint32_t count = 0;
    if (!gk_audio_start_diag_enabled() || count >= gk_audio_dspp_diag_cap())
        return;
    ++count;
    // R2-full probe (1): join each connection to its endpoint template names
    // plus the source instrument's voice mask, so a race-route census can
    // partition connected vs bare started sampler voices. Observation only;
    // same gate and cap as the existing connect line.
    char src_tpl[GK_MAX_NAME_LEN];
    char dst_tpl[GK_MAX_NAME_LEN];
    uint32_t src_mask = 0;
    src_tpl[0] = '\0';
    dst_tpl[0] = '\0';
    if (cn) {
        gk_audio_template_label(cn->src_item, src_tpl, sizeof(src_tpl));
        gk_audio_template_label(cn->dst_item, dst_tpl, sizeof(dst_tpl));
        gk_item *src = gk_live_item(cn->src_item);
        if (src && src->ctype == GK_AUDIO_INSTRUMENT_CTYPE)
            src_mask = src->audio_voice_mask;
    }
    fprintf(stderr,
            "[audio-dspp] connect n=%u src=%#x:%s[%d] -> dst=%#x:%s[%d] "
            "op=%#x applied=%d src_tpl=%s dst_tpl=%s src_mask=%#x\n",
            count, cn->src_item, cn->src_name, cn->src_part, cn->dst_item,
            cn->dst_name, cn->dst_part, operand, applied,
            src_tpl[0] ? src_tpl : "?", dst_tpl[0] ? dst_tpl : "?",
            src_mask);
}

// Apply one retained connection to the live sims. Returns 1 when the
// connection effect was installed (destination code image patched, a
// per-frame MOVE copy recorded for a BIND+RBASE destination, or a route
// installed in a mix node's graph), 0 when skipped (a sim is missing or a
// resource is invalid — nothing is fabricated).
static int gk_dsp_apply_connection(const gk_audio_connection *cn) {
    if (!cn || !cn->used) return 0;
    gk_item *src = gk_live_item(cn->src_item);
    gk_item *dst = gk_live_item(cn->dst_item);
    if (!src || !dst) {
        gk_log_dspp_connect(cn, 0, 0);
        return 0;
    }
    // Generated-mixer hop: a mixer node source with a DSPP-sim destination
    // patches the destination exactly like a sim-source OUTPUT connection
    // (vendor ConnectInstrumentParts: the generated mixer image's Output is
    // an ordinary data word). The source address is the node's reserved
    // output range in the shared image; the per-frame tick publishes the
    // computed outputs there. Without a live space or reservation the
    // connection stays a node route (applied=0), the pre-hop behavior.
    if (gk_mixnode_kind_of(src) == 2 && dst->audio_dsp_sim) {
        uint8_t st = 0;
        uint32_t sp = 0;
        uint8_t dt = 0;
        uint32_t dp = 0;
        if (gk_find_audio_port(src, cn->src_name, &st, &sp) != M2K_OK ||
            st != M2_DSP_RESOURCE_OUTPUT || cn->src_part < 0 ||
            (uint32_t)cn->src_part >= sp ||
            gk_find_audio_port(dst, cn->dst_name, &dt, &dp) != M2K_OK ||
            (dt != M2_DSP_RESOURCE_INPUT && dt != M2_DSP_RESOURCE_KNOB) ||
            cn->dst_part < 0 || (uint32_t)cn->dst_part >= dp) {
            gk_log_dspp_connect(cn, 0, 0);
            return 0;
        }
        uint32_t base = gk_mixnode_reserve_words(cn->src_item, sp);
        if (base == 0xFFFFFFFFu) {
            gk_log_dspp_connect(cn, 0, 0);
            return gk_dsp_apply_node_route(cn, src, dst);
        }
        uint32_t src_addr = base + (uint32_t)cn->src_part;
        uint16_t operand =
            (uint16_t)(0x8000u | (src_addr & 0x03FFu));
        dspp_sim *dst_sim = (dspp_sim *)dst->audio_dsp_sim;
        const dspp_resource *dr =
            gk_dsp_find_resource(dst_sim, cn->dst_name);
        const dspp_template *dt2 =
            dr ? dspp_sim_resources(dst_sim) : NULL;
        if (dr && dt2 && (dr->flags & 0x20u /* DRSC_F_BIND */) &&
            dr->bind_index < dt2->resource_count &&
            dt2->resources[dr->bind_index].type == 8u /* RBASE */) {
            dspp_sim_connect_move(
                dst_sim, dr->alloc_value + (uint32_t)cn->dst_part,
                src_addr);
            gk_log_dspp_connect(cn, operand, 1);
            return 1;
        }
        if (dr) {
            dspp_sim_connect(dst_sim, dr->name, (uint32_t)cn->dst_part,
                             operand);
            gk_log_dspp_connect(cn, operand, 1);
            return 1;
        }
        gk_log_dspp_connect(cn, 0, 0);
        return 0;
    }
    // R1: either endpoint without a DSPP sim falls to the mix-node arm
    // (sample voices never have sims; nodes never build images).
    if (!src->audio_dsp_sim || !dst->audio_dsp_sim)
        return gk_dsp_apply_node_route(cn, src, dst);
    dspp_sim *src_sim = (dspp_sim *)src->audio_dsp_sim;
    dspp_sim *dst_sim = (dspp_sim *)dst->audio_dsp_sim;
    const dspp_resource *sr = gk_dsp_find_resource(src_sim, cn->src_name);
    const dspp_resource *dr = gk_dsp_find_resource(dst_sim, cn->dst_name);
    if (!sr || sr->type != 4u /* DRSC_TYPE_OUTPUT */ ||
        sr->alloc_value == 0xFFFFFFFFu || cn->src_part < 0 ||
        (uint32_t)cn->src_part >= sr->many) {
        gk_log_dspp_connect(cn, 0, 0);
        return 0;
    }
    if (!dr || (dr->type != 3u /* INPUT */ && dr->type != 1u /* KNOB */) ||
        dr->alloc_value == 0xFFFFFFFFu || cn->dst_part < 0 ||
        (uint32_t)cn->dst_part >= dr->many) {
        gk_log_dspp_connect(cn, 0, 0);
        return 0;
    }
    // BIND+RBASE destinations take a per-frame MOVE copy on hardware
    // (dsppConnectWithMove, dspp_instr.c): data[DstAddr] = data[SrcAddr]
    // every batch via the header CallConnectionMoves block. Record the copy
    // on the destination sim; no destination code word is patched (the
    // vendor's relocation scan runs only in the non-MOVE arm).
    // SrcAddr = dsppGetResourceAttribute(OUTPUT, part) = alloc + part; the
    // full operand is DSPN_OPERAND_ADDR | SrcAddr (dspp_instr.c).
    uint32_t src_addr = sr->alloc_value + (uint32_t)cn->src_part;
    uint16_t operand =
        (uint16_t)(0x8000u | (src_addr & 0x03FFu));
    const dspp_template *dt = dspp_sim_resources(dst_sim);
    if (dt && (dr->flags & 0x20u /* DRSC_F_BIND */) &&
        dr->bind_index < dt->resource_count &&
        dt->resources[dr->bind_index].type == 8u /* DRSC_TYPE_RBASE */) {
        // DstAddr = dsppGetResourceAttribute(dst, part) under the
        // dsppBindResource default (base alloc + bind offset), already
        // resolved into alloc_value by the loader.
        dspp_sim_connect_move(dst_sim,
                              dr->alloc_value + (uint32_t)cn->dst_part,
                              src_addr);
        gk_log_dspp_connect(cn, operand, 1);
        return 1;
    }
    // Canonical sim name: the guest match is case-insensitive while the
    // loader lookup is exact.
    dspp_sim_connect(dst_sim, dr->name, (uint32_t)cn->dst_part, operand);
    gk_log_dspp_connect(cn, operand, 1);
    return 1;
}

// Re-apply every retained connection touching inst (either endpoint) to the
// live sims — or, for mix nodes, to the node graph (connect-before-start
// order: a node start re-installs routes recorded while it was stopped).
// Called after a sim is created (connect-before-start order) and after a
// disconnect rebuilds a destination image.
static void gk_dsp_resync_connections(gk_item *inst, uint32_t inst_handle) {
    if (!inst) return;
    if (!inst->audio_dsp_sim && gk_mixnode_kind_of(inst) == 0) return;
    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i) {
        gk_audio_connection *cn = &g_gk.connections[i];
        if (!cn->used) continue;
        if (cn->src_item != inst_handle && cn->dst_item != inst_handle)
            continue;
        (void)gk_dsp_apply_connection(cn);
    }
}

static void gk_log_dspp_knob(uint32_t inst, const char *name, int32_t part,
                              float value, int32_t raw) {
    static uint32_t count = 0;
    if (!gk_audio_start_diag_enabled() || count >= gk_audio_dspp_diag_cap())
        return;
    ++count;
    fprintf(stderr, "[audio-dspp] knob n=%u inst=%#x %s[%d] f=%g raw=%d\n",
            count, inst, name, part, (double)value, raw);
}

// Feed a retained SetKnobPart float into the instrument's live sim through
// dsppSetKnob. Vendor swiSetKnobPart (audio_knob.c:592) converts the value
// with dsppConvertSignalToGeneric(knobType, 1<<RateShift, value) before
// ConvertFP_SF15, so a typed knob (AF_SIGNAL_TYPE_SAMPLE_RATE, OSC_FREQ,
// LFO_FREQ, WHOLE_NUMBER) reaches the DSP code as the generic value its
// scaling expects; the raw word is then clipped to the type's RawLimits
// (unsigned {1,4} clamp to [0,65535], the rest to [-32768,32767]). Writing
// value*32768 for every subtype is off by up to 44100x for a typed knob and
// lands on the rail. Unknown subtypes fail closed.
static int32_t gk_patch_graph_signal_raw(float value, uint32_t signal_type,
                                         uint32_t rate_divider);
static void gk_dsp_poke_knob(gk_item *inst, uint32_t inst_handle,
                             const char *knob_name, int32_t part, float value) {
    if (!inst || !knob_name || part < 0) return;
    if (!inst->audio_dsp_sim) {
        // R1 capture: mix-node instruments (patch/mixer templates) retain
        // knob values with no sim to poke. Log Gain/Amplitude traffic on
        // nodes through the same bounded knob line (SF15 raw, signed, as
        // gk_dsp_poke_knob) so capture runs see guest gain staging that the
        // sim-only path would hide. No behavior change.
        if (gk_mixnode_kind_of(inst) != 0) {
            int32_t raw = (int32_t)(value * 32768.0f);
            if (raw < -32768) raw = -32768;
            if (raw > 32767) raw = 32767;
            gk_log_dspp_knob(inst_handle, knob_name, part, value, raw);
        }
        return;
    }
    dspp_sim *sim = (dspp_sim *)inst->audio_dsp_sim;
    const dspp_resource *r = gk_dsp_find_resource(sim, knob_name);
    if (!r || r->type != 1u /* DRSC_TYPE_KNOB */ ||
        r->alloc_value == 0xFFFFFFFFu || (uint32_t)part >= r->many) {
        gk_log_dspp_knob(inst_handle, knob_name, part, value, 0x7FFFFFFF);
        return;
    }
    if (r->subtype > 5u) {
        gk_log_dspp_knob(inst_handle, knob_name, part, value, 0x7FFFFFFF);
        return;
    }
    const uint32_t rate_divider =
        inst->calc_rate_divider ? inst->calc_rate_divider : 1u;
    const int32_t raw =
        gk_patch_graph_signal_raw(value, r->subtype, rate_divider);
    if (r->subtype != 0u && r->subtype != 1u) {
        // Bounded observation of the typed-knob conversion (M2_KNOBTYPE_DIAG):
        // a nonzero line means this write was landing on the rail before the
        // swiSetKnobPart conversion was applied.
        static int knobtype_diag = -1;
        static uint32_t knobtype_n = 0;
        if (knobtype_diag < 0) {
            const char *e = getenv("M2_KNOBTYPE_DIAG");
            knobtype_diag = (e && *e && *e != '0') ? 1 : 0;
        }
        if (knobtype_diag && knobtype_n < 64u) {
            ++knobtype_n;
            fprintf(stderr,
                    "[knobtype] n=%u inst=%#x %s[%d] type=%u f=%g raw=%d\n",
                    knobtype_n, inst_handle, knob_name, part, r->subtype,
                    (double)value, raw);
        }
    }
    dspp_sim_poke_data(sim, r->alloc_value + (uint32_t)part,
                       (uint16_t)(raw & 0xFFFF));
    gk_log_dspp_knob(inst_handle, knob_name, part, value, raw);
}

// SetKnobPart writes the owner's allocated DSP word immediately, even when
// the instrument is stopped. Runtime sims are created at StartInstrument, so
// replay the last retained value for each resource/part after the sim's
// authentic allocation/default initialization. Multiple Knob items may name
// the same resource; the vendor contract says the last SetKnobPart wins, so
// use the per-part write serial rather than Item-slot order.
static void gk_dsp_sync_retained_knobs(gk_item *instrument,
                                       uint32_t instrument_handle) {
    if (!instrument || !instrument->audio_dsp_sim) return;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *knob = &g_gk.items[i];
        if (!knob->used || knob->ctype != GK_AUDIO_KNOB_CTYPE ||
            knob->knob_instrument != instrument_handle)
            continue;
        for (uint32_t part = 0; part < knob->knob_parts; ++part) {
            if (!knob->knob_value_set[part]) continue;
            const uint64_t order = knob->knob_value_order[part];
            int latest = 1;
            for (uint32_t j = 0; j < GK_MAX_ITEMS; ++j) {
                const gk_item *other = &g_gk.items[j];
                if (!other->used || other->ctype != GK_AUDIO_KNOB_CTYPE ||
                    other->knob_instrument != instrument_handle ||
                    other->knob_parts <= part ||
                    !other->knob_value_set[part] ||
                    !gk_audio_name_equal(other->audio_name,
                                         knob->audio_name))
                    continue;
                if (other->knob_value_order[part] > order) {
                    latest = 0;
                    break;
                }
            }
            if (latest)
                gk_dsp_poke_knob(instrument, instrument_handle,
                                 knob->audio_name, (int32_t)part,
                                 knob->knob_values[part]);
        }
    }
}

int32_t m2_guest_audio_connect_instrument_parts(
    PPCContext *cpu, uint32_t src_instrument, uint32_t src_name_ea,
    int32_t src_part, uint32_t dst_instrument, uint32_t dst_name_ea,
    int32_t dst_part) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *src = gk_live_item(src_instrument);
    gk_item *dst = gk_live_item(dst_instrument);
    if (!src || src->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        !dst || dst->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;

    char src_name[GK_MAX_NAME_LEN];
    char dst_name[GK_MAX_NAME_LEN];
    if (gk_copy_audio_name(cpu, src_name_ea, src_name) < 0 ||
        gk_copy_audio_name(cpu, dst_name_ea, dst_name) < 0)
        return M2_AUDIO_ERR_BAD_PTR;

    // The original SWI checks destination occupancy before DSP resource
    // validation, so preserve that observable ordering.
    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i) {
        const gk_audio_connection *connection = &g_gk.connections[i];
        if (connection->used && connection->dst_item == dst_instrument &&
            connection->dst_part == dst_part &&
            gk_audio_name_equal(connection->dst_name, dst_name))
            return M2_AUDIO_ERR_IN_USE;
    }

    uint8_t src_type = 0;
    uint32_t src_parts = 0;
    int32_t result = gk_find_audio_port(src, src_name, &src_type, &src_parts);
    if (result < 0) return result;
    if (src_type != M2_DSP_RESOURCE_OUTPUT)
        return M2_AUDIO_ERR_NAME_MISSING;
    if (src_part < 0 || (uint32_t)src_part >= src_parts)
        return M2_AUDIO_ERR_OUT_OF_RANGE;

    uint8_t dst_type = 0;
    uint32_t dst_parts = 0;
    result = gk_find_audio_port(dst, dst_name, &dst_type, &dst_parts);
    if (result < 0) return result;
    if (dst_type != M2_DSP_RESOURCE_INPUT &&
        dst_type != M2_DSP_RESOURCE_KNOB)
        return M2_AUDIO_ERR_NAME_MISSING;
    if (dst_part < 0 || (uint32_t)dst_part >= dst_parts)
        return M2_AUDIO_ERR_OUT_OF_RANGE;

    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i) {
        gk_audio_connection *connection = &g_gk.connections[i];
        if (connection->used) continue;
        memset(connection, 0, sizeof(*connection));
        connection->used = 1;
        connection->src_item = src_instrument;
        connection->dst_item = dst_instrument;
        connection->src_part = src_part;
        connection->dst_part = dst_part;
        memcpy(connection->src_name, src_name, sizeof(connection->src_name));
        memcpy(connection->dst_name, dst_name, sizeof(connection->dst_name));
        gk_mix_graph_touch();
        // Apply to the live sims when both endpoints run DSP code (e.g. a
        // start-later order re-applies at sim creation); sample-backed or
        // import-blocked endpoints without a sim skip without fabrication.
        (void)gk_dsp_apply_connection(connection);
        // A new route can graph-route a started sampler (suppress its direct
        // voice) or complete a chain; recompute the partition.
        gk_voice_partition_refresh();
        return M2K_OK;
    }
    return M2_AUDIO_ERR_NO_MEMORY;
}

// DisconnectInstrumentParts only identifies a connection by its destination
// instrument, destination port name, and destination part. The original SWI
// checks that destination Item, validates the guest name pointer, then looks
// up the matching connection before asking the DSP layer to disconnect it.
// The DSP layer restores the relocation default at the removed endpoint
// (dsppDisconnectInstrumentParts re-runs dsppGetResourceRelocationValue),
// or drops the MOVE for a MOVE-connected endpoint (early return after
// dsppDisconnectWithMove); the bounded host mirrors both through the same
// loader call.

int32_t m2_guest_audio_disconnect_instrument_parts(
    PPCContext *cpu, uint32_t dst_instrument, uint32_t dst_name_ea,
    int32_t dst_part) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *dst = gk_live_item(dst_instrument);
    if (!dst || dst->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;

    char dst_name[GK_MAX_NAME_LEN];
    if (gk_copy_audio_name(cpu, dst_name_ea, dst_name) < 0)
        return M2_AUDIO_ERR_BAD_PTR;

    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i) {
        gk_audio_connection *connection = &g_gk.connections[i];
        if (!connection->used || connection->dst_item != dst_instrument ||
            connection->dst_part != dst_part ||
            !gk_audio_name_equal(connection->dst_name, dst_name))
            continue;
        char hit_name[GK_MAX_NAME_LEN];
        int32_t hit_part = connection->dst_part;
        memcpy(hit_name, connection->dst_name, sizeof(hit_name));
        uint32_t hit_src = connection->src_item;
        memset(connection, 0, sizeof(*connection));
        gk_mix_graph_touch();
        // Restore the endpoint: relocation default at the removed endpoint's
        // sites, or drop the recorded MOVE copy for a BIND+RBASE endpoint
        // (vendor dsppDisconnectInstrumentParts); other connections and
        // data memory are undisturbed, and links always re-walk from the
        // pristine image.
        if (dst->audio_dsp_sim)
            dspp_sim_disconnect((dspp_sim *)dst->audio_dsp_sim, hit_name,
                                (uint32_t)hit_part);
        // A dropped route can silence a sampler graph-routed before the drop;
        // recompute the partition.
        gk_voice_partition_refresh();
        // Generated-mixer hop teardown: free the source node's output
        // reservation when this was its last live carrier into any sim (a
        // node with no remaining sim destination keeps no words reserved).
        {
            int still_wired = 0;
            for (uint32_t j = 0; j < GK_MAX_AUDIO_CONNECTIONS; ++j) {
                const gk_audio_connection *rest = &g_gk.connections[j];
                if (rest->used && rest->src_item == hit_src &&
                    gk_live_item(rest->dst_item) &&
                    gk_live_item(rest->dst_item)->audio_dsp_sim)
                    still_wired = 1;
            }
            if (!still_wired) gk_mixnode_release_words(hit_src);
        }
        return M2K_OK;
    }
    return M2_AUDIO_ERR_BAD_PTR;
}

static const uint8_t *gk_audio_sample_bytes(PPCContext *cpu,
                                             const gk_item *sample) {
    if (!cpu || !cpu->mem || !sample || sample->sample_address == 0u ||
        sample->sample_num_bytes == 0u ||
        sample->sample_address >= RECOMP_GUEST_MEM ||
        sample->sample_num_bytes > RECOMP_GUEST_MEM - sample->sample_address)
        return NULL;
    return cpu->mem + sample->sample_address;
}

static float gk_audio_stream_gain(const gk_item *instrument) {
    if (!instrument || (instrument->audio_start_tags & 1u) == 0u)
        return 1.0f;
    return instrument->audio_start_4e;
}

static int gk_audio_stream_is_pcm16be(const gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return 0;
    const gk_item *tpl = gk_live_item(instrument->template_item);
    return tpl && tpl->ctype == GK_AUDIO_TEMPLATE_CTYPE &&
           gk_audio_name_equal(tpl->audio_name, "sampler_16_f2.dsp");
}

// The recovered SoundSpooler publishes byte-width placeholders, but the
// selected sampler still imposes a host-visible frame shape: CBD2 consumes
// stereo byte pairs, while sampler_16_f2 consumes big-endian stereo S16
// pairs. Keep malformed buffers from being reported as successfully started
// after the host adapter rejected them.
static int32_t gk_audio_stream_data_status(const gk_item *instrument,
                                           const uint8_t *bytes,
                                           uint32_t byte_count) {
    // SoundSpooler may start an addressless width-1 placeholder while its
    // fill path is still pending. That is a legal guest-side setup state; it
    // is not a host playback segment and is completed by a later populated
    // StartAttachment call.
    if (!bytes && byte_count == 0u) return M2K_OK;
    if (!bytes) return M2_AUDIO_ERR_BAD_PTR;
    if (gk_audio_stream_is_pcm16be(instrument)) {
        if (byte_count < 4u || (byte_count & 3u) != 0u)
            return M2_AUDIO_ERR_OUT_OF_RANGE;
    } else if (byte_count < 2u || (byte_count & 1u) != 0u) {
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    }
    return M2K_OK;
}

// LinkAttachments retains the successor attachment in the guest-visible
// attachment chain. For the recovered SoundSpooler shape, mirror the same
// link into the host's authentic CBD2 sampler queue; for two physical delay
// samples, validate the source-required same-FIFO relationship so the
// completion pump can perform the bounded current/next promotion. Att2 == 0
// removes the pending successor without changing guest ownership.
int32_t m2_guest_audio_link_attachments(PPCContext *cpu,
                                        uint32_t attachment1,
                                        uint32_t attachment2) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *first = gk_live_item(attachment1);
    if (!first || first->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
        first->attachment_type != 1u)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master1 = gk_live_item(first->attachment_master);
    if (!master1 || master1->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_MISMATCH;
    if (attachment2 == 0) {
        m2_host_audio_unlink_cbd2_stream(first->attachment_master,
                                         attachment1);
        first->attachment_next = 0;
        gk_update_delay_attachment_interrupt(first);
        return M2K_OK;
    }
    gk_item *second = gk_live_item(attachment2);
    if (!second || second->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
        second->attachment_type != 1u)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master2 = gk_live_item(second->attachment_master);
    if (!master2 || master2->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        master1 != master2)
        return M2_AUDIO_ERR_MISMATCH;
    gk_item *sample1 = gk_live_item(first->attachment_slave);
    gk_item *sample2 = gk_live_item(second->attachment_slave);
    const int physical1 =
        sample1 && sample1->ctype == GK_AUDIO_SAMPLE_CTYPE &&
        sample1->sample_kind == 1u;
    const int physical2 =
        sample2 && sample2->ctype == GK_AUDIO_SAMPLE_CTYPE &&
        sample2->sample_kind == 1u;
    if (physical1 || physical2) {
        // The loader's physical channel has one FIFO binding. Mixing its
        // supervisor delay-line state with a host PCM/CBD2 adapter would
        // fabricate a second current descriptor, so keep that unsupported
        // combination fail-closed. A source-defined patch graph is the
        // recovered exception: its exposed FIFO belongs to a constituent
        // DSPP image, not to the patch shell.
        if (!physical1 || !physical2 ||
            (gk_mixnode_kind_of(master1) != 0 &&
             (gk_mixnode_kind_of(master1) != 1 ||
              master1->audio_patch_graph == NULL)))
            return M2_AUDIO_ERR_MISMATCH;
        dspp_sim *sim = NULL;
        if (gk_mixnode_kind_of(master1) == 1) {
            if (!master1->audio_patch_graph) {
                const int create_rc = gk_patch_graph_create(
                    master1, first->attachment_master);
                if (create_rc == -2)
                    return M2_AUDIO_ERR_EXTERNALREF;
                if (create_rc != 0)
                    return M2_AUDIO_ERR_UNIMPLEMENTED;
            }
            if (!master1->audio_patch_graph)
                return M2_AUDIO_ERR_UNIMPLEMENTED;
        } else if (!master1->audio_dsp_sim) {
            const int create_rc = gk_dsp_sim_create_for(
                master1, first->attachment_master);
            if (create_rc == -2)
                return M2_AUDIO_ERR_EXTERNALREF;
            if (create_rc != 0 || !master1->audio_dsp_sim)
                return M2_AUDIO_ERR_UNIMPLEMENTED;
            sim = (dspp_sim *)master1->audio_dsp_sim;
        } else {
            sim = (dspp_sim *)master1->audio_dsp_sim;
        }
        const char *hook1 = first->attachment_has_hook
                                ? first->attachment_hook
                                : NULL;
        const char *hook2 = second->attachment_has_hook
                                ? second->attachment_hook
                                : NULL;
        uint32_t channel1 = 0u, channel2 = 0u;
        int output1 = 0, output2 = 0;
        int32_t rc = gk_mixnode_kind_of(master1) == 1
                         ? gk_patch_graph_fifo(master1, hook1, &sim,
                                               &channel1, &output1)
                         : gk_resolve_fifo_channel(sim, hook1, &channel1,
                                                   &output1);
        if (rc != M2K_OK) return rc;
        rc = gk_mixnode_kind_of(master1) == 1
                 ? gk_patch_graph_fifo(master1, hook2, &sim, &channel2,
                                       &output2)
                 : gk_resolve_fifo_channel(sim, hook2, &channel2, &output2);
        if (rc != M2K_OK) return rc;
        if (channel1 != channel2 || output1 != output2)
            return M2_AUDIO_ERR_MISMATCH;
    }
    if (sample1 && sample2 && sample1->ctype == GK_AUDIO_SAMPLE_CTYPE &&
        sample2->ctype == GK_AUDIO_SAMPLE_CTYPE &&
        sample1->sample_stream_placeholder &&
        sample2->sample_stream_placeholder) {
        // Before StartInstrument the source queue may be linked before the
        // sampler owns a host stream; StartAttachment walks this retained
        // guest chain and publishes it then. Once the instrument is running,
        // a failed host append must remain visible to the caller and must not
        // leave the guest and host queues claiming different successors.
        if (master1->audio_started && !first->attachment_stopped) {
            const uint8_t *bytes = gk_audio_sample_bytes(cpu, sample2);
            const int32_t data_status = gk_audio_stream_data_status(
                master1, bytes, sample2->sample_num_bytes);
            if (data_status != M2K_OK) return data_status;
            const int32_t link_status =
                gk_audio_stream_is_pcm16be(master1)
                    ? m2_host_audio_link_pcm16be_stream(
                          first->attachment_master, attachment1,
                          attachment2, bytes, sample2->sample_num_bytes)
                    : m2_host_audio_link_cbd2_stream(
                          first->attachment_master, attachment1,
                          attachment2, bytes, sample2->sample_num_bytes);
            if (link_status <= 0) return M2_AUDIO_ERR_NO_MEMORY;
            // The host stream promotes queued buffers without another guest
            // StartAttachment call (vendor ProcessAttachmentDMA starts the
            // successor). Its eventual completion must not be suppressed by
            // the attachment's initial/stopped state.
            // A callback may have consumed the first attachment before this
            // thread observes its Cue. Vendor LinkAttachments then retains a
            // future link only; it must not start or arm completion for next.
            if (link_status == 1) second->attachment_stopped = 0u;
        }
    }
    first->attachment_next = attachment2;
    gk_update_delay_attachment_interrupt(first);
    return M2K_OK;
}

static void gk_log_audio_attachment_start(PPCContext *cpu,
                                          uint32_t attachment,
                                          uint32_t taglist_ea,
                                          int32_t result) {
    static uint32_t count;
    if (!gk_audio_start_diag_enabled() || count >= 64u) return;
    ++count;
    gk_item *a = gk_live_item(attachment);
    gk_item *s = a ? gk_live_item(a->attachment_slave) : NULL;
    fprintf(stderr,
            "[audio-attachment] n=%u att=%#x type=%u master=%#x "
            "slave=%#x sample_type=%u placeholder=%u sid=%u addr=%#x "
            "bytes=%u tags=%#x caller=%#x rc=%d\n",
            count, attachment, a ? a->attachment_type : 0u,
            a ? a->attachment_master : 0u, a ? a->attachment_slave : 0u,
            s ? s->ctype : 0u, s ? s->sample_stream_placeholder : 0u,
            s ? s->host_sample_id : 0u, s ? s->sample_address : 0u,
            s ? s->sample_num_bytes : 0u, taglist_ea, cpu ? cpu->lr : 0u,
            result);
}

// StartAttachment validates the attachment, then starts voice playback if the
// sample data has been uploaded to the host backend. SoundSpooler samples are
// byte-stream placeholders (AF_TAG_WIDTH=1); the host CBD2 sampler consumes
// their published bytes while preserving the DSP predictor across links.
int32_t m2_guest_audio_start_attachment(PPCContext *cpu,
                                        uint32_t attachment,
                                        uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(attachment);
    if (!live || live->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (taglist_ea != 0)
        return M2_AUDIO_ERR_BAD_TAG;
    gk_item *master = gk_live_item(live->attachment_master);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (live->attachment_type != 1u && live->attachment_type != 2u)
        return M2_AUDIO_ERR_BAD_ITEM;
    // Starting an attachment leaves AF_STOPPED (DSPPStartSampleAttachment /
    // DSPPStartEnvAttachment both raise aatt_ActivityLevel), so a Cue
    // suppressed by an earlier StopAttachment can be delivered again.
    live->attachment_stopped = 0u;

    // For sample attachments, attempt host playback if sample is uploaded
    if (live->attachment_type == 1u) {
        gk_item *sample = gk_live_item(live->attachment_slave);
        if (sample && sample->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            sample->sample_kind == 1u) {
            const int32_t result = gk_bind_delay_attachment(live);
            gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                          result);
            return result;
        }
        if (sample && sample->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            sample->host_sample_id != 0u) {
            const float rate_hz = (master->audio_start_tags & 2u)
                                      ? (master->audio_start_rate_is_relative
                                             ? master->audio_start_4f * sample->sample_rate
                                             : master->audio_start_4f)
                                      : sample->sample_rate;
            const float gain = (master->audio_start_tags & 1u)
                                   ? master->audio_start_4e
                                   : 1.0f;
            int32_t result =
                m2_host_audio_start_voice_indexed_for_attachment_with_params(
                    sample->host_sample_id, attachment,
                    sample->sample_sustain_begin, sample->sample_sustain_end,
                    sample->sample_release_begin, sample->sample_release_end,
                    rate_hz, gain);
            if (result >= 0) {
                // aatt_Channel: the mixer slot this attachment now owns, so
                // StopAttachment stops exactly this voice.
                live->attachment_voice = result;
                if (result < 32) {
                    master->audio_voice_mask |= (1u << (uint32_t)result);
                }
                // A newly started/restarted host voice defaults to direct
                // playback. Apply the retained graph route just as
                // StartInstrument does, or it also plays unattenuated in
                // the SDL mix. Sim-backed adapters retain their own path.
                gk_mix_graph_touch();
                if (!master->audio_dsp_sim) gk_voice_partition_refresh();
                gk_log_audio_attachment_start(cpu, attachment, taglist_ea, M2K_OK);
                return M2K_OK;
            }
            gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                          M2_AUDIO_ERR_NO_MEMORY);
            return M2_AUDIO_ERR_NO_MEMORY;  // all voices busy
        }
        if (sample && sample->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            sample->sample_stream_placeholder) {
            const uint8_t *bytes = gk_audio_sample_bytes(cpu, sample);
            const int32_t data_status = gk_audio_stream_data_status(
                master, bytes, sample->sample_num_bytes);
            if (data_status != M2K_OK) {
                gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                              data_status);
                return data_status;
            }
            if (!bytes && sample->sample_num_bytes == 0u) {
                gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                              M2K_OK);
                return M2K_OK;
            }
            const int32_t host_status = gk_audio_stream_is_pcm16be(master)
                                            ? m2_host_audio_start_pcm16be_stream(
                                                  live->attachment_master,
                                                  attachment, bytes,
                                                  sample->sample_num_bytes,
                                                  gk_audio_stream_gain(master))
                                            : m2_host_audio_start_cbd2_stream(
                                                  live->attachment_master,
                                                  attachment, bytes,
                                                  sample->sample_num_bytes,
                                                  gk_audio_stream_gain(master));
            if (host_status <= 0) {
                // StartAttachment returns the sample-start error. The host
                // stream adapter exposes allocation/materialization failure
                // as a non-positive result, so keep that failure visible at
                // the guest boundary instead of reporting false success.
                gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                              M2_AUDIO_ERR_NO_MEMORY);
                return M2_AUDIO_ERR_NO_MEMORY;
            }
            // A queue can be assembled before StartInstrument. Publish any
            // already-linked successors now that the sampler owns a stream.
            uint32_t first = attachment;
            uint32_t next = live->attachment_next;
            for (uint32_t n = 0; next != 0u && n < GK_MAX_ITEMS; ++n) {
                gk_item *successor = gk_live_item(next);
                if (!successor || successor->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
                    break;
                gk_item *successor_sample =
                    gk_live_item(successor->attachment_slave);
                if (!successor_sample ||
                    successor_sample->ctype != GK_AUDIO_SAMPLE_CTYPE ||
                    !successor_sample->sample_stream_placeholder)
                    break;
                const uint8_t *successor_bytes =
                    gk_audio_sample_bytes(cpu, successor_sample);
                const int32_t successor_status = gk_audio_stream_data_status(
                    master, successor_bytes, successor_sample->sample_num_bytes);
                if (successor_status != M2K_OK) {
                    gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                                  successor_status);
                    return successor_status;
                }
                const int32_t link_status =
                    gk_audio_stream_is_pcm16be(master)
                        ? m2_host_audio_link_pcm16be_stream(
                              live->attachment_master, first, next,
                              successor_bytes,
                              successor_sample->sample_num_bytes)
                        : m2_host_audio_link_cbd2_stream(
                              live->attachment_master, first, next,
                              successor_bytes,
                              successor_sample->sample_num_bytes);
                if (link_status <= 0) {
                    gk_log_audio_attachment_start(
                        cpu, attachment, taglist_ea, M2_AUDIO_ERR_NO_MEMORY);
                    return M2_AUDIO_ERR_NO_MEMORY;
                }
                first = next;
                successor->attachment_stopped = 0u;
                next = successor->attachment_next;
            }
            gk_log_audio_attachment_start(cpu, attachment, taglist_ea, M2K_OK);
            return M2K_OK;
        }
    }
    if (live->attachment_type == 2u) {
        const uint64_t clock_frames = gk_audio_clock_read(
            m2_host_audio_frame_count(), 0);
        const uint32_t now = (uint32_t)(
            clock_frames / GK_AUDIO_GLOBAL_CLOCK_DURATION);
        const int32_t result = gk_start_envelope_attachment(
            live, master->audio_start_pitch_note,
            master->audio_start_time_scale, now);
        gk_log_audio_attachment_start(cpu, attachment, taglist_ea, result);
        return result;
    }
    gk_log_audio_attachment_start(cpu, attachment, taglist_ea,
                                  M2_AUDIO_ERR_UNIMPLEMENTED);
    return M2_AUDIO_ERR_UNIMPLEMENTED;
}

// ---- Numeric DSPP descriptor attach seam (folio 6 attach boundary) --------
// Vendor ground: internalCreateAudioAttachment validates the sample hook
// (ws_root/src/folios/audio/audio_attachments.c: unknown hook keeps the
// BAD_NAME lookup error; non-FIFO port -> AF_ERR_BAD_PORT_TYPE; ordinary
// sample to an OUT_FIFO -> AF_ERR_SECURITY) and DSPPAttachSample binds the
// hook to its FIFO channel (dspp_instr.c:1702-1730; NULL hook takes the only
// FIFO, dsppFindFIFOByName at dspp_instr.c:1636-1654, else AF_ERR_BAD_NAME),
// where the numeric address/count descriptor shape is validated by
// dspp_sim_dma_attach_numeric in the loader. This seam wires the same order
// after the StartAttachment-style master/type validation: pure-synth and
// no-upload instruments (no buildable DSP image) stay at UNIMPLEMENTED;
// 0x4E/0x4F start tags are retained uninterpreted; started/busy instruments
// report NO_MEMORY; then hook resolution with the loader rc mapping below.
// Re-attaching a channel replaces its record and count-0+address-0 stays
// allowed (loader contract); unbuilt nodes are never fabricated (BAD_ITEM
// for dead handles, NAME_MISSING for unresolvable hooks). Live current/next
// host buffers, FIFO words, and interrupt banks are untouched, so a numeric
// descriptor alone never moves samples, raises signals, or completes.
static int32_t gk_resolve_fifo_channel(dspp_sim *sim, const char *hook,
                                       uint32_t *channel_out,
                                       int *is_out_fifo_out) {
    if (channel_out) *channel_out = 0;
    if (is_out_fifo_out) *is_out_fifo_out = 0;
    if (!sim) return M2_AUDIO_ERR_BAD_ITEM;
    const dspp_template *res = dspp_sim_resources(sim);
    if (!res) return M2_AUDIO_ERR_BAD_ITEM;
    if (!hook) {
        // Vendor dsppFindFIFOByName NULL path: the default hook resolves
        // only when the instrument carries exactly one FIFO.
        uint32_t channel = 0;
        int out = 0, count = 0;
        for (uint32_t i = 0; i < res->resource_count; ++i) {
            uint8_t t = res->resources[i].type;
            if (t != 5u /* DRSC_TYPE_IN_FIFO */ &&
                t != 6u /* DRSC_TYPE_OUT_FIFO */)
                continue;
            ++count;
            channel = res->resources[i].alloc_value;
            out = (t == 6u);
        }
        if (count != 1) return M2_AUDIO_ERR_NAME_MISSING;
        // Unbuilt channel allocation binds nothing; never fabricate.
        if (channel == 0xFFFFFFFFu || channel >= 32u /* DSPI_NUM_DMA_CHANNELS */)
            return M2_AUDIO_ERR_NAME_MISSING;
        if (channel_out) *channel_out = channel;
        if (is_out_fifo_out) *is_out_fifo_out = out;
        return M2K_OK;
    }
    const dspp_resource *r = gk_dsp_find_resource(sim, hook);
    if (!r) return M2_AUDIO_ERR_NAME_MISSING;
    // Vendor AF_ERR_BAD_PORT_TYPE surfaces on the folio as MISMATCH.
    if (r->type != 5u /* DRSC_TYPE_IN_FIFO */ &&
        r->type != 6u /* DRSC_TYPE_OUT_FIFO */)
        return M2_AUDIO_ERR_MISMATCH;
    if (r->alloc_value == 0xFFFFFFFFu || r->alloc_value >= 32u)
        return M2_AUDIO_ERR_NAME_MISSING;
    if (channel_out) *channel_out = r->alloc_value;
    if (is_out_fifo_out) *is_out_fifo_out = (r->type == 6u);
    return M2K_OK;
}
// Copy a folio sample-hook name: hook_name_ea 0 is the vendor NULL default;
// faults fail closed with BAD_PTR (connect-instrument-parts rule). An empty
// string finds no resource and reports NAME_MISSING through the resolver.
static int32_t gk_copy_fifo_hook(PPCContext *cpu, uint32_t hook_name_ea,
                                 char out[GK_MAX_NAME_LEN],
                                 const char **hook_out) {
    if (hook_out) *hook_out = NULL;
    if (hook_name_ea == 0u) return M2K_OK; // vendor NULL default
    if (!out || !gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem ||
        hook_name_ea >= RECOMP_GUEST_MEM ||
        m2m_copy_guest_string_ctx(cpu, hook_name_ea, out,
                                  GK_MAX_NAME_LEN) < 0)
        return M2_AUDIO_ERR_BAD_PTR;
    if (hook_out) *hook_out = out;
    return M2K_OK;
}

// Bind one original delay-line Sample attachment to the instrument's actual
// FIFO resource. This is the physical Audio Folio seam: the guest still owns
// the Item/attachment relationship, while the host only supplies the
// supervisor delay buffer and FDMA channel state. A source-defined patch
// resolves its exposed FIFO through the constituent graph; authored physical
// loop/release ranges stay attached to the loader-owned phase scheduler.
static int32_t gk_bind_delay_attachment(gk_item *attachment) {
    if (!attachment || !attachment->used ||
        attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
        attachment->attachment_type != 1u)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master = gk_live_item(attachment->attachment_master);
    gk_item *sample = gk_live_item(attachment->attachment_slave);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE || !sample ||
        sample->ctype != GK_AUDIO_SAMPLE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (sample->sample_kind != 1u || !sample->sample_delay_line)
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    const int graph_patch = gk_mixnode_kind_of(master) == 1 &&
                            master->audio_patch_graph != NULL;
    if (gk_mixnode_kind_of(master) != 0 && !graph_patch)
        return M2_AUDIO_ERR_UNIMPLEMENTED;

    dspp_sim *sim = NULL;
    if (graph_patch) {
        const char *hook_arg = attachment->attachment_has_hook
                                   ? attachment->attachment_hook
                                   : NULL;
        int32_t hook_rc = gk_patch_graph_fifo(
            master, hook_arg, &sim, NULL, NULL);
        if (hook_rc != M2K_OK) return hook_rc;
        if (!sim) return M2_AUDIO_ERR_UNIMPLEMENTED;
    } else if (!master->audio_dsp_sim) {
        const int32_t create_rc = gk_dsp_sim_create_for(
            master, attachment->attachment_master);
        if (create_rc == -2)
            return M2_AUDIO_ERR_EXTERNALREF;
        if (create_rc != 0 || !master->audio_dsp_sim)
            return M2_AUDIO_ERR_UNIMPLEMENTED;
        sim = (dspp_sim *)master->audio_dsp_sim;
    } else {
        sim = (dspp_sim *)master->audio_dsp_sim;
    }
    const char *hook_arg = attachment->attachment_has_hook
                               ? attachment->attachment_hook
                               : NULL;
    uint32_t channel = 0u;
    int is_out = 0;
    int32_t hook_rc = graph_patch
                          ? gk_patch_graph_fifo(master, hook_arg, NULL,
                                                &channel, &is_out)
                          : gk_resolve_fifo_channel(sim, hook_arg, &channel,
                                                    &is_out);
    if (hook_rc != M2K_OK) return hook_rc;

    const uint64_t frame_count =
        (uint64_t)sample->sample_num_bytes /
        ((uint64_t)sample->sample_channels * 2u);
    if (frame_count == 0u ||
        (uint64_t)attachment->attachment_start_at >= frame_count ||
        (is_out && attachment->attachment_start_at != 0))
        return M2_AUDIO_ERR_OUT_OF_RANGE;

    if (attachment->attachment_delay_bound) {
        if (channel != attachment->attachment_delay_channel ||
            is_out != (attachment->attachment_delay_output != 0u) ||
            attachment->attachment_delay_sim != sim)
            return M2_AUDIO_ERR_MISMATCH;
        if (dspp_sim_dma_restart_delay_line(
                sim, channel, sample->sample_delay_line, is_out,
                (uint32_t)attachment->attachment_start_at) != 0)
            return M2_AUDIO_ERR_IN_USE;
        gk_update_delay_attachment_interrupt(attachment);
        return M2K_OK;
    }

    if (dspp_sim_dma_attach_delay_line(
            sim, channel, sample->sample_delay_line, is_out,
            (uint32_t)attachment->attachment_start_at) != 0)
        return M2_AUDIO_ERR_IN_USE;
    attachment->attachment_delay_channel = channel;
    attachment->attachment_delay_bound = 1u;
    attachment->attachment_delay_output = is_out ? 1u : 0u;
    attachment->attachment_delay_sim = sim;
    gk_update_delay_attachment_interrupt(attachment);
    return M2K_OK;
}

static void gk_update_delay_attachment_interrupt(gk_item *attachment) {
    if (!attachment || !attachment->attachment_delay_bound) return;
    dspp_sim *sim = attachment->attachment_delay_sim;
    if (!sim) {
        gk_item *master = gk_live_item(attachment->attachment_master);
        if (master && master->ctype == GK_AUDIO_INSTRUMENT_CTYPE)
            sim = (dspp_sim *)master->audio_dsp_sim;
    }
    if (!sim)
        return;
    // Vendor IsAttSignalNeeded: a Cue, a successor, or a live
    // FATLADYSINGS segment arms the channel's DMANext interrupt. The
    // physical delay adapter exposes the same event-vector bit; the folio
    // daemon, not this helper, owns Cue delivery.
    const int needed = attachment->attachment_cue != 0u ||
                       attachment->attachment_next != 0u ||
                       (attachment->attachment_flags &
                        M2_AUDIO_ATTACHMENT_FLAG_FATLADYSINGS) != 0u;
    dspp_sim_dma_set_channel_interrupt(
        sim, attachment->attachment_delay_channel, needed);
    if (gk_audio_start_diag_enabled()) {
        static uint32_t count;
        if (count < 64u) {
            ++count;
            fprintf(stderr,
                    "[audio-delay] interrupt att=%#x ch=%u cue=%#x "
                    "next=%#x flags=%#x needed=%d enabled=%d\n",
                    gk_make_handle(
                        GK_TYPE_ITEM_VA,
                        (uint32_t)(attachment - g_gk.items),
                        attachment->generation),
                    attachment->attachment_delay_channel,
                    attachment->attachment_cue,
                    attachment->attachment_next,
                    attachment->attachment_flags, needed,
                    dspp_sim_dma_channel_interrupt_enabled(
                        (const dspp_sim *)sim,
                        attachment->attachment_delay_channel));
        }
    }
}

// Stop and detach one physical delay attachment. Stop is explicit platform
// state (and may trigger AF_SAMPF_CLEARONSTOP); it does not enqueue a Cue
// completion. Natural finite completion is recorded by the DSPP seam before
// this helper is needed for teardown.
static void gk_unbind_delay_attachment(gk_item *attachment) {
    if (!attachment || !attachment->attachment_delay_bound) return;
    dspp_sim *sim = attachment->attachment_delay_sim;
    if (!sim) {
        gk_item *master = gk_live_item(attachment->attachment_master);
        if (master && master->audio_dsp_sim)
            sim = (dspp_sim *)master->audio_dsp_sim;
    }
    if (sim) {
        (void)dspp_sim_dma_stop_delay_line(
            sim, attachment->attachment_delay_channel);
        dspp_sim_dma_detach_delay_line(
            sim, attachment->attachment_delay_channel);
    }
    attachment->attachment_delay_channel = 0u;
    attachment->attachment_delay_bound = 0u;
    attachment->attachment_delay_output = 0u;
    attachment->attachment_delay_sim = NULL;
}

static void gk_stop_delay_attachments(gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            gk_live_item(attachment->attachment_master) != instrument)
            continue;
        gk_unbind_delay_attachment(attachment);
    }
}

static int32_t gk_start_delay_attachments(gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    // A port-only patch has no constituent FIFO. A source-shaped patch graph
    // does: its exposed attachment endpoints are bound below.
    if (gk_mixnode_kind_of(instrument) != 0 &&
        instrument->audio_patch_graph == NULL)
        return M2K_OK;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 1u ||
            gk_live_item(attachment->attachment_master) != instrument)
            continue;
        gk_item *sample = gk_live_item(attachment->attachment_slave);
        if (!sample || sample->ctype != GK_AUDIO_SAMPLE_CTYPE ||
            sample->sample_kind != 1u)
            continue;
        if (attachment->attachment_flags &
            M2_AUDIO_ATTACHMENT_FLAG_NOAUTOSTART)
            continue;
        const int32_t rc = gk_bind_delay_attachment(attachment);
        if (rc != M2K_OK) {
            gk_stop_delay_attachments(instrument);
            return rc;
        }
    }
    return M2K_OK;
}

// ---- Audio envelope attachment service -------------------------------------
// The vendor AudioEnvExtension is a single pending AudioEvent plus four DSPP
// data-resource addresses. Keep that same ownership split here: the guest
// owns the EnvelopeSegment array and all envelope decisions remain in the
// source-shaped attachment state; the host only writes the original DSPP
// control words and advances the recovered audio-clock event.
static int32_t gk_envelope_resource_addresses(
    gk_item *attachment, uint32_t *request_out, uint32_t *incr_out,
    uint32_t *target_out, uint32_t *current_out) {
    if (request_out) *request_out = 0;
    if (incr_out) *incr_out = 0;
    if (target_out) *target_out = 0;
    if (current_out) *current_out = 0;
    if (!attachment || attachment->attachment_type != 2u)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master = gk_live_item(attachment->attachment_master);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        !master->audio_dsp_sim)
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    const char *hook = attachment->attachment_has_hook
                           ? attachment->attachment_hook
                           : "Env";
    char names[4][GK_MAX_NAME_LEN];
    const char *suffixes[4] = { ".request", ".incr", ".target", ".current" };
    const uint8_t expected_types[4] = { 1u, 1u, 2u, 2u };
    uint32_t *outs[4] = { request_out, incr_out, target_out, current_out };
    for (uint32_t i = 0; i < 4u; ++i) {
        const int n = snprintf(names[i], sizeof(names[i]), "%s%s", hook,
                               suffixes[i]);
        if (n < 0 || (size_t)n >= sizeof(names[i]))
            return M2_AUDIO_ERR_NAME_MISSING;
        const dspp_resource *resource = gk_dsp_find_resource(
            (dspp_sim *)master->audio_dsp_sim, names[i]);
        if (!resource || resource->type != expected_types[i] ||
            resource->alloc_value == 0xFFFFFFFFu || resource->many == 0u)
            return resource ? M2_AUDIO_ERR_BAD_RESOURCE_TYPE
                            : M2_AUDIO_ERR_NAME_MISSING;
        if (outs[i]) *outs[i] = resource->alloc_value;
    }
    return M2K_OK;
}

static int gk_envelope_read_segment(const gk_item *envelope, int32_t index,
                                    float *value_out, float *duration_out) {
    if (value_out) *value_out = 0.0f;
    if (duration_out) *duration_out = 0.0f;
    if (!envelope || envelope->ctype != GK_AUDIO_ENVELOPE_CTYPE ||
        index < 0 || index >= envelope->envelope_num_points ||
        envelope->envelope_address == 0u || !g_gk.cpu || !g_gk.cpu->mem)
        return -1;
    const uint64_t ea = (uint64_t)envelope->envelope_address +
                        (uint64_t)(uint32_t)index * 8u;
    if (ea + 8u > RECOMP_GUEST_MEM) return -1;
    uint32_t value_bits = rd32(g_gk.cpu, (uint32_t)ea);
    uint32_t duration_bits = rd32(g_gk.cpu, (uint32_t)ea + 4u);
    if (value_out) memcpy(value_out, &value_bits, sizeof(*value_out));
    if (duration_out)
        memcpy(duration_out, &duration_bits, sizeof(*duration_out));
    return 0;
}

static int32_t gk_envelope_rate_shift(const gk_item *instrument) {
    if (!instrument) return 0;
    if (instrument->calc_rate_divider == 2u) return 1;
    if (instrument->calc_rate_divider == 8u) return 3;
    return 0;
}

static void gk_envelope_set_time_scale(gk_item *attachment,
                                       int32_t pitch_note,
                                       float time_scale) {
    gk_item *envelope = gk_live_item(attachment->attachment_slave);
    if (!envelope || envelope->ctype != GK_AUDIO_ENVELOPE_CTYPE) return;
    float scaled = 1.0f;
    if (pitch_note >= 0 && envelope->envelope_notes_per_double != 0) {
        scaled = powf(2.0f,
                      ((float)envelope->envelope_base_note -
                       (float)pitch_note) /
                          (float)envelope->envelope_notes_per_double);
    }
    if ((envelope->envelope_flags &
         M2_AUDIO_ENVELOPE_FLAG_LOCKTIMESCALE) == 0u)
        scaled *= time_scale;
    if (!isfinite(scaled)) scaled = 1.0f;
    attachment->envelope_time_scale = scaled;
}

// One source NextEnvSegment pass. `current_time` is the AudioTime at which the
// callback is being performed; callers already hold the graph boundary, and
// the timer caller also holds g_audio_timer_lock.
static int32_t gk_envelope_next_segment(gk_item *attachment,
                                        uint32_t current_time) {
    if (!attachment || attachment->attachment_type != 2u)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master = gk_live_item(attachment->attachment_master);
    gk_item *envelope = gk_live_item(attachment->attachment_slave);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        !envelope || envelope->ctype != GK_AUDIO_ENVELOPE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (attachment->envelope_cur_index >= envelope->envelope_num_points) {
        attachment->envelope_activity = 0u;
        attachment->envelope_event_posted = 0u;
        attachment->envelope_event_time = 0u;
        return M2K_OK;
    }

    uint32_t request = 0, incr = 0, target_resource = 0, current = 0;
    int32_t rc = gk_envelope_resource_addresses(
        attachment, &request, &incr, &target_resource, &current);
    if (rc != M2K_OK) return rc;

    const int32_t rate_shift = gk_envelope_rate_shift(master);
    int32_t frames;
    if (attachment->envelope_frames_left > 0) {
        frames = attachment->envelope_frames_left;
    } else {
        const float scaled_time = attachment->envelope_delta_time;
        if (!(scaled_time > 0.0f) || !isfinite(scaled_time))
            frames = 0;
        else if (scaled_time >= 2147483647.0f / 44100.0f)
            frames = INT32_MAX;
        else
            frames = (int32_t)(scaled_time * 44100.0f);
        frames >>= rate_shift;
    }

    float target = 0.0f;
    if (gk_envelope_read_segment(envelope, attachment->envelope_cur_index,
                                 &target, NULL) != 0)
        return M2_AUDIO_ERR_BAD_PTR;
    // NextEnvSegment calls dsppConvertSignalToGeneric with rateShift 0.
    // The shared conversion helper preserves the vendor's signed/unsigned and
    // whole-number clipping for the supported signal types.
    int32_t target_value = gk_patch_graph_signal_raw(
        target, envelope->envelope_signal_type, 1u);
    if (frames <= 0) frames = 1;
    if (frames > 32767) {
        // ENV_PHASERANGE is 32767; a long segment advances at the smallest
        // possible phase increment and is resumed with FramesLeft.
        frames = frames < 0 ? INT32_MAX : frames;
    }
    int32_t phase_increment;
    if (frames > 32767)
        phase_increment = 1;
    else
        phase_increment = (32767 + (frames - 1)) / frames;
    const int32_t actual_frames = 32767 / phase_increment;
    const int32_t frames_left = frames - actual_frames;
    if (((int64_t)frames_left << rate_shift) > 400) {
        float interpolated =
            ((target - attachment->envelope_prev_target) *
             (float)actual_frames) /
                (float)frames + attachment->envelope_prev_target;
        target = interpolated;
        target_value = gk_patch_graph_signal_raw(
            target, envelope->envelope_signal_type, 1u);
        attachment->envelope_frames_left = frames_left;
    } else {
        attachment->envelope_frames_left = 0;
        float duration = 0.0f;
        if (gk_envelope_read_segment(
                envelope, attachment->envelope_cur_index, NULL,
                &duration) != 0)
            return M2_AUDIO_ERR_BAD_PTR;
        attachment->envelope_delta_time =
            duration * attachment->envelope_time_scale;
        ++attachment->envelope_cur_index;
    }
    attachment->envelope_prev_target = target;
    dspp_sim *sim = (dspp_sim *)master->audio_dsp_sim;
    dspp_sim_poke_data(sim, incr, (uint16_t)phase_increment);
    dspp_sim_poke_data(sim, request, (uint16_t)target_value);

    int post_event = 1;
    if (attachment->envelope_activity == 1u &&
        envelope->envelope_sustain_begin >= 0 &&
        attachment->envelope_cur_index > envelope->envelope_sustain_end) {
        attachment->envelope_cur_index = envelope->envelope_sustain_begin;
        attachment->envelope_delta_time =
            envelope->envelope_sustain_time * attachment->envelope_time_scale;
        if (envelope->envelope_sustain_begin ==
            envelope->envelope_sustain_end)
            post_event = 0;
    }
    if (envelope->envelope_release_begin >= 0 &&
        attachment->envelope_cur_index > envelope->envelope_release_end) {
        attachment->envelope_cur_index = envelope->envelope_release_begin;
        attachment->envelope_delta_time =
            envelope->envelope_release_time * attachment->envelope_time_scale;
    }
    if (!post_event) {
        attachment->envelope_event_posted = 0u;
        attachment->envelope_event_time = 0u;
        return M2K_OK;
    }
    const uint64_t scaled_frames =
        (uint64_t)(actual_frames > 0 ? actual_frames : 1) << rate_shift;
    uint32_t delay = (uint32_t)(scaled_frames / GK_AUDIO_GLOBAL_CLOCK_DURATION);
    if (delay < 1u) delay = 1u;
    attachment->envelope_event_time = current_time + delay;
    attachment->envelope_event_posted = 1u;
    (void)target_resource;
    (void)current;
    return M2K_OK;
}

static int32_t gk_start_envelope_attachment(gk_item *attachment,
                                            int32_t pitch_note,
                                            float time_scale,
                                            uint32_t current_time) {
    if (!attachment || attachment->attachment_type != 2u)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master = gk_live_item(attachment->attachment_master);
    gk_item *envelope = gk_live_item(attachment->attachment_slave);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        !master->audio_dsp_sim || !envelope ||
        envelope->ctype != GK_AUDIO_ENVELOPE_CTYPE)
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    if (attachment->attachment_start_at < 0 ||
        attachment->attachment_start_at >= envelope->envelope_num_points)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    uint32_t request = 0, incr = 0, target_resource = 0, current = 0;
    int32_t rc = gk_envelope_resource_addresses(
        attachment, &request, &incr, &target_resource, &current);
    if (rc != M2K_OK) return rc;
    gk_envelope_set_time_scale(attachment, pitch_note, time_scale);
    float target = 0.0f;
    if (gk_envelope_read_segment(envelope, attachment->attachment_start_at,
                                 &target, NULL) != 0)
        return M2_AUDIO_ERR_BAD_PTR;
    const int32_t target_value = gk_patch_graph_signal_raw(
        target, envelope->envelope_signal_type, 1u);
    const int32_t current_value = target_value > 0 ? target_value - 1
                                                   : target_value + 1;
    dspp_sim *sim = (dspp_sim *)master->audio_dsp_sim;
    dspp_sim_poke_data(sim, current, (uint16_t)current_value);
    dspp_sim_poke_data(sim, target_resource, (uint16_t)target_value);
    attachment->envelope_cur_index = attachment->attachment_start_at;
    attachment->envelope_frames_left = 0;
    attachment->envelope_delta_time = 0.0f;
    attachment->envelope_prev_target = target;
    attachment->envelope_activity = 1u;
    attachment->envelope_event_posted = 0u;
    attachment->envelope_event_time = 0u;
    (void)request;
    (void)incr;
    return gk_envelope_next_segment(attachment, current_time);
}

static int32_t gk_start_envelope_attachments(gk_item *instrument,
                                              int32_t pitch_note,
                                              float time_scale) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    const uint64_t clock_frames = gk_audio_clock_read(
        m2_host_audio_frame_count(), 0);
    const uint32_t now = (uint32_t)(clock_frames /
                                    GK_AUDIO_GLOBAL_CLOCK_DURATION);
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 2u ||
            gk_live_item(attachment->attachment_master) != instrument ||
            (attachment->attachment_flags &
             M2_AUDIO_ATTACHMENT_FLAG_NOAUTOSTART) != 0u)
            continue;
        const int32_t rc = gk_start_envelope_attachment(
            attachment, pitch_note, time_scale, now);
        if (rc != M2K_OK) {
            gk_stop_envelope_attachments(instrument);
            return rc;
        }
    }
    return M2K_OK;
}

static void gk_stop_envelope_attachments(gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return;
    pthread_mutex_lock(&g_audio_timer_lock);
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 2u ||
            gk_live_item(attachment->attachment_master) != instrument)
            continue;
        attachment->envelope_activity = 0u;
        attachment->envelope_event_posted = 0u;
        attachment->envelope_event_time = 0u;
    }
    pthread_mutex_unlock(&g_audio_timer_lock);
}

static int32_t gk_release_envelope_attachments(gk_item *instrument,
                                                float time_scale,
                                                int time_scale_set,
                                                uint32_t current_time) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    int32_t released = 0;
    pthread_mutex_lock(&g_audio_timer_lock);
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 2u ||
            gk_live_item(attachment->attachment_master) != instrument ||
            attachment->envelope_activity != 1u)
            continue;
        gk_item *envelope = gk_live_item(attachment->attachment_slave);
        if (!envelope || envelope->ctype != GK_AUDIO_ENVELOPE_CTYPE) {
            pthread_mutex_unlock(&g_audio_timer_lock);
            return M2_AUDIO_ERR_BAD_ITEM;
        }
        if (time_scale_set)
            gk_envelope_set_time_scale(attachment, -1, time_scale);
        attachment->envelope_activity = 2u;
        int repost = 0;
        if (envelope->envelope_release_jump >= 0 &&
            attachment->envelope_cur_index <= envelope->envelope_release_jump) {
            attachment->envelope_cur_index =
                envelope->envelope_release_jump + 1;
            repost = 1;
        } else if (!attachment->envelope_event_posted) {
            ++attachment->envelope_cur_index;
            repost = 1;
        }
        if (repost) {
            attachment->envelope_event_posted = 0u;
            attachment->envelope_event_time = 0u;
            attachment->envelope_frames_left = 0;
            float duration = 0.0f;
            if (attachment->envelope_cur_index > 0 &&
                gk_envelope_read_segment(
                    envelope, attachment->envelope_cur_index - 1, NULL,
                    &duration) != 0) {
                pthread_mutex_unlock(&g_audio_timer_lock);
                return M2_AUDIO_ERR_BAD_PTR;
            }
            attachment->envelope_delta_time =
                duration * attachment->envelope_time_scale;
            const int32_t rc =
                gk_envelope_next_segment(attachment, current_time);
            if (rc != M2K_OK) {
                pthread_mutex_unlock(&g_audio_timer_lock);
                return rc;
            }
        }
        ++released;
    }
    pthread_mutex_unlock(&g_audio_timer_lock);
    return released;
}

// Complete one physical delay attachment at the folio boundary. The vendor
// leaves the already-transferred FIFO words in place while
// ProcessAttachmentDMA promotes a linked next attachment; use the loader's
// promotion API for that same ordering instead of detaching (which would
// reset and discard resident FIFO data). An unlinked stopped attachment is
// released once its resident FIFO is empty, which is the silence transition.
static void gk_promote_delay_attachment(gk_item *completed) {
    if (!completed || !completed->used ||
        !completed->attachment_delay_bound)
        return;
    gk_item *master = gk_live_item(completed->attachment_master);
    dspp_sim *sim = completed->attachment_delay_sim;
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE || !sim)
        return;
    const uint32_t next_handle = completed->attachment_next;
    if (gk_audio_start_diag_enabled()) {
        static uint32_t count;
        if (count < 64u) {
            ++count;
            dspp_dma_armed armed = dspp_sim_dma_armed_interrupts(sim);
            fprintf(stderr,
                    "[audio-delay] promote from=%#x next=%#x ch=%u "
                    "stopped=%d fifo_empty=%d enabled=%d armed=%#x\n",
                    gk_make_handle(
                        GK_TYPE_ITEM_VA,
                        (uint32_t)(completed - g_gk.items),
                        completed->generation),
                    next_handle, completed->attachment_delay_channel,
                    dspp_sim_dma_delay_line_stopped(
                        sim, completed->attachment_delay_channel),
                    dspp_sim_dma_delay_line_fifo_empty(
                        sim, completed->attachment_delay_channel),
                    dspp_sim_dma_channel_interrupt_enabled(
                        sim, completed->attachment_delay_channel),
                    armed.dmanext);
        }
    }
    gk_item *next = gk_live_item(next_handle);
    gk_item *next_sample = next
                               ? gk_live_item(next->attachment_slave)
                               : NULL;
    if (!next || next->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
        next->attachment_type != 1u || next->attachment_master !=
            completed->attachment_master ||
        !next_sample || next_sample->ctype != GK_AUDIO_SAMPLE_CTYPE ||
        next_sample->sample_kind != 1u || !next_sample->sample_delay_line) {
        if (next_handle != 0u) completed->attachment_next = 0u;
        return;
    }

    const char *hook = next->attachment_has_hook ? next->attachment_hook : NULL;
    uint32_t next_channel = 0u;
    int next_output = 0;
    int32_t next_hook_rc = master->audio_patch_graph
                               ? gk_patch_graph_fifo(
                                     master, hook, NULL, &next_channel,
                                     &next_output)
                               : gk_resolve_fifo_channel(
                                     sim, hook, &next_channel, &next_output);
    if (next_hook_rc != M2K_OK ||
        next_channel != completed->attachment_delay_channel ||
        next_output != (completed->attachment_delay_output != 0u)) {
        completed->attachment_next = 0u;
        return;
    }

    if (dspp_sim_dma_promote_delay_line(
            sim, completed->attachment_delay_channel,
            next_sample->sample_delay_line, next_output,
            (uint32_t)next->attachment_start_at) != 0) {
        // The source would fall back to silence if the queued successor can
        // no longer be installed. Do not leave an unservable chain edge.
        completed->attachment_next = 0u;
        return;
    }

    completed->attachment_delay_channel = 0u;
    completed->attachment_delay_bound = 0u;
    completed->attachment_delay_output = 0u;
    completed->attachment_delay_sim = NULL;
    next->attachment_delay_channel = next_channel;
    next->attachment_delay_bound = 1u;
    next->attachment_delay_output = next_output ? 1u : 0u;
    next->attachment_delay_sim = sim;
    gk_update_delay_attachment_interrupt(next);
    if (gk_audio_start_diag_enabled()) {
        static uint32_t count;
        if (count < 64u) {
            ++count;
            dspp_dma_armed armed = dspp_sim_dma_armed_interrupts(sim);
            fprintf(stderr,
                    "[audio-delay] promoted next=%#x ch=%u enabled=%d "
                    "armed=%#x\n",
                    next_handle, next_channel,
                    dspp_sim_dma_channel_interrupt_enabled(
                        sim, next_channel),
                    armed.dmanext);
        }
    }
}

static void gk_cleanup_finished_delay_attachments(void) {
    if (!gk_bound()) return;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            !attachment->attachment_delay_bound ||
            attachment->attachment_next != 0u)
            continue;
        gk_item *master = gk_live_item(attachment->attachment_master);
        dspp_sim *sim = attachment->attachment_delay_sim;
        if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE || !sim)
            continue;
        if (dspp_sim_dma_delay_line_stopped(
                sim, attachment->attachment_delay_channel) &&
            dspp_sim_dma_delay_line_fifo_empty(
                sim, attachment->attachment_delay_channel))
            gk_unbind_delay_attachment(attachment);
    }
}

// Bind a validated numeric (non-sim) DSPP DMA descriptor to the instrument's
// FIFO hook channel. is_delay states the vendor IsDelayLine(asmp) predicate
// for the slave: delay-line Samples are now represented by the local Audio
// Folio pool, but this numeric seam does not infer that predicate from the
// slave Item, so live callers still pass it explicitly. OUT_FIFO hooks reject
// ordinary samples with SECURITY; tests pass 1 to prove the delay path binds.
// start_taglist_ea carries only the retained 0x4E/0x4F pair (uninterpreted);
// anything else fails closed with BAD_TAG.
int32_t m2_guest_audio_attach_numeric_descriptor(PPCContext *cpu,
                                                 uint32_t instrument,
                                                 uint32_t hook_name_ea,
                                                 uint32_t address,
                                                 uint32_t count_samples,
                                                 uint32_t flags,
                                                 int32_t is_delay,
                                                 uint32_t start_taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_start_tag_params params;
    int32_t tag_rc = gk_parse_start_tags(cpu, instrument, start_taglist_ea,
                                         &params);
    if (tag_rc != M2K_OK) return tag_rc;
    if (params.has_amplitude) {
        live->audio_start_4e = params.amplitude;
        live->audio_start_tags |= 1u;
    }
    if (params.has_frequency) {
        live->audio_start_4f = params.frequency;
        live->audio_start_rate_is_relative = (uint8_t)params.rate_is_relative;
        live->audio_start_tags |= 2u;
    }
    if (params.pitch_note >= 0)
        live->audio_start_pitch_note = params.pitch_note;
    if (params.velocity >= 0)
        live->audio_start_velocity = params.velocity;
    // Pure-synth/no-upload stays UNIMPLEMENTED: build the DSP image on
    // demand; patch/mixer shells, missing templates, and imports have no
    // DMA hardware to bind.
    if (!live->audio_dsp_sim &&
        (gk_dsp_sim_create_for(live, instrument) != 0 ||
         !live->audio_dsp_sim))
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    // A started instrument owns live channels; new binds wait.
    if (live->audio_started) return M2_AUDIO_ERR_NO_MEMORY;
    char hook[GK_MAX_NAME_LEN];
    const char *hook_arg = NULL;
    int32_t hook_rc = gk_copy_fifo_hook(cpu, hook_name_ea, hook, &hook_arg);
    if (hook_rc != M2K_OK) return hook_rc;
    uint32_t channel = 0;
    int is_out = 0;
    hook_rc = gk_resolve_fifo_channel((dspp_sim *)live->audio_dsp_sim,
                                      hook_arg, &channel, &is_out);
    if (hook_rc != M2K_OK) return hook_rc;
    if (is_out && !is_delay) return M2_AUDIO_ERR_SECURITY;
    int rc = dspp_sim_dma_attach_numeric((dspp_sim *)live->audio_dsp_sim,
                                         channel, address, count_samples,
                                         flags);
    switch (rc) {
    case DSPP_NUMERIC_OK:
        return M2K_OK;
    case DSPP_NUMERIC_ERR_BAD_ITEM:
        return M2_AUDIO_ERR_BAD_ITEM;
    case DSPP_NUMERIC_ERR_OUT_OF_RANGE:
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    case DSPP_NUMERIC_ERR_BAD_TYPE:
        return M2_AUDIO_ERR_BAD_TAG_VALUE;
    // No NULLADDRESS host code; ValidateAudioItemData/afi_IsRamAddr ground
    // maps it to BAD_PTR.
    case DSPP_NUMERIC_ERR_NULL_ADDRESS:
        return M2_AUDIO_ERR_BAD_PTR;
    default:
        return M2_AUDIO_ERR_BAD_ITEM;
    }
}
// Read back the validated numeric descriptor bound to the instrument's FIFO
// hook channel. Observation only: never builds a sim and never fabricates
// (unattached channels report zeros with M2K_OK, mirroring the loader).
int32_t m2_guest_audio_read_numeric_descriptor(PPCContext *cpu,
                                               uint32_t instrument,
                                               uint32_t hook_name_ea,
                                               uint32_t *address_out,
                                               uint32_t *count_out,
                                               uint32_t *flags_out) {
    if (address_out) *address_out = 0;
    if (count_out) *count_out = 0;
    if (flags_out) *flags_out = 0;
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (!live->audio_dsp_sim) return M2_AUDIO_ERR_UNIMPLEMENTED;
    char hook[GK_MAX_NAME_LEN];
    const char *hook_arg = NULL;
    int32_t hook_rc = gk_copy_fifo_hook(cpu, hook_name_ea, hook, &hook_arg);
    if (hook_rc != M2K_OK) return hook_rc;
    uint32_t channel = 0;
    hook_rc = gk_resolve_fifo_channel((dspp_sim *)live->audio_dsp_sim,
                                      hook_arg, &channel, NULL);
    if (hook_rc != M2K_OK) return hook_rc;
    int rc = dspp_sim_dma_numeric_descriptor(
        (const dspp_sim *)live->audio_dsp_sim, channel, address_out,
        count_out, flags_out);
    return rc == DSPP_NUMERIC_OK ? M2K_OK : M2_AUDIO_ERR_BAD_ITEM;
}
// Read back the consumed generation for the instrument's FIFO hook channel.
// Observation only: never builds a sim (unbuilt reads stay UNIMPLEMENTED),
// raises no signals, and touches no delivery (completion-qualified delivery
// stays a separate folio seam). Unattached channels report 0 with M2K_OK,
// mirroring the loader.
int32_t m2_guest_audio_read_numeric_consumed(PPCContext *cpu,
                                             uint32_t instrument,
                                             uint32_t hook_name_ea,
                                             uint32_t *generation_out) {
    if (generation_out) *generation_out = 0;
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (!live->audio_dsp_sim) return M2_AUDIO_ERR_UNIMPLEMENTED;
    char hook[GK_MAX_NAME_LEN];
    const char *hook_arg = NULL;
    int32_t hook_rc = gk_copy_fifo_hook(cpu, hook_name_ea, hook, &hook_arg);
    if (hook_rc != M2K_OK) return hook_rc;
    uint32_t channel = 0;
    hook_rc = gk_resolve_fifo_channel((dspp_sim *)live->audio_dsp_sim,
                                      hook_arg, &channel, NULL);
    if (hook_rc != M2K_OK) return hook_rc;
    if (generation_out)
        *generation_out = dspp_sim_dma_numeric_consumed(
            (const dspp_sim *)live->audio_dsp_sim, channel);
    return M2K_OK;
}
// Push guest-RAM words into the instrument's FIFO hook channel (DMA direction
// into the DSPP). Bounded host equivalent of FDMA servicing a guest-RAM
// descriptor: words are 16-bit big-endian (rd16, same convention as sample
// upload), capped at the 8-word physical FIFO depth — larger counts fail
// closed with OUT_OF_RANGE rather than partially feeding. Mirrors the
// read_numeric_consumed validation order: BAD_ITEM on dead/wrong-type
// handles or foreign memory, UNIMPLEMENTED when no DSP image exists (attach
// builds it), hook errors pass through, and OUT_FIFO hooks reject with
// SECURITY (input-direction feed into an output FIFO). Raises no signals
// and touches no delivery by itself; the drain side stays authentic DSPP
// reads, and completion/Cue delivery stays at the frame-boundary pump.
int32_t m2_guest_audio_push_numeric_fifo(PPCContext *cpu,
                                         uint32_t instrument,
                                         uint32_t hook_name_ea,
                                         uint32_t words_ea,
                                         uint32_t word_count) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (!live->audio_dsp_sim) return M2_AUDIO_ERR_UNIMPLEMENTED;
    if (word_count > 8u) return M2_AUDIO_ERR_OUT_OF_RANGE;
    if (word_count > 0u &&
        (words_ea == 0u || words_ea > RECOMP_GUEST_MEM - word_count * 2u))
        return M2_AUDIO_ERR_BAD_PTR;
    char hook[GK_MAX_NAME_LEN];
    const char *hook_arg = NULL;
    int32_t hook_rc = gk_copy_fifo_hook(cpu, hook_name_ea, hook, &hook_arg);
    if (hook_rc != M2K_OK) return hook_rc;
    uint32_t channel = 0;
    int is_out = 0;
    hook_rc = gk_resolve_fifo_channel((dspp_sim *)live->audio_dsp_sim,
                                      hook_arg, &channel, &is_out);
    if (hook_rc != M2K_OK) return hook_rc;
    if (is_out) return M2_AUDIO_ERR_SECURITY;
    for (uint32_t i = 0; i < word_count; ++i)
        dspp_sim_fifo_push((dspp_sim *)live->audio_dsp_sim, channel,
                           (int16_t)rd16(cpu, words_ea + i * 2u));
    return M2K_OK;
}

// Resolve the DMA channel carrying an attachment's retained sample hook.
// Observation only: never builds a sim (unbuilt reads stay UNIMPLEMENTED),
// raises no signals, and touches no completion or delivery. Mirrors the
// m2_guest_audio_read_numeric_consumed validation order — BAD_ITEM on
// dead/wrong-type attachment or master handles, UNIMPLEMENTED when the
// master instrument has no DSP image, hook errors pass through — except the
// hook comes from the attachment's retained AF_TAG_NAME (vendor
// aatt_HookName) instead of a guest EA, so no guest read can fault. The
// completion pump uses this map to attribute a polled channel event to the
// attachments sharing its FIFO (vendor fico_Attachments); envelope hooks
// resolve to MISMATCH through the FIFO-only resolver and never deliver.
int32_t m2_guest_audio_resolve_attachment_channel(uint32_t attachment,
                                                 uint32_t *channel_out) {
    if (channel_out) *channel_out = 0;
    if (!gk_bound()) return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(attachment);
    if (!live || live->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *master = gk_live_item(live->attachment_master);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (master->audio_patch_graph) {
        const char *hook_arg =
            live->attachment_has_hook ? live->attachment_hook : NULL;
        uint32_t channel = 0u;
        int32_t hook_rc = gk_patch_graph_fifo(
            master, hook_arg, NULL, &channel, NULL);
        if (hook_rc != M2K_OK) return hook_rc;
        if (channel_out) *channel_out = channel;
        return M2K_OK;
    }
    if (!master->audio_dsp_sim) return M2_AUDIO_ERR_UNIMPLEMENTED;
    const char *hook_arg =
        live->attachment_has_hook ? live->attachment_hook : NULL;
    uint32_t channel = 0;
    int32_t hook_rc = gk_resolve_fifo_channel(
        (dspp_sim *)master->audio_dsp_sim, hook_arg, &channel, NULL);
    if (hook_rc != M2K_OK) return hook_rc;
    if (channel_out) *channel_out = channel;
    return M2K_OK;
}

int32_t m2_guest_audio_get_instrument_patch_block_count(uint32_t instrument,
                                                        uint32_t *count_out) {
    if (count_out) *count_out = 0u;
    if (!gk_bound()) return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (live->audio_patch_graph) {
        if (count_out) *count_out = live->audio_patch_graph->block_count;
        return M2K_OK;
    }
    const gk_patch_template *pt = gk_patch_template_for_instrument(live);
    if (pt) {
        if (count_out) *count_out = pt->block_count;
        return M2K_OK;
    }
    return M2K_OK; // 0 constituent blocks
}

// Read back the armed (pending & enabled) DMA-interrupt banks for the instrument's
// DSP image. Observation only: never builds a sim (unbuilt reads stay UNIMPLEMENTED),
// raises no signals/Cues, and touches no completion or delivery (guest delivery stays
// a future seam). The hook only validates the caller's channel — hook EA 0 takes the
// instrument's single default FIFO, otherwise the named hook — mirroring the
// m2_guest_audio_read_numeric_consumed order; the banks themselves forward the loader
// query verbatim (whole-image words with M2K_OK).
int32_t m2_guest_audio_read_dma_armed(PPCContext *cpu, uint32_t instrument,
                                      uint32_t hook_name_ea,
                                      uint32_t *dmanext_out,
                                      uint32_t *consumed_out,
                                      uint32_t *underover_out) {
    if (dmanext_out) *dmanext_out = 0;
    if (consumed_out) *consumed_out = 0;
    if (underover_out) *underover_out = 0;
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (!live->audio_dsp_sim) return M2_AUDIO_ERR_UNIMPLEMENTED;
    char hook[GK_MAX_NAME_LEN];
    const char *hook_arg = NULL;
    int32_t hook_rc = gk_copy_fifo_hook(cpu, hook_name_ea, hook, &hook_arg);
    if (hook_rc != M2K_OK) return hook_rc;
    uint32_t channel = 0;
    hook_rc = gk_resolve_fifo_channel((dspp_sim *)live->audio_dsp_sim,
                                      hook_arg, &channel, NULL);
    if (hook_rc != M2K_OK) return hook_rc;
    (void)channel; // validation only: the banks below forward whole-image words.
    dspp_dma_armed armed = dspp_sim_dma_armed_interrupts(
        (const dspp_sim *)live->audio_dsp_sim);
    if (dmanext_out) *dmanext_out = armed.dmanext;
    if (consumed_out) *consumed_out = armed.consumed;
    if (underover_out) *underover_out = armed.underover;
    return M2K_OK;
}

// MonitorAttachment has a fully recoverable association prefix: the source
// validates the attachment, treats Cue=0 as an exact removal, validates a
// nonzero Cue, and accepts only CUE_AT_END. Host playback adapters publish
// completion events for uploaded PCM and CBD2 segments, and numeric DSPP DMA
// channels record completion-qualified events when their consumed generation
// reaches the bound count; the frame-boundary pump delivers those compatibility
// events to the owning guest task. Physical finite delay attachments use the
// standard DMANext/FIRQ/audio-daemon path below, separate from numeric polling.
int32_t m2_guest_audio_monitor_attachment(PPCContext *cpu,
                                          uint32_t attachment,
                                          uint32_t cue,
                                          int32_t cue_at) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(attachment);
    if (!live || live->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (cue == 0) {
        live->attachment_cue = 0;
        gk_update_delay_attachment_interrupt(live);
        return M2K_OK;
    }
    gk_item *cue_live = gk_live_item(cue);
    if (!cue_live || cue_live->ctype != GK_AUDIO_CUE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (cue_at != M2_AUDIO_CUE_AT_END)
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    live->attachment_cue = cue;
    live->attachment_cue_at = cue_at;
    gk_update_delay_attachment_interrupt(live);
    return M2K_OK;
}

// R3 BAD_TAG capture (diagnostic only, no behavior change):
// the 0x4E/0x4F-only rule below stays closed. When the walk rejects a list,
// this logs the failing bytes with the owning template and the guest caller
// (cpu->lr, the return address into guest code) so headless/live reruns can
// classify the pair filed in the reconciliation trial. Bounded
// (16 lines) behind the existing audio start gate.
static void gk_audio_template_label(uint32_t instrument, char *buf,
                                    uint32_t len) {
    if (!buf || len == 0) return;
    buf[0] = '\0';
    gk_item *inst = gk_live_item(instrument);
    if (!inst || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE) return;
    gk_item *tpl = gk_live_item(inst->template_item);
    if (!tpl || tpl->ctype != GK_AUDIO_TEMPLATE_CTYPE) return;
    if (tpl->patch_index > 0)
        snprintf(buf, len, "patch%u", tpl->patch_index);
    else if (tpl->mixer_spec != 0)
        snprintf(buf, len, "mixer:%ux%u/f%#x",
                 (tpl->mixer_spec >> 24) & 0xffu,
                 (tpl->mixer_spec >> 16) & 0xffu, tpl->mixer_spec & 0xffffu);
    else if (tpl->audio_name[0]) {
        memcpy(buf, tpl->audio_name, len);
        buf[len - 1] = '\0';
    }
}
static void gk_log_audio_start_badtag(PPCContext *cpu, uint32_t instrument,
                                      uint32_t taglist_ea, uint32_t fail_tag,
                                      uint32_t fail_val) {
    static uint32_t count = 0;
    if (!gk_audio_start_diag_enabled() || count >= 16u) return;
    ++count;
    char tname[GK_MAX_NAME_LEN];
    gk_audio_template_label(instrument, tname, sizeof(tname));
    uint32_t caller = cpu ? cpu->lr : 0u;
    fprintf(stderr,
            "[audio-start-badtag] n=%u inst=%#x tpl=%s caller=%#x "
            "fail=(%#x,%#x) tags=",
            count, instrument, tname[0] ? tname : "?", caller, fail_tag,
            fail_val);
    for (uint32_t i = 0; i < 8; ++i) {
        uint32_t ea = taglist_ea + i * 8u;
        if (taglist_ea == 0 || !cpu || ea + 8u > RECOMP_GUEST_MEM) {
            fprintf(stderr, " OOB");
            break;
        }
        uint32_t tag = rd32(cpu, ea);
        uint32_t val = rd32(cpu, ea + 4u);
        fprintf(stderr, " (%#x,%#x)", tag, val);
        if (tag == M2_TAG_END) break;
    }
    fprintf(stderr, "\n");
}
// Portfolio Audio Folio StartInstrument taglist parser. Matches vendor
// DSPPStartInstrument: supports amplitude (AMPLITUDE_FP, VELOCITY,
// SQUARE_VELOCITY, EXPONENTIAL_VELOCITY), frequency (SAMPLE_RATE_FP,
// RATE_FP, FREQUENCY_FP, DETUNE_FP, PITCH), TIME_SCALE_FP, and rejects
// amplitude or frequency tag conflicts with AF_ERR_TAGCONFLICT. Untagged
// starts leave fields unset so existing knob values are preserved.
static int32_t gk_parse_start_tags(PPCContext *cpu, uint32_t instrument,
                                   uint32_t taglist_ea,
                                   gk_start_tag_params *out) {
    if (!out) return M2_AUDIO_ERR_BAD_PTR;
    memset(out, 0, sizeof(*out));
    out->pitch_note = -1;
    out->velocity = -1;
    out->time_scale = 1.0f;
    if (taglist_ea == 0) return M2K_OK;
    if (!gk_bound() || !g_gk.cpu || !g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    uint32_t cur = taglist_ea;
    uint32_t jumps = 0;
    uint32_t amp_tag = 0u;
    int freq_type = 0;
    float exp_velocity_scalar = 1.0f / 20.0f;

    for (uint32_t n = 0; n < 16; ++n) {
        if (cur == 0 || cur > RECOMP_GUEST_MEM - 8u)
            return M2_AUDIO_ERR_BAD_PTR;
        uint32_t tag = rd32(cpu, cur);
        uint32_t val = rd32(cpu, cur + 4u);
        cur += 8u;
        if (tag == M2_TAG_END) break;
        if (tag == 0xFFFFFFFFu) continue;
        if (tag == M2_TAG_JUMP) {
            if (++jumps > 2) {
                gk_log_audio_start_badtag(cpu, instrument, taglist_ea, tag, val);
                return M2_AUDIO_ERR_BAD_TAG;
            }
            cur = val;
            continue;
        }
        switch (tag) {
        case M2_AUDIO_TAG_AMPLITUDE_FP: {
            if (amp_tag != 0u) return M2_AUDIO_ERR_TAGCONFLICT;
            float fval = 0.0f;
            memcpy(&fval, &val, sizeof(fval));
            out->amplitude = fval;
            out->has_amplitude = 1;
            amp_tag = tag;
            break;
        }
        case M2_AUDIO_TAG_VELOCITY: {
            if (amp_tag != 0u) return M2_AUDIO_ERR_TAGCONFLICT;
            out->velocity = (int32_t)val;
            out->amplitude = (float)out->velocity / 128.0f;
            out->has_amplitude = 1;
            amp_tag = tag;
            break;
        }
        case M2_AUDIO_TAG_SQUARE_VELOCITY: {
            if (amp_tag != 0u) return M2_AUDIO_ERR_TAGCONFLICT;
            out->velocity = (int32_t)val;
            const float v = (float)out->velocity / 127.0f;
            out->amplitude = v * v;
            out->has_amplitude = 1;
            amp_tag = tag;
            break;
        }
        case M2_AUDIO_TAG_EXPONENTIAL_VELOCITY: {
            if (amp_tag != 0u) return M2_AUDIO_ERR_TAGCONFLICT;
            out->velocity = (int32_t)val;
            out->has_amplitude = 1;
            amp_tag = tag;
            break;
        }
        case M2_AUDIO_TAG_EXP_VELOCITY_SCALAR: {
            memcpy(&exp_velocity_scalar, &val, sizeof(exp_velocity_scalar));
            break;
        }
        case M2_AUDIO_TAG_SAMPLE_RATE_FP: {
            if (freq_type != 0) return M2_AUDIO_ERR_TAGCONFLICT;
            float fval = 0.0f;
            memcpy(&fval, &val, sizeof(fval));
            out->frequency = fval;
            out->has_frequency = 1;
            out->rate_is_relative = 0;
            freq_type = 3;
            break;
        }
        case M2_AUDIO_TAG_RATE_FP: {
            if (freq_type != 0) return M2_AUDIO_ERR_TAGCONFLICT;
            float fval = 0.0f;
            memcpy(&fval, &val, sizeof(fval));
            out->frequency = fval;
            out->has_frequency = 1;
            out->rate_is_relative = 1;
            freq_type = 2;
            break;
        }
        case M2_AUDIO_TAG_FREQUENCY_FP: {
            if (freq_type != 0) return M2_AUDIO_ERR_TAGCONFLICT;
            float fval = 0.0f;
            memcpy(&fval, &val, sizeof(fval));
            out->frequency = fval;
            out->has_frequency = 1;
            out->rate_is_relative = 0;
            freq_type = 1;
            break;
        }
        case M2_AUDIO_TAG_DETUNE_FP: {
            if (freq_type != 0) return M2_AUDIO_ERR_TAGCONFLICT;
            float fval = 0.0f;
            memcpy(&fval, &val, sizeof(fval));
            out->frequency = fval;
            out->has_frequency = 1;
            out->rate_is_relative = 1;
            freq_type = 4;
            break;
        }
        case M2_AUDIO_TAG_PITCH: {
            if (freq_type != 0) return M2_AUDIO_ERR_TAGCONFLICT;
            out->pitch_note = (int32_t)val;
            out->frequency = 440.0f * powf(2.0f, ((float)out->pitch_note - 69.0f) / 12.0f);
            out->has_frequency = 1;
            out->rate_is_relative = 0;
            freq_type = 5;
            break;
        }
        case M2_AUDIO_TAG_TIME_SCALE_FP: {
            memcpy(&out->time_scale, &val, sizeof(out->time_scale));
            break;
        }
        default:
            gk_log_audio_start_badtag(cpu, instrument, taglist_ea, tag, val);
            return M2_AUDIO_ERR_BAD_TAG;
        }
    }

    if (amp_tag == M2_AUDIO_TAG_EXPONENTIAL_VELOCITY) {
        out->amplitude = powf(2.0f, ((float)out->velocity - 127.0f) * exp_velocity_scalar);
    }
    return M2K_OK;
}

// Stop only voices whose current attachment belongs to this instrument.
// Different cars can share a PCM buffer, so a matching sample id alone does
// not establish ownership after a voice slot has been recycled.
static void gk_stop_instrument_voices(gk_item *inst) {
    if (!inst) return;
    uint32_t mask = inst->audio_voice_mask;
    inst->audio_voice_mask = 0;
    inst->audio_voice_routed_mask = 0;
    for (uint32_t i = 0; i < 32u; ++i) {
        if ((mask & (1u << i)) == 0) continue;
        if (gk_voice_owned_sid(inst, i)) m2_host_audio_stop_voice(i);
    }
}

// ---- pure-synth DSPP execution boundary -------------------------------------
//
// The exercised pure-synth instruments (line_out.dsp, svfilter.dsp, and the
// game's custom patch templates) previously stopped at an explicit
// UNIMPLEMENTED boundary because the host had no DSPP executor. The vendor
// simulator semantics are now recovered in dsp_template_loader.c (loaded from
// the original disc bytes, relocated with the dspp_relocator.c policy, and
// executed with the dspp_simulator.c Bulldog semantics).
//
// What is claimed here: templates that do not require an imported external
// resource (svfilter.dsp and the oscillator/filter family) execute their
// authentic DCOD instructions and publish their output registers each audio
// frame. line_out.dsp writes into gMixer, an import from nanokernel.dsp that
// this bounded host does not schedule; those instruments keep the explicit
// AF_ERR_EXTERNALREF boundary rather than fabricating a mixer graph.
// Output-backed fidelity through the real mixer remains a separate open
// boundary; the DSPP outputs are observed but not summed into the SDL stream.

// ---- patch/mixer-template mix nodes (R1) ------------------------------------
//
// Repair-list R1: custom patch/mixer-template instrument starts returned
// UNIMPLEMENTED and every connection touching them logged applied=0, while
// the guest's Sound3D submix graph (sampler voices -> 5x1 submix nodes ->
// line_out) needs them started. Patch templates declare only ports, no code
// (CreatePatchTemplate keeps DEFINE_PORT/DEFINE_KNOB/EXPOSE), so no DSPP
// image can be built — but these nodes need no synthesis, only gain routing.
//
// Mixer nodes (mixer_spec != 0) execute the vendor mixer formula exactly:
// Output[o] = Amplitude * sum_i(Input[i] * Gain[o*NI+i]), with all Gain
// parts defaulting to 0 and Amplitude defaulting to 1.0. Evidence:
// M2 SDK src/folios/audio/dspp_mixer.c mxBuildCode (TIMES/TIMES_PLUS_ACCUME
// MAC array per output, optional Amplitude scale, optional gMixer
// accumulate), includes/audio/audio.h CalcMixerGainPart
// (GainPart = outChan*numIn + inChan), and folios/audio/audio_template.c
// CreateMixerTemplate autodoc ("All parts of the Gain knob default to 0.
// The Amplitude knob, if requested, defaults to 1.0").
//
// Patch nodes (patch_index > 0) route their patch-scope internal connects
// as straight wires: the vendor parser resolves NULL-block CONNECTs to the
// patch's own ports (folios/audiopatch/createpatch_parser.c ParseCmdConnect:
// "name==NULL means to use pd_PortTemplate"), and the game authors only
// Input[0] -> Output[0..1] fan-outs (capture: [audio-template-conn], block
// EAs 0). Each OUTPUT part driven by such a route copies the routed input
// word; undriven outputs read 0, and routes naming sub-instrument blocks
// (the uncompiled ADD_TEMPLATE sub-graph, linker createpatch_linker.c)
// are never honored. Vendor patch shape (ports/knobs/connect only, no
// synthesis) is evidenced by .../Examples/Audio/Patches/*.mp and
// .../Tests/Audio/Patches/*.mp.
//
// The resident mix accumulator is the R2 direction: line_out.ins computes
// gMixer[o] = CLIP(gMixer[o] + Input[o]) per frame, and nanokernel.ins
// exports the 2-part stereo gMixer accumulators (transferred to the DAC
// FIFO, then cleared). This section feeds that accumulator from started
// line_out-bound node outputs (R1/R2); R2-full renders it per tick as the DAC
// transfer DAC[ch] = gMixer[ch] x Amplitude(unity) into the SDL mixer FIFO
// (see the pump below) with the connection partition below suppressing
// direct SDL playback only for graph-routed started samplers.
//
// Scope limits (no fabrication): started sample-voice instruments feed the
// graph through the host tap (m2_host_audio_voice_tap_frame, one frame per
// source per tick); unstarted/voiceless sources still read 0. KNOB
// destinations stay uninstalled (signal-driven knob modulation is not
// recovered; the tick reads retained knob values only). The fixed-point
// domain is the 16-bit SF15 word with int32 accumulation and clip; the
static int gk_mixnode_kind_of(const gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return 0;
    gk_item *tpl = gk_live_item(instrument->template_item);
    if (!tpl || tpl->ctype != GK_AUDIO_TEMPLATE_CTYPE) return 0;
    if (tpl->patch_index > 0 &&
        tpl->patch_index <= GK_MAX_PATCH_TEMPLATES &&
        g_gk_patches[tpl->patch_index - 1].used)
        return 1;
    if (tpl->mixer_spec != 0) return 2;
    return 0;
}
// Per-tick memo domain: node outputs (by item slot, up to 8 words — the
// mixer max; patch OUTPUT parts flatten in template order, capped the
// same) and per-connection input values. Recomputed from template + knobs
// + connection table + sim peeks every serial bump, so DeleteItem needs no
// invalidation: dead or stopped slots are never read (compute checks kind
// and started state before publishing, readers check the part count).
#define GK_MIXNODE_MAX_OUT 8u
#define GK_MIXNODE_MAX_DEPTH 16u
static int16_t gk_mix_out[GK_MAX_ITEMS][GK_MIXNODE_MAX_OUT];
static uint32_t gk_mix_out_count[GK_MAX_ITEMS];
static uint32_t gk_mix_out_serial[GK_MAX_ITEMS];
static int16_t gk_mix_conn_value[GK_MAX_AUDIO_CONNECTIONS];
static uint32_t gk_mix_conn_serial[GK_MAX_AUDIO_CONNECTIONS];
static uint32_t gk_mix_serial = 0;

// ---- live-graph index -------------------------------------------------------
// The item and connection pools are fixed 256-entry arrays that the per-DAC-
// frame mixer pass (gk_mixnode_tick_frame, find_knob, input_sample,
// sum_outputs, route_reaches_dac) otherwise rescans by name every DAC frame.
// The graph structure changes only when an item is minted/deleted, a
// connection installs/drops, an instrument starts/stops, or a patch
// registers; between those, the per-frame pass only reads values. Index the
// used entries once per structural revision so the per-frame path walks the
// live graph (a handful of entries) instead of ~512 slots.
//
// Guest tasks mutate the graph on their own host threads while the main
// thread pumps, so the revision is atomic. A rebuild that races a mutation is
// retried; if the graph is never stable the next caller rebuilds again.
// Consumers still revalidate used/ctype on every entry, so a stale slot left
// by a torn rebuild is skipped rather than read.
static _Atomic uint32_t gk_mix_graph_rev = 1u;
static uint32_t gk_mix_graph_built_rev;
static uint16_t gk_mix_graph_inst[GK_MAX_ITEMS];
static uint16_t gk_mix_graph_knob[GK_MAX_ITEMS];
static uint16_t gk_mix_graph_conn[GK_MAX_AUDIO_CONNECTIONS];
// Per-revision adjacency indexes. The heads and next links are built in
// ascending pool order, so walking them preserves the first-match semantics
// of the linear scans they replace.
static uint16_t gk_mix_graph_knob_head[GK_MAX_ITEMS];
static uint16_t gk_mix_graph_knob_next[GK_MAX_ITEMS];
static uint16_t gk_mix_graph_conn_head[GK_MAX_ITEMS];
static uint16_t gk_mix_graph_conn_next[GK_MAX_AUDIO_CONNECTIONS];
static uint16_t gk_mix_graph_dsp[GK_MAX_ITEMS];
// Connections whose destination is a line_out.dsp "Input" part. That shape is
// template metadata, so the per-DAC-frame route pass can walk this list
// instead of resolving and comparing destination names for every live
// connection. The source-side classification (mix-node kind, and a pure DSP
// source's OUTPUT word) is template metadata too and is resolved here.
// Started state and calc-rate due-ness stay per-frame checks.
typedef struct gk_mix_graph_lineout_route {
    uint16_t conn;      // connection pool index
    uint16_t out_index; // resolved mix-node output word, UINT16_MAX when none
    uint8_t  src_kind;  // gk_mixnode_kind_of(source) on this revision
    uint32_t dsp_addr;  // resolved source OUTPUT base, UINT32_MAX when none
    uint32_t dsp_parts; // source OUTPUT part count
} gk_mix_graph_lineout_route;
static gk_mix_graph_lineout_route gk_mix_graph_lineout[GK_MAX_AUDIO_CONNECTIONS];
// gk_mixnode_kind_of() per instrument slot on this revision.
static int8_t gk_mix_graph_kind[GK_MAX_ITEMS];
// Started instrument slots whose template is a generated mixer with
// WITH_LINE_OUT. The kind and flag are template metadata on this revision.
static uint16_t gk_mix_graph_with_out[GK_MAX_ITEMS];
static uint32_t gk_mix_graph_inst_n;
static uint32_t gk_mix_graph_conn_n;
static uint32_t gk_mix_graph_dsp_n;
static uint32_t gk_mix_graph_lineout_n;
static uint32_t gk_mix_graph_with_out_n;
// Wire feeding each generated-mixer Input part and the knobs its formula
// reads, by item slot. -1 when absent, which reads as the vendor default.
#define GK_MIXNODE_MAX_IN 32u
static int16_t gk_mix_graph_input_conn[GK_MAX_ITEMS][GK_MIXNODE_MAX_IN];
static int16_t gk_mix_graph_gain_knob[GK_MAX_ITEMS];
static int16_t gk_mix_graph_amp_knob[GK_MAX_ITEMS];
// Per-connection source lookups, resolved on first use after each rebuild.
// A source sim can appear between revisions, so its entry names the sim it
// was resolved against.
#define GK_MIX_OUT_UNRESOLVED (-2)
static int16_t gk_mix_graph_src_out[GK_MAX_AUDIO_CONNECTIONS];
static const dspp_sim *gk_mix_graph_src_sim[GK_MAX_AUDIO_CONNECTIONS];
static const dspp_resource *gk_mix_graph_src_res[GK_MAX_AUDIO_CONNECTIONS];
// Per-slot memo of the "started source reaches the DAC accumulator" route
// predicate. The predicate is structural on the same revision; without the
// memo gk_dsp_sum_outputs re-walks the connection table for every started sim
// on every DAC frame.
static int8_t gk_mix_graph_route[GK_MAX_ITEMS];
// Per-slot memo of the "started sim's OUTPUT is a control source" predicate
// (every live OUTPUT route feeds a destination KNOB, none feeds an INPUT).
// Same structural revision as gk_mix_graph_route; see gk_dsp_sim_control_only.
static int8_t gk_mix_graph_control[GK_MAX_ITEMS];

static void gk_mix_graph_touch(void) {
    atomic_fetch_add_explicit(&gk_mix_graph_rev, 1u, memory_order_relaxed);
}

static void gk_mix_graph_build(void) {
    uint32_t ni = 0, nk = 0, nc = 0, nd = 0;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_mix_graph_knob_head[i] = UINT16_MAX;
        gk_mix_graph_conn_head[i] = UINT16_MAX;
        gk_mix_graph_kind[i] = -1;
        const gk_item *it = &g_gk.items[i];
        if (!it->used) continue;
        if (it->ctype == GK_AUDIO_INSTRUMENT_CTYPE) {
            gk_mix_graph_inst[ni++] = (uint16_t)i;
            gk_mix_graph_kind[i] = (int8_t)gk_mixnode_kind_of(it);
            if (it->audio_started && it->audio_dsp_sim)
                gk_mix_graph_dsp[nd++] = (uint16_t)i;
        } else if (it->ctype == GK_AUDIO_KNOB_CTYPE) {
            gk_mix_graph_knob[nk++] = (uint16_t)i;
        }
    }
    // Ascending index order preserves the pools' first-match semantics for
    // every scan this index replaces.
    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i)
        if (g_gk.connections[i].used) gk_mix_graph_conn[nc++] = (uint16_t)i;
    gk_mix_graph_inst_n = ni;
    gk_mix_graph_conn_n = nc;
    gk_mix_graph_dsp_n = nd;

    // Build knob lists per owning instrument. Iterating positions backwards
    // and prepending leaves each list in ascending pool order.
    for (uint32_t n = 0; n < nk; ++n) gk_mix_graph_knob_next[n] = UINT16_MAX;
    for (uint32_t n = nk; n > 0u; --n) {
        const uint32_t pos = n - 1u;
        const gk_item *knob = &g_gk.items[gk_mix_graph_knob[pos]];
        const uint32_t slot = gk_live_item_slot(knob->knob_instrument);
        if (slot == UINT16_MAX) continue;
        gk_mix_graph_knob_next[pos] = gk_mix_graph_knob_head[slot];
        gk_mix_graph_knob_head[slot] = (uint16_t)pos;
    }

    // Build connection lists per destination item. The destination handle is
    // resolved once here; the per-sample path then walks only that node's
    // wires instead of every live connection.
    for (uint32_t n = 0; n < nc; ++n) gk_mix_graph_conn_next[n] = UINT16_MAX;
    for (uint32_t n = nc; n > 0u; --n) {
        const uint32_t pos = n - 1u;
        const gk_audio_connection *cn =
            &g_gk.connections[gk_mix_graph_conn[pos]];
        const uint32_t slot = gk_live_item_slot(cn->dst_item);
        if (slot == UINT16_MAX) continue;
        gk_mix_graph_conn_next[pos] = gk_mix_graph_conn_head[slot];
        gk_mix_graph_conn_head[slot] = (uint16_t)pos;
    }

    memset(gk_mix_graph_route, -1, sizeof(gk_mix_graph_route));
    memset(gk_mix_graph_control, -1, sizeof(gk_mix_graph_control));

    // Ascending connection order keeps the first-match wire for each part.
    memset(gk_mix_graph_input_conn, -1, sizeof(gk_mix_graph_input_conn));
    memset(gk_mix_graph_src_sim, 0, sizeof(gk_mix_graph_src_sim));
    memset(gk_mix_graph_src_res, 0, sizeof(gk_mix_graph_src_res));
    for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i)
        gk_mix_graph_src_out[i] = GK_MIX_OUT_UNRESOLVED;
    for (uint32_t n = 0; n < nc; ++n) {
        const uint32_t i = gk_mix_graph_conn[n];
        const gk_audio_connection *cn = &g_gk.connections[i];
        const uint32_t slot = gk_live_item_slot(cn->dst_item);
        if (slot == UINT16_MAX || cn->dst_part < 0 ||
            (uint32_t)cn->dst_part >= GK_MIXNODE_MAX_IN ||
            gk_mix_graph_input_conn[slot][cn->dst_part] >= 0 ||
            !gk_audio_name_equal(cn->dst_name, "Input"))
            continue;
        gk_mix_graph_input_conn[slot][cn->dst_part] = (int16_t)i;
    }
    for (uint32_t n = 0; n < ni; ++n) {
        const uint32_t slot = gk_mix_graph_inst[n];
        gk_mix_graph_gain_knob[slot] = -1;
        gk_mix_graph_amp_knob[slot] = -1;
        if (gk_mix_graph_kind[slot] != 2) continue;
        const uint32_t handle = gk_make_handle(GK_TYPE_ITEM_VA, slot,
                                               g_gk.items[slot].generation);
        const gk_item *gain = gk_mixnode_find_knob(handle, "Gain");
        const gk_item *amp = gk_mixnode_find_knob(handle, "Amplitude");
        if (gain) gk_mix_graph_gain_knob[slot] = (int16_t)(gain - g_gk.items);
        if (amp) gk_mix_graph_amp_knob[slot] = (int16_t)(amp - g_gk.items);
    }

    // The per-DAC-frame route pass only carries connections that land on a
    // line_out.dsp "Input" part. Resolve that shape here so the frame pass
    // does not compare destination names for every live connection.
    gk_mix_graph_lineout_n = 0;
    for (uint32_t n = 0; n < nc; ++n) {
        const gk_audio_connection *cn =
            &g_gk.connections[gk_mix_graph_conn[n]];
        gk_item *dst = gk_live_item(cn->dst_item);
        if (!dst || dst->ctype != GK_AUDIO_INSTRUMENT_CTYPE) continue;
        gk_item *dtpl = gk_live_item(dst->template_item);
        if (!dtpl || dtpl->ctype != GK_AUDIO_TEMPLATE_CTYPE) continue;
        if (!dtpl->audio_name[0] ||
            !gk_audio_name_equal(dtpl->audio_name, "line_out.dsp"))
            continue;
        if (!gk_audio_name_equal(cn->dst_name, "Input")) continue;
        if (cn->dst_part < 0 || cn->dst_part > 1) continue;
        gk_mix_graph_lineout_route *route =
            &gk_mix_graph_lineout[gk_mix_graph_lineout_n++];
        route->conn = gk_mix_graph_conn[n];
        route->out_index = UINT16_MAX;
        route->src_kind = 0;
        route->dsp_addr = UINT32_MAX;
        route->dsp_parts = 0;
        const uint32_t src_slot = gk_live_item_slot(cn->src_item);
        if (src_slot == UINT16_MAX) continue;
        gk_item *src = &g_gk.items[src_slot];
        if (src->ctype != GK_AUDIO_INSTRUMENT_CTYPE) continue;
        route->src_kind = (uint8_t)gk_mix_graph_kind[src_slot];
        if (route->src_kind == 2) {
            // Generated mixer: the only output name is "Output".
            if (cn->src_part >= 0 &&
                gk_audio_name_equal(cn->src_name, "Output"))
                route->out_index = (uint16_t)cn->src_part;
        } else if (route->src_kind == 1 && cn->src_part >= 0) {
            // Patch node: flatten OUTPUT part numbering in template order.
            const gk_patch_template *pt =
                src->audio_patch_graph ? src->audio_patch_graph->tpl : NULL;
            if (!pt) {
                gk_item *tpl = gk_live_item(src->template_item);
                if (tpl && tpl->patch_index > 0 &&
                    tpl->patch_index <= GK_MAX_PATCH_TEMPLATES &&
                    g_gk_patches[tpl->patch_index - 1].used)
                    pt = &g_gk_patches[tpl->patch_index - 1];
            }
            uint32_t flat = 0;
            for (uint32_t i = 0; pt && i < pt->resource_count; ++i) {
                if (pt->resources[i].type != M2_DSP_RESOURCE_OUTPUT) continue;
                if (gk_audio_name_equal(cn->src_name, pt->resources[i].name)) {
                    if ((uint32_t)cn->src_part < pt->resources[i].parts)
                        route->out_index =
                            (uint16_t)(flat + (uint32_t)cn->src_part);
                    break;
                }
                flat += pt->resources[i].parts;
                if (flat >= GK_MIXNODE_MAX_OUT) break;
            }
        } else if (route->src_kind == 0 && src->audio_dsp_sim &&
                   cn->src_part >= 0) {
            // A pure DSP source reads its OUTPUT resource word. The name is
            // template metadata, so resolve the allocation once here.
            const dspp_resource *r = gk_dsp_find_resource(
                (dspp_sim *)src->audio_dsp_sim, cn->src_name);
            if (r && r->type == 4u /* DRSC_TYPE_OUTPUT */ &&
                r->alloc_value != 0xFFFFFFFFu) {
                route->dsp_addr = r->alloc_value;
                route->dsp_parts = r->many;
            }
        }
    }

    // WITH_LINE_OUT mixers feed the same frame buckets through their computed
    // output words; collect the started ones on the same revision.
    gk_mix_graph_with_out_n = 0;
    for (uint32_t n = 0; n < ni; ++n) {
        const uint32_t slot = gk_mix_graph_inst[n];
        gk_item *inst = &g_gk.items[slot];
        if (!inst->used || !inst->audio_started) continue;
        if (gk_mix_graph_kind[slot] != 2) continue;
        gk_item *tpl = gk_live_item(inst->template_item);
        if (!tpl || (tpl->mixer_spec & 0xffffu & 0x02u) == 0u) continue;
        gk_mix_graph_with_out[gk_mix_graph_with_out_n++] =
            gk_mix_graph_inst[n];
    }
}

// Refresh the index when the graph revision moved. Call at the top of each
// structural consumer, never from inside a loop that walks this index.
static void gk_mix_graph_ensure(void) {
    uint32_t rev0 = atomic_load_explicit(&gk_mix_graph_rev, memory_order_relaxed);
    if (rev0 == gk_mix_graph_built_rev) return;
    for (int attempt = 0; attempt < 8; ++attempt) {
        gk_mix_graph_build();
        const uint32_t rev1 =
            atomic_load_explicit(&gk_mix_graph_rev, memory_order_relaxed);
        if (rev1 == rev0) {
            gk_mix_graph_built_rev = rev0;
            return;
        }
        rev0 = rev1;
    }
    // Contended rebuild: force the next consumer to try again.
    gk_mix_graph_built_rev = 0u;
}

// ---- generated-mixer hop into the DSPP graph --------------------------------
//
// On hardware a CreateMixerTemplate instrument is real DSP code: the folio
// generates a mixer image (dspp_mixer.c) whose Output resources are ordinary
// allocated DSPP data words, so ConnectInstrumentParts(mixer,Output ->
// svfilter/line_out,Input) patches the destination operand with the source
// address and the destination template reads the mixer's live word. This
// bounded host executes the mixer formula in the mix-node layer (no DSP
// image exists for the generated shape), which left every generated-mixer ->
// sim hop at the vendor shape but with no carrier: the connection installed
// (applied=0 node-route) yet the destination sim's Input stayed at its
// unconnected immediate-0, so the engine chain
// sampler_sqs2 -> mixer:8x1 -> svfilter -> mixer:7x1 -> line_out went silent
// at the first hop (census: mixer-source -> svfilter/line_out
// applied=0).
//
// The recovery here is the carrier, not new math: reserve one Output-word
// range per generated-mixer node in the shared DSPP data image (the same
// allocator the vendor's generated image would draw from), and install the
// connection exactly like a sim-source connection — dspp_sim_connect patches
// the destination's relocation sites with the source address operand. Each
// frame the mix-node tick publishes the mixer's computed output words into
// the reserved range, so the destination template reads live mixer values
// from the one M2 data memory, as on hardware. Stopped or unstarted mixers
// publish 0 (the vendor stopped-instrument behavior); DeleteItem frees the
// reservation back to the shared allocator. No guest-visible state changes:
// the reservation is host-side simulation support for the authentic mixer
// formula, exactly like the sim code images themselves.
typedef struct gk_mixnode_words {
    uint32_t item;      // owning instrument handle (0 = slot free)
    uint32_t addr;      // reserved base address in the shared data image
    uint32_t count;     // words reserved (mixer outputs, <= GK_MIXNODE_MAX_OUT)
} gk_mixnode_words;
#define GK_MIXNODE_WORDS_MAX 8u
static gk_mixnode_words gk_mixnode_word_res[GK_MIXNODE_WORDS_MAX];

// Reserve count words in the shared space for one mixer node's outputs.
// Returns the base address, or 0xFFFFFFFF when no space is live, the table
// is full, or the shared allocator is exhausted (callers fail the connect
// like the vendor's failed allocation, never fabricating an address).
static uint32_t gk_mixnode_reserve_words(uint32_t item_handle,
                                         uint32_t count) {
    if (!g_gk.audio_dsp_space || count == 0 ||
        count > GK_MIXNODE_MAX_OUT || item_handle == 0u)
        return 0xFFFFFFFFu;
    for (uint32_t i = 0; i < GK_MIXNODE_WORDS_MAX; ++i) {
        if (gk_mixnode_word_res[i].item == item_handle)
            return gk_mixnode_word_res[i].addr; // already reserved
    }
    for (uint32_t i = 0; i < GK_MIXNODE_WORDS_MAX; ++i) {
        if (gk_mixnode_word_res[i].item != 0u) continue;
        uint32_t addr = 0xFFFFFFFFu;
        if (dspp_sim_space_reserve_words(g_gk.audio_dsp_space, count,
                                         &addr) != 0)
            return 0xFFFFFFFFu;
        gk_mixnode_word_res[i].item = item_handle;
        gk_mixnode_word_res[i].addr = addr;
        gk_mixnode_word_res[i].count = count;
        return addr;
    }
    return 0xFFFFFFFFu;
}

// Release one mixer node's reservation (item deleted/stopped).
static void gk_mixnode_release_words(uint32_t item_handle) {
    if (item_handle == 0u) return;
    for (uint32_t i = 0; i < GK_MIXNODE_WORDS_MAX; ++i) {
        if (gk_mixnode_word_res[i].item != item_handle) continue;
        dspp_sim_space_release_words(g_gk.audio_dsp_space,
                                     gk_mixnode_word_res[i].addr,
                                     gk_mixnode_word_res[i].count);
        gk_mixnode_word_res[i].item = 0;
        gk_mixnode_word_res[i].addr = 0;
        gk_mixnode_word_res[i].count = 0;
    }
}

// Mixer-output carrier reservation table: one range per live generated-mixer
// node with an installed sim-carried connection.
// Resident gMixer accumulator (R2 direction): stereo int32, published after
// the nanokernel's full/half/eighth-rate staging. The raw half-rate result is
// retained in g_gk.audio_mixer_half for the intervening odd DAC frame.
static int32_t gk_gmixer[2];

// ---- R2 host-side voice signal feed ---------------------------------------
// Sample voices render SDL-direct in AudioShim with no signal path back into
// the guest graph, so mix-node inputs wired to sample-voice instruments read
// 0. The tap advances a guest-thread cursor per voice by one frame per ticked
// frame, independent of the SDL play cursor (both read the same immutable
// uploaded PCM). Evidence anchors: the mixer voice ownership mask + live-sid
// check (gk_stop_instrument_voices above — a slot counts only while active
// AND still playing one of the instrument's samples; slots recycle in
// mix_into, so a bare mask would tap another instrument's voice; the 32-slot
// bound matches kMaxVoices in host/audio/audio_shim.h); the host pool contract
// (interleaved S16 stereo pairs, m2_host_audio_add_sample) fixes the part
// mapping part0=L part1=R, parts>=2 read 0 (no mono/packed voice format is
// evidenced in-tree). Weak default keeps standalone recomp consumers (and
// the folio unit test, which strong-overrides the older voice APIs but not
// this one) linkable: without the SDL-backed shim every tap reads 0, the
// pre-R2 behavior.
__attribute__((weak)) int m2_host_audio_voice_tap_frame(uint32_t voice_index,
                                                        int16_t *l_out,
                                                        int16_t *r_out) {
    (void)voice_index;
    if (l_out) *l_out = 0;
    if (r_out) *r_out = 0;
    return 0;
}
// R2-full connection partition: standalone recomp consumers (and backends
// that predate the flag) have no direct/SDL split, so suppression is a
// no-op and every voice stays direct — the pre-R2-full behavior.
__attribute__((weak)) void m2_host_audio_set_voice_direct(uint32_t voice_index,
                                                          int on) {
    (void)voice_index;
    (void)on;
}
__attribute__((weak)) int m2_host_audio_drain_voice_to_direct(
    uint32_t voice_index) {
    (void)voice_index;
    return 0;
}
__attribute__((weak)) int32_t m2_host_audio_pause_voice(uint32_t voice_index) {
    (void)voice_index;
    return 0;
}
__attribute__((weak)) int32_t m2_host_audio_resume_voice(uint32_t voice_index) {
    (void)voice_index;
    return 0;
}
// Older standalone audio adapters expose sample identity only. UINT32_MAX
// means attachment identity is unavailable there; the production host above
// returns the actual owner, or zero for an unowned/inactive slot.
__attribute__((weak)) uint32_t m2_host_audio_voice_attachment(
    uint32_t voice_index) {
    (void)voice_index;
    return UINT32_MAX;
}
// Per-source tap memo: every outgoing wire from one voice instrument in one
// frame carries the same sample (a connection is a wire, not a read). Probe
// reads recompute under a fresh serial (see m2_guest_audio_read_probe_part),
// so a probe also consumes one tap frame per source — test sequences must
// tick-then-read to assert exact frames.
static int32_t gk_voice_tap_cache[GK_MAX_ITEMS][2];
static uint32_t gk_voice_tap_serial[GK_MAX_ITEMS];
// Attachment identity distinguishes instruments sharing the same PCM sample.
// The sample-only fallback serves older standalone audio adapters.
// Returns the sid, or 0 when the current owner belongs to another instrument.
static uint32_t gk_voice_owned_sid(gk_item *inst, uint32_t i) {
    uint32_t sid = m2_host_audio_voice_sample(i);
    if (sid == 0) return 0;
    const uint32_t owner = m2_host_audio_voice_attachment(i);
    if (owner != UINT32_MAX) {
        const gk_item *a = gk_live_item(owner);
        if (!a || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            a->attachment_type != 1u ||
            gk_live_item(a->attachment_master) != inst)
            return 0;
        const gk_item *s = gk_live_item(a->attachment_slave);
        return s && s->ctype == GK_AUDIO_SAMPLE_CTYPE &&
                       s->host_sample_id == sid
                   ? sid : 0;
    }
    for (uint32_t k = 0; k < GK_MAX_ITEMS; ++k) {
        const gk_item *a = &g_gk.items[k];
        if (!a->used || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            a->attachment_type != 1u)
            continue;
        if (gk_live_item(a->attachment_master) != inst) continue;
        gk_item *s = gk_live_item(a->attachment_slave);
        if (s && s->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            s->host_sample_id == sid)
            return sid;
    }
    return 0;
}
static int gk_mix_diag_enabled(void) {
    static int checked = 0, enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_AUDIO_MIX_DIAG");
        enabled = e && *e && *e != '0';
        checked = 1;
    }
    return enabled;
}
static void gk_mix_bump_serial(void) {
    if (++gk_mix_serial == 0) {
        // Serial wrap (one per tick; ~136 years at 44.1kHz): re-baseline
        // every memo so slot serial 0 again means stale.
        memset(gk_mix_out_serial, 0, sizeof(gk_mix_out_serial));
        memset(gk_mix_conn_serial, 0, sizeof(gk_mix_conn_serial));
        memset(gk_voice_tap_serial, 0, sizeof(gk_voice_tap_serial));
        gk_mix_serial = 1;
    }
}
// ConvertFP_SF15 (dspp_knobs.c): float to signed 16-bit word with clip.
static int32_t gk_mixnode_sf15(float v) {
    int32_t raw = (int32_t)(v * 32768.0f);
    if (raw < -32768) raw = -32768;
    if (raw > 32767) raw = 32767;
    return raw;
}
static int16_t gk_mixnode_clip(int32_t v) {
    if (v < -32768) v = -32768;
    if (v > 32767) v = 32767;
    return (int16_t)v;
}
// Live Gain/Amplitude knob item owned by a mixer node, if the guest created
// one (CreateKnob exposes Gain with inputs*outputs parts per
// gk_find_audio_port). Absent knobs read the vendor defaults (Gain 0,
// Amplitude 1.0); the item scan stays correct under guest knob delete and
// recreate with no cache to invalidate.
static gk_item *gk_mixnode_find_knob(uint32_t inst_handle, const char *name) {
    if (!inst_handle || !name) return NULL;
    const uint32_t slot = gk_live_item_slot(inst_handle);
    if (slot == UINT16_MAX) return NULL;
    for (uint16_t n = gk_mix_graph_knob_head[slot]; n != UINT16_MAX;
         n = gk_mix_graph_knob_next[n]) {
        gk_item *k = &g_gk.items[gk_mix_graph_knob[n]];
        if (!k->used || k->ctype != GK_AUDIO_KNOB_CTYPE) continue;
        if (k->knob_instrument != inst_handle) continue;
        if (gk_audio_name_equal(k->audio_name, name)) return k;
    }
    return NULL;
}
static int gk_patch_has_resource(const gk_patch_template *pt,
                                 const char *name, uint8_t type,
                                 uint32_t parts) {
    if (!pt || !name) return 0;
    for (uint32_t i = 0; i < pt->resource_count; ++i) {
        const gk_patch_resource *r = &pt->resources[i];
        if (r->type == type && r->parts == parts &&
            gk_audio_name_equal(r->name, name))
            return 1;
    }
    return 0;
}
// MakeSound3DPatchTemplate(0x6d), as authored by sndInit3DSounds, exposes
// these exact ports and filter knobs. Distance attenuation and Doppler are
// intentionally not performed here: the vendor Sound3D library returns them
// through Get3DSoundParms and the game applies them to the source sampler's
// Amplitude and SampleRate knobs in sfxProcessOppSnd.
static int gk_patch_is_sound3d(const gk_patch_template *pt) {
    return (gk_patch_has_resource(pt, "Input", M2_DSP_RESOURCE_INPUT, 1u) ||
            gk_patch_has_resource(pt, "Input", M2_DSP_RESOURCE_INPUT, 2u)) &&
           gk_patch_has_resource(pt, "Output", M2_DSP_RESOURCE_OUTPUT, 2u) &&
           gk_patch_has_resource(pt, "Drift", M2_DSP_RESOURCE_OUTPUT, 2u) &&
           gk_patch_has_resource(pt, "Alpha", M2_DSP_RESOURCE_KNOB, 2u) &&
           gk_patch_has_resource(pt, "Beta", M2_DSP_RESOURCE_KNOB, 2u) &&
           gk_patch_has_resource(pt, "Feed", M2_DSP_RESOURCE_KNOB, 2u) &&
           gk_patch_has_resource(pt, "Delay", M2_DSP_RESOURCE_KNOB, 2u) &&
           gk_patch_has_resource(pt, "DelayRate", M2_DSP_RESOURCE_KNOB, 1u);
}
static uint32_t gk_mixnode_slot(const gk_item *inst) {
    return (uint32_t)(inst - g_gk.items);
}
// Sum one tap frame per still-owned voice of a started sample-voice source,
// memoized per source slot per serial so sibling wires (and the direct
// line_out feed below) share the sample. Stale or exhausted voices
// contribute 0. Callers gate part range; out-of-range slots are left alone.
// Bounded [voice-tap] observation: M2_AUDIO_VOICE_TRACE=<item slot> reports
// the first silent tap contributions of that source with the voice ownership
// and host voice-id state at that exact DAC frame. Used to separate "the
// guest released/stopped the voice" from "the host stopped feeding the
// graph"; cap 24 lines, observation only.
static long gk_voice_trace_slot = -1;
static void gk_voice_trace_configure(void) {
    static int checked = 0;
    if (checked) return;
    checked = 1;
    const char *e = getenv("M2_AUDIO_VOICE_TRACE");
    gk_voice_trace_slot = (e && *e) ? strtol(e, NULL, 0) : -1;
}
// Wiring-arm census for the traced source (M2_AUDIO_VOICE_TRACE). Every arm
// of the two connection consumers that can name this source records which
// branch it took, so "host stopped feeding the graph" splits into "the arm is
// no longer reached" versus "the arm ran and the tap returned zero".
enum {
    GK_VTR_A_SRC_IDLE = 0, // src not a started instrument, or bad src_part
    GK_VTR_A_MIXNODE,      // resolved as a mix-node output
    GK_VTR_A_SIM,          // resolved from the source's own DSPP sim word
    GK_VTR_A_TAP,          // sample-voice arm ran (input_sample)
    GK_VTR_A_MASK0,        // sample-voice arm skipped: mask empty
    GK_VTR_A_NAME_MISS,    // connection name/port did not resolve
    GK_VTR_A_PART_RANGE,   // dst part outside the consumer's accepted range
    GK_VTR_A_RATE_NOT_DUE, // destination instrument rate gate closed
    GK_VTR_A_FEED_GUARD,   // line_out single-delivery guard skipped the wire
    GK_VTR_A_FEED_TAP,     // line_out feed took the sample-voice arm
    GK_VTR_A_FEED_OTHER,   // line_out feed took another arm or skipped
    GK_VTR_A_COUNT
};
static const char *const gk_voice_trace_arm_names[GK_VTR_A_COUNT] = {
    "src-idle", "mixnode", "sim", "tap", "mask0", "name-miss",
    "part-range", "rate-not-due", "feed-guard", "feed-tap", "feed-other"};
static uint32_t gk_voice_trace_arm[GK_VTR_A_COUNT];
static uint32_t gk_voice_trace_armed;
static uint32_t gk_voice_trace_frame;
static uint32_t gk_voice_trace_lines;
static uint32_t gk_voice_trace_tap_calls;
static uint32_t gk_voice_trace_tap_owned;
static int32_t gk_voice_trace_tap_l, gk_voice_trace_tap_r;
static int gk_voice_trace_matches(const gk_item *src) {
    if (gk_voice_trace_slot < 0 || !src) return 0;
    return (long)(src - g_gk.items) == gk_voice_trace_slot;
}
static void gk_voice_trace_note(const gk_item *src, int arm) {
    if (!gk_voice_trace_matches(src)) return;
    if (arm >= 0 && arm < GK_VTR_A_COUNT) ++gk_voice_trace_arm[arm];
}
// Per-DAC-frame report: dense for the first 16 frames after the traced
// instrument first goes started, then one line per 256 frames while it stays
// started. Cap 200 lines keeps the observation bounded on a long run.
static void gk_voice_trace_tick_frame(void) {
    gk_voice_trace_configure();
    if (gk_voice_trace_slot < 0) return;
    if (gk_voice_trace_slot >= (long)GK_MAX_ITEMS) return;
    gk_item *src = &g_gk.items[gk_voice_trace_slot];
    const int live = src->used && src->ctype == GK_AUDIO_INSTRUMENT_CTYPE;
    const int started = live && src->audio_started;
    if (started) gk_voice_trace_armed = 1;
    if (gk_voice_trace_armed) {
        const int want = gk_voice_trace_frame < 16u ||
                         (gk_voice_trace_frame % 256u) == 0u;
        if (want && gk_voice_trace_lines < 200u) {
            ++gk_voice_trace_lines;
            fprintf(stderr,
                    "[voice-frame] n=%u f=%u serial=%u gframe=%u rendered=%u "
                    "live=%d started=%d "
                    "mask=%#x sim=%d kind=%d sid_v0=%u tap_calls=%u owned=%u "
                    "tl=%d tr=%d arms=",
                    gk_voice_trace_lines, gk_voice_trace_frame, gk_mix_serial,
                    m2_guest_current_frame_c(), m2_host_audio_frame_count(),
                    live, started, live ? src->audio_voice_mask : 0u,
                    live && src->audio_dsp_sim != NULL, live ? gk_mixnode_kind_of(src) : 0,
                    m2_host_audio_voice_sample(0), gk_voice_trace_tap_calls,
                    gk_voice_trace_tap_owned, gk_voice_trace_tap_l,
                    gk_voice_trace_tap_r);
            for (int a = 0; a < GK_VTR_A_COUNT; ++a) {
                if (gk_voice_trace_arm[a] == 0) continue;
                fprintf(stderr, " %s=%u", gk_voice_trace_arm_names[a],
                        gk_voice_trace_arm[a]);
            }
            fprintf(stderr, " gmixer=[%d %d]\n", gk_gmixer[0], gk_gmixer[1]);
        }
        ++gk_voice_trace_frame;
        memset(gk_voice_trace_arm, 0, sizeof(gk_voice_trace_arm));
        gk_voice_trace_tap_calls = 0;
        gk_voice_trace_tap_owned = 0;
        gk_voice_trace_tap_l = 0;
        gk_voice_trace_tap_r = 0;
    }
}
static void gk_voice_tap_fill(gk_item *src) {
    if (!src || src->ctype != GK_AUDIO_INSTRUMENT_CTYPE) return;
    uint32_t slot = gk_mixnode_slot(src);
    if (slot >= GK_MAX_ITEMS) return;
    if (gk_voice_tap_serial[slot] == gk_mix_serial) return;
    gk_voice_trace_configure();
    int32_t tl = 0, tr = 0;
    uint32_t owned = 0;
    for (uint32_t vi = 0; vi < 32u; ++vi) {
        if ((src->audio_voice_mask & (1u << vi)) == 0) continue;
        if (!gk_voice_owned_sid(src, vi)) continue;
        ++owned;
        int16_t fl = 0, fr = 0;
        if (m2_host_audio_voice_tap_frame(vi, &fl, &fr)) {
            tl += fl;
            tr += fr;
        }
    }
    if (gk_voice_trace_matches(src)) {
        ++gk_voice_trace_tap_calls;
        gk_voice_trace_tap_owned = owned;
        gk_voice_trace_tap_l = tl;
        gk_voice_trace_tap_r = tr;
    }
    gk_voice_tap_cache[slot][0] = tl;
    gk_voice_tap_cache[slot][1] = tr;
    gk_voice_tap_serial[slot] = gk_mix_serial;
}

static int16_t gk_mixnode_port_output(gk_item *inst, uint32_t inst_handle,
                                      const char *name, int32_t part,
                                      uint32_t depth);
static int16_t gk_mixnode_input_sample(uint32_t dst_item, const char *dst_name,
                                       int32_t dst_part, uint32_t depth);
static int16_t gk_mix_conn_sample(uint32_t conn, uint32_t depth);
static void gk_patch_graph_resolve(gk_item *instrument,
                                   uint32_t instrument_handle);

// Graph-index kind of a live instrument. An instrument minted since the last
// rebuild has no entry yet and takes the template walk.
static int gk_mix_kind(const gk_item *instrument) {
    const int kind = gk_mix_graph_kind[instrument - g_gk.items];
    return kind >= 0 ? kind : gk_mixnode_kind_of(instrument);
}

// A resolved knob slot, still owned by this instrument.
static gk_item *gk_mix_resolved_knob(int16_t slot, uint32_t inst_handle) {
    if (slot < 0) return NULL;
    gk_item *knob = &g_gk.items[slot];
    return knob->used && knob->ctype == GK_AUDIO_KNOB_CTYPE &&
                   knob->knob_instrument == inst_handle
               ? knob : NULL;
}

typedef struct gk_mix_branch_tracker {
    uint32_t slot_plus_one;
    uint32_t frames;
    uint32_t windows;
    uint32_t nz[7];
    int32_t peak[7];
    int32_t gain[7];
    int64_t sum[7];
} gk_mix_branch_tracker;

// Existing M2_AUDIO_MIX_DIAG, extended for the race's final stereo pair of
// 7x1 mixers. Report each post-Gain input contribution once per DAC second;
// this is observational and does not alter graph values or guest control.
static void gk_mix_branch_census(uint32_t slot, uint32_t inst_handle,
                                 const int32_t contribution[7],
                                 const int32_t gain[7]) {
    static gk_mix_branch_tracker trackers[8];
    if (!gk_mix_diag_enabled()) return;
    gk_mix_branch_tracker *t = NULL;
    for (uint32_t i = 0; i < 8u; ++i) {
        if (trackers[i].slot_plus_one == slot + 1u) {
            t = &trackers[i];
            break;
        }
        if (!t && trackers[i].slot_plus_one == 0u) t = &trackers[i];
    }
    if (!t) return;
    if (t->slot_plus_one == 0u) t->slot_plus_one = slot + 1u;
    for (uint32_t i = 0; i < 7u; ++i) {
        const int32_t v = contribution[i];
        int32_t a = v < 0 ? -v : v;
        if (v != 0) ++t->nz[i];
        if (a > t->peak[i]) t->peak[i] = a;
        t->sum[i] += v;
        t->gain[i] = gain[i];
    }
    if (++t->frames < 44100u) return;
    if (t->windows < 32u) {
        fprintf(stderr, "[audio-branch] w=%u inst=%#x",
                t->windows, inst_handle);
        for (uint32_t i = 0; i < 7u; ++i)
            fprintf(stderr, " i%u(nz=%u pk=%d mean=%lld g=%d)", i,
                    t->nz[i], t->peak[i],
                    (long long)(t->sum[i] / (int64_t)t->frames), t->gain[i]);
        fprintf(stderr, "\n");
    }
    ++t->windows;
    t->frames = 0u;
    memset(t->nz, 0, sizeof(t->nz));
    memset(t->peak, 0, sizeof(t->peak));
    memset(t->sum, 0, sizeof(t->sum));
}

// Compute one node's outputs for the current serial. Marks the memo first
// so dependency cycles (rejected by the folio, tolerated here) read zeros
// instead of recursing unboundedly; depth caps pathological chains.
static void gk_mixnode_compute(gk_item *inst, uint32_t inst_handle,
                               uint32_t depth) {
    if (!inst || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE) return;
    uint32_t slot = gk_mixnode_slot(inst);
    if (slot >= GK_MAX_ITEMS) return;
    if (gk_mix_out_serial[slot] == gk_mix_serial) return;
    gk_mix_out_serial[slot] = gk_mix_serial;
    memset(gk_mix_out[slot], 0, sizeof(gk_mix_out[slot]));
    gk_mix_out_count[slot] = 0;
    int kind = gk_mix_kind(inst);
    if (kind == 0 || !inst->audio_started || inst->audio_paused ||
        depth > GK_MIXNODE_MAX_DEPTH)
        return;
    if (kind == 1) {
        // A source-defined patch has one host-side graph of the original DSPP
        // constituent templates. Its outputs are read from the same shared
        // data words that the constituent code writes. Empty graph pointers
        // are retained for the older port-only patch-shell compatibility
        // shape, whose patch-scope wires are handled below.
        const gk_patch_template *pt =
            inst->audio_patch_graph ? inst->audio_patch_graph->tpl : NULL;
        if (!pt) {
            gk_item *tpl = gk_live_item(inst->template_item);
            if (tpl && tpl->patch_index > 0 &&
                tpl->patch_index <= GK_MAX_PATCH_TEMPLATES &&
                g_gk_patches[tpl->patch_index - 1].used)
                pt = &g_gk_patches[tpl->patch_index - 1];
        }
        if (!pt) return;
        if (inst->audio_patch_graph) {
            gk_patch_graph *graph = inst->audio_patch_graph;
            if (graph->resolved_rev != gk_mix_graph_built_rev ||
                graph->resolved_rev == 0u)
                gk_patch_graph_resolve(inst, inst_handle);
            gk_patch_graph_tick(inst, inst_handle, depth);
            for (uint32_t i = 0; i < graph->output_count; ++i)
                gk_mix_out[slot][i] = (int16_t)dspp_sim_peek_data(
                    graph->block_sims[0], graph->output_address[i]);
            gk_mix_out_count[slot] = graph->output_count;
            return;
        }
        if (gk_patch_is_sound3d(pt)) {
            // Port-only compatibility patch: filter_3d.ins, twice (one per
            // ear). A real Sound3D PAN_DELAY patch takes the graph branch
            // above; this fallback remains for historical patch fixtures that
            // deliberately contain no constituent templates.
            const int16_t x = gk_mixnode_input_sample(
                inst_handle, "Input", 0, depth + 1u);
            const uint32_t phase = inst->sound3d_delay_phase % 3u;
            const int16_t x3 = inst->sound3d_delayed_input[phase];
            inst->sound3d_delayed_input[phase] = x;
            inst->sound3d_delay_phase = (uint8_t)((phase + 1u) % 3u);
            gk_item *alpha = gk_mixnode_find_knob(inst_handle, "Alpha");
            gk_item *beta = gk_mixnode_find_knob(inst_handle, "Beta");
            gk_item *feed = gk_mixnode_find_knob(inst_handle, "Feed");
            int16_t ear[2] = {x, x};
            for (uint32_t e = 0; e < 2u; ++e) {
                const int32_t a = alpha && e < alpha->knob_parts
                                      ? gk_mixnode_sf15(alpha->knob_values[e])
                                      : 0;
                const int32_t b = beta && e < beta->knob_parts
                                      ? gk_mixnode_sf15(beta->knob_values[e])
                                      : 0;
                const int32_t f = feed && e < feed->knob_parts
                                      ? gk_mixnode_sf15(feed->knob_values[e])
                                      : 32767;
                const int32_t y = (int32_t)(((int64_t)x * f +
                                   (int64_t)x3 * b +
                                   (int64_t)inst->sound3d_previous_output[e] * a) >> 15);
                ear[e] = gk_mixnode_clip(y);
                inst->sound3d_previous_output[e] = ear[e];
            }
            uint32_t flat = 0;
            for (uint32_t i = 0;
                 i < pt->resource_count && flat < GK_MIXNODE_MAX_OUT; ++i) {
                if (pt->resources[i].type != M2_DSP_RESOURCE_OUTPUT) continue;
                for (uint32_t p = 0;
                     p < pt->resources[i].parts && flat < GK_MIXNODE_MAX_OUT;
                     ++p) {
                    gk_mix_out[slot][flat++] =
                        gk_audio_name_equal(pt->resources[i].name, "Output") &&
                                p < 2u
                            ? ear[p]
                            : 0;
                }
            }
            gk_mix_out_count[slot] = flat;
            return;
        }
        uint32_t flat = 0;
        for (uint32_t i = 0; i < pt->resource_count && flat < GK_MIXNODE_MAX_OUT;
             ++i) {
            if (pt->resources[i].type != M2_DSP_RESOURCE_OUTPUT) continue;
            for (uint32_t p = 0;
                 p < pt->resources[i].parts && flat < GK_MIXNODE_MAX_OUT;
                 ++p) {
                int16_t v = 0;
                // First matching patch-scope route wins (unobserved
                // multi-drive; documented).
                for (uint32_t r = 0; r < pt->route_count; ++r) {
                    const gk_patch_route *rt = &pt->routes[r];
                    if (rt->from_block_ea != 0u || rt->to_block_ea != 0u)
                        continue;
                    if (rt->to_part != p ||
                        !gk_audio_name_equal(rt->to_port,
                                             pt->resources[i].name))
                        continue;
                    // The source must be a patch INPUT port (vendor
                    // PATCH_RESOURCE_CONNECTABLE_SRC); anything else
                    // (knobs, exposed) carries no signal here.
                    int src_ok = 0;
                    for (uint32_t k = 0; k < pt->resource_count; ++k) {
                        if (pt->resources[k].type != M2_DSP_RESOURCE_INPUT)
                            continue;
                        if (!gk_audio_name_equal(rt->from_port,
                                                 pt->resources[k].name))
                            continue;
                        if (rt->from_part < pt->resources[k].parts)
                            src_ok = 1;
                        break;
                    }
                    if (!src_ok) break;
                    if (depth + 1u > GK_MIXNODE_MAX_DEPTH) break;
                    v = gk_mixnode_input_sample(inst_handle, rt->from_port,
                                                (int32_t)rt->from_part,
                                                depth + 1u);
                    break;
                }
                gk_mix_out[slot][flat++] = v;
            }
        }
        gk_mix_out_count[slot] = flat;
        return;
    }
    // Mixer node: vendor MAC formula (dspp_mixer.c mxBuildCode).
    gk_item *tpl = gk_live_item(inst->template_item);
    if (!tpl || tpl->mixer_spec == 0) return;
    uint32_t ni = (tpl->mixer_spec >> 24) & 0xffu;
    uint32_t no = (tpl->mixer_spec >> 16) & 0xffu;
    uint32_t flags = tpl->mixer_spec & 0xffffu;
    if (ni == 0 || ni > 32u || no == 0 || no > GK_MIXNODE_MAX_OUT) return;
    gk_mix_out_count[slot] = no;
    gk_item *gain =
        gk_mix_resolved_knob(gk_mix_graph_gain_knob[slot], inst_handle);
    int32_t amp_raw = 32767; // Amplitude knob default 1.0 (autodoc)
    if ((flags & 0x01u) != 0u) {
        gk_item *amp =
            gk_mix_resolved_knob(gk_mix_graph_amp_knob[slot], inst_handle);
        if (amp && amp->knob_parts >= 1u && amp->knob_value_set[0])
            amp_raw = gk_mixnode_sf15(amp->knob_values[0]);
    }
    int32_t branch_contribution[7] = {0};
    int32_t branch_gain[7] = {0};
    for (uint32_t o = 0; o < no; ++o) {
        int32_t acc = 0;
        for (uint32_t i = 0; i < ni; ++i) {
            const int16_t conn = gk_mix_graph_input_conn[slot][i];
            int16_t in = conn >= 0 && depth + 1u <= GK_MIXNODE_MAX_DEPTH
                             ? gk_mix_conn_sample((uint32_t)conn, depth + 1u)
                             : 0;
            // CalcMixerGainPart: part = outChan*numIn + inChan. Unset
            // parts read the zero-init retained value: vendor Gain default.
            int32_t g = 0;
            uint32_t gp = o * ni + i;
            if (gain && gp < gain->knob_parts)
                g = gk_mixnode_sf15(gain->knob_values[gp]);
            const int32_t contribution = ((int32_t)in * g) >> 15;
            acc += contribution;
            if (ni == 7u && no == 1u && o == 0u) {
                branch_contribution[i] = contribution;
                branch_gain[i] = g;
            }
        }
        // Several full-level inputs can sum beyond S16. Keep the product
        // wide until scaling, otherwise host integer overflow flips the
        // waveform's sign before the output clip can handle the peak.
        if ((flags & 0x01u) != 0u)
            acc = (int32_t)(((int64_t)acc * amp_raw) >> 15);
        gk_mix_out[slot][o] = gk_mixnode_clip(acc);
    }
    if (ni == 7u && no == 1u)
        gk_mix_branch_census(slot, inst_handle, branch_contribution,
                             branch_gain);
}
// Index of a node output port part in its flattened gk_mix_out words (mixer
// "Output"/patch OUTPUT port + part; patch parts flatten across OUTPUT ports in
// template order). -1 when the port or part does not exist.
static int gk_mixnode_output_index(gk_item *inst, int kind, const char *name,
                                   int32_t part) {
    if (part < 0) return -1;
    if (kind == 2)
        return gk_audio_name_equal(name, "Output") ? (int)part : -1;
    if (kind != 1) return -1;
    const gk_patch_template *pt =
        inst->audio_patch_graph ? inst->audio_patch_graph->tpl : NULL;
    if (!pt) {
        gk_item *tpl = gk_live_item(inst->template_item);
        if (tpl && tpl->patch_index > 0 &&
            tpl->patch_index <= GK_MAX_PATCH_TEMPLATES &&
            g_gk_patches[tpl->patch_index - 1].used)
            pt = &g_gk_patches[tpl->patch_index - 1];
    }
    if (!pt) return -1;
    uint32_t flat = 0;
    for (uint32_t i = 0; i < pt->resource_count; ++i) {
        if (pt->resources[i].type != M2_DSP_RESOURCE_OUTPUT) continue;
        if (gk_audio_name_equal(name, pt->resources[i].name))
            return (uint32_t)part < pt->resources[i].parts
                       ? (int)(flat + (uint32_t)part) : -1;
        flat += pt->resources[i].parts;
        if (flat >= GK_MIXNODE_MAX_OUT) break;
    }
    return -1;
}
// Resolve one value of a node's output port.
static int16_t gk_mixnode_port_output(gk_item *inst, uint32_t inst_handle,
                                      const char *name, int32_t part,
                                      uint32_t depth) {
    if (!inst || !name || part < 0) return 0;
    gk_mixnode_compute(inst, inst_handle, depth);
    uint32_t slot = gk_mixnode_slot(inst);
    if (slot >= GK_MAX_ITEMS) return 0;
    const int index = gk_mixnode_output_index(inst, gk_mix_kind(inst), name, part);
    if (index < 0 || (uint32_t)index >= gk_mix_out_count[slot]) return 0;
    return gk_mix_out[slot][index];
}
// First wire feeding a destination port part, or -1. The connection table is
// the record, so routes install at connect time and values flow from here.
static int gk_mix_find_input_conn(uint32_t dst_item, const char *dst_name,
                                  int32_t dst_part) {
    const uint32_t dst_slot = gk_live_item_slot(dst_item);
    if (dst_slot == UINT16_MAX) return -1;
    for (uint16_t n = gk_mix_graph_conn_head[dst_slot]; n != UINT16_MAX;
         n = gk_mix_graph_conn_next[n]) {
        const uint32_t i = gk_mix_graph_conn[n];
        const gk_audio_connection *cn = &g_gk.connections[i];
        if (cn->used && cn->dst_item == dst_item &&
            cn->dst_part == dst_part &&
            gk_audio_name_equal(cn->dst_name, dst_name))
            return (int)i;
    }
    return -1;
}
// Current sample carried by one wire, memoized per serial. Started node
// sources recurse (memoized per serial); started DSP sim sources peek their
// authentic OUTPUT word; started sample-voice sources sum one tap frame per
// still-owned voice (memoized per source, so every outgoing wire carries the
// same sample); anything unstarted reads 0.
static int16_t gk_mix_conn_sample(uint32_t conn, uint32_t depth) {
    const gk_audio_connection *cn = &g_gk.connections[conn];
    if (!cn->used) return 0;
    if (gk_mix_conn_serial[conn] == gk_mix_serial)
        return gk_mix_conn_value[conn];
    int16_t v = 0;
    gk_item *src = gk_live_item(cn->src_item);
    if (src && src->ctype == GK_AUDIO_INSTRUMENT_CTYPE &&
        src->audio_started && cn->src_part >= 0) {
        const int kind = gk_mix_kind(src);
        if (kind != 0) {
            gk_voice_trace_note(src, GK_VTR_A_MIXNODE);
            gk_mixnode_compute(src, cn->src_item, depth + 1u);
            int index = gk_mix_graph_src_out[conn];
            if (index == GK_MIX_OUT_UNRESOLVED) {
                index = gk_mixnode_output_index(src, kind, cn->src_name,
                                                cn->src_part);
                gk_mix_graph_src_out[conn] = (int16_t)index;
            }
            const uint32_t slot = gk_mixnode_slot(src);
            if (index >= 0 && (uint32_t)index < gk_mix_out_count[slot])
                v = gk_mix_out[slot][index];
        } else if (src->audio_dsp_sim) {
            gk_voice_trace_note(src, GK_VTR_A_SIM);
            dspp_sim *sim = (dspp_sim *)src->audio_dsp_sim;
            if (gk_mix_graph_src_sim[conn] != sim) {
                gk_mix_graph_src_sim[conn] = sim;
                gk_mix_graph_src_res[conn] =
                    gk_dsp_find_resource(sim, cn->src_name);
            }
            const dspp_resource *r = gk_mix_graph_src_res[conn];
            if (r && r->type == 4u /* DRSC_TYPE_OUTPUT */ &&
                r->alloc_value != 0xFFFFFFFFu &&
                (uint32_t)cn->src_part < r->many)
                v = (int16_t)dspp_sim_peek_data(
                    sim, r->alloc_value + (uint32_t)cn->src_part);
        } else if (src->audio_voice_mask != 0) {
            // R2 voice feed: started sample-voice instrument with no DSPP
            // sim (mask-nonzero implies uploaded sample voices; the sim
            // arm above already claimed sim-backed sources). Shared tap
            // fill: one frame per still-owned voice, memoized per source
            // per frame so sibling wires share the sample.
            uint32_t slot = gk_mixnode_slot(src);
            if (slot < GK_MAX_ITEMS && cn->src_part < 2) {
                gk_voice_trace_note(src, GK_VTR_A_TAP);
                gk_voice_tap_fill(src);
                v = gk_mixnode_clip(gk_voice_tap_cache[slot][cn->src_part]);
            } else {
                gk_voice_trace_note(src, GK_VTR_A_PART_RANGE);
            }
        } else {
            gk_voice_trace_note(src, GK_VTR_A_MASK0);
        }
    } else {
        gk_voice_trace_note(src, GK_VTR_A_SRC_IDLE);
    }
    gk_mix_conn_value[conn] = v;
    gk_mix_conn_serial[conn] = gk_mix_serial;
    return v;
}
// Resolve one sample feeding a node's input slot by name.
static int16_t gk_mixnode_input_sample(uint32_t dst_item, const char *dst_name,
                                       int32_t dst_part, uint32_t depth) {
    if (!dst_name || dst_part < 0 || depth > GK_MIXNODE_MAX_DEPTH) return 0;
    const int conn = gk_mix_find_input_conn(dst_item, dst_name, dst_part);
    return conn >= 0 ? gk_mix_conn_sample((uint32_t)conn, depth) : 0;
}
// Per-frame node tick, called from m2_guest_audio_tick_dspp_frames after the
// DSPP sims advance (node inputs from sims read fresh words). The vendor
// nanokernel clears gMixer after each DAC transfer, then runs full-rate
// output instruments every frame and stages half/eighth-rate output
// instruments separately. On even frames it publishes full + (old half / 2)
// + (new half / 2), retaining the raw new half result; on odd frames it
// publishes full + the retained raw half result. This is the host equivalent
// of nanokernel.ins's MixerFull/MixerHalf branch. The route arms below feed
// those buckets from line_out.dsp Inputs and WITH_LINE_OUT mixer outputs.
static void gk_mixnode_tick_frame(void) {
    gk_mix_graph_ensure();
    gk_mix_bump_serial();
    int32_t full[2] = {0, 0};
    int32_t half[2] = {0, 0};
    int32_t eighth[2] = {0, 0};
    int any = 0;
    for (uint32_t n = 0; n < gk_mix_graph_inst_n; ++n) {
        const uint32_t s = gk_mix_graph_inst[n];
        gk_item *inst = &g_gk.items[s];
        if (!inst->used || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
            !inst->audio_started)
            continue;
        if (gk_mix_graph_kind[s] == 0) {
            // R2-full: started sample-voice and DSP-sim instruments are
            // graph sources too (direct source -> line_out routes feed
            // below), so they arm the feed scan alongside started nodes.
            if (inst->audio_voice_mask != 0 || inst->audio_dsp_sim != NULL)
                any = 1;
            continue;
        }
        any = 1;
        gk_mixnode_compute(
            inst, gk_make_handle(GK_TYPE_ITEM_VA, s, inst->generation), 0);
    }
    if (any) {
        for (uint32_t n = 0; n < gk_mix_graph_lineout_n; ++n) {
            const gk_mix_graph_lineout_route *route = &gk_mix_graph_lineout[n];
            const gk_audio_connection *cn = &g_gk.connections[route->conn];
            if (!cn->used) continue;
            gk_item *src = gk_live_item(cn->src_item);
            if (!src || !src->audio_started) continue;
            gk_item *dst = gk_live_item(cn->dst_item);
            if (!dst || dst->ctype != GK_AUDIO_INSTRUMENT_CTYPE) continue;
            if (cn->dst_part < 0 || cn->dst_part > 1) continue;
            // Single-delivery guard: when the destination
            // line_out's own instrumentation runs (started sim, import
            // resolved), the authentic carrier owns this route — the sim
            // accumulates Input into the head's gMixer and the platform
            // staging transfers it (nanokernel.ins OutputToDAC block).
            // Feeding the bucket too would count the same signal twice.
            // A stopped or sim-less line_out keeps the host bucket as the
            // route's carrier (the vendor's stopped instrument delivers
            // nothing itself).
            if (dst->audio_dsp_sim && dst->audio_started) {
                gk_voice_trace_note(src, GK_VTR_A_FEED_GUARD);
                continue;
            }
            if (!gk_audio_rate_due(dst)) {
                gk_voice_trace_note(src, GK_VTR_A_RATE_NOT_DUE);
                continue;
            }
            int32_t *bucket = full;
            if (dst->calc_rate_divider == 2u)
                bucket = half;
            else if (dst->calc_rate_divider == 8u)
                bucket = eighth;

            int16_t v = 0;
            if (route->src_kind != 0) {
                // The output word was resolved with the route, so the frame
                // path only recomputes the node and reads the memoized word.
                if (route->out_index == UINT16_MAX) {
                    gk_voice_trace_note(src, GK_VTR_A_FEED_OTHER);
                    continue;
                }
                gk_mixnode_compute(src, cn->src_item, 0);
                const uint32_t slot = gk_mixnode_slot(src);
                if (slot >= GK_MAX_ITEMS ||
                    (uint32_t)route->out_index >= gk_mix_out_count[slot]) {
                    gk_voice_trace_note(src, GK_VTR_A_FEED_OTHER);
                    continue;
                }
                v = gk_mix_out[slot][route->out_index];
            } else if (src->audio_dsp_sim && route->dsp_addr != UINT32_MAX &&
                       (uint32_t)cn->src_part < route->dsp_parts) {
                // A pure DSP source has no mix-node wrapper, but its OUTPUT
                // word is the same source value the DSPP connection arm
                // exposes. This keeps a direct DSP -> line_out route on the
                // authentic shared-mix path; the allocation was resolved when
                // the route record was built.
                v = (int16_t)dspp_sim_peek_data(
                    (dspp_sim *)src->audio_dsp_sim,
                    route->dsp_addr + (uint32_t)cn->src_part);
            } else if (src->audio_voice_mask != 0 &&
                       src->audio_dsp_sim == NULL && cn->src_part >= 0 &&
                       cn->src_part < 2) {
                // R2-full: direct sample-voice -> line_out routes feed the
                // same tap sum the node inputs read. line_out.ins sums every
                // Input and the vendor graph has no direct-to-DAC voice path
                // (nanokernel.ins gMixer doc), so without this feed a
                // partitioned voice on a direct route would go silent
                // instead of single-play.
                uint32_t slot = gk_mixnode_slot(src);
                if (slot >= GK_MAX_ITEMS) continue;
                gk_voice_trace_note(src, GK_VTR_A_FEED_TAP);
                gk_voice_tap_fill(src);
                v = gk_mixnode_clip(gk_voice_tap_cache[slot][cn->src_part]);
            } else {
                gk_voice_trace_note(src, GK_VTR_A_FEED_OTHER);
                continue;
            }
            // line_out.ins: gMixer _%A Input _A _CLIP _+ — the clip is on
            // the accumulate, so saturate every add. The explicit _CLIP
            // (added 931104 per the .ins header) is what saturates: the
            // mixer's own WITH_LINE_OUT arm below keeps plain addition,
            // matching dspp_mixer.c's OPCODE_PLUS_ACCUME.
            bucket[cn->dst_part] =
                gk_mixnode_clip(bucket[cn->dst_part] + v);
        }
        for (uint32_t n = 0; n < gk_mix_graph_with_out_n; ++n) {
            const uint32_t s = gk_mix_graph_with_out[n];
            gk_item *inst = &g_gk.items[s];
            if (!inst->used || !inst->audio_started ||
                inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
                continue;
            uint32_t slot = gk_mixnode_slot(inst);
            if (slot >= GK_MAX_ITEMS || !gk_audio_rate_due(inst)) continue;
            int32_t *bucket = full;
            if (inst->calc_rate_divider == 2u)
                bucket = half;
            else if (inst->calc_rate_divider == 8u)
                bucket = eighth;
            // WITH_LINE_OUT requires 2 outputs (validated at creation).
            for (uint32_t o = 0; o < 2u && o < gk_mix_out_count[slot]; ++o)
                bucket[o] += gk_mix_out[slot][o];
        }
    }

    int32_t half_result[2];
    if ((g_gk.audio_frame_low & 1u) == 0u) {
        for (uint32_t ch = 0; ch < 2u; ++ch) {
            const int32_t old_half = g_gk.audio_mixer_half[ch];
            g_gk.audio_mixer_half[ch] = half[ch];
            half_result[ch] = (old_half >> 1) + (half[ch] >> 1);
        }
    } else {
        half_result[0] = g_gk.audio_mixer_half[0];
        half_result[1] = g_gk.audio_mixer_half[1];
    }
    for (uint32_t ch = 0; ch < 2u; ++ch)
        gk_gmixer[ch] = gk_mixnode_clip(full[ch] + half_result[ch] +
                                        eighth[ch]);

    // Generated-mixer hop publish: each started mixer node's
    // computed Output words go into its reserved range of the shared DSPP
    // data image, so downstream sim destinations (svfilter, line_out) patched
    // with that address read live mixer values — the carrier the vendor's
    // generated mixer image provides on hardware. Unstarted nodes publish 0
    // (the stopped-instrument word); unmemoized slots stay 0. Rate grouping
    // is not applied to the carrier words: the vendor's generated mixer runs
    // at the instrument's own calc rate and its output word holds the last
    // computed value between runs, which the memo already reflects.
    for (uint32_t w = 0; w < GK_MIXNODE_WORDS_MAX; ++w) {
        const gk_mixnode_words *res = &gk_mixnode_word_res[w];
        if (res->item == 0u || !g_gk.audio_dsp_space) continue;
        gk_item *owner = gk_live_item(res->item);
        if (!owner || owner->ctype != GK_AUDIO_INSTRUMENT_CTYPE) continue;
        uint32_t slot = gk_mixnode_slot(owner);
        for (uint32_t k = 0; k < res->count; ++k) {
            uint16_t v = 0;
            if (owner->audio_started && slot < GK_MAX_ITEMS &&
                k < gk_mix_out_count[slot])
                v = (uint16_t)(int16_t)gk_mix_out[slot][k];
            dspp_sim_space_poke_kernel_data(g_gk.audio_dsp_space,
                                            res->addr + k, v);
        }
    }

    // Nanokernel DAC staging (importer-kernel route): when the on-disc head
    // is resident, real line_out/mixer instruments accumulate into the
    // head's gMixer data words (their import resolved to those addresses).
    // The nanokernel then transfers gMixer[ch] x Amplitude to the DAC pair
    // each frame (OutputToDAC 0/1 PART+ _A _= gMixer ... _A Amplitude _A _*,
    // nanokernel.ins) and clears the accumulators. Mirror that transfer into
    // the resident mix: each frame, add the head's gMixer words (sign-16 as
    // the DSPP data memory holds them, Amplitude raw $7FFF = unity), then
    // clear them for the next frame's accumulation. The clear is the vendor
    // _MOVE gMixer i PART+ _A 0 after the DAC write. The head sim itself is
    // not registered in the tick loop: the folio owns its program counter
    // through the patched-head SLEEP and only the DSPI/DAC staging is
    // guest-visible here.
    if (g_gk.audio_dsp_space) {
        // Name resolution walks every export owner, so resolve the two
        // staging names once per export-table revision instead of on every
        // DAC frame.
        static dspp_sim_space *gmix_space;
        static uint32_t gmix_generation;
        static uint32_t gmix_addr;
        static uint32_t gmix_amp_addr;
        static int gmix_valid;
        const uint32_t export_generation =
            dspp_sim_space_export_generation(g_gk.audio_dsp_space);
        if (gmix_space != g_gk.audio_dsp_space ||
            gmix_generation != export_generation) {
            gmix_space = g_gk.audio_dsp_space;
            gmix_generation = export_generation;
            gmix_addr = 0;
            gmix_amp_addr = 0xFFFFFFFFu;
            gmix_valid =
                dspp_sim_space_export_address(g_gk.audio_dsp_space, "gMixer",
                                              &gmix_addr) == 0;
            if (!gmix_valid) gmix_addr = 0;
            if (dspp_sim_space_export_address(g_gk.audio_dsp_space,
                                              "Amplitude",
                                              &gmix_amp_addr) != 0)
                gmix_amp_addr = 0xFFFFFFFFu;
        }
        const uint32_t gmixer_addr = gmix_addr;
        const uint32_t amp_addr = gmix_amp_addr;
        if (gmix_valid && gmixer_addr + 1u < DSPP_DATA_MEMORY_WORDS) {
            int32_t amp = 32767; // vendor Amplitude default 1.0 ($7FFF)
            if (amp_addr < DSPP_DATA_MEMORY_WORDS) {
                uint16_t raw = dspp_sim_space_peek_kernel_data(
                    g_gk.audio_dsp_space, amp_addr);
                if (raw != 0u) amp = (int32_t)(int16_t)raw;
            }
            for (uint32_t ch = 0; ch < 2u; ++ch) {
                int32_t acc = (int32_t)(int16_t)dspp_sim_space_peek_kernel_data(
                    g_gk.audio_dsp_space, gmixer_addr + ch);
                if (acc != 0) {
                    // Bounded head-staging visibility (M2_AUDIO_START_DIAG):
                    // the gMixer word held a nonzero accumulator this frame.
                    // A sustained nonzero here with no matching output
                    // instrument write names a shared-space alias (see
                    // [audio-alloc]) instead of a graph mix.
                    if (gk_audio_start_diag_enabled()) {
                        static uint32_t head_stage_diag;
                        if (head_stage_diag < 16u) {
                            ++head_stage_diag;
                            fprintf(stderr,
                                    "[audio-head] n=%u ch=%u gMixer=%#x "
                                    "amp_addr=%#x acc=%d amp=%d\n",
                                    head_stage_diag, ch, gmixer_addr + ch,
                                    amp_addr, acc, amp);
                        }
                    }
                    // OutputToDAC = gMixer x Amplitude (plain _=, no _CLIP;
                    // nanokernel.ins), Amplitude raw $7FFF is the vendor
                    // folio default 1.0 and the game never calls the
                    // privileged SetAudioFolioInfo. The S16 clamp below is
                    // the host's resident-mix representation.
                    int32_t scaled = (acc * amp) >> 15;
                    gk_gmixer[ch] = gk_mixnode_clip(gk_gmixer[ch] + scaled);
                    dspp_sim_space_poke_kernel_data(g_gk.audio_dsp_space,
                                                    gmixer_addr + ch, 0u);
                }
            }
        }
    }

    // Live-race evidence for the voice feed (default off): the first frames
    // with a nonzero resident mix prove started voices flow through the
    // graph on the real guest route. Bounded (8) behind M2_AUDIO_MIX_DIAG.
    if ((gk_gmixer[0] != 0 || gk_gmixer[1] != 0) &&
        gk_mix_diag_enabled()) {
        static uint32_t mix_diag_n = 0;
        if (mix_diag_n < 8u) {
            ++mix_diag_n;
            fprintf(stderr, "[audio-mix] n=%u gmixer=[%d %d]\n", mix_diag_n,
                    gk_gmixer[0], gk_gmixer[1]);
        }
    }
    gk_voice_trace_tick_frame();
}
// R1-observable / R2 seam: read the nanokernel-published DAC-frame mix
// (int32 holding the full/half/eighth-rate staged output: voice-fed since R2,
// with line_out.ins clip order on each bucket accumulate). R2-full pushes it
// per tick as the DAC transfer (see the pump below), so this seam also serves
// the render path's observation primitive.
void m2_guest_audio_read_resident_mix(int32_t stereo_out[2]) {
    if (!stereo_out) return;
    stereo_out[0] = gk_gmixer[0];
    stereo_out[1] = gk_gmixer[1];
}
// ---- R2-full connection partition -----------------------------------------
// The vendor graph has no direct-to-DAC voice path: sampler sound exits only
// via Output ports into output instruments (nanokernel.ins gMixer doc: the
// accumulators are "transfered to the DAC FIFO and then cleared" and only
// "Output instruments (e.g., line_out.dsp(@), Mixer(@)s with
// AF_F_MIXER_WITH_LINE_OUT, etc.) accumulate their results into these
// variables"). Once this host renders the resident mix into the SDL FIFO,
// a started sampler whose Output route reaches the DAC would play twice
// (direct SDL voice plus mixed FIFO). The partition suppresses direct SDL
// accumulation ONLY for such graph-routed started samplers; bare voices
// (audible only direct), pure-synth UNIMPLEMENTED, and import-blocked
// EXTERNALREF skips stay exactly as-is. Suppression never mutes the tap:
// the tap cursor is independent, so the graph still hears the voice.
// Side-effect-free "would this retained connection install" check, mirroring
// the tick's feed arms (line_out terminal, R2-full voice-source extension
// included) and gk_dsp_apply_connection's install arms (node route, sim
// patch/MOVE) without touching sims. Templates are immutable, so
// connect-time port validation still holds; the started-state and liveness
// checks are what can change under a refresh.
static int gk_conn_hop_live(const gk_audio_connection *cn, gk_item *src,
                            gk_item *dst) {
    if (!cn || !cn->used || !src || !dst) return 0;
    if (src->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
        dst->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return 0;
    if (!src->audio_started) return 0;
    if (cn->src_part < 0 || cn->dst_part < 0) return 0;
    // Generated-mixer hop: a started mixer source into a sim destination
    // installs exactly when the connect arm does (port shapes valid and the
    // carrier words reserved). Word reservation is implied by connect-time
    // installation; a failed reservation never installed anything.
    if (gk_mixnode_kind_of(src) == 2 && dst->audio_dsp_sim) {
        uint8_t st = 0, dt = 0;
        uint32_t sp = 0, dp = 0;
        return gk_find_audio_port(src, cn->src_name, &st, &sp) == M2K_OK &&
               st == M2_DSP_RESOURCE_OUTPUT &&
               (uint32_t)cn->src_part < sp &&
               gk_find_audio_port(dst, cn->dst_name, &dt, &dp) == M2K_OK &&
               (dt == M2_DSP_RESOURCE_INPUT || dt == M2_DSP_RESOURCE_KNOB) &&
               (uint32_t)cn->dst_part < dp;
    }
    gk_item *dtpl = gk_live_item(dst->template_item);
    if (dtpl && dtpl->ctype == GK_AUDIO_TEMPLATE_CTYPE &&
        dtpl->audio_name[0] &&
        gk_audio_name_equal(dtpl->audio_name, "line_out.dsp") &&
        gk_audio_name_equal(cn->dst_name, "Input") && cn->dst_part <= 1)
        return gk_mixnode_kind_of(src) != 0 ||
               src->audio_dsp_sim != NULL ||
               (src->audio_voice_mask != 0 && src->audio_dsp_sim == NULL &&
                cn->src_part < 2);
    if (gk_mixnode_kind_of(dst) != 0) {
        uint8_t st = 0, dt = 0;
        uint32_t sp = 0, dp = 0;
        return gk_find_audio_port(src, cn->src_name, &st, &sp) == M2K_OK &&
               st == M2_DSP_RESOURCE_OUTPUT &&
               (uint32_t)cn->src_part < sp &&
               gk_find_audio_port(dst, cn->dst_name, &dt, &dp) == M2K_OK &&
               dt == M2_DSP_RESOURCE_INPUT &&
               (uint32_t)cn->dst_part < dp;
    }
    if (src->audio_dsp_sim && dst->audio_dsp_sim) {
        const dspp_resource *sr = gk_dsp_find_resource(
            (dspp_sim *)src->audio_dsp_sim, cn->src_name);
        const dspp_resource *dr = gk_dsp_find_resource(
            (dspp_sim *)dst->audio_dsp_sim, cn->dst_name);
        return sr && sr->type == 4u /* DRSC_TYPE_OUTPUT */ &&
               sr->alloc_value != 0xFFFFFFFFu &&
               (uint32_t)cn->src_part < sr->many && dr &&
               (dr->type == 3u /* INPUT */ || dr->type == 1u /* KNOB */) &&
               dr->alloc_value != 0xFFFFFFFFu &&
               (uint32_t)cn->dst_part < dr->many;
    }
    return 0;
}
// Does an applied route chain from inst_handle reach the DAC accumulator?
// Terminals mirror the tick's two gmixer feed arms: line_out.dsp Input[0..1]
// (fed without requiring line_out started — it stays EXTERNALREF) and
// started WITH_LINE_OUT mixers (their outputs accumulate directly).
// Intermediate hops must be started nodes or sims: unstarted stages output 0
// (compute/stranded sim), so a chain through one leaves the voice direct.
// Depth-capped (cycles are folio-rejected but tolerated here).
#define GK_VOICE_ROUTE_MAX_DEPTH 8u
static int gk_route_reaches_dac(uint32_t inst_handle, uint32_t depth) {
    if (depth > GK_VOICE_ROUTE_MAX_DEPTH) return 0;
    for (uint32_t n = 0; n < gk_mix_graph_conn_n; ++n) {
        const gk_audio_connection *cn =
            &g_gk.connections[gk_mix_graph_conn[n]];
        if (!cn->used || cn->src_item != inst_handle) continue;
        gk_item *src = gk_live_item(cn->src_item);
        gk_item *dst = gk_live_item(cn->dst_item);
        if (!gk_conn_hop_live(cn, src, dst)) continue;
        gk_item *dtpl = gk_live_item(dst->template_item);
        if (dtpl && dtpl->ctype == GK_AUDIO_TEMPLATE_CTYPE &&
            dtpl->audio_name[0] &&
            gk_audio_name_equal(dtpl->audio_name, "line_out.dsp"))
            return 1;
        if (dst->audio_started && gk_mixnode_kind_of(dst) == 2) {
            gk_item *dt = gk_live_item(dst->template_item);
            if (dt && (dt->mixer_spec & 0xffffu & 0x02u) != 0u) return 1;
        }
        if (!dst->audio_started) continue;
        if (gk_mixnode_kind_of(dst) == 0 && dst->audio_dsp_sim == NULL)
            continue;
        if (gk_route_reaches_dac(cn->dst_item, depth + 1u)) return 1;
    }
    return 0;
}
// Partition predicate: a started sampler (nonzero voice mask) with an applied
// Output route into a started line_out-bound sink.
static int gk_voice_graph_routed(gk_item *inst, uint32_t inst_handle) {
    if (!inst || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE) return 0;
    if (!inst->audio_started || inst->audio_voice_mask == 0) return 0;
    return gk_route_reaches_dac(inst_handle, 0);
}
// Recompute direct/SDL suppression for every owned voice from the live graph.
// Once a voice has reached the DAC through a graph, stopping or disconnecting
// that path must silence it. Portfolio has no implicit sampler-to-DAC route;
// restoring the host's bare-voice fallback here would expose a still-looping
// opponent engine at full level. A new voice gets a fresh mask at start, and
// the explicit finite one-shot deletion handoff remains separate.
static void gk_voice_partition_refresh(void) {
    if (!gk_bound()) return;
    gk_mix_graph_ensure();
    for (uint32_t s = 0; s < GK_MAX_ITEMS; ++s) {
        gk_item *inst = &g_gk.items[s];
        if (!inst->used || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
            !inst->audio_started || inst->audio_voice_mask == 0)
            continue;
        uint32_t handle =
            gk_make_handle(GK_TYPE_ITEM_VA, s, inst->generation);
        int routed = gk_voice_graph_routed(inst, handle);
        for (uint32_t vi = 0; vi < 32u; ++vi) {
            if ((inst->audio_voice_mask & (1u << vi)) == 0) continue;
            if (!gk_voice_owned_sid(inst, vi)) continue;
            if (routed) inst->audio_voice_routed_mask |= 1u << vi;
            const int direct = !routed &&
                (inst->audio_voice_routed_mask & (1u << vi)) == 0;
            m2_host_audio_set_voice_direct(vi, direct);
            if (gk_audio_start_diag_enabled()) {
                static uint32_t part_diag_n = 0;
                if (part_diag_n < 32u) {
                    ++part_diag_n;
                    fprintf(stderr,
                            "[audio-partition] n=%u inst=%#x voice=%u "
                            "direct=%d\n",
                            part_diag_n, handle, vi, direct);
                }
            }
        }
    }
}
// Install a route into a mix node (R1 arm of gk_dsp_apply_connection).
// Returns 1 when the route is live in the node graph (the per-frame tick
// honors it to the extent source signals exist), 0 when skipped. INPUT
// destinations install; KNOB destinations stay at 0 (signal-driven knob
// modulation is not recovered). No sim is touched and nothing is
// fabricated: started voices resolve through the host tap, unstarted and
// voiceless sources resolve to 0 at tick time.
static int gk_dsp_apply_node_route(const gk_audio_connection *cn,
                                   gk_item *src, gk_item *dst) {
    int install = 0;
    if (cn && src && dst && gk_mixnode_kind_of(dst) != 0 &&
        cn->src_part >= 0 && cn->dst_part >= 0) {
        uint8_t st = 0, dt = 0;
        uint32_t sp = 0, dp = 0;
        if (gk_find_audio_port(src, cn->src_name, &st, &sp) == M2K_OK &&
            st == M2_DSP_RESOURCE_OUTPUT &&
            (uint32_t)cn->src_part < sp &&
            gk_find_audio_port(dst, cn->dst_name, &dt, &dp) == M2K_OK &&
            dt == M2_DSP_RESOURCE_INPUT &&
            (uint32_t)cn->dst_part < dp)
            install = 1;
    }
    gk_log_dspp_connect(cn, 0, install);
    return install;
}
// Locate and read a DSP template from the disc tree via the raw-file bridge.
// The guest-visible name (e.g. "svfilter.dsp") maps to
// System.m2/Audio/dsp/<name>. Returns 0 on success with a malloc'd buffer
// the caller frees, or -1 when no bridge/missing file/too large.
static int gk_read_dsp_template_file(const char *name, uint8_t **data_out,
                                     uint32_t *size_out) {
    *data_out = NULL;
    *size_out = 0;
    if (!m2_host_raw_open || !m2_host_raw_size || !m2_host_raw_read ||
        !m2_host_raw_close)
        return -1;
    char path[128];
    int n = snprintf(path, sizeof(path), M2_DSP_DISC_PREFIX "%s", name);
    if (n <= 0 || (size_t)n >= sizeof(path)) return -1;
    uint32_t token = m2_host_raw_open(path);
    if (token == 0u) return -1;
    uint32_t size = m2_host_raw_size(token);
    if (size == 0u || size > (64u << 10)) {
        m2_host_raw_close(token);
        return -1;
    }
    uint8_t *buf = (uint8_t *)malloc(size);
    if (!buf) {
        m2_host_raw_close(token);
        return -1;
    }
    int32_t got = m2_host_raw_read(token, buf, size);
    m2_host_raw_close(token);
    if (got < 0 || (uint32_t)got != size) {
        free(buf);
        return -1;
    }
    *data_out = buf;
    *size_out = size;
    return 0;
}

// One shared DSPP addressable space per binding. Creation models the vendor
// device + folio init: dsphInitInterruptRegs clears the interrupt banks and
// InitDSPPInterrupt enables the DMANext main bit (see
// dspp_sim_space_init_folio_interrupts). The folio's trigger enables arrive
// later through ArmTrigger (dsphEnableTriggerInterrupts).
static dspp_sim_space *gk_audio_space(void) {
    if (!g_gk.audio_dsp_space) {
        g_gk.audio_dsp_space = dspp_sim_space_create();
        if (g_gk.audio_dsp_space)
            dspp_sim_space_init_folio_interrupts(g_gk.audio_dsp_space);
    }
    return g_gk.audio_dsp_space;
}

// DSPPInitInsMemory presets MRSC defaults, then overlays DINI values for
// the requested allocation/start flag. Patch blocks and direct instruments
// share this boundary; starting never reapplies allocation-only defaults.
static void gk_dsp_sim_initialize_resources(dspp_sim *sim, uint32_t when) {
    if (!sim) return;
    const dspp_template *res = dspp_sim_resources(sim);
    if (!res) return;
    for (uint32_t r = 0; r < res->resource_count; ++r) {
        const dspp_resource *resource = &res->resources[r];
        if (!(resource->flags & when) ||
            (resource->type != 1u /* KNOB */ &&
             resource->type != 2u /* VARIABLE */ &&
             resource->type != 4u /* OUTPUT */) ||
            resource->alloc_value == 0xFFFFFFFFu)
            continue;
        for (uint32_t k = 0; k < resource->many; ++k)
            dspp_sim_poke_data(sim, resource->alloc_value + k,
                               (uint16_t)resource->default_value);
    }
    for (uint32_t i = 0; i < res->initializer_count; ++i) {
        const dspp_initializer *ini = &res->initializers[i];
        if (!(ini->flags & when) || ini->resource_index >= res->resource_count)
            continue;
        const dspp_resource *r = &res->resources[ini->resource_index];
        if (r->alloc_value == 0xFFFFFFFFu) continue;
        for (uint32_t k = 0; k < ini->value_count && k < r->many; ++k)
            dspp_sim_poke_data(sim, r->alloc_value + k,
                               (uint16_t)(ini->values[k] & 0xFFFFu));
    }
}

// Build a DSPP simulator for the instrument's on-disc template. The gk_item
// keeps only a host-owned dspp_sim pointer; nothing guest-visible changes.
static int gk_dsp_sim_create_for(gk_item *instrument,
                                 uint32_t instrument_handle) {
    if (!gk_bound() || !instrument ||
        instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return -1;
    if (instrument->audio_dsp_sim) return 0; // already built
    gk_item *template_live = gk_live_item(instrument->template_item);
    if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE ||
        template_live->audio_name[0] == '\0')
        return -1;
    // Custom patch templates have no DCOD image; they stay at their
    // existing boundary.
    if (template_live->patch_index > 0) return -1;
    if (template_live->mixer_spec != 0) return -1; // generated mixer shape

    uint8_t *data = NULL;
    uint32_t size = 0;
    if (gk_read_dsp_template_file(template_live->audio_name, &data, &size) != 0) {
        if (gk_audio_start_diag_enabled()) {
            static uint32_t read_fail_count;
            if (read_fail_count < 32u)
                fprintf(stderr, "[audio-dspp] read failed: %s\n",
                        template_live->audio_name), ++read_fail_count;
        }
        return -1;
    }
    dspp_template parsed;
    int rc = dspp_load_template(data, size, &parsed);
    free(data);
    if (rc != 0) {
        if (gk_audio_start_diag_enabled()) {
            static uint32_t parse_fail_count;
            if (parse_fail_count < 32u)
                fprintf(stderr, "[audio-dspp] parse failed: %s rc=%d\n",
                        template_live->audio_name, rc), ++parse_fail_count;
        }
        return -1;
    }

    // Imported resources (DRSC_F_IMPORT, e.g. gMixer) resolve through the
    // space's exporter table (vendor dsppImportResource). When no live
    // instrument exports the name yet, start the on-disc nanokernel.dsp
    // first: the vendor audio folio loads it at folio init, and its
    // DRSC_F_EXPORT resources (gMixer, gScratch1/2/3, gReserved*,
    // gBenchStart, rate-list jump labels) are the authentic import source
    // for every output/scratch template. A template whose import is still
    // missing fails with AF_ERR_EXTERNALREF, matching the vendor folio on
    // a real missing external.
    int has_import = 0;
    for (uint32_t i = 0; i < parsed.resource_count; ++i) {
        if (parsed.resources[i].flags & 0x80u /* DRSC_F_IMPORT */) {
            has_import = 1;
            break;
        }
    }
    if (has_import && !gk_audio_space())
        return -2;
    if (has_import &&
        dspp_sim_space_ensure_kernel(g_gk.audio_dsp_space) != 0) {
        if (gk_audio_start_diag_enabled()) {
            static uint32_t import_count;
            if (import_count < 32u)
                fprintf(stderr,
                        "[audio-dspp] template=%s import unresolvable "
                        "-> EXTERNALREF\n",
                        template_live->audio_name),
                    ++import_count;
        }
        return -2;
    }

    if (!gk_audio_space()) return -1;
    if (dspp_sim_space_ensure_kernel(g_gk.audio_dsp_space) != 0) return -1;
    dspp_sim *sim = dspp_sim_create_in_space(&parsed, g_gk.audio_dsp_space);
    if (!sim) return -1;
    // DSPPInitInsMemory first presets every DRSC_F_INIT_AT_ALLOC resource
    // from its MRSC default, then applies DINI_F_AT_ALLOC overrides.
    gk_dsp_sim_initialize_resources(sim, 0x01u /* DINI_F_AT_ALLOC */);
    instrument->audio_dsp_sim = sim;
    // Bounded allocation visibility (M2_AUDIO_START_DIAG): dump each sim's
    // data-word resources next to the resident head's exported DAC words so a
    // shared-space alias (a client word landing on the head's gMixer) is
    // readable from a log without a debugger. Cap 64 lines.
    if (gk_audio_start_diag_enabled()) {
        static uint32_t alloc_dump_count;
        if (alloc_dump_count < 64u) {
            ++alloc_dump_count;
            uint32_t head_gmixer = 0xFFFFFFFFu, head_amp = 0xFFFFFFFFu;
            if (g_gk.audio_dsp_space) {
                dspp_sim_space_export_address(g_gk.audio_dsp_space, "gMixer",
                                              &head_gmixer);
                dspp_sim_space_export_address(g_gk.audio_dsp_space, "Amplitude",
                                              &head_amp);
            }
            fprintf(stderr, "[audio-alloc] n=%u tpl=%s head_gMixer=%#x "
                            "head_Amplitude=%#x:",
                    alloc_dump_count, dspp_sim_resources(sim)->name,
                    head_gmixer, head_amp);
            const dspp_template *res = dspp_sim_resources(sim);
            for (uint32_t r = 0; r < res->resource_count; ++r) {
                const dspp_resource *rr = &res->resources[r];
                if (rr->alloc_value == 0xFFFFFFFFu) continue;
                if (rr->type != 1u /* KNOB */ && rr->type != 2u /* VARIABLE */ &&
                    rr->type != 4u /* OUTPUT */ && rr->type != 8u /* RBASE */)
                    continue;
                fprintf(stderr, " %s=%#x+%u", rr->name, rr->alloc_value,
                        rr->many);
            }
            fprintf(stderr, "\n");
        }
    }
    // DSPP's resource allocator initializes the shared image before this
    // point; SetKnobPart values written while stopped then overlay it, as
    // dsppSetKnob does against the vendor's already-allocated word.
    gk_dsp_sync_retained_knobs(instrument, instrument_handle);
    return 0;
}

// ---- source-defined AudioPatch constituent graph --------------------------
//
// CreatePatchTemplate is a command compiler in the original AudioPatch folio:
// ADD_TEMPLATE opens each constituent DSPP image, CONNECT patches the
// constituent relocation sites, and SET_CONSTANT supplies a real data-word
// source.  The patch itself has no DCOD image.  Keep that ownership boundary
// here by opening the original constituent files and using the existing DSPP
// loader/executor; the graph stores no guest pointers and adds no host game
// behavior.
static const gk_patch_template *gk_patch_template_for_instrument(
    const gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return NULL;
    const gk_item *template_live = gk_live_item(instrument->template_item);
    if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE ||
        template_live->patch_index == 0u ||
        template_live->patch_index > GK_MAX_PATCH_TEMPLATES)
        return NULL;
    const gk_patch_template *pt =
        &g_gk_patches[template_live->patch_index - 1u];
    return pt->used ? pt : NULL;
}

static int gk_patch_graph_find_block(const gk_patch_template *pt,
                                     const char *name) {
    if (!pt || !name || !name[0]) return -1;
    for (uint32_t i = 0; i < pt->block_count; ++i)
        if (gk_audio_name_equal(pt->blocks[i].name, name)) return (int)i;
    return -1;
}

static const gk_patch_resource *gk_patch_graph_find_resource(
    const gk_patch_template *pt, const char *name) {
    if (!pt || !name || !name[0]) return NULL;
    for (uint32_t i = 0; i < pt->resource_count; ++i)
        if (gk_audio_name_equal(pt->resources[i].name, name))
            return &pt->resources[i];
    return NULL;
}

// Resolve every external carrier's resource once. The carrier resource name
// is template metadata, so the per-frame tick path can index the resource
// table directly instead of rescanning it by name.
static void gk_patch_graph_cache_resources(gk_patch_graph *graph) {
    if (!graph || !graph->tpl) return;
    for (uint32_t i = 0; i < graph->carrier_count; ++i) {
        gk_patch_graph_carrier *carrier = &graph->carriers[i];
        carrier->resource_index = -1;
        if (!carrier->external) continue;
        const gk_patch_resource *resource =
            gk_patch_graph_find_resource(graph->tpl, carrier->resource);
        if (resource)
            carrier->resource_index =
                (int16_t)(resource - graph->tpl->resources);
    }
}

static const gk_patch_graph_carrier *gk_patch_graph_find_carrier(
    const gk_patch_graph *graph, const char *resource, uint32_t part) {
    if (!graph || !resource) return NULL;
    for (uint32_t i = 0; i < graph->carrier_count; ++i) {
        const gk_patch_graph_carrier *carrier = &graph->carriers[i];
        if (carrier->external && carrier->part == part &&
            gk_audio_name_equal(carrier->resource, resource))
            return carrier;
    }
    return NULL;
}

static int gk_patch_graph_add_carrier(gk_patch_graph *graph,
                                      const char *resource, uint32_t part,
                                      int external, uint32_t *address_out) {
    if (!graph || !g_gk.audio_dsp_space || graph->block_count == 0u)
        return -1;
    if (external) {
        const gk_patch_graph_carrier *existing =
            gk_patch_graph_find_carrier(graph, resource, part);
        if (existing) {
            if (address_out) *address_out = existing->address;
            return 0;
        }
    }
    if (graph->carrier_count >= GK_MAX_PATCH_CARRIERS) return -1;
    uint32_t address = 0xFFFFFFFFu;
    if (dspp_sim_space_reserve_words(g_gk.audio_dsp_space, 1u, &address) !=
        0)
        return -1;
    gk_patch_graph_carrier *carrier =
        &graph->carriers[graph->carrier_count++];
    memset(carrier, 0, sizeof(*carrier));
    carrier->resource_index = -1;
    if (resource)
        snprintf(carrier->resource, sizeof(carrier->resource), "%s",
                 resource);
    carrier->part = part;
    carrier->address = address;
    carrier->external = external ? 1u : 0u;
    if (address_out) *address_out = address;
    return 0;
}

// Convert a patch-scope signal in the same order as
// ConvertAudioSignalToGeneric -> ConvertFP_SF15 -> dsppClipRawValue.  Patch
// constants and external knobs are authored in signal units; patch INPUT
// wires, in contrast, are already DSPP raw words and bypass this helper.
static int32_t gk_patch_graph_signal_raw(float value, uint32_t signal_type,
                                         uint32_t rate_divider) {
    if (rate_divider == 0u) rate_divider = 1u;
    float generic = 0.0f;
    switch (signal_type) {
    case 0u: // AF_SIGNAL_TYPE_GENERIC_SIGNED
    case 1u: // AF_SIGNAL_TYPE_GENERIC_UNSIGNED
        generic = value;
        break;
    case 2u: // AF_SIGNAL_TYPE_OSC_FREQ
        generic = value * (float)(rate_divider * 2u) / 44100.0f;
        break;
    case 3u: // AF_SIGNAL_TYPE_LFO_FREQ
        generic = value * (float)(rate_divider * 2u * 256u) / 44100.0f;
        break;
    case 4u: // AF_SIGNAL_TYPE_SAMPLE_RATE
        generic = value * (float)rate_divider / 44100.0f;
        break;
    case 5u: // AF_SIGNAL_TYPE_WHOLE_NUMBER
        generic = value / 32768.0f;
        break;
    default:
        return 0;
    }
    float scaled = generic * 32768.0f;
    int32_t raw;
    if (scaled <= -2147483648.0f)
        raw = INT32_MIN;
    else if (scaled >= 2147483647.0f)
        raw = INT32_MAX;
    else
        raw = (int32_t)scaled;
    if (signal_type == 1u || signal_type == 4u) {
        if (raw < 0) raw = 0;
        if (raw > 65535) raw = 65535;
    } else {
        if (raw < -32768) raw = -32768;
        if (raw > 32767) raw = 32767;
    }
    return raw;
}

static int gk_patch_graph_external_address(
    gk_patch_graph *graph, const gk_patch_template *pt, const char *name,
    uint32_t part, uint32_t *address_out) {
    const gk_patch_resource *resource =
        gk_patch_graph_find_resource(pt, name);
    if (!resource ||
        (resource->type != M2_DSP_RESOURCE_INPUT &&
         resource->type != M2_DSP_RESOURCE_KNOB) ||
        part >= resource->parts)
        return -1;
    return gk_patch_graph_add_carrier(graph, resource->name, part, 1,
                                      address_out);
}

static int gk_patch_graph_source_address(
    gk_patch_graph *graph, const gk_patch_template *pt, const char *block,
    const char *port, uint32_t part, uint32_t *address_out) {
    if (!graph || !pt || !port || !address_out) return -1;
    if (!block || !block[0])
        return gk_patch_graph_external_address(graph, pt, port, part,
                                               address_out);
    const int block_index = gk_patch_graph_find_block(pt, block);
    if (block_index < 0 || (uint32_t)block_index >= graph->block_count)
        return -1;
    dspp_sim *sim = graph->block_sims[block_index];
    const dspp_resource *resource = gk_dsp_find_resource(sim, port);
    if (!resource || resource->type != 4u /* DRSC_TYPE_OUTPUT */ ||
        resource->alloc_value == 0xFFFFFFFFu || part >= resource->many)
        return -1;
    *address_out = resource->alloc_value + part;
    return *address_out < DSPP_DATA_MEMORY_WORDS ? 0 : -1;
}

static int gk_patch_graph_apply_constants(gk_patch_graph *graph,
                                          const gk_patch_template *pt) {
    for (uint32_t i = 0; i < pt->constant_count; ++i) {
        const gk_patch_constant *constant = &pt->constants[i];
        const int block_index =
            gk_patch_graph_find_block(pt, constant->block);
        if (block_index < 0 || (uint32_t)block_index >= graph->block_count)
            return -1;
        dspp_sim *sim = graph->block_sims[block_index];
        const dspp_resource *resource =
            gk_dsp_find_resource(sim, constant->port);
        if (!resource ||
            (resource->type != 3u /* INPUT */ &&
             resource->type != 1u /* KNOB */) ||
            resource->alloc_value == 0xFFFFFFFFu ||
            constant->part >= resource->many)
            return -1;
        uint32_t address = 0xFFFFFFFFu;
        if (gk_patch_graph_add_carrier(graph, NULL, i, 0, &address) != 0)
            return -1;
        const int32_t raw = gk_patch_graph_signal_raw(
            constant->value, resource->subtype, 1u);
        dspp_sim_poke_data(sim, address, (uint16_t)raw);
        dspp_sim_connect(sim, resource->name, constant->part,
                         (uint16_t)(0x8000u | (address & 0x03FFu)));
    }
    return 0;
}

static int gk_patch_graph_apply_routes(gk_patch_graph *graph,
                                       const gk_patch_template *pt) {
    // First allocate every patch-scope source carrier.  This includes a
    // direct patch INPUT -> OUTPUT route, which has no constituent
    // destination but still reads a live guest connection at tick time.
    for (uint32_t i = 0; i < pt->route_count; ++i) {
        const gk_patch_route *route = &pt->routes[i];
        if (route->from_block[0] != '\0') continue;
        const gk_patch_resource *resource =
            gk_patch_graph_find_resource(pt, route->from_port);
        if (!resource ||
            (resource->type != M2_DSP_RESOURCE_INPUT &&
             resource->type != M2_DSP_RESOURCE_KNOB) ||
            route->from_part >= resource->parts)
            return -1;
        if (gk_patch_graph_external_address(
                graph, pt, resource->name, route->from_part, NULL) != 0)
            return -1;
    }

    for (uint32_t i = 0; i < pt->route_count; ++i) {
        const gk_patch_route *route = &pt->routes[i];
        // A route to the patch scope is read through gk_patch_graph_resolve; it
        // does not patch a constituent input.
        if (route->to_block[0] == '\0') continue;
        const int block_index =
            gk_patch_graph_find_block(pt, route->to_block);
        if (block_index < 0 || (uint32_t)block_index >= graph->block_count)
            return -1;
        dspp_sim *dst = graph->block_sims[block_index];
        const dspp_resource *destination =
            gk_dsp_find_resource(dst, route->to_port);
        if (!destination ||
            (destination->type != 3u /* INPUT */ &&
             destination->type != 1u /* KNOB */) ||
            destination->alloc_value == 0xFFFFFFFFu ||
            route->to_part >= destination->many)
            return -1;
        uint32_t source_address = 0xFFFFFFFFu;
        if (gk_patch_graph_source_address(
                graph, pt, route->from_block, route->from_port,
                route->from_part, &source_address) != 0)
            return -1;
        dspp_sim_connect(dst, destination->name, route->to_part,
                         (uint16_t)(0x8000u | (source_address & 0x03FFu)));
    }
    return 0;
}

static void gk_patch_graph_release(gk_patch_graph *graph) {
    if (!graph) return;
    for (uint32_t i = 0; i < graph->carrier_count; ++i)
        dspp_sim_space_release_words(g_gk.audio_dsp_space,
                                     graph->carriers[i].address, 1u);
    for (uint32_t i = graph->block_count; i > 0u; --i)
        if (graph->block_sims[i - 1u]) dspp_sim_destroy(graph->block_sims[i - 1u]);
    free(graph);
}

static int gk_patch_graph_create(gk_item *instrument,
                                 uint32_t instrument_handle) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return -1;
    if (instrument->audio_patch_graph) return 0;
    const gk_patch_template *pt =
        gk_patch_template_for_instrument(instrument);
    if (!pt) return -1;
    // Port-only historical fixtures have no constituent DCOD image. Keep
    // their established compatibility route; only a source-shaped patch is
    // promoted to a DSPP graph.
    if (pt->block_count == 0u) return 0;
    if (!gk_audio_space()) return -1;

    gk_patch_graph *graph =
        (gk_patch_graph *)calloc(1, sizeof(gk_patch_graph));
    if (!graph) return -1;
    graph->patch_index = (uint32_t)(gk_live_item(instrument->template_item)
                                        ->patch_index);
    graph->tpl = pt;
    graph->block_count = pt->block_count;

    int result = -1;
    for (uint32_t i = 0; i < pt->block_count; ++i) {
        const gk_patch_block *block = &pt->blocks[i];
        if (!block->template_name[0])
            goto fail;
        uint8_t *data = NULL;
        uint32_t size = 0;
        if (gk_read_dsp_template_file(block->template_name, &data, &size) !=
            0)
            goto fail;
        dspp_template parsed;
        const int parse_rc = dspp_load_template(data, size, &parsed);
        free(data);
        if (parse_rc != 0)
            goto fail;
        int has_import = 0;
        for (uint32_t r = 0; r < parsed.resource_count; ++r) {
            if (parsed.resources[r].flags & 0x80u /* DRSC_F_IMPORT */) {
                has_import = 1;
                break;
            }
        }
        if (has_import && dspp_sim_space_ensure_kernel(g_gk.audio_dsp_space) !=
                             0) {
            result = -2;
            goto fail;
        }
        dspp_sim *sim = dspp_sim_create_in_space(&parsed,
                                                 g_gk.audio_dsp_space);
        if (!sim) {
            result = has_import ? -2 : -1;
            goto fail;
        }
        graph->block_sims[i] = sim;
        gk_dsp_sim_initialize_resources(sim, 0x01u /* DINI_F_AT_ALLOC */);
    }
    const int constants_rc = gk_patch_graph_apply_constants(graph, pt);
    if (constants_rc != 0)
        goto fail;
    const int routes_rc = gk_patch_graph_apply_routes(graph, pt);
    if (routes_rc != 0)
        goto fail;
    gk_patch_graph_cache_resources(graph);

    instrument->audio_patch_graph = graph;
    (void)instrument_handle;
    return 0;

fail:
    gk_patch_graph_release(graph);
    return result;
}

static void gk_patch_graph_destroy(gk_item *instrument) {
    if (!instrument || !instrument->audio_patch_graph) return;
    // Physical patch attachments bind to constituent sims, not the patch
    // shell. Unbind them before those sims are destroyed.
    gk_stop_delay_attachments(instrument);
    gk_patch_graph *graph = instrument->audio_patch_graph;
    instrument->audio_patch_graph = NULL;
    gk_patch_graph_release(graph);
}

// Name lookups for the per-frame path: what feeds each external carrier and
// where each flattened OUTPUT part lives. Patch metadata is static and the
// wires and knobs change only with the graph revision.
static void gk_patch_graph_resolve(gk_item *instrument,
                                   uint32_t instrument_handle) {
    gk_patch_graph *graph = instrument->audio_patch_graph;
    const gk_patch_template *pt = graph->tpl;
    uint32_t flat = 0;
    for (uint32_t i = 0;
         pt && i < pt->resource_count && flat < GK_MIXNODE_MAX_OUT; ++i) {
        if (pt->resources[i].type != M2_DSP_RESOURCE_OUTPUT) continue;
        for (uint32_t p = 0;
             p < pt->resources[i].parts && flat < GK_MIXNODE_MAX_OUT; ++p) {
            uint32_t address = UINT32_MAX;
            for (uint32_t r = 0; r < pt->route_count; ++r) {
                const gk_patch_route *route = &pt->routes[r];
                if (route->to_block[0] != '\0' || route->to_part != p ||
                    !gk_audio_name_equal(route->to_port,
                                         pt->resources[i].name))
                    continue;
                if (gk_patch_graph_source_address(
                        graph, pt, route->from_block, route->from_port,
                        route->from_part, &address) != 0)
                    address = UINT32_MAX;
                break;
            }
            graph->output_address[flat++] = address;
        }
    }
    graph->output_count = flat;
    for (uint32_t i = 0; pt && i < graph->carrier_count; ++i) {
        gk_patch_graph_carrier *carrier = &graph->carriers[i];
        carrier->source_conn = -1;
        carrier->source_knob = -1;
        if (!carrier->external || carrier->resource_index < 0 ||
            (uint32_t)carrier->resource_index >= pt->resource_count)
            continue;
        const gk_patch_resource *resource =
            &pt->resources[carrier->resource_index];
        if (resource->type == M2_DSP_RESOURCE_INPUT) {
            carrier->source_conn = (int16_t)gk_mix_find_input_conn(
                instrument_handle, resource->name, (int32_t)carrier->part);
        } else if (resource->type == M2_DSP_RESOURCE_KNOB) {
            const gk_item *knob =
                gk_mixnode_find_knob(instrument_handle, resource->name);
            if (knob) carrier->source_knob = (int16_t)(knob - g_gk.items);
        }
    }
    graph->resolved_rev = gk_mix_graph_built_rev;
}

static void gk_patch_graph_tick(gk_item *instrument,
                                uint32_t instrument_handle,
                                uint32_t depth) {
    (void)depth;
    if (!instrument || !instrument->audio_patch_graph) return;
    gk_patch_graph *graph = instrument->audio_patch_graph;
    const gk_patch_template *pt = graph->tpl;
    if (!pt || graph->block_count == 0u || !graph->block_sims[0]) return;
    for (uint32_t i = 0; i < graph->carrier_count; ++i) {
        gk_patch_graph_carrier *carrier = &graph->carriers[i];
        if (!carrier->external || carrier->resource_index < 0 ||
            (uint32_t)carrier->resource_index >= pt->resource_count)
            continue;
        const gk_patch_resource *resource =
            &pt->resources[carrier->resource_index];
        if (carrier->part >= resource->parts) continue;
        int32_t raw = 0;
        if (resource->type == M2_DSP_RESOURCE_INPUT) {
            // A guest connection already carries a DSPP word. The patch
            // compiler wires it directly to the constituent relocation.
            if (carrier->source_conn >= 0)
                raw = gk_mix_conn_sample((uint32_t)carrier->source_conn, 0u);
        } else if (resource->type == M2_DSP_RESOURCE_KNOB) {
            float value = resource->default_value;
            gk_item *knob = gk_mix_resolved_knob(carrier->source_knob,
                                                 instrument_handle);
            if (knob && carrier->part < knob->knob_parts)
                value = knob->knob_values[carrier->part];
            raw = gk_patch_graph_signal_raw(
                value, resource->signal_type, instrument->calc_rate_divider);
        } else {
            continue;
        }
        dspp_sim_poke_data(graph->block_sims[0], carrier->address,
                           (uint16_t)raw);
    }
    // AddTemplate order is the vendor patch-link order. Do not topologically
    // reorder the constituent programs: FIFO and stateful DSP blocks rely on
    // the original linker sequence and shared hardware state.
    for (uint32_t i = 0; i < graph->block_count; ++i) {
        if (!graph->block_sims[i]) continue;
        dspp_sim_tick(graph->block_sims[i]);
    }
}

static int32_t gk_patch_graph_fifo(gk_item *instrument, const char *hook,
                                   dspp_sim **sim_out,
                                   uint32_t *channel_out,
                                   int *is_out_fifo_out) {
    if (sim_out) *sim_out = NULL;
    if (channel_out) *channel_out = 0u;
    if (is_out_fifo_out) *is_out_fifo_out = 0;
    if (!instrument || !instrument->audio_patch_graph)
        return M2_AUDIO_ERR_BAD_ITEM;
    const gk_patch_template *pt =
        gk_patch_template_for_instrument(instrument);
    gk_patch_graph *graph = instrument->audio_patch_graph;
    if (!pt) return M2_AUDIO_ERR_BAD_ITEM;
    if (hook && hook[0]) {
        const gk_patch_resource *resource =
            gk_patch_graph_find_resource(pt, hook);
        if (!resource || !resource->exposed || !resource->source_block[0] ||
            !resource->source_port[0])
            return M2_AUDIO_ERR_NAME_MISSING;
        const int block_index =
            gk_patch_graph_find_block(pt, resource->source_block);
        if (block_index < 0 || (uint32_t)block_index >= graph->block_count)
            return M2_AUDIO_ERR_NAME_MISSING;
        uint32_t channel = 0u;
        int is_out = 0;
        const int32_t rc = gk_resolve_fifo_channel(
            graph->block_sims[block_index], resource->source_port, &channel,
            &is_out);
        if (rc != M2K_OK) return rc;
        if (sim_out) *sim_out = graph->block_sims[block_index];
        if (channel_out) *channel_out = channel;
        if (is_out_fifo_out) *is_out_fifo_out = is_out;
        return M2K_OK;
    }

    // NULL hook uses the vendor default only when the complete patch graph
    // has exactly one FIFO endpoint.
    dspp_sim *found_sim = NULL;
    uint32_t found_channel = 0u;
    int found_out = 0;
    uint32_t count = 0u;
    for (uint32_t i = 0; i < graph->block_count; ++i) {
        const dspp_template *resources = dspp_sim_resources(graph->block_sims[i]);
        if (!resources) continue;
        for (uint32_t r = 0; r < resources->resource_count; ++r) {
            const dspp_resource *resource = &resources->resources[r];
            if (resource->type != 5u && resource->type != 6u) continue;
            ++count;
            found_sim = graph->block_sims[i];
            found_channel = resource->alloc_value;
            found_out = resource->type == 6u;
        }
    }
    if (count != 1u || found_channel >= 32u)
        return M2_AUDIO_ERR_NAME_MISSING;
    if (sim_out) *sim_out = found_sim;
    if (channel_out) *channel_out = found_channel;
    if (is_out_fifo_out) *is_out_fifo_out = found_out;
    return M2K_OK;
}

static void gk_dsp_sim_destroy_for(gk_item *instrument) {
    if (!instrument) return;
    if (instrument->audio_patch_graph)
        gk_patch_graph_destroy(instrument);
    if (!instrument->audio_dsp_sim) return;
    // Audio Folio delay attachments are owned by the instrument's physical
    // DSPP binding. Stop and detach them before destroying the simulator so
    // the opaque delay-line storage cannot retain a stale channel owner.
    gk_stop_delay_attachments(instrument);
    dspp_sim_destroy((dspp_sim *)instrument->audio_dsp_sim);
    instrument->audio_dsp_sim = NULL;
}

// DSPPStopInstrument disables code/DMA without freeing its data or FIFO
// resources. Retained connections still name those words while stopped.
static void gk_dsp_sim_stop_dma(dspp_sim *sim) {
    if (!sim) return;
    const dspp_template *res = dspp_sim_resources(sim);
    for (uint32_t r = 0; res && r < res->resource_count; ++r) {
        const dspp_resource *resource = &res->resources[r];
        if (resource->type != 5u && resource->type != 6u) continue;
        if (resource->alloc_value == 0xFFFFFFFFu) continue;
        for (uint32_t k = 0; k < resource->many; ++k)
            dspp_sim_dma_set_control(sim, resource->alloc_value + k, 0, 0);
    }
}

// DSPPStartInstrument applies only DINI_F_AT_START after starting its
// attachments. Allocation-only filter/phase state persists across restarts.
static void gk_dsp_sim_initialize_start(gk_item *instrument) {
    gk_dsp_sim_initialize_resources((dspp_sim *)instrument->audio_dsp_sim,
                                  0x02u /* DINI_F_AT_START */);
    if (instrument->audio_patch_graph) {
        gk_patch_graph *graph = instrument->audio_patch_graph;
        for (uint32_t b = 0; b < graph->block_count; ++b)
            gk_dsp_sim_initialize_resources(graph->block_sims[b], 0x02u);
    }
}

// nanokernel.ins keeps separate full-, half-, and eighth-rate execution
// lists. FrameCountLow is incremented before the rate tests: full-rate code
// runs on every frame, half-rate code on even frame counts, and eighth-rate
// code when the low counter is divisible by eight. AF_TAG_CALCRATE_DIVIDE
// stores the corresponding divisor on each instrument. This is the
// execution-list boundary; the host reads the last published output on
// frames where a reduced-rate instrument does not execute.
static int gk_audio_rate_due(const gk_item *inst) {
    const uint32_t divider = inst && inst->calc_rate_divider != 0u
                                 ? inst->calc_rate_divider
                                 : 1u;
    if (divider == 2u) return (g_gk.audio_frame_low & 1u) == 0u;
    if (divider == 8u) return (g_gk.audio_frame_low & 7u) == 0u;
    return 1;
}

// ---- DSPP FIRQ + audio daemon delivery (vendor dspp_irq_bulldog.c,
// audio_folio.c RunAudioDaemon) --------------------------------------------
// The folio FIRQ walks validInts = DSPX_INTERRUPT_SET & DSPX_INTERRUPT_ENABLE
// in precedence order (DMANext -> timer -> soft/trigger) and wakes the audio
// daemon with af_DMASignal/af_TimerSignal/af_TriggerSignal; the daemon then
// runs HandleDMASignal, HandleTimerSignal, HandleTriggerSignal. The host
// platform layer does the same thing synchronously: gk_audio_firq_dispatch()
// runs the loader's first-level pass after each DSP frame, and the daemon
// halves run at the frame boundary (the trigger half immediately, since its
// HandleTriggerSignal is already synchronous here).
//
// Arm/Disarm/Reset follow audio_trigger.c: InternalRearmTrigger writes the
// trigger soft bit into DSPX_INTERRUPT_ENABLE (dsphEnableTriggerInterrupts)
// and sets af_ArmedTriggers; InternalDisarmTrigger clears the enable
// (dsphDisableTriggerInterrupts) and the armed bit; InternalResetTrigger
// clears only the pending bit (DSPX_INTERRUPT_CLR, dsphClearTriggerInterrupts).
// Unarmed pending bits linger for a later arm without RESET, exactly as the
// vendor documents ("the Cue is sent immediately upon arming").
//
// HandleTriggerSignal then reads received = SET & (ArmedTriggers << shift) and
// clears exactly those bits (dsphGetReceivedTriggers), so the FIRQ's disable
// step and the daemon's clear are distinct, as in the vendor. Ownerless
// (host-only) Cues complete silently: no compatibility broadcast is
// fabricated. Pure-synth/no-upload instruments have no sim and no DSP
// hardware, so nothing is raised or delivered.
#define GK_AUDIO_TRIGGER_MAX 16u // DSPR_MAX_TRIGGERS
#define GK_AUDIO_TRIGGER_CONTINUOUS 0x02u // AF_F_TRIGGER_CONTINUOUS
#define GK_AUDIO_TRIGGER_RESET 0x01u // AF_F_TRIGGER_RESET
#define GK_AUDIO_TRIGGER_VALID_FLAGS \
    (GK_AUDIO_TRIGGER_CONTINUOUS | GK_AUDIO_TRIGGER_RESET)
#define GK_DSPX_INTERRUPT_SET 0x64000u
#define GK_DSPX_INTERRUPT_CLR 0x64004u
#define GK_DSPX_INTERRUPT_ENABLE 0x64008u
#define GK_DSPX_INTERRUPT_DISABLE 0x6400Cu
#define GK_DSPX_SOFT_SHIFT 16u
#define GK_DSPX_SOFT_MASK 0xFFFF0000u
#define GK_DSPI_CPU_INT 0x03E6u
// SuperinternalSignal wake bits (vendor audio_structs.h af_DMASignal etc.);
// one bit per daemon handler, drained by the frame-boundary daemon halves.
#define GK_AUDIO_DAEMON_DMA 0x1u
#define GK_AUDIO_DAEMON_TIMER 0x2u
#define GK_AUDIO_DAEMON_TRIGGER 0x4u
typedef struct gk_trigger_entry {
    uint32_t cue_item; // guest Cue handle, 0 = disarmed
    uint32_t instrument_item; // owning Instrument for named ArmTrigger
    uint8_t flags; // retained TCE_FLAGS (continuous only)
} gk_trigger_entry;
static gk_trigger_entry gk_trigger_cue[GK_AUDIO_TRIGGER_MAX]; // zero = disarmed
static uint32_t gk_trigger_armed; // bit i = trigger i armed (af_ArmedTriggers)

// First started DSPP-backed instrument's sim. The main-interrupt bank is
// shared across every live sim in the space, so any started sim observes the
// same pending bits. NULL when no DSP hardware is live (pure-synth or
// no-upload stays at UNIMPLEMENTED with no trigger source).
static dspp_sim *gk_any_started_dsp_sim(void) {
    if (!gk_bound()) return NULL;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *inst = &g_gk.items[i];
        if (!inst->used || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
            !inst->audio_started)
            continue;
        if (inst->audio_dsp_sim) return (dspp_sim *)inst->audio_dsp_sim;
        if (inst->audio_patch_graph) {
            for (uint32_t b = 0; b < inst->audio_patch_graph->block_count;
                 ++b) {
                if (inst->audio_patch_graph->block_sims[b])
                    return inst->audio_patch_graph->block_sims[b];
            }
        }
    }
    return NULL;
}

// Vendor dsphEnable/DisableTriggerInterrupts: set/clear the trigger soft bits
// in the main enable bank. No sim means no live DSPP: nothing to write.
static void gk_trigger_interrupt_enable(uint32_t trigmask, int enable) {
    if (trigmask == 0u) return;
    dspp_sim *sim = gk_any_started_dsp_sim();
    if (!sim) return;
    uint32_t soft = (trigmask << GK_DSPX_SOFT_SHIFT) & GK_DSPX_SOFT_MASK;
    dspp_sim_dma_register_write(
        sim, enable ? GK_DSPX_INTERRUPT_ENABLE : GK_DSPX_INTERRUPT_DISABLE,
        soft);
}

// Vendor SignalTriggerCue + one-shot/continuous tail. The timer lock is held:
// table, armed mask, and Cue state stay consistent against concurrent arms.
// One-shot disarms (disable + clear armed); continuous re-arms
// (InternalRearmTrigger: set armed + enable, in case the received-bit disable
// in the FIRQ cleared it).
static void gk_signal_trigger_cue(uint32_t trignum) {
    uint32_t cue_handle = gk_trigger_cue[trignum].cue_item;
    uint8_t flags = gk_trigger_cue[trignum].flags;
    gk_item *cue = gk_live_item(cue_handle);
    if (cue && cue->ctype == GK_AUDIO_CUE_CTYPE &&
        cue->cue_signal_mask != 0u) {
        uint32_t owner = cue->cue_owner;
        uint32_t mask = cue->cue_signal_mask;
        if (flags & GK_AUDIO_TRIGGER_CONTINUOUS) {
            gk_trigger_armed |= 1u << trignum;
            gk_trigger_interrupt_enable(1u << trignum, 1);
        } else {
            gk_trigger_cue[trignum].cue_item = 0u;
            gk_trigger_cue[trignum].instrument_item = 0u;
            gk_trigger_cue[trignum].flags = 0u;
            gk_trigger_armed &= ~(1u << trignum);
            gk_trigger_interrupt_enable(1u << trignum, 0);
        }
        // A host-only Cue has no guest recipient: it completes (one-shot
        // disarms above) but no compatibility broadcast is fabricated.
        if (owner != M2K_ITEM_NONE)
            (void)m2k_send_signal(g_gk.kctx, owner,
                                  __builtin_ctz(mask));
    } else {
        // Deleted or never-valid Cue: disarm without fabricating a signal.
        gk_trigger_cue[trignum].cue_item = 0u;
        gk_trigger_cue[trignum].instrument_item = 0u;
        gk_trigger_cue[trignum].flags = 0u;
        gk_trigger_armed &= ~(1u << trignum);
        gk_trigger_interrupt_enable(1u << trignum, 0);
    }
}

// Daemon half of the trigger path (vendor HandleTriggerSignal ->
// dsphGetReceivedTriggers(af_ArmedTriggers)): read SET, keep the armed bits,
// clear exactly those, then SignalTriggerCue each received trigger. The FIRQ
// half has already disabled the received soft bits in the enable bank.
// Called with the main bank freshly serviced; takes the timer lock.
static void gk_audio_handle_trigger_signal(dspp_sim *sim) {
    if (!sim) return;
    uint32_t pending = dspp_sim_dma_register_read(sim, GK_DSPX_INTERRUPT_SET) &
                       GK_DSPX_SOFT_MASK;
    if (pending == 0u) return;
    pthread_mutex_lock(&g_audio_timer_lock);
    uint32_t received = (pending >> GK_DSPX_SOFT_SHIFT) & gk_trigger_armed;
    if (received != 0u) {
        dspp_sim_dma_register_write(sim, GK_DSPX_INTERRUPT_CLR,
                                    received << GK_DSPX_SOFT_SHIFT);
        for (uint32_t t = 0; t < GK_AUDIO_TRIGGER_MAX; ++t) {
            if (received & (1u << t)) gk_signal_trigger_cue(t);
        }
    }
    pthread_mutex_unlock(&g_audio_timer_lock);
}

// First-level FIRQ pass (vendor dsphFIRQHandler) plus the synchronous daemon
// hand-off for the trigger half. The loader owns the register contract (see
// dspp_sim_dma_firq_dispatch); this wrapper records the daemon wake bits and
// the completed-channel mask, then runs HandleTriggerSignal.
static void gk_audio_firq_dispatch(void) {
    if (!gk_bound()) return;
    dspp_sim *sim = gk_any_started_dsp_sim();
    if (!sim) return;
    dspp_firq_dispatch fired = dspp_sim_dma_firq_dispatch(sim);
    if (fired.dmanext != 0u) {
        g_gk.audio_dma_completed |= fired.dmanext; // af_ChannelsComplete
        g_gk.audio_daemon_signals |= GK_AUDIO_DAEMON_DMA;
    }
    if (fired.timer) g_gk.audio_daemon_signals |= GK_AUDIO_DAEMON_TIMER;
    if (fired.soft != 0u) {
        g_gk.audio_daemon_signals |= GK_AUDIO_DAEMON_TRIGGER;
        gk_audio_handle_trigger_signal(sim);
        g_gk.audio_daemon_signals &= ~GK_AUDIO_DAEMON_TRIGGER;
    }
}

// Shared arm/disarm state transition. The direct trigger-number form remains
// a focused synthetic-test hook; production selector 34 supplies the owning
// instrument and resolves its named TRIGGER resource before reaching here.
static int32_t gk_arm_trigger_number(PPCContext *cpu, uint32_t trignum,
                                      uint32_t cue_item, uint32_t flags,
                                      uint32_t instrument_item) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (trignum >= GK_AUDIO_TRIGGER_MAX)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    if (flags & ~GK_AUDIO_TRIGGER_VALID_FLAGS)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    pthread_mutex_lock(&g_audio_timer_lock);
    if (cue_item == 0u) {
        gk_trigger_cue[trignum].cue_item = 0u;
        gk_trigger_cue[trignum].instrument_item = 0u;
        gk_trigger_cue[trignum].flags = 0u;
        gk_trigger_armed &= ~(1u << trignum);
        gk_trigger_interrupt_enable(1u << trignum, 0); // InternalDisarmTrigger
        pthread_mutex_unlock(&g_audio_timer_lock);
        return M2K_OK;
    }
    gk_item *cue = gk_live_item(cue_item);
    if (!cue || cue->ctype != GK_AUDIO_CUE_CTYPE) {
        pthread_mutex_unlock(&g_audio_timer_lock);
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    if (flags & GK_AUDIO_TRIGGER_RESET) {
        dspp_sim *sim = gk_any_started_dsp_sim();
        if (sim)
            dspp_sim_dma_register_write(sim, GK_DSPX_INTERRUPT_CLR,
                                        1u << (trignum + GK_DSPX_SOFT_SHIFT));
    }
    gk_trigger_cue[trignum].cue_item = cue_item;
    gk_trigger_cue[trignum].instrument_item = instrument_item;
    gk_trigger_cue[trignum].flags =
        (uint8_t)(flags & GK_AUDIO_TRIGGER_CONTINUOUS);
    gk_trigger_armed |= 1u << trignum;
    gk_trigger_interrupt_enable(1u << trignum, 1); // InternalRearmTrigger
    pthread_mutex_unlock(&g_audio_timer_lock);
    return M2K_OK;
}

// Synthetic trigger-number form used by the focused DSPP trigger contract
// test. It deliberately does not stand in for the guest selector ABI.
int32_t m2_guest_audio_arm_trigger(PPCContext *cpu, uint32_t trignum,
                                   uint32_t cue_item, uint32_t flags) {
    return gk_arm_trigger_number(cpu, trignum, cue_item, flags, 0u);
}

// ArmTrigger/DisarmTrigger (audio folio game ordinal 34). The vendor resolves
// the requested name in the instrument template and uses that instrument's
// globally allocated trigger number. The runtime simulator retains the same
// resource allocation in dspp_resource::alloc_value, so no host trigger bit
// is invented here. NULL triggerName selects the vendor default "Trigger".
int32_t m2_guest_audio_arm_trigger_named(PPCContext *cpu,
                                          uint32_t instrument,
                                          uint32_t trigger_name_ea,
                                          uint32_t cue_item,
                                          uint32_t flags) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    char trigger_name[GK_MAX_NAME_LEN];
    if (trigger_name_ea == 0u) {
        snprintf(trigger_name, sizeof(trigger_name), "Trigger");
    } else if (m2m_copy_guest_string_ctx(cpu, trigger_name_ea, trigger_name,
                                         sizeof(trigger_name)) < 0) {
        return M2_AUDIO_ERR_BAD_PTR;
    }
    // swiArmTrigger validates these arguments before resolving the named
    // resource. Keep malformed calls from being converted into a name or
    // simulator-state error at this boundary.
    if (cue_item != 0u) {
        gk_item *cue = gk_live_item(cue_item);
        if (!cue || cue->ctype != GK_AUDIO_CUE_CTYPE)
            return M2_AUDIO_ERR_BAD_ITEM;
    }
    if (flags & ~GK_AUDIO_TRIGGER_VALID_FLAGS)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    dspp_sim *sim = (dspp_sim *)live->audio_dsp_sim;
    if (!sim || !live->audio_started)
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    const dspp_resource *resource = gk_dsp_find_resource(sim, trigger_name);
    if (!resource || resource->type != 9u /* DRSC_TYPE_TRIGGER */)
        return M2_AUDIO_ERR_NAME_MISSING;
    if (resource->alloc_value >= GK_AUDIO_TRIGGER_MAX)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    return gk_arm_trigger_number(cpu, resource->alloc_value, cue_item, flags,
                                 instrument);
}

// Deleting an instrument releases its simulator trigger allocation. The
// Audio Folio also removes any TriggerCueTable entries owned by that
// instrument so a reused global trigger number cannot inherit a stale Cue.
static void gk_disarm_audio_triggers_for_item(uint32_t instrument) {
    if (!gk_bound()) return;
    pthread_mutex_lock(&g_audio_timer_lock);
    for (uint32_t trignum = 0; trignum < GK_AUDIO_TRIGGER_MAX; ++trignum) {
        if (gk_trigger_cue[trignum].instrument_item != instrument) continue;
        gk_trigger_cue[trignum].cue_item = 0u;
        gk_trigger_cue[trignum].instrument_item = 0u;
        gk_trigger_cue[trignum].flags = 0u;
        gk_trigger_armed &= ~(1u << trignum);
        gk_trigger_interrupt_enable(1u << trignum, 0);
    }
    pthread_mutex_unlock(&g_audio_timer_lock);
}

// Raise one DSPP -> CPU soft-interrupt bit through the authentic DSPI_CPU_INT
// write path (what guest DSP code stores to when a trigger goes off). Test
// and diagnostic use only: production raises come from ticked DSP programs.
int32_t m2_guest_audio_raise_trigger(PPCContext *cpu, uint32_t trignum) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (trignum >= GK_AUDIO_TRIGGER_MAX)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    dspp_sim *sim = gk_any_started_dsp_sim();
    if (!sim) return M2_AUDIO_ERR_BAD_ITEM; // no live DSP hardware to raise
    dspp_sim_dspi_write(sim, GK_DSPI_CPU_INT, (uint16_t)(1u << trignum));
    return M2K_OK;
}

// Run the requested DAC frames of every started DSPP-backed instrument and
// publish the observed outputs through the bounded diagnostic. The mixer
// render below consumes these ticks; this entry stays as the observation
// primitive.
static void gk_audio_tick_dspp_frames_locked(uint32_t frames) {
    gk_mix_graph_ensure();
    for (uint32_t frame = 0; frame < frames; ++frame) {
        ++g_gk.audio_frame_low;
        for (uint32_t n = 0; n < gk_mix_graph_dsp_n; ++n) {
            const uint32_t i = gk_mix_graph_dsp[n];
            gk_item *inst = &g_gk.items[i];
            if (!inst->used || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
                !inst->audio_started || inst->audio_paused ||
                !inst->audio_dsp_sim || !gk_audio_rate_due(inst))
                continue;
            dspp_sim *sim = (dspp_sim *)inst->audio_dsp_sim;
            dspp_sim_tick(sim);
            if (gk_audio_start_diag_enabled() && inst->dsp_out_frame < 8u) {
                const dspp_template *res = dspp_sim_resources(sim);
                uint32_t outs[2] = {0, 0};
                uint32_t n_out = 0;
                for (uint32_t r = 0; r < res->resource_count; ++r) {
                    if (res->resources[r].type == 4u /* DRSC_TYPE_OUTPUT */ &&
                        res->resources[r].alloc_value != 0xFFFFFFFFu &&
                        n_out < 2u)
                        outs[n_out++] = res->resources[r].alloc_value;
                }
                uint32_t out0 = outs[0];
                uint32_t out1 = n_out > 1u ? outs[1] : outs[0];
                fprintf(stderr,
                        "[audio-dspp] inst=%#x frame=%u out0=%#x out1=%#x\n",
                        gk_make_handle(GK_TYPE_ITEM_VA, i, inst->generation),
                        inst->dsp_out_frame,
                        (unsigned)dspp_sim_peek_data(sim, out0),
                        (unsigned)dspp_sim_peek_data(sim, out1));
                ++inst->dsp_out_frame;
            }
        }
        // On-disc nanokernel (head) residency: the folio keeps the head
        // instrument's allocations and export names live for every later
        // import. Its cyclic HeadMainLoop is not host-executed here: the
        // CR4215 boot-entry SLEEP patch plus the wake-restart cycle model
        // leave word 0 as the effective entry, so the head sim's tick is a
        // data-only pass (MOVE records and FIFO state). The vendor's
        // per-frame head behaviors — gMixer -> DAC transfer, accumulator
        // clears, half/eighth staging, FrameCountLow advance — are mirrored
        // in gk_mixnode_tick_frame against the head's own data words.
        if (g_gk.audio_dsp_space)
            dspp_sim_space_tick_kernel(g_gk.audio_dsp_space, 1u);
        // R1: compute started mix nodes after the sims advance (node inputs
        // from sims read fresh words) and feed the resident gMixer accumulator.
        // Sim-free when no node is started (single kind scan inside).
        gk_mixnode_tick_frame();
        // DSPP FIRQ pass (vendor dsphFIRQHandler + dsphHandleDMANEXT/timer/
        // soft): service armed main/second-level bits after the sims advanced.
        gk_audio_firq_dispatch();
    }
}

void m2_guest_audio_tick_dspp_frames(uint32_t frames) {
    if (!gk_bound()) return;
    m2_guest_audio_graph_lock();
    gk_audio_tick_dspp_frames_locked(frames);
    m2_guest_audio_graph_unlock();
}

// A started sim whose OUTPUT only feeds destination KNOBs is a modulation
// source, not a DAC audio source: the vendor port contract carries signal on
// INPUT and control on KNOB, and a control word reaches gMixer/DAC only after
// the destination instrument multiplies/accumulates it. Adding the raw word
// to the fallback mix is a host artifact (envelope.dsp -> mixer:2x2 Gain is
// the exercised case: the envelope's 0..1 SF15 ramp became a full-scale DC
// rail that clipped the intro movie audio for its whole duration). A sim that
// also drives an INPUT keeps the existing route-scoped fallback behavior, and
// an unrouted output stays direct-to-DAC as documented below. Structural on
// the graph revision, so memoized like gk_mix_graph_route.
static int gk_dsp_sim_control_only(uint32_t slot) {
    if (slot >= GK_MAX_ITEMS) return 0;
    if (gk_mix_graph_control[slot] < 0) {
        uint32_t handle =
            gk_make_handle(GK_TYPE_ITEM_VA, slot, g_gk.items[slot].generation);
        int control = 0;
        for (uint32_t n = 0; n < gk_mix_graph_conn_n; ++n) {
            const gk_audio_connection *cn =
                &g_gk.connections[gk_mix_graph_conn[n]];
            if (!cn->used || cn->src_item != handle) continue;
            gk_item *src = gk_live_item(cn->src_item);
            gk_item *dst = gk_live_item(cn->dst_item);
            if (!src || !dst || src->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
                dst->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
                continue;
            uint8_t st = 0, dt = 0;
            uint32_t sp = 0, dp = 0;
            if (gk_find_audio_port(src, cn->src_name, &st, &sp) != M2K_OK ||
                st != M2_DSP_RESOURCE_OUTPUT)
                continue;
            if (gk_find_audio_port(dst, cn->dst_name, &dt, &dp) != M2K_OK)
                continue;
            if (dt == M2_DSP_RESOURCE_INPUT) {
                control = 0; // an audio path exists: keep the fallback
                break;
            }
            if (dt == M2_DSP_RESOURCE_KNOB) control = 1;
        }
        gk_mix_graph_control[slot] = (int8_t)control;
    }
    return gk_mix_graph_control[slot];
}

// Sum the first OUTPUT resource of every started sim into a stereo pair:
// part 0 drives L, part 1 (when many>=2) drives R, otherwise L is duplicated.
// Route-scoped: a sim whose output reaches the DAC through an
// installed graph route (sim carrier or mix-node chain) already delivers via
// the resident mix, so the fallback skips it — otherwise the pump would
// count that signal twice. Direct DSP-to-DAC and all output-instrument
// ownership cases stay at the documented boundary below.
static void gk_dsp_sum_outputs(int32_t *l_out, int32_t *r_out) {
    gk_mix_graph_ensure();
    int32_t l = 0, r = 0;
    for (uint32_t n = 0; n < gk_mix_graph_dsp_n; ++n) {
        const uint32_t i = gk_mix_graph_dsp[n];
        gk_item *inst = &g_gk.items[i];
        if (!inst->used || inst->ctype != GK_AUDIO_INSTRUMENT_CTYPE ||
            !inst->audio_started || inst->audio_paused || !inst->audio_dsp_sim)
            continue;
        dspp_sim *sim = (dspp_sim *)inst->audio_dsp_sim;
        const dspp_template *res = dspp_sim_resources(sim);
        if (!res) continue;
        // Graph-carried outputs are excluded from the fallback (single
        // delivery). The predicate is structural, so memoize it per graph
        // revision instead of re-walking the route table per DAC frame.
        if (gk_mix_graph_route[i] < 0) {
            uint32_t handle =
                gk_make_handle(GK_TYPE_ITEM_VA, i, inst->generation);
            gk_mix_graph_route[i] =
                (int8_t)(gk_route_reaches_dac(handle, 0u) ? 1 : 0);
        }
        if (gk_mix_graph_route[i]) continue;
        if (gk_dsp_sim_control_only(i)) continue;
        for (uint32_t k = 0; k < res->resource_count; ++k) {
            const dspp_resource *rr = &res->resources[k];
            if (rr->type != 4u /* DRSC_TYPE_OUTPUT */ ||
                rr->alloc_value == 0xFFFFFFFFu || rr->many == 0u)
                continue;
            int16_t s0 = (int16_t)dspp_sim_peek_data(sim, rr->alloc_value);
            int16_t s1 = rr->many >= 2u
                             ? (int16_t)dspp_sim_peek_data(sim,
                                                           rr->alloc_value + 1u)
                             : s0;
            l += s0;
            r += s1;
            break;
        }
    }
    *l_out = l;
    *r_out = r;
}

// Bounded mixer catch-up per pump: a video-frame stall must not tick an
// unbounded backlog into the DSP sims.
#define GK_DSPP_MIX_CATCHUP_MAX 8192u
#define GK_DSPP_MIX_BATCH 512u
#define GK_DSPP_ASYNC_BATCH 128u
// Frames simulated under one graph-lock hold on the asynchronous worker. The
// guest issues per-frame audio setter calls on the same recursive graph lock
// (the audio selector dispatch guards every ordinal), and a paced
// race sample showed the StateDriver thread blocked ~9.6 ms per frame behind
// the worker's full catch-up holds. Chunking the simulation keeps each hold
// near one frame's cost; a later attribution showed the residual wait was
// simply the in-flight chunk at setter arrival, so the chunk loop also yields
// between sample frames while a setter is pending (dynamic, uncontended path
// unchanged). The simulated sample order is unchanged and the output is
// pushed in the same batch as before.
#define GK_DSPP_LOCK_CHUNK 8u

// Interactive hosts may service the authentic DSPP sample clock on a bounded
// platform worker. The main timer pump still owns Cue/audio-clock delivery;
// this flag only prevents duplicate output ticks while the worker is active.
// Headless, controlled, and focused tests retain the synchronous path.
static atomic_int gk_dspp_async_service = ATOMIC_VAR_INIT(0);
static atomic_uint_fast64_t gk_dspp_backoff_sleeps = ATOMIC_VAR_INIT(0);
// Protected by the audio graph lock. Frames produced so far: the synchronous
// pump follows the device counter with it; the asynchronous worker fills to the
// host's request and only keeps the count current.
static uint32_t gk_dspp_pushed_upto;
static int gk_dspp_output_started;

uint64_t m2_guest_audio_dspp_backoff_sleeps(void) {
    return atomic_load_explicit(&gk_dspp_backoff_sleeps, memory_order_relaxed);
}

void m2_guest_audio_set_async_dspp(int enabled) {
    m2_guest_audio_graph_lock();
    // Anchor the synchronous pump's reference; the worker itself does not use it.
    if (enabled && gk_bound()) {
        const uint32_t rendered = m2_host_audio_frame_count();
        if (!gk_dspp_output_started || rendered < gk_dspp_pushed_upto) {
            gk_dspp_pushed_upto = rendered;
            gk_dspp_output_started = 1;
        }
    }
    atomic_store_explicit(&gk_dspp_async_service, enabled != 0,
                          memory_order_release);
    m2_guest_audio_graph_unlock();
}

int m2_guest_audio_async_dspp_enabled(void) {
    return atomic_load_explicit(&gk_dspp_async_service,
                                memory_order_acquire);
}

uint32_t m2_guest_audio_pump_dspp_output(void) {
    if (!gk_bound()) return 0u;
    m2_guest_audio_graph_lock();
    const uint32_t rendered = m2_host_audio_frame_count();
    if (rendered == 0) {
        // No mixer: keep the observation cadence only.
        gk_audio_tick_dspp_frames_locked(1u);
        m2_guest_audio_graph_unlock();
        return 0u;
    }
    const int async_service = m2_guest_audio_async_dspp_enabled();
    uint32_t deficit;
    if (async_service) {
        // Fill the output queue to its target level. Samples the device
        // already played as silence during a stall are not owed: producing
        // them would only delay everything after them.
        deficit = m2_host_audio_dspp_fill_request();
        if (deficit > GK_DSPP_ASYNC_BATCH) deficit = GK_DSPP_ASYNC_BATCH;
    } else {
        if (!gk_dspp_output_started || rendered < gk_dspp_pushed_upto) {
            // Skip the boot backlog (mixer ran before any DSPP start) and any
            // host counter reset; subsequent pumps track the mixer deficit.
            gk_dspp_pushed_upto = rendered;
            gk_dspp_output_started = 1;
            m2_guest_audio_graph_unlock();
            return 0u;
        }
        deficit = rendered - gk_dspp_pushed_upto;
        if (deficit > GK_DSPP_MIX_CATCHUP_MAX) deficit = GK_DSPP_MIX_CATCHUP_MAX;
    }
    if (deficit == 0) {
        m2_guest_audio_graph_unlock();
        return 0u;
    }
    // Account for the samples this call will simulate before releasing the
    // lock; only this worker calls the pump while async service is enabled.
    gk_dspp_pushed_upto += deficit;
    m2_guest_audio_graph_unlock();
    int16_t batch[GK_DSPP_MIX_BATCH * 2u];
    uint32_t remaining = deficit;
    // A persistent waiter reduces chunks to one sample. Renewing ten 20us
    // sleeps at every reacquisition can delay 2.9ms of audio by 25.6ms.
    // Share the voluntary sleep budget across this bounded service call.
    unsigned backoff_left = 10u;
    while (remaining > 0) {
        uint32_t n = remaining > GK_DSPP_MIX_BATCH ? GK_DSPP_MIX_BATCH
                                                  : remaining;
        for (uint32_t first = 0; first < n;) {
            const uint32_t chunk =
                (n - first) > GK_DSPP_LOCK_CHUNK ? GK_DSPP_LOCK_CHUNK
                                                 : (n - first);
            // Let a waiting guest audio setter in before taking the graph
            // lock again; the worker's own re-lock would otherwise win the
            // race against the woken guest. Only the asynchronous worker
            // yields: the synchronous platform pump is the caller the setter
            // is waiting on, and backing off there would stall the pump.
            // Bounded so the audio clock keeps its 44.1 kHz supply even if a
            // setter stalls.
            if (m2_guest_audio_async_dspp_enabled()) {
                while (backoff_left > 0u) {
                    if (!m2_guest_audio_setter_pending()) break;
                    --backoff_left;
                    struct timespec backoff;
                    backoff.tv_sec = 0;
                    backoff.tv_nsec = 20000L;
                    atomic_fetch_add_explicit(&gk_dspp_backoff_sleeps, 1u,
                                              memory_order_relaxed);
                    nanosleep(&backoff, NULL);
                }
            }
            m2_guest_audio_graph_lock();
            uint32_t done = 0;
            while (done < chunk) {
                gk_audio_tick_dspp_frames_locked(1u);
                int32_t l = 0, r = 0;
                gk_dsp_sum_outputs(&l, &r);
                // R2-full DAC transfer: nanokernel.ins writes OutputToDAC[ch] =
                // gMixer[ch] x Amplitude with a plain _= (no _CLIP) and the
                // Amplitude knob is unity ($7FFF raw; the folio default is 1.0
                // and the game never calls the privileged SetAudioFolioInfo —
                // ord 39 is untyped/fail-closed in both dispatches), so the
                // resident mix adds at 1.0. Saturate at the host S16 rail;
                // the fallback pure-DSP output sum remains
                // route-scoped until direct DSP-to-DAC and all
                // output-instrument ownership cases are covered.
                l += gk_gmixer[0];
                r += gk_gmixer[1];
                const uint32_t out = first + done;
                batch[out * 2u] = gk_mixnode_clip(l);
                batch[out * 2u + 1u] = gk_mixnode_clip(r);
                ++done;
                // Yield between sample frames while a graph-lock waiter is
                // blocked. The waiter's blocked time is then bounded by one
                // DSP sample-frame of simulation instead of the whole 8-frame
                // chunk, while an uncontended worker keeps its chunk-sized
                // holds. See the audio-lock attribution: the
                // residual guest wait was the in-flight chunk at arrival.
                // Advisory and bounded: if the flag sticks, the worker still
                // makes one frame of progress per lock and the backoff above
                // stays capped.
                if (m2_guest_audio_setter_pending()) break;
            }
            m2_guest_audio_graph_unlock();
            first += done;
        }
        m2_host_audio_push_dspp_frames(batch, n);
        remaining -= n;
    }
    return deficit;
}

// Start host voices for uploaded sample attachments of inst using vendor
// ScanMultiSamples semantics: attachments are partitioned by FIFO hook,
// attachments with AF_ATTF_NOAUTOSTART are filtered out, and at most one
// matching sample per FIFO is started. If all attachments are filtered out by
// AF_ATTF_NOAUTOSTART or pitch/velocity ranges, 0 voices are started and 0 is
// returned (valid start, attachments will be started later via StartAttachment).
// Previously owned voices stop first so repeated starts do not leak mixer voices.
// A stream-only SoundSpooler instrument has a valid sample attachment whose
// AF_TAG_WIDTH=1 placeholder is filled later; report that case separately so
// StartInstrument can succeed without fabricating a voice.
// Returns voices started (>= 0), M2_AUDIO_ERR_NO_MEMORY if host voices are
// exhausted, or -1 for pure synth/unresolved sample data.
static int32_t gk_start_instrument_voices(gk_item *inst,
                                          int *stream_only_out) {
    gk_stop_instrument_voices(inst);
    gk_stop_delay_attachments(inst);
    inst->audio_paused = 0;
    if (stream_only_out) *stream_only_out = 0;
    uint32_t att_indices[GK_MAX_ITEMS];
    uint32_t total_attachments = 0;
    int stream_placeholders = 0;
    int unresolved_samples = 0;
    for (uint32_t k = 0; k < GK_MAX_ITEMS; ++k) {
        const gk_item *a = &g_gk.items[k];
        if (!a->used || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            a->attachment_type != 1u)
            continue;
        if (gk_live_item(a->attachment_master) != inst) continue;
        gk_item *s = gk_live_item(a->attachment_slave);
        if (!s || s->ctype != GK_AUDIO_SAMPLE_CTYPE)
            continue;
        if (s->host_sample_id == 0u) {
            if (s->sample_stream_placeholder)
                ++stream_placeholders;
            else
                ++unresolved_samples;
        }
        att_indices[total_attachments++] = k;
    }

    if (total_attachments == 0) {
        return -1;
    }

    if (stream_placeholders > 0 && unresolved_samples == 0) {
        if (stream_only_out) *stream_only_out = 1;
        return 0;
    }

    char fifo_hooks[16][GK_MAX_NAME_LEN];
    uint8_t fifo_has_hook[16];
    uint32_t num_fifos = 0;

    for (uint32_t i = 0; i < total_attachments; ++i) {
        const gk_item *a = &g_gk.items[att_indices[i]];
        const char *hook = a->attachment_has_hook ? a->attachment_hook : "";
        int found = 0;
        for (uint32_t f = 0; f < num_fifos; ++f) {
            if (a->attachment_has_hook == fifo_has_hook[f] &&
                strcmp(hook, fifo_hooks[f]) == 0) {
                found = 1;
                break;
            }
        }
        if (!found && num_fifos < 16) {
            fifo_has_hook[num_fifos] = a->attachment_has_hook;
            strncpy(fifo_hooks[num_fifos], hook, GK_MAX_NAME_LEN - 1);
            fifo_hooks[num_fifos][GK_MAX_NAME_LEN - 1] = '\0';
            ++num_fifos;
        }
    }

    uint32_t mask = 0;
    int32_t started = 0;
    const int32_t note = inst->audio_start_pitch_note;
    const int32_t vel = inst->audio_start_velocity;

    for (uint32_t f = 0; f < num_fifos; ++f) {
        const gk_item *chosen_a = NULL;
        uint32_t chosen_k = 0;

        for (uint32_t i = 0; i < total_attachments; ++i) {
            uint32_t k = att_indices[i];
            const gk_item *a = &g_gk.items[k];
            const char *hook = a->attachment_has_hook ? a->attachment_hook : "";
            if (a->attachment_has_hook != fifo_has_hook[f] ||
                strcmp(hook, fifo_hooks[f]) != 0)
                continue;

            if ((a->attachment_flags & M2_AUDIO_ATTACHMENT_FLAG_NOAUTOSTART) != 0)
                continue;

            gk_item *s = gk_live_item(a->attachment_slave);
            if (!s || s->ctype != GK_AUDIO_SAMPLE_CTYPE || s->host_sample_id == 0u)
                continue;

            if (note < 0 && vel < 0) {
                chosen_a = a;
                chosen_k = k;
                break;
            }

            if ((note < 0 || (note >= (int32_t)s->sample_low_note && note <= (int32_t)s->sample_high_note)) &&
                (vel < 0  || (vel >= (int32_t)s->sample_low_velocity && vel <= (int32_t)s->sample_high_velocity))) {
                chosen_a = a;
                chosen_k = k;
                break;
            }
        }

        if (chosen_a != NULL) {
            gk_item *s = gk_live_item(chosen_a->attachment_slave);
            const uint32_t attachment_item = gk_make_handle(
                GK_TYPE_ITEM_VA, chosen_k, chosen_a->generation);
            const float rate_hz = (inst->audio_start_tags & 2u)
                                      ? (inst->audio_start_rate_is_relative
                                             ? inst->audio_start_4f * s->sample_rate
                                             : inst->audio_start_4f)
                                      : s->sample_rate;
            const float gain = (inst->audio_start_tags & 1u)
                                   ? inst->audio_start_4e
                                   : 1.0f;
            int32_t idx =
                m2_host_audio_start_voice_indexed_for_attachment_with_params(
                    s->host_sample_id, attachment_item,
                    s->sample_sustain_begin, s->sample_sustain_end,
                    s->sample_release_begin, s->sample_release_end, rate_hz,
                    gain);
            if (idx >= 0 && idx < 32) {
                // Same aatt_Channel ownership record as StartAttachment.
                {
                    gk_item *owned = gk_live_item(attachment_item);
                    if (owned) {
                        owned->attachment_voice = idx;
                        owned->attachment_stopped = 0u;
                    }
                }
                mask |= (1u << (uint32_t)idx);
                ++started;
            } else {
                // A later FIFO allocation may fail after earlier ones
                // started. Publish their ownership before stopping them;
                // otherwise these voices remain untracked and consume pool
                // slots even though StartInstrument reported failure.
                inst->audio_voice_mask = mask;
                gk_stop_instrument_voices(inst);
                return M2_AUDIO_ERR_NO_MEMORY;
            }
        }
    }

    inst->audio_voice_mask = mask;
    return started > 0 ? started : -1;
}

// StopInstrument validates the instrument and a NULL tag list (the spooler
// stop path passes NULL). Vendor swiStopInstrument validates the Item, rejects
// a tag list (AF_ERR_BADTAG), and then returns 0 without touching the device
// whenever ains_Status <= AF_STOPPED, so an already-stopped (or never-started)
// instrument is a successful status transition rather than an unimplemented
// boundary. An instrument this bridge marked started stops its still-owned
// host voices and reports the same AF_STOPPED transition as M2K_OK. The
// terminal FATLADYSINGS branch of ProcessAttachmentDMA depends on that
// identity: it treats a negative stop result as a real error and returns
// before SignalMonitoringCue.
int32_t m2_guest_audio_stop_instrument(PPCContext *cpu,
                                       uint32_t instrument,
                                       uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (taglist_ea != 0)
        return M2_AUDIO_ERR_BAD_TAG;
    gk_log_audio_lifecycle("stop", cpu, instrument, M2K_OK,
                           live->audio_started);
    if (!live->audio_started)
        return M2K_OK;
    gk_stop_envelope_attachments(live);
    gk_stop_instrument_voices(live);
    m2_host_audio_reset_cbd2_stream(instrument);
    gk_stop_delay_attachments(live);
    gk_dsp_sim_stop_dma((dspp_sim *)live->audio_dsp_sim);
    if (live->audio_patch_graph) {
        gk_patch_graph *graph = live->audio_patch_graph;
        for (uint32_t b = 0; b < graph->block_count; ++b)
            gk_dsp_sim_stop_dma(graph->block_sims[b]);
    }
    live->audio_started = 0;
    live->audio_paused = 0;
    gk_mix_graph_touch();
    // Stopping a node can break chains through it; recompute the partition.
    // The stopped instrument's own voices are already inactive.
    gk_voice_partition_refresh();
    return M2K_OK;
}

// ReleaseInstrument has a recoverable Item prefix. For sample-backed voices,
// the host carries the original sustain/release frame ranges and performs the
// DSPPReleaseSampleAttachment transition: the currently playing sustain-loop
// pass completes first (only the next DMA block is rewritten), then the voice
// plays the authored release tail, enters the release loop, or completes at
// the loop boundary. The release tag parser below accepts the vendor's
// AF_TAG_TIME_SCALE_FP argument. The envelope attachment scheduler applies
// that value to its source-shaped release duration; sample DMA itself is not
// time-scaled by DSPPReleaseInstrument.
typedef struct gk_release_tag_params {
    uint8_t has_time_scale;
    float time_scale;
} gk_release_tag_params;

static int32_t gk_parse_release_tags(PPCContext *cpu, uint32_t taglist_ea,
                                     gk_release_tag_params *out) {
    if (!out) return M2_AUDIO_ERR_BAD_PTR;
    memset(out, 0, sizeof(*out));
    out->time_scale = 1.0f;
    if (taglist_ea == 0u) return M2K_OK;
    if (!cpu || !gk_bound() || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;

    uint32_t cur = taglist_ea;
    uint32_t jumps = 0u;
    int ended = 0;
    for (uint32_t n = 0; n < 16u; ++n) {
        if (cur == 0u || cur > RECOMP_GUEST_MEM - 8u)
            return M2_AUDIO_ERR_BAD_PTR;
        const uint32_t tag = rd32(cpu, cur);
        const uint32_t value = rd32(cpu, cur + 4u);
        cur += 8u;
        if (tag == M2_TAG_END) {
            ended = 1;
            break;
        }
        if (tag == 0xFFFFFFFFu) continue; // TAG_NOP
        if (tag == M2_TAG_JUMP) {
            if (++jumps > 2u) return M2_AUDIO_ERR_BAD_TAG;
            cur = value;
            continue;
        }
        if (tag != M2_AUDIO_TAG_TIME_SCALE_FP)
            return M2_AUDIO_ERR_BAD_TAG;
        memcpy(&out->time_scale, &value, sizeof(out->time_scale));
        out->has_time_scale = 1u;
    }
    return ended ? M2K_OK : M2_AUDIO_ERR_BAD_TAG;
}

static int32_t gk_release_delay_attachments(gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;

    int32_t released = 0;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 1u ||
            !attachment->attachment_delay_bound ||
            gk_live_item(attachment->attachment_master) != instrument)
            continue;
        gk_item *sample = gk_live_item(attachment->attachment_slave);
        if (!sample || sample->ctype != GK_AUDIO_SAMPLE_CTYPE ||
            sample->sample_kind != 1u || !sample->sample_delay_line)
            return M2_AUDIO_ERR_UNIMPLEMENTED;
        if (dspp_sim_dma_release_delay_line(
                attachment->attachment_delay_sim,
                attachment->attachment_delay_channel) != 0)
            return M2_AUDIO_ERR_UNIMPLEMENTED;
        ++released;
    }
    return released;
}
int32_t m2_guest_audio_release_instrument(PPCContext *cpu,
                                          uint32_t instrument,
                                          uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    // Vendor swiReleaseInstrument order: validate the Item, then return 0 for
    // ains_Status <= AF_RELEASED before the tag list reaches
    // DSPPReleaseInstrument. A release of an already-stopped/released
    // instrument is therefore a successful no-op even for a non-NULL taglist;
    // only started instruments reach the explicit DSPP tag boundary below.
    gk_log_audio_lifecycle("release", cpu, instrument, M2K_OK,
                           live->audio_started);
    if (!live->audio_started)
        return M2K_OK;
    gk_release_tag_params release_params;
    const int32_t tag_rc =
        gk_parse_release_tags(cpu, taglist_ea, &release_params);
    if (tag_rc != M2K_OK) return tag_rc;
    if (release_params.has_time_scale) {
        live->audio_release_time_scale = release_params.time_scale;
        live->audio_release_time_scale_set = 1u;
    }

    const uint64_t envelope_clock_frames = gk_audio_clock_read(
        m2_host_audio_frame_count(), 0);
    const uint32_t envelope_time = (uint32_t)(
        envelope_clock_frames / GK_AUDIO_GLOBAL_CLOCK_DURATION);
    const int32_t envelope_released = gk_release_envelope_attachments(
        live, release_params.time_scale, release_params.has_time_scale,
        envelope_time);
    if (envelope_released < 0)
        return envelope_released;
    const int32_t physical_released = gk_release_delay_attachments(live);
    if (physical_released < 0)
        return physical_released;

    int released = physical_released + envelope_released;
    int ordinary_seen = 0;
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 1u ||
            attachment->attachment_delay_bound ||
            gk_live_item(attachment->attachment_master) != live)
            continue;
        ++ordinary_seen;
        const uint32_t attachment_item = gk_make_handle(
            GK_TYPE_ITEM_VA, i, attachment->generation);
        if (m2_host_audio_release_voice_for_attachment(attachment_item) == 0)
            ++released;
    }
    // DSPPReleaseInstrument returns the tag-parser result (zero for a NULL
    // list) when its FIFO scan finds no attachment. Preserve the existing
    // fail-closed result when ordinary attachments exist but none can be
    // released, while accepting the vendor's empty-attachment success case.
    if (released != 0 || ordinary_seen == 0)
        return M2K_OK;
    return M2_AUDIO_ERR_UNIMPLEMENTED;
}
static int gk_audio_start_diag_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_AUDIO_START_DIAG");
        enabled = e && *e && *e != '0';
        checked = 1;
    }
    return enabled;
}
// Bounded [audio-stop]/[audio-release]/[audio-unload] observation, same gate
// and line family as [audio-start]. A caller that cannot be attributed from
// [audio-start] alone is a lifecycle request: this records the exact selector
// call site (cpu->pc, set by the generated site), the enclosing lifted frame
// (cpu->lr), the instrument's started-state at the request, and the result.
// Cap 64 lines; observation only.
// Published by the audio folio dispatch (see host/audio/audio_shim.cpp): the
// exact guest selector call site of that dispatch entry. Needed because
// UnloadInstrument has no PPCContext argument.
// Weak default keeps standalone recomp consumers (which link no
// audio_shim.cpp) resolvable; the SDL-backed shim's strong definition
// publishes the real site.
__attribute__((weak)) uint32_t m2_audio_selector_pc = 0;
static void gk_log_audio_lifecycle(const char *kind, PPCContext *cpu,
                                   uint32_t instrument, int32_t rc,
                                   int started) {
    static uint32_t count = 0;
    if (!gk_audio_start_diag_enabled() || count >= 64u) return;
    ++count;
    PPCContext *ctx = cpu ? cpu : g_gk.cpu;
    fprintf(stderr,
            "[audio-%s] n=%u inst=%#x site=%#x pc=%#x lr=%#x started=%d "
            "rc=%d\n",
            kind, count, instrument, m2_audio_selector_pc,
            ctx ? ctx->pc : 0u, ctx ? ctx->lr : 0u, started, rc);
}
// R2-full probe (2) gate: AF_TAG_CALCRATE_DIVIDE census at CreateInstrument.
// Default off; bounded (32 lines) when enabled. No behavior change.
static int gk_audio_calcrate_diag_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_AUDIO_CALCRATE_DIAG");
        enabled = e && *e && *e != '0';
        checked = 1;
    }
    return enabled;
}
static void gk_log_audio_calcrate(uint32_t instrument, const char *tpl,
                                  uint32_t divider, uint32_t priority) {
    static uint32_t count = 0;
    if (!gk_audio_calcrate_diag_enabled() || count >= 32u) return;
    ++count;
    fprintf(stderr,
            "[audio-calcrate] n=%u inst=%#x tpl=%s div=%u pri=%u\n",
            count, instrument, (tpl && tpl[0]) ? tpl : "?", divider,
            priority);
}
// R3 capture rails: the [audio-start] detail cap (default 64) and the [audio-dspp] knob/connect cap (default
// 32) stay bounded, but a capture run can raise either via env (ceiling
// 4096) so race-phase starts past the old cap are classified instead of
// silently dropped. Defaults preserve the old volumes exactly.
static uint32_t gk_audio_diag_cap(const char *name, uint32_t dflt) {
    const char *e = getenv(name);
    if (!e || !*e || *e == '0') return dflt;
    long v = strtol(e, NULL, 10);
    if (v <= 0) return dflt;
    if (v > 4096) v = 4096;
    return (uint32_t)v;
}
static uint32_t gk_audio_start_diag_cap(void) {
    static int checked = 0;
    static uint32_t cap = 64u;
    if (!checked) {
        cap = gk_audio_diag_cap("M2_AUDIO_START_DIAG_N", 64u);
        checked = 1;
    }
    return cap;
}
static uint32_t gk_audio_dspp_diag_cap(void) {
    static int checked = 0;
    static uint32_t cap = 32u;
    if (!checked) {
        cap = gk_audio_diag_cap("M2_AUDIO_DSPP_DIAG_N", 32u);
        checked = 1;
    }
    return cap;
}
static void gk_log_audio_start(PPCContext *cpu, uint32_t instrument,
                               uint32_t taglist_ea, int32_t rc,
                               uint32_t n_voice) {
    static uint32_t count = 0;
    static uint32_t fail_count = 0;
    if (!gk_audio_start_diag_enabled()) return;
    if (count >= gk_audio_start_diag_cap()) {
        // Past-cap failures still classify (R3 race-phase BAD_TAG hunt);
        // successes stay silent to bound the line rate.
        if (rc != M2K_OK && fail_count < 32u) {
            ++fail_count;
            char tname[GK_MAX_NAME_LEN];
            gk_audio_template_label(instrument, tname, sizeof(tname));
            fprintf(stderr,
                    "[audio-start-fail] n=%u inst=%#x tpl=%s caller=%#x "
                    "tag=%#x rc=%d\n",
                    fail_count, instrument, tname[0] ? tname : "?",
                    cpu ? cpu->lr : 0u, taglist_ea, rc);
        }
        return;
    }
    ++count;
    char tname[GK_MAX_NAME_LEN];
    tname[0] = '\0';
    uint32_t n_att = 0, n_samp_up = 0, n_conn = 0;
    uint32_t first_sid = 0, first_bytes = 0;
    gk_item *inst = gk_live_item(instrument);
    if (inst && inst->ctype == GK_AUDIO_INSTRUMENT_CTYPE) {
        gk_item *tpl = gk_live_item(inst->template_item);
        if (tpl && tpl->ctype == GK_AUDIO_TEMPLATE_CTYPE &&
            tpl->audio_name[0]) {
            memcpy(tname, tpl->audio_name, sizeof(tname));
            tname[sizeof(tname) - 1] = '\0';
        }
        for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
            const gk_item *a = &g_gk.items[i];
            if (!a->used || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
                a->attachment_master != instrument)
                continue;
            ++n_att;
            if (a->attachment_type == 1u) {
                gk_item *s = gk_live_item(a->attachment_slave);
                if (s && s->ctype == GK_AUDIO_SAMPLE_CTYPE &&
                    s->host_sample_id != 0u) {
                    ++n_samp_up;
                    if (!first_sid) {
                        first_sid = s->host_sample_id;
                        first_bytes = s->sample_num_bytes;
                    }
                }
            }
        }
        for (uint32_t i = 0; i < GK_MAX_AUDIO_CONNECTIONS; ++i) {
            const gk_audio_connection *cn = &g_gk.connections[i];
            if (cn->used && (cn->src_item == instrument ||
                             cn->dst_item == instrument))
                ++n_conn;
        }
    }
    if (taglist_ea != 0 && cpu != NULL && g_gk.cpu != NULL) {
        fprintf(stderr, "[audio-start] n=%u tags=", count);
        for (uint32_t i = 0; i < 8; ++i) {
            uint32_t ea = taglist_ea + i * 8u;
            if (ea + 8u > RECOMP_GUEST_MEM) {
                fprintf(stderr, " OOB");
                break;
            }
            uint32_t tag = rd32(cpu, ea);
            uint32_t val = rd32(cpu, ea + 4u);
            fprintf(stderr, " (%#x,%#x)", tag, val);
            if (tag == M2_TAG_END) break;
        }
        fprintf(stderr, "\n");
    }
    fprintf(stderr,
            "[audio-start] n=%u inst=%#x tpl=%s att=%u samp_up=%u conn=%u "
            "sid0=%u bytes0=%u tag=%#x site=%#x caller=%#x rc=%d v=%u\n",
            count, instrument, tname[0] ? tname : "?", n_att, n_samp_up,
            n_conn, first_sid, first_bytes, taglist_ea, cpu ? cpu->pc : 0u,
            cpu ? cpu->lr : 0u, rc, n_voice);
}

// StartInstrument validates the instrument and its optional tag list, retains
// the observed M2 start tags, and starts one host voice per uploaded sample
// attachment. Sample-backed instruments therefore go audible with M2K_OK and
// unblock the spooler chain (ssplStartSpoolerTags proceeds to StartAttachment
// per buffer only on success). Pure-synth instruments (oscillator/filter DSP
// with no sample attachments, or headless with no mixer upload) stay at the
// explicit UNIMPLEMENTED boundary — no success is fabricated for DSP the host
// cannot render — except patch/mixer-template instruments, which start as
// gain-routing mix nodes (R1 section above). sndSetEng-style callers discard
// the return either way.
int32_t m2_guest_audio_start_instrument(PPCContext *cpu,
                                         uint32_t instrument,
                                         uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem) {
        gk_log_audio_start(cpu, instrument, taglist_ea,
                           M2_AUDIO_ERR_BAD_ITEM, 0);
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE) {
        gk_log_audio_start(cpu, instrument, taglist_ea,
                           M2_AUDIO_ERR_BAD_ITEM, 0);
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    gk_start_tag_params params;
    int32_t tag_rc = gk_parse_start_tags(cpu, instrument, taglist_ea,
                                         &params);
    if (tag_rc != M2K_OK) {
        gk_log_audio_start(cpu, instrument, taglist_ea, tag_rc, 0);
        return tag_rc;
    }
    // The original DSPPStartInstrument changes Amplitude/SampleRate only when
    // the corresponding start tag is present. Untagged starts preserve the
    // current knob values, including values written through SetKnobPart.
    if (params.has_amplitude) {
        live->audio_start_4e = params.amplitude;
        live->audio_start_tags |= 1u;
    }
    if (params.has_frequency) {
        live->audio_start_4f = params.frequency;
        live->audio_start_rate_is_relative = (uint8_t)params.rate_is_relative;
        live->audio_start_tags |= 2u;
    }
    live->audio_start_pitch_note = params.pitch_note;
    live->audio_start_velocity = params.velocity;
    live->audio_start_time_scale = params.time_scale;
    m2_host_audio_reset_cbd2_stream(instrument);

    int stream_only = 0;
    int32_t nv = gk_start_instrument_voices(live, &stream_only);
    if (nv == M2_AUDIO_ERR_NO_MEMORY) {
        live->audio_started = 0;
        gk_log_audio_start(cpu, instrument, taglist_ea,
                           M2_AUDIO_ERR_NO_MEMORY, 0);
        return M2_AUDIO_ERR_NO_MEMORY;
    }
    if (nv < 0) {
        // Pure-synth boundary: attempt authentic DSPP execution from the
        // on-disc template before reporting the unresolved status. Templates
        // whose code runs without an imported resource now start (their
        // outputs are observed per frame); imported-resource templates
        // (line_out into gMixer) report the source's AF_ERR_EXTERNALREF;
        // anything else stays at the explicit UNIMPLEMENTED boundary.
        live->audio_started = 0;
        // R1: patch/mixer-template instruments start as gain-routing mix
        // nodes. Port-only templates retain their established compatibility
        // route; source-defined patch templates first build their original
        // constituent DSPP graph so exposed physical attachments bind to the
        // actual constituent FIFO.
        if (gk_mixnode_kind_of(live) != 0) {
            int graph_rc = 0;
            if (gk_mixnode_kind_of(live) == 1)
                graph_rc = gk_patch_graph_create(live, instrument);
            if (graph_rc != 0) {
                const int32_t error = graph_rc == -2
                                          ? M2_AUDIO_ERR_EXTERNALREF
                                          : M2_AUDIO_ERR_UNIMPLEMENTED;
                gk_log_audio_start(cpu, instrument, taglist_ea, error, 0);
                return error;
            }
            live->audio_started = 1;
            gk_mix_graph_touch();
            // Connect-before-start order: install retained routes now that
            // the node endpoint is live.
            gk_dsp_resync_connections(live, instrument);
            const int32_t delay_rc = gk_start_delay_attachments(live);
            if (delay_rc != M2K_OK) {
                live->audio_started = 0;
                gk_dsp_sim_destroy_for(live);
                gk_log_audio_start(cpu, instrument, taglist_ea, delay_rc, 0);
                return delay_rc;
            }
            const int32_t envelope_rc = gk_start_envelope_attachments(
                live, params.pitch_note, params.time_scale);
            if (envelope_rc != M2K_OK) {
                live->audio_started = 0;
                gk_dsp_sim_destroy_for(live);
                gk_log_audio_start(cpu, instrument, taglist_ea, envelope_rc,
                                   0);
                return envelope_rc;
            }
            // A started node can complete chains (route samplers); refresh.
            gk_dsp_sim_initialize_start(live);
            gk_voice_partition_refresh();
            gk_log_audio_start(cpu, instrument, taglist_ea, M2K_OK, 0);
            return M2K_OK;
        }
        int dsp_rc = gk_dsp_sim_create_for(live, instrument);
        if (dsp_rc == 0) {
            live->audio_started = 1;
            live->dsp_out_frame = 0;
            gk_mix_graph_touch();
            // Connect-before-start order: apply retained connections now
            // that the destination image exists.
            gk_dsp_resync_connections(live, instrument);
            const int32_t delay_rc = gk_start_delay_attachments(live);
            if (delay_rc != M2K_OK) {
                live->audio_started = 0;
                gk_dsp_sim_destroy_for(live);
                gk_log_audio_start(cpu, instrument, taglist_ea, delay_rc, 0);
                return delay_rc;
            }
            const int32_t envelope_rc = gk_start_envelope_attachments(
                live, params.pitch_note, params.time_scale);
            if (envelope_rc != M2K_OK) {
                live->audio_started = 0;
                gk_dsp_sim_destroy_for(live);
                gk_log_audio_start(cpu, instrument, taglist_ea, envelope_rc,
                                   0);
                return envelope_rc;
            }
            gk_dsp_sim_initialize_start(live);
            gk_voice_partition_refresh();
            gk_log_audio_start(cpu, instrument, taglist_ea, M2K_OK, 0);
            return M2K_OK;
        }
        gk_log_audio_start(cpu, instrument, taglist_ea,
                           dsp_rc == -2 ? M2_AUDIO_ERR_EXTERNALREF
                                        : M2_AUDIO_ERR_UNIMPLEMENTED,
                           0);
        return dsp_rc == -2 ? M2_AUDIO_ERR_EXTERNALREF
                            : M2_AUDIO_ERR_UNIMPLEMENTED;
    }
    live->audio_started = 1;
    live->audio_paused = 0;
    const int32_t delay_rc = gk_start_delay_attachments(live);
    if (delay_rc != M2K_OK) {
        gk_stop_instrument_voices(live);
        live->audio_started = 0;
        gk_dsp_sim_destroy_for(live);
        gk_log_audio_start(cpu, instrument, taglist_ea, delay_rc, 0);
        return delay_rc;
    }
    const int32_t envelope_rc = gk_start_envelope_attachments(
        live, params.pitch_note, params.time_scale);
    if (envelope_rc != M2K_OK) {
        gk_stop_instrument_voices(live);
        live->audio_started = 0;
        gk_dsp_sim_destroy_for(live);
        gk_log_audio_start(cpu, instrument, taglist_ea, envelope_rc, 0);
        return envelope_rc;
    }
    gk_mix_graph_touch();
    // Fresh voices start direct; suppress now when a retained route already
    // graph-routes this sampler (start-after-connect order).
    gk_dsp_sim_initialize_start(live);
    gk_voice_partition_refresh();
    gk_log_audio_start(cpu, instrument, taglist_ea, M2K_OK, (uint32_t)nv);
    return M2K_OK;
}

// CreateKnob's convenience thunk publishes AF_TAG_INSTRUMENT=17 and
// AF_TAG_NAME=12 before a TAG_JUMP to its optional list. The production
// callers pass a NULL optional list; this bridge therefore validates exactly
// the fixed operands that cross the recovered CreateItemVA window.
static uint32_t gk_create_audio_knob(uint32_t instrument_item,
                                     uint32_t name_ea,
                                     int name_present) {
    if (!name_present) return (uint32_t)M2_AUDIO_ERR_NAME_MISSING;

    char knob_name[GK_MAX_NAME_LEN];
    if (!gk_bound() || !g_gk.cpu || name_ea == 0 ||
        name_ea >= RECOMP_GUEST_MEM ||
        m2m_copy_guest_string_ctx(g_gk.cpu, name_ea, knob_name,
                                   sizeof(knob_name)) < 0)
        return (uint32_t)M2_AUDIO_ERR_BAD_PTR;

    gk_item *instrument = gk_live_item(instrument_item);
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;

    uint8_t port_type = 0;
    uint32_t parts = 0;
    int32_t result = gk_find_audio_port(instrument, knob_name,
                                        &port_type, &parts);
    if (result < 0) return (uint32_t)result;
    if (port_type != M2_DSP_RESOURCE_KNOB || parts == 0 ||
        parts > GK_MAX_AUDIO_KNOB_PARTS)
        return (uint32_t)(parts > GK_MAX_AUDIO_KNOB_PARTS
                              ? M2_AUDIO_ERR_OUT_OF_RANGE
                              : M2_AUDIO_ERR_NAME_MISSING);

    uint32_t knob = gk_mint_item("audio knob", GK_AUDIO_KNOB_CTYPE,
                                 name_ea, 2, 1);
    if (knob == M2K_ITEM_NONE) return (uint32_t)M2_AUDIO_ERR_NO_MEMORY;
    gk_item *live = gk_live_item(knob);
    if (!live) {
        gk_DeleteItem(knob);
        return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
    }
    live->knob_instrument = instrument_item;
    live->knob_parts = parts;
    memcpy(live->audio_name, knob_name, sizeof(live->audio_name));
    gk_item *template_live = gk_live_item(instrument->template_item);
    if (template_live && template_live->patch_index > 0 &&
        template_live->patch_index <= GK_MAX_PATCH_TEMPLATES) {
        const gk_patch_template *pt =
            &g_gk_patches[template_live->patch_index - 1];
        if (pt->used) {
            for (uint32_t i = 0; i < pt->resource_count; ++i) {
                if (gk_audio_name_equal(knob_name, pt->resources[i].name)) {
                    for (uint32_t p = 0; p < parts; ++p) {
                        live->knob_values[p] = pt->resources[i].default_value;
                        live->knob_value_set[p] = 1;
                    }
                    break;
                }
            }
        }
    } else if (template_live && template_live->mixer_spec != 0) {
        if (gk_audio_name_equal(knob_name, "Gain")) {
            for (uint32_t p = 0; p < parts; ++p) {
                live->knob_values[p] = 0.0f;
                live->knob_value_set[p] = 1;
            }
        } else if (gk_audio_name_equal(knob_name, "Amplitude")) {
            for (uint32_t p = 0; p < parts; ++p) {
                live->knob_values[p] = 1.0f;
                live->knob_value_set[p] = 1;
            }
        }
    }
    return knob;
}

// CreateProbe uses the same ItemVA tag prefix as CreateKnob, but the resource
// must be an output. An optional TagArg list may supply AF_TAG_TYPE (75) to
// specify the signal type; unknown or unsupported tags fail closed with
// M2_AUDIO_ERR_UNIMPLEMENTED.
static uint32_t gk_create_audio_probe(uint32_t instrument_item,
                                      uint32_t name_ea,
                                      int name_present,
                                      uint32_t taglist_ea) {
    if (!name_present) return (uint32_t)M2_AUDIO_ERR_NAME_MISSING;
    if (taglist_ea != 0) {
        if (!gk_bound() || !g_gk.cpu || !g_gk.cpu->mem)
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
        uint32_t cur_ea = taglist_ea;
        for (uint32_t count = 0; count < 16; ++count) {
            if (cur_ea == 0 || cur_ea > RECOMP_GUEST_MEM - 8u)
                return (uint32_t)M2_AUDIO_ERR_BAD_PTR;
            uint32_t tag = rd32(g_gk.cpu, cur_ea);
            uint32_t val = rd32(g_gk.cpu, cur_ea + 4u);
            cur_ea += 8u;
            if (tag == M2_TAG_END) break;
            if (tag == 0xFFFFFFFFu /* M2_TAG_NOP */) continue;
            if (tag == M2_TAG_JUMP) {
                cur_ea = val;
                continue;
            }
            if (tag == 75u /* AF_TAG_TYPE */) {
                // Requested signal type (e.g. AF_SIGNAL_TYPE_WHOLE_NUMBER)
                continue;
            }
            return (uint32_t)M2_AUDIO_ERR_UNIMPLEMENTED;
        }
    }

    char probe_name[GK_MAX_NAME_LEN];
    if (!gk_bound() || !g_gk.cpu || name_ea == 0 ||
        name_ea >= RECOMP_GUEST_MEM ||
        m2m_copy_guest_string_ctx(g_gk.cpu, name_ea, probe_name,
                                   sizeof(probe_name)) < 0)
        return (uint32_t)M2_AUDIO_ERR_BAD_PTR;

    gk_item *instrument = gk_live_item(instrument_item);
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;

    uint8_t port_type = 0;
    uint32_t parts = 0;
    int32_t result = gk_find_audio_port(instrument, probe_name,
                                        &port_type, &parts);
    if (result < 0) return (uint32_t)result;
    if (port_type != M2_DSP_RESOURCE_OUTPUT || parts == 0 ||
        parts > GK_MAX_AUDIO_KNOB_PARTS)
        return (uint32_t)(parts > GK_MAX_AUDIO_KNOB_PARTS
                              ? M2_AUDIO_ERR_OUT_OF_RANGE
                              : M2_AUDIO_ERR_NAME_MISSING);

    uint32_t probe = gk_mint_item("audio probe", GK_AUDIO_PROBE_CTYPE,
                                 name_ea, 2, 1);
    if (probe == M2K_ITEM_NONE) return (uint32_t)M2_AUDIO_ERR_NO_MEMORY;
    gk_item *live = gk_live_item(probe);
    if (!live) {
        gk_DeleteItem(probe);
        return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
    }
    live->probe_instrument = instrument_item;
    live->probe_parts = parts;
    memcpy(live->audio_name, probe_name, sizeof(live->audio_name));
    return probe;
}

// SetKnobPart has a status return and a single-precision value in fpr1. The
// original converts/clips and writes DSP data (dsppSetKnob: ConvertFP_SF15 +
// signal-type clip into Data[alloc+part]); retain each validated guest value
// in host metadata and feed the live sim the same conversion when the owning
// instrument runs DSP code.
static float gk_sampler_attached_rate(const gk_item *instrument) {
    if (!instrument) return 44100.0f;
    for (uint32_t k = 0; k < GK_MAX_ITEMS; ++k) {
        const gk_item *a = &g_gk.items[k];
        if (!a->used || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            a->attachment_type != 1u ||
            gk_live_item(a->attachment_master) != instrument)
            continue;
        const gk_item *sample = gk_live_item(a->attachment_slave);
        if (sample && sample->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            sample->sample_rate > 0.0f)
            return sample->sample_rate;
    }
    return 44100.0f;
}

static int gk_instrument_is_sampler(const gk_item *instrument) {
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return 0;
    const gk_item *template_live = gk_live_item(instrument->template_item);
    if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE)
        return 0;
    static const char prefix[] = "sampler_";
    for (uint32_t i = 0; i < sizeof(prefix) - 1u; ++i) {
        char a = template_live->audio_name[i];
        char b = prefix[i];
        if (a >= 'A' && a <= 'Z') a = (char)(a + ('a' - 'A'));
        if (a != b) return 0;
    }
    return 1;
}

// Bounded race-audio sampler observation. Log only coarse rate/gain bucket
// transitions so a user-driven stop/idle test can identify which original
// sample voice becomes a drone without recording every per-frame knob write.
// This is observational: it neither changes guest values nor host playback.
static int gk_audio_voice_diag_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_AUDIO_VOICE_DIAG");
        enabled = e && *e && *e != '0';
        checked = 1;
    }
    return enabled;
}

static void gk_log_sampler_voice_params(const gk_item *instrument,
                                        float rate_hz, float gain) {
    static int32_t prior_rate_bucket[GK_MAX_ITEMS];
    static int32_t prior_gain_bucket[GK_MAX_ITEMS];
    static uint8_t seen[GK_MAX_ITEMS];
    static uint32_t count = 0;
    if (!gk_audio_voice_diag_enabled() || !instrument || count >= 2048u)
        return;
    const uint32_t slot = (uint32_t)(instrument - g_gk.items);
    if (slot >= GK_MAX_ITEMS) return;
    const int32_t rate_bucket = (int32_t)(rate_hz / 250.0f);
    const int32_t gain_bucket = (int32_t)(gain * 20.0f);
    if (seen[slot] && prior_rate_bucket[slot] == rate_bucket &&
        prior_gain_bucket[slot] == gain_bucket)
        return;
    seen[slot] = 1u;
    prior_rate_bucket[slot] = rate_bucket;
    prior_gain_bucket[slot] = gain_bucket;

    uint32_t sid = 0;
    for (uint32_t k = 0; k < GK_MAX_ITEMS; ++k) {
        const gk_item *a = &g_gk.items[k];
        if (!a->used || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            a->attachment_type != 1u ||
            gk_live_item(a->attachment_master) != instrument)
            continue;
        const gk_item *sample = gk_live_item(a->attachment_slave);
        if (sample && sample->ctype == GK_AUDIO_SAMPLE_CTYPE) {
            sid = sample->host_sample_id;
            break;
        }
    }
    const uint32_t handle =
        gk_make_handle(GK_TYPE_ITEM_VA, slot, instrument->generation);
    fprintf(stderr,
            "[audio-voice] n=%u inst=%#x sid=%u rate=%.1f gain=%.4f\n",
            ++count, handle, sid, rate_hz, gain);
}

static void gk_sampler_refresh_voice_params(gk_item *instrument) {
    if (!instrument || !instrument->audio_started ||
        instrument->audio_voice_mask == 0u)
        return;
    const float rate_hz = (instrument->audio_start_tags & 2u)
                              ? instrument->audio_start_4f
                              : gk_sampler_attached_rate(instrument);
    const float gain = (instrument->audio_start_tags & 1u)
                           ? instrument->audio_start_4e
                           : 1.0f;
    gk_log_sampler_voice_params(instrument, rate_hz, gain);
    for (uint32_t vi = 0; vi < 32u; ++vi) {
        if ((instrument->audio_voice_mask & (1u << vi)) == 0u ||
            !gk_voice_owned_sid(instrument, vi))
            continue;
        m2_host_audio_set_voice_params(vi, rate_hz, gain);
    }
}

int32_t m2_guest_audio_set_knob_part(PPCContext *cpu, uint32_t knob_item,
                                     int32_t part, float value) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *knob = gk_live_item(knob_item);
    if (!knob || knob->ctype != GK_AUDIO_KNOB_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *instrument = gk_live_item(knob->knob_instrument);
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (part < 0 || (uint32_t)part >= knob->knob_parts)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    knob->knob_values[part] = value;
    knob->knob_value_set[part] = 1;
    if (++g_gk.audio_knob_set_serial == 0)
        ++g_gk.audio_knob_set_serial;
    knob->knob_value_order[part] = g_gk.audio_knob_set_serial;
    // Feed the live sim through dsppSetKnob when the owning instrument runs
    // DSP code; instruments without a sim keep the retained value only.
    gk_dsp_poke_knob(instrument, knob->knob_instrument, knob->audio_name,
                      part, value);
    // Sample-backed samplers are rendered by the host FIFO/oscillator bridge,
    // not a duplicate DSP sim. Their two authored controls must therefore be
    // retained even while stopped, just as dsppSetKnob writes the allocated
    // DSP data word before DSPPStartInstrument. This ordering is used by the
    // race engine channels: they set SampleRate/Amplitude, then start. If a
    // voice is already live, refresh it immediately as well.
    if (part == 0 && gk_instrument_is_sampler(instrument)) {
        if (gk_audio_name_equal(knob->audio_name, "SampleRate")) {
            instrument->audio_start_4f = value;
            instrument->audio_start_tags |= 2u;
            gk_sampler_refresh_voice_params(instrument);
        } else if (gk_audio_name_equal(knob->audio_name, "Amplitude")) {
            instrument->audio_start_4e = value;
            instrument->audio_start_tags |= 1u;
            gk_sampler_refresh_voice_params(instrument);
            // A streamed sampler has no uploaded voice to refresh.
            m2_host_audio_set_stream_gain(knob->knob_instrument, value);
        }
    }
    return M2K_OK;
}

// ReadKnobPart checks the output pointer after the knob and part checks. The
// recovered bridge can publish values retained by SetKnobPart; the DSP-backed
// default value is intentionally left unresolved and does not
// write a fabricated value into guest RAM.
int32_t m2_guest_audio_read_knob_part(PPCContext *cpu, uint32_t knob_item,
                                      int32_t part, uint32_t value_ptr_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *knob = gk_live_item(knob_item);
    if (!knob || knob->ctype != GK_AUDIO_KNOB_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *instrument = gk_live_item(knob->knob_instrument);
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (part < 0 || (uint32_t)part >= knob->knob_parts)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    if (value_ptr_ea == 0 || value_ptr_ea > RECOMP_GUEST_MEM - 4u)
        return M2_AUDIO_ERR_SECURITY;
    if (!knob->knob_value_set[part])
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    wrf32(cpu, value_ptr_ea, knob->knob_values[part]);
    return M2K_OK;
}

// CreatePatchTemplate (AudioPatch folio 5 selector 0) constructs a custom
// patch template from a guest PatchCmd list and an optional TagArg list.
// The resulting item is registered as GK_AUDIO_TEMPLATE_CTYPE in the shared
// item pool so that CreateInstrument and CreateAttachmentVA accept it.
int32_t m2_guest_audiopatch_create_patch_template(PPCContext *cpu,
                                                  uint32_t patch_cmds_ea,
                                                  uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || !cpu->mem || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;

    int slot = -1;
    for (uint32_t i = 0; i < GK_MAX_PATCH_TEMPLATES; ++i) {
        if (!g_gk_patches[i].used) {
            slot = (int)i;
            break;
        }
    }
    if (slot < 0) return M2_AUDIO_ERR_NO_MEMORY;

    uint32_t name_ea = 0;
    if (taglist_ea != 0) {
        uint32_t cur_tag_ea = taglist_ea;
        for (uint32_t t = 0; t < 16; ++t) {
            if (cur_tag_ea == 0 || cur_tag_ea > RECOMP_GUEST_MEM - 8u) break;
            uint32_t tag = rd32(cpu, cur_tag_ea);
            uint32_t val = rd32(cpu, cur_tag_ea + 4u);
            cur_tag_ea += 8u;
            if (tag == M2_TAG_END) break;
            if (tag == 0xFFFFFFFFu) continue;
            if (tag == M2_TAG_JUMP) {
                cur_tag_ea = val;
                continue;
            }
            if (tag == 1u /* TAG_ITEM_NAME */) {
                name_ea = val;
            }
        }
    }

    gk_patch_template *pt = &g_gk_patches[slot];
    memset(pt, 0, sizeof(*pt));
    pt->used = 1;
    gk_mix_graph_touch();

    uint32_t cur_cmd_ea = patch_cmds_ea;
    uint32_t steps = 0;
    const uint32_t max_steps = 512;
    // Retain the complete source PatchCmd shape.  The graph realization is
    // built when the patch instrument starts, after every constituent DSPP
    // template has been allocated in the shared M2 address space.
    uint32_t n_add = 0, n_conn = 0, n_const = 0, n_coher = 0, n_other = 0;
    while (cur_cmd_ea != 0 && steps++ < max_steps) {
        if (cur_cmd_ea > RECOMP_GUEST_MEM - M2_PATCH_CMD_SIZE) {
            pt->used = 0;
            gk_mix_graph_touch();
            return M2_AUDIO_ERR_BAD_PTR;
        }
        uint32_t cmd_id = rd32(cpu, cur_cmd_ea);
        if (cmd_id == M2_PATCH_CMD_END) break;
        if (cmd_id == M2_PATCH_CMD_NOP) {
            cur_cmd_ea += M2_PATCH_CMD_SIZE;
            continue;
        }
        if (cmd_id == M2_PATCH_CMD_JUMP) {
            cur_cmd_ea = rd32(cpu, cur_cmd_ea + 4u);
            continue;
        }
        if (cmd_id == M2_PATCH_CMD_DEFINE_PORT) {
            uint32_t port_name_ea = rd32(cpu, cur_cmd_ea + 4u);
            uint32_t num_parts = rd32(cpu, cur_cmd_ea + 8u);
            uint32_t port_type = rd32(cpu, cur_cmd_ea + 12u);
            if (pt->resource_count < GK_MAX_PATCH_RESOURCES) {
                gk_patch_resource *res = &pt->resources[pt->resource_count++];
                (void)m2m_copy_guest_string_ctx(cpu, port_name_ea, res->name, sizeof(res->name));
                res->parts = num_parts;
                if (port_type == 0u /* AF_PORT_TYPE_INPUT */)
                    res->type = M2_DSP_RESOURCE_INPUT;
                else if (port_type == 1u /* AF_PORT_TYPE_OUTPUT */)
                    res->type = M2_DSP_RESOURCE_OUTPUT;
                else if (port_type == 2u /* AF_PORT_TYPE_KNOB */)
                    res->type = M2_DSP_RESOURCE_KNOB;
                else
                    res->type = M2_DSP_RESOURCE_VARIABLE;
                res->signal_type = rd32(cpu, cur_cmd_ea + 16u);
                res->default_value = 0.0f;
            }
        } else if (cmd_id == M2_PATCH_CMD_DEFINE_KNOB) {
            uint32_t knob_name_ea = rd32(cpu, cur_cmd_ea + 4u);
            uint32_t num_parts = rd32(cpu, cur_cmd_ea + 8u);
            float def_val = rdf32(cpu, cur_cmd_ea + 16u);
            if (pt->resource_count < GK_MAX_PATCH_RESOURCES) {
                gk_patch_resource *res = &pt->resources[pt->resource_count++];
                (void)m2m_copy_guest_string_ctx(cpu, knob_name_ea, res->name, sizeof(res->name));
                res->parts = num_parts;
                res->type = M2_DSP_RESOURCE_KNOB;
                res->signal_type = rd32(cpu, cur_cmd_ea + 12u);
                res->default_value = def_val;
            }
        } else if (cmd_id == M2_PATCH_CMD_EXPOSE) {
            uint32_t port_name_ea = rd32(cpu, cur_cmd_ea + 4u);
            uint32_t source_block_ea = rd32(cpu, cur_cmd_ea + 8u);
            uint32_t source_port_ea = rd32(cpu, cur_cmd_ea + 12u);
            if (pt->resource_count < GK_MAX_PATCH_RESOURCES) {
                gk_patch_resource *res = &pt->resources[pt->resource_count++];
                (void)m2m_copy_guest_string_ctx(cpu, port_name_ea, res->name, sizeof(res->name));
                res->parts = 1;
                res->type = M2_DSP_RESOURCE_VARIABLE;
                res->signal_type = 0u;
                res->default_value = 0.0f;
                res->exposed = 1u;
                if (source_block_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, source_block_ea, res->source_block,
                        sizeof(res->source_block));
                if (source_port_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, source_port_ea, res->source_port,
                        sizeof(res->source_port));
            }
        } else if (cmd_id == M2_PATCH_CMD_ADD_TEMPLATE) {
            ++n_add;
            if (pt->block_count < GK_MAX_PATCH_BLOCKS) {
                gk_patch_block *block = &pt->blocks[pt->block_count++];
                const uint32_t block_name_ea = rd32(cpu, cur_cmd_ea + 4u);
                block->template_item = rd32(cpu, cur_cmd_ea + 8u);
                if (block_name_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, block_name_ea, block->name,
                        sizeof(block->name));
                gk_item *source_template =
                    gk_live_item(block->template_item);
                if (source_template &&
                    source_template->ctype == GK_AUDIO_TEMPLATE_CTYPE)
                    memcpy(block->template_name, source_template->audio_name,
                           sizeof(block->template_name));
            }
        } else if (cmd_id == M2_PATCH_CMD_CONNECT) {
            ++n_conn;
            // Retain every route up to the bounded source-shaped graph
            // capacity. Empty block names identify the patch scope.
            if (pt->route_count < GK_MAX_PATCH_ROUTES) {
                gk_patch_route *rt = &pt->routes[pt->route_count++];
                rt->from_block_ea = rd32(cpu, cur_cmd_ea + 4u);
                rt->to_block_ea = rd32(cpu, cur_cmd_ea + 16u);
                rt->from_block[0] = rt->to_block[0] = '\0';
                rt->from_port[0] = rt->to_port[0] = '\0';
                if (rt->from_block_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, rt->from_block_ea, rt->from_block,
                        sizeof(rt->from_block));
                if (rt->to_block_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, rt->to_block_ea, rt->to_block,
                        sizeof(rt->to_block));
                (void)m2m_copy_guest_string_ctx(cpu,
                                                rd32(cpu, cur_cmd_ea + 8u),
                                                rt->from_port,
                                                sizeof(rt->from_port));
                (void)m2m_copy_guest_string_ctx(cpu,
                                                rd32(cpu, cur_cmd_ea + 20u),
                                                rt->to_port,
                                                sizeof(rt->to_port));
                rt->from_part = rd32(cpu, cur_cmd_ea + 12u);
                rt->to_part = rd32(cpu, cur_cmd_ea + 24u);
            }
            if (gk_audio_start_diag_enabled()) {
                static uint32_t pconn_count = 0;
                if (pconn_count < 32u) {
                    ++pconn_count;
                    char fb[GK_MAX_NAME_LEN], fp[GK_MAX_NAME_LEN];
                    char tb[GK_MAX_NAME_LEN], tp[GK_MAX_NAME_LEN];
                    fb[0] = fp[0] = tb[0] = tp[0] = '\0';
                    (void)m2m_copy_guest_string_ctx(
                        cpu, rd32(cpu, cur_cmd_ea + 4u), fb, sizeof(fb));
                    (void)m2m_copy_guest_string_ctx(
                        cpu, rd32(cpu, cur_cmd_ea + 8u), fp, sizeof(fp));
                    (void)m2m_copy_guest_string_ctx(
                        cpu, rd32(cpu, cur_cmd_ea + 16u), tb, sizeof(tb));
                    (void)m2m_copy_guest_string_ctx(
                        cpu, rd32(cpu, cur_cmd_ea + 20u), tp, sizeof(tp));
                    fprintf(stderr,
                            "[audio-template-conn] n=%u from=(%#x,%s,%u) "
                            "to=(%#x,%s,%u)\n",
                            pconn_count, rd32(cpu, cur_cmd_ea + 4u), fp,
                            rd32(cpu, cur_cmd_ea + 12u),
                            rd32(cpu, cur_cmd_ea + 16u), tp,
                            rd32(cpu, cur_cmd_ea + 24u));
                }
            }
        } else if (cmd_id == M2_PATCH_CMD_SET_CONSTANT) {
            ++n_const;
            if (pt->constant_count < GK_MAX_PATCH_CONSTANTS) {
                gk_patch_constant *constant =
                    &pt->constants[pt->constant_count++];
                const uint32_t block_ea = rd32(cpu, cur_cmd_ea + 4u);
                const uint32_t port_ea = rd32(cpu, cur_cmd_ea + 8u);
                if (block_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, block_ea, constant->block,
                        sizeof(constant->block));
                if (port_ea != 0u)
                    (void)m2m_copy_guest_string_ctx(
                        cpu, port_ea, constant->port,
                        sizeof(constant->port));
                constant->part = rd32(cpu, cur_cmd_ea + 12u);
                constant->value = rdf32(cpu, cur_cmd_ea + 16u);
            }
        } else if (cmd_id == M2_PATCH_CMD_SET_COHERENCE) {
            ++n_coher;
            pt->coherence_state = rd32(cpu, cur_cmd_ea + 4u);
        } else {
            ++n_other;
        }
        cur_cmd_ea += M2_PATCH_CMD_SIZE;
    }
    uint32_t item = gk_mint_item(name_ea != 0 ? "audio patch template" : "audio template",
                                 GK_AUDIO_TEMPLATE_CTYPE, name_ea, 2, 0);
    gk_item *live = gk_live_item(item);
    if (!live) {
        gk_DeleteItem(item);
        pt->used = 0;
        gk_mix_graph_touch();
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    live->patch_index = (uint16_t)(slot + 1);
    // R1/R3 capture: classify the live patch templates (port/knob shape plus
    // the sub-graph histogram above). Bounded (16) behind the existing audio
    // start gate; no behavior change.
    if (gk_audio_start_diag_enabled()) {
        static uint32_t patch_count = 0;
        if (patch_count < 16u) {
            ++patch_count;
            uint32_t n_ports = 0, n_knobs = 0, n_expose = 0;
            for (uint32_t i = 0; i < pt->resource_count; ++i) {
                if (pt->resources[i].type == M2_DSP_RESOURCE_INPUT ||
                    pt->resources[i].type == M2_DSP_RESOURCE_OUTPUT)
                    ++n_ports;
                else if (pt->resources[i].type == M2_DSP_RESOURCE_KNOB)
                    ++n_knobs;
                else
                    ++n_expose;
            }
            fprintf(stderr,
                    "[audio-template] n=%u kind=patch item=%#x slot=%d "
                    "ports=%u knobs=%u expose=%u add=%u conn=%u const=%u "
                    "coher=%u other=%u routes=%u\n",
                    patch_count, item, slot, n_ports, n_knobs, n_expose,
                    n_add, n_conn, n_const, n_coher, n_other,
                    pt->route_count);
        }
    }
    return (int32_t)item;
}

static int recomp_call_audiopatch_dispatch_impl(PPCContext *c, uint32_t ordinal,
                                                uint32_t pc) {
    (void)pc;
    if (ordinal != 0u) return 0;
    if (!c) return 1;
    uint32_t patch_cmds_ea = c->gpr[3];
    uint32_t taglist_ea = c->gpr[4];
    int32_t result = m2_guest_audiopatch_create_patch_template(
        c, patch_cmds_ea, taglist_ea);
    c->gpr[3] = (uint32_t)result;
    return 1;
}

// Public entry point; see the filesystem dispatch wrapper
// (selector_observed.h).
int recomp_call_audiopatch_dispatch(PPCContext *c, uint32_t ordinal,
                                    uint32_t pc) {
    const int handled = recomp_call_audiopatch_dispatch_impl(c, ordinal, pc);
    m2_selector_note(M2_FOLIO_AUDIOPATCH, ordinal, handled);
    return handled;
}

// ReadProbePart has the same shared helper and error ordering as
// ReadKnobPart: validate the probe Item, part range, and writable float32
// destination before the DSP readback/conversion. Instruments without an
// executor (DSP templates the host never built a sim for) stop without
// modifying guest RAM; mix-node instruments (R1) publish their current
// output word as a float (SF15 word / 32768), resolved on demand so a read
// without a preceding tick still observes the live graph.
int32_t m2_guest_audio_read_probe_part(PPCContext *cpu, uint32_t probe_item,
                                       int32_t part, uint32_t value_ptr_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *probe = gk_live_item(probe_item);
    if (!probe || probe->ctype != GK_AUDIO_PROBE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *instrument = gk_live_item(probe->probe_instrument);
    if (!instrument || instrument->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (part < 0 || (uint32_t)part >= probe->probe_parts)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    if (value_ptr_ea == 0 || value_ptr_ea > RECOMP_GUEST_MEM - 4u)
        return M2_AUDIO_ERR_SECURITY;
    if (gk_mixnode_kind_of(instrument) != 0) {
        if (!instrument->audio_started || instrument->audio_paused) {
            wrf32(cpu, value_ptr_ea, 0.0f);
            return M2K_OK;
        }
        // Fresh serial so the resolve below recomputes from the live graph
        // instead of trusting a stale tick memo. Pure function of template
        // + knobs + connections + sim peeks — except voice-tap sources,
        // which consume one tap frame per probe recompute (R2).
        gk_mix_bump_serial();
        int16_t w = gk_mixnode_port_output(instrument, probe->probe_instrument,
                                           probe->audio_name, part, 0);
        wrf32(cpu, value_ptr_ea, (float)w / 32768.0f);
        return M2K_OK;
    }
    if (instrument->audio_dsp_sim) {
        if (!instrument->audio_started || instrument->audio_paused) {
            wrf32(cpu, value_ptr_ea, 0.0f);
            return M2K_OK;
        }
        const dspp_template *t =
            dspp_sim_resources((const dspp_sim *)instrument->audio_dsp_sim);
        if (t) {
            for (uint32_t i = 0; i < t->resource_count; ++i) {
                const dspp_resource *r = &t->resources[i];
                if (gk_audio_name_equal(r->name, probe->audio_name)) {
                    if (r->alloc_value != 0xFFFFFFFFu &&
                        (uint32_t)part < r->many) {
                        uint32_t addr = r->alloc_value + (uint32_t)part;
                        uint16_t raw = dspp_sim_peek_data(
                            (const dspp_sim *)instrument->audio_dsp_sim, addr);
                        int16_t sraw = (int16_t)raw;
                        wrf32(cpu, value_ptr_ea, (float)sraw / 32768.0f);
                        return M2K_OK;
                    }
                    break;
                }
            }
        }
    }
    return M2_AUDIO_ERR_UNIMPLEMENTED;
}

// AbortTimerCue validates the source Cue Item and its task ownership, then
// unposts the bounded local AudioEvent state. Host-only callers have no
// CURRENTTASKITEM, so ownership is enforced when creation captured a guest
// task rather than being guessed for compatibility handles.
int32_t m2_guest_audio_abort_timer_cue(PPCContext *cpu, uint32_t cue_item) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    pthread_mutex_lock(&g_audio_timer_lock);
    gk_item *cue = gk_live_item(cue_item);
    if (!cue || cue->ctype != GK_AUDIO_CUE_CTYPE) {
        pthread_mutex_unlock(&g_audio_timer_lock);
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    if (cue->cue_owner != M2K_ITEM_NONE) {
        uint32_t current = m2k_current_task_item(g_gk.kctx);
        if (current != cue->cue_owner) {
            pthread_mutex_unlock(&g_audio_timer_lock);
            return M2_AUDIO_ERR_NOT_OWNER;
        }
    }
    cue->cue_posted = 0;
    cue->cue_trigger_time = 0;
    pthread_mutex_unlock(&g_audio_timer_lock);
    return M2K_OK;
}

// ResumeInstrument validates the source AudioInstrument Item. If stopped,
// it returns M2K_OK per vendor swiResumeInstrument (ains_Status <= AF_STOPPED).
// Otherwise, clears the paused flag and resumes each owned voice.
int32_t m2_guest_audio_resume_instrument(PPCContext *cpu,
                                         uint32_t instrument) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (!live->audio_started)
        return M2K_OK;
    if (live->audio_paused) {
        live->audio_paused = 0;
        for (uint32_t i = 0; i < 32u; ++i) {
            if ((live->audio_voice_mask & (1u << i)) != 0u) {
                m2_host_audio_resume_voice(i);
            }
        }
    }
    return M2K_OK;
}

// PauseInstrument validates the source AudioInstrument Item. If stopped,
// it returns M2K_OK per vendor swiPauseInstrument (ains_Status <= AF_STOPPED).
// Otherwise, sets the paused flag and pauses each owned voice.
int32_t m2_guest_audio_pause_instrument(PPCContext *cpu,
                                        uint32_t instrument) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(instrument);
    if (!live || live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (!live->audio_started)
        return M2K_OK;
    if (!live->audio_paused) {
        live->audio_paused = 1;
        for (uint32_t i = 0; i < 32u; ++i) {
            if ((live->audio_voice_mask & (1u << i)) != 0u) {
                m2_host_audio_pause_voice(i);
            }
        }
    }
    return M2K_OK;
}

// GetCueSignal historically returns zero for a bad Cue Item. A valid Cue
// stores the task-relative SuperAllocSignal mask captured at creation.
uint32_t m2_guest_audio_get_cue_signal(PPCContext *cpu, uint32_t cue_item) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return 0;
    pthread_mutex_lock(&g_audio_timer_lock);
    gk_item *cue = gk_live_item(cue_item);
    if (!cue || cue->ctype != GK_AUDIO_CUE_CTYPE) {
        pthread_mutex_unlock(&g_audio_timer_lock);
        return 0;
    }
    uint32_t signal = cue->cue_signal_mask;
    pthread_mutex_unlock(&g_audio_timer_lock);
    return signal;
}

// GetAudioResourceInfo accepts the five source resource types and writes a
// three-word AudioResourceInfo result. The production sndPrintDSPInfo calls
// use a guest stack destination of size 12 and resource types 0..3. This
// bridge has no DSP allocator totals or largest-span state, so validate the
// source type and bounded destination, then stop before fabricating output.
int32_t m2_guest_audio_get_resource_info(PPCContext *cpu, uint32_t info_ea,
                                         uint32_t info_size,
                                         uint32_t resource_type) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (resource_type >= M2_AUDIO_RESOURCE_TYPE_COUNT)
        return M2_AUDIO_ERR_BAD_RESOURCE_TYPE;
    if (info_ea == 0 || info_ea >= RECOMP_GUEST_MEM ||
        info_size > RECOMP_GUEST_MEM - info_ea)
        return M2_AUDIO_ERR_BAD_PTR;
    return M2_AUDIO_ERR_UNIMPLEMENTED;
}

// SetAudioItemInfo's sample path is the first recovered imported VA boundary.
// The production spooler publishes AF_TAG_ADDRESS, AF_TAG_NUMBYTES, and
// AF_TAG_SUPPRESS_WRITE_BACK_D_CACHE for a guest-owned sample buffer. Preserve
// only the fixed-width data metadata here; host-coherent memory makes the
// cache-control tag an intentional no-op, and DSP playback remains unresolved.
static int gk_sample_diag_enabled(void);
static uint32_t gk_upload_sample_bytes(PPCContext *, uint32_t, uint32_t,
                                       uint32_t, uint32_t, uint32_t,
                                       uint32_t, uint32_t *);

static void gk_log_audio_item_info(PPCContext *cpu, uint32_t audio_item,
                                    uint32_t taglist_ea) {
    static uint32_t count = 0;
    if (!gk_sample_diag_enabled() || count >= 64u) return;
    ++count;
    fprintf(stderr, "[audio-item] n=%u item=%#x taglist=%#x tags=",
            count, audio_item, taglist_ea);
    if (taglist_ea == 0u) {
        fprintf(stderr, " NULL\n");
        return;
    }
    if (!cpu || !cpu->mem || taglist_ea > RECOMP_GUEST_MEM - 8u) {
        fprintf(stderr, " OOB\n");
        return;
    }
    for (uint32_t i = 0; i < 8u; ++i) {
        const uint32_t ea = taglist_ea + i * 8u;
        if (ea > RECOMP_GUEST_MEM - 8u) {
            fprintf(stderr, " OOB");
            break;
        }
        const uint32_t tag = rd32(cpu, ea);
        const uint32_t value = rd32(cpu, ea + 4u);
        fprintf(stderr, " (%#x,%#x)", tag, value);
        if (tag == M2_TAG_END) break;
    }
    fprintf(stderr, "\n");
}

int32_t m2_guest_audio_set_item_info(PPCContext *cpu, uint32_t audio_item,
                                     uint32_t taglist_ea) {
    gk_log_audio_item_info(cpu, audio_item, taglist_ea);
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(audio_item);
    if (!live || live->ctype != GK_AUDIO_SAMPLE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (taglist_ea == 0) return M2K_OK;
    if (live->sample_kind != 0u) {
        uint32_t sample_flags = live->sample_flags;
        int terminated = 0;
        for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
            const uint32_t ea = taglist_ea + i * 8u;
            if (ea > RECOMP_GUEST_MEM - 8u)
                return M2_AUDIO_ERR_BAD_PTR;
            const uint32_t tag = rd32(cpu, ea);
            const uint32_t value = rd32(cpu, ea + 4u);
            if (tag == M2_TAG_END) {
                terminated = 1;
                break;
            }
            if (tag == M2_AUDIO_TAG_SET_FLAGS) {
                if (value & ~M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP)
                    return M2_AUDIO_ERR_BAD_TAG_VALUE;
                sample_flags |= value;
            } else if (tag == M2_AUDIO_TAG_CLEAR_FLAGS) {
                if (value & ~M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP)
                    return M2_AUDIO_ERR_BAD_TAG_VALUE;
                sample_flags &= ~value;
            } else {
                return M2_AUDIO_ERR_BAD_TAG;
            }
        }
        if (!terminated) return M2_AUDIO_ERR_BAD_TAG;
        live->sample_flags = sample_flags;
        if (live->sample_delay_line)
            dspp_delay_line_set_clear_on_stop(
                live->sample_delay_line,
                (sample_flags & M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP) != 0u);
        return M2K_OK;
    }

    uint32_t sample_address = live->sample_address;
    uint32_t sample_num_bytes = live->sample_num_bytes;
    uint32_t sample_bits = live->sample_bits;
    uint32_t sample_channels = live->sample_channels;
    uint32_t sample_compression = live->sample_compression;
    uint32_t sample_compression_ratio = live->sample_compression_ratio;
    float sample_rate = live->sample_rate;
    int32_t sustain_begin = live->sample_sustain_begin;
    int32_t sustain_end = live->sample_sustain_end;
    int32_t release_begin = live->sample_release_begin;
    int32_t release_end = live->sample_release_end;
    uint8_t low_note = live->sample_low_note;
    uint8_t high_note = live->sample_high_note;
    uint8_t low_velocity = live->sample_low_velocity;
    uint8_t high_velocity = live->sample_high_velocity;
    int terminated = 0;
    for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
        const uint32_t ea = taglist_ea + i * 8u;
        if (ea > RECOMP_GUEST_MEM - 8u)
            return M2_AUDIO_ERR_BAD_PTR;
        const uint32_t tag = rd32(cpu, ea);
        const uint32_t value = rd32(cpu, ea + 4u);
        if (tag == M2_TAG_END) {
            terminated = 1;
            break;
        }
        switch (tag) {
        case M2_AUDIO_TAG_ADDRESS:
            sample_address = value;
            break;
        case M2_AUDIO_TAG_NUMBYTES:
            sample_num_bytes = value;
            break;
        case M2_AUDIO_TAG_NUMBITS:
            if (value < 1u || value > 16u) return M2_AUDIO_ERR_OUT_OF_RANGE;
            sample_bits = value;
            break;
        case M2_AUDIO_TAG_WIDTH:
            if (value < 1u || value > 2u) return M2_AUDIO_ERR_OUT_OF_RANGE;
            sample_bits = value * 8u;
            break;
        case M2_AUDIO_TAG_CHANNELS:
            if (value < 1u || value > 255u) return M2_AUDIO_ERR_OUT_OF_RANGE;
            sample_channels = value;
            break;
        case M2_AUDIO_TAG_COMPRESSIONTYPE:
            sample_compression = value;
            break;
        case M2_AUDIO_TAG_COMPRESSIONRATIO:
            if (value < 1u || value > 255u) return M2_AUDIO_ERR_OUT_OF_RANGE;
            sample_compression_ratio = value;
            break;
        case M2_AUDIO_TAG_SAMPLE_RATE_FP:
            memcpy(&sample_rate, &value, sizeof(sample_rate));
            if (sample_rate < 10.0f || sample_rate > 1000000.0f)
                return M2_AUDIO_ERR_OUT_OF_RANGE;
            break;
        case M2_AUDIO_TAG_SUSTAINBEGIN:
            sustain_begin = (int32_t)value;
            break;
        case M2_AUDIO_TAG_SUSTAINEND:
            sustain_end = (int32_t)value;
            break;
        case M2_AUDIO_TAG_RELEASEBEGIN:
            release_begin = (int32_t)value;
            break;
        case M2_AUDIO_TAG_RELEASEEND:
            release_end = (int32_t)value;
            break;
        case M2_AUDIO_TAG_LOWNOTE:
            low_note = (uint8_t)(value > 127 ? 127 : value);
            break;
        case M2_AUDIO_TAG_HIGHNOTE:
            high_note = (uint8_t)(value > 127 ? 127 : value);
            break;
        case M2_AUDIO_TAG_LOWVELOCITY:
            low_velocity = (uint8_t)(value > 127 ? 127 : value);
            break;
        case M2_AUDIO_TAG_HIGHVELOCITY:
            high_velocity = (uint8_t)(value > 127 ? 127 : value);
            break;
        case M2_AUDIO_TAG_SUPPRESS_WRITE_BACK_D_CACHE:
            // Guest and host share coherent recompiled RAM; no cache flush is
            // needed, but the source tag is accepted as part of this call.
            break;
        default:
            return M2_AUDIO_ERR_BAD_TAG;
        }
    }
    if (!terminated) return M2_AUDIO_ERR_BAD_TAG;

    // Validate the final pair before committing either field. This mirrors
    // internalSetSampleInfo's temporary-copy behavior and prevents malformed
    // guest EAs from escaping into any future host playback path.
    if (sample_address >= RECOMP_GUEST_MEM ||
        (sample_num_bytes != 0u && sample_address == 0u) ||
        sample_num_bytes > RECOMP_GUEST_MEM - sample_address)
        return M2_AUDIO_ERR_BAD_PTR;
    live->sample_address = sample_address;
    live->sample_num_bytes = sample_num_bytes;
    live->sample_bits = sample_bits;
    live->sample_channels = sample_channels;
    live->sample_compression = sample_compression;
    live->sample_compression_ratio = sample_compression_ratio;
    live->sample_rate = sample_rate;
    live->sample_sustain_begin = sustain_begin;
    live->sample_sustain_end = sustain_end;
    live->sample_release_begin = release_begin;
    live->sample_release_end = release_end;
    live->sample_low_note = low_note;
    live->sample_high_note = high_note;
    live->sample_low_velocity = low_velocity;
    live->sample_high_velocity = high_velocity;

    // SoundSpooler creates byte-width sample Items before it has a buffer.
    // SetAudioItemInfo later publishes arbitrary stream bytes; retain the
    // guest-visible metadata, but do not reinterpret those bytes as PCM.
    if (live->sample_stream_placeholder)
        return M2K_OK;

    // Creation and updates must interpret the same retained format. Never
    // keep a previous playable ID when the new payload cannot be decoded.
    live->host_sample_id = sample_address == 0u ? 0u : gk_upload_sample_bytes(
        cpu, sample_address, sample_num_bytes, sample_channels,
        sample_compression, sample_compression_ratio, sample_bits, NULL);
    return M2K_OK;
}

// GetAudioItemInfo supports Instrument, Knob, Sample, Envelope, and
// Attachment Items. Each source type-specific reader accepts a null or empty
// tag list without reading item state. The sample reader exposes the address,
// byte count, and authored sustain/release frame bounds retained by the
// recovered SetAudioItemInfo path; other non-empty per-type settings remain
// unresolved. The production Get3DSoundInstrument call supplies an Instrument
// Item and a null tag list at guest PC 0x6ac8c.
int32_t m2_guest_audio_get_item_info(PPCContext *cpu, uint32_t audio_item,
                                     uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(audio_item);
    if (!live)
        return M2_AUDIO_ERR_BAD_ITEM;
    switch (live->ctype) {
    case GK_AUDIO_INSTRUMENT_CTYPE:
    case GK_AUDIO_KNOB_CTYPE:
    case GK_AUDIO_SAMPLE_CTYPE:
    case GK_AUDIO_ENVELOPE_CTYPE:
    case GK_AUDIO_ATTACHMENT_CTYPE:
        break;
    default:
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    if (taglist_ea == 0)
        return M2K_OK;
    if (taglist_ea > RECOMP_GUEST_MEM - 8u)
        return M2_AUDIO_ERR_BAD_PTR;
    if (rd32(cpu, taglist_ea) == M2_TAG_END)
        return M2K_OK;
    if (live->ctype == GK_AUDIO_SAMPLE_CTYPE) {
        for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
            const uint32_t ea = taglist_ea + i * 8u;
            if (ea > RECOMP_GUEST_MEM - 8u)
                return M2_AUDIO_ERR_BAD_PTR;
            const uint32_t tag = rd32(cpu, ea);
            if (tag == M2_TAG_END) return M2K_OK;
            if (tag == M2_AUDIO_TAG_ADDRESS)
                wr32(cpu, ea + 4u, live->sample_address);
            else if (tag == M2_AUDIO_TAG_NUMBYTES)
                wr32(cpu, ea + 4u, live->sample_num_bytes);
            else if (tag == M2_AUDIO_TAG_NUMBITS)
                wr32(cpu, ea + 4u, live->sample_bits);
            else if (tag == M2_AUDIO_TAG_WIDTH)
                wr32(cpu, ea + 4u, (live->sample_bits + 7u) / 8u);
            else if (tag == M2_AUDIO_TAG_CHANNELS)
                wr32(cpu, ea + 4u, live->sample_channels);
            else if (tag == M2_AUDIO_TAG_COMPRESSIONTYPE)
                wr32(cpu, ea + 4u, live->sample_compression);
            else if (tag == M2_AUDIO_TAG_COMPRESSIONRATIO)
                wr32(cpu, ea + 4u, live->sample_compression_ratio);
            else if (tag == M2_AUDIO_TAG_SAMPLE_RATE_FP) {
                uint32_t bits = 0;
                memcpy(&bits, &live->sample_rate, sizeof(bits));
                wr32(cpu, ea + 4u, bits);
            }
            else if (tag == M2_AUDIO_TAG_SUSTAINBEGIN)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_sustain_begin);
            else if (tag == M2_AUDIO_TAG_SUSTAINEND)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_sustain_end);
            else if (tag == M2_AUDIO_TAG_RELEASEBEGIN)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_release_begin);
            else if (tag == M2_AUDIO_TAG_RELEASEEND)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_release_end);
            else if (tag == M2_AUDIO_TAG_LOWNOTE)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_low_note);
            else if (tag == M2_AUDIO_TAG_HIGHNOTE)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_high_note);
            else if (tag == M2_AUDIO_TAG_LOWVELOCITY)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_low_velocity);
            else if (tag == M2_AUDIO_TAG_HIGHVELOCITY)
                wr32(cpu, ea + 4u, (uint32_t)live->sample_high_velocity);
            else
                return M2_AUDIO_ERR_BAD_TAG;
        }
        return M2_AUDIO_ERR_BAD_TAG;
    }
    return M2_AUDIO_ERR_UNIMPLEMENTED;
}

// SignalAtAudioTime validates the clock/Cue prefix and the caller-owned Cue
// requirement, then retains the source's one-event in-list state. The clock is
// AF_GLOBAL_CLOCK (Item 0) or a live AUDIO_CLOCK_NODE Item, exactly as
// swiSignalAtAudioTime resolves it (audio_timer.c:623-635). The posted event
// records that clock so the timer pass compares the trigger time against the
// same timebase; delivery of the Cue signal happens in the frame/DSPP pump.
int32_t m2_guest_audio_signal_at_audio_time(PPCContext *cpu, uint32_t clock,
                                            uint32_t cue_item,
                                            uint32_t time) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (clock != 0u) {
        gk_item *clk = gk_live_item(clock);
        if (!clk || clk->ctype != GK_AUDIO_CLOCK_CTYPE)
            return M2_AUDIO_ERR_BAD_ITEM;
    }
    pthread_mutex_lock(&g_audio_timer_lock);
    gk_item *cue = gk_live_item(cue_item);
    if (!cue || cue->ctype != GK_AUDIO_CUE_CTYPE) {
        pthread_mutex_unlock(&g_audio_timer_lock);
        return M2_AUDIO_ERR_BAD_ITEM;
    }
    if (cue->cue_owner != M2K_ITEM_NONE) {
        uint32_t current = m2k_current_task_item(g_gk.kctx);
        if (current != cue->cue_owner) {
            pthread_mutex_unlock(&g_audio_timer_lock);
            return M2_AUDIO_ERR_NOT_OWNER;
        }
    }
    if (cue->cue_posted) {
        pthread_mutex_unlock(&g_audio_timer_lock);
        return M2_AUDIO_ERR_IN_USE;
    }
    cue->cue_trigger_time = time;
    // acue_Event.aevt_Clock = aclk (audio_timer.c:654): the trigger time is
    // expressed in this clock's own tick cadence, not the global one.
    cue->cue_clock = clock;
    cue->cue_posted = 1;
    pthread_mutex_unlock(&g_audio_timer_lock);
    return M2K_OK;
}

// Vendor GetAudioClockTime (folios/audio/audio_timer.c:314-340): advance the
// clock's AudioTime by the whole ticks contained in the DSP frames elapsed
// since the last read, carrying the leftover frames in aclk_RemainderFrames
// so repeated reads at one frame count are idempotent and a Duration change
// can neither invent nor lose a tick. `clock == NULL` is AF_GLOBAL_CLOCK and
// returns the pre-existing global timebase unchanged. Caller holds
// g_audio_timer_lock and passes the already-sampled frame count, because
// gk_audio_clock_read takes that lock itself.
static uint32_t gk_audio_clock_time_from_frames(gk_item *clock, uint32_t frames) {
    if (!clock) return frames / GK_AUDIO_GLOBAL_CLOCK_DURATION;
    const uint32_t duration = clock->clock_duration != 0u
                                  ? clock->clock_duration
                                  : GK_AUDIO_GLOBAL_CLOCK_DURATION;
    if (frames < clock->clock_old_frames) {
        // A reopened host device restarts its raw frame counter. Rebase on the
        // new epoch instead of accumulating the wrap as a huge elapsed count;
        // this mirrors the fallback reset in gk_audio_clock_read.
        clock->clock_old_frames = frames;
        clock->clock_remainder_frames = 0;
        return clock->clock_time;
    }
    uint32_t elapsed = frames - clock->clock_old_frames;
    clock->clock_old_frames = frames;
    if (elapsed == 0u) return clock->clock_time; // source saves the divide
    elapsed += clock->clock_remainder_frames;
    const uint32_t ticks = elapsed / duration;
    clock->clock_remainder_frames = elapsed - ticks * duration;
    clock->clock_time += ticks;
    return clock->clock_time;
}

// Resolve the AudioClock a posted Cue is timed against (vendor
// AudioEvent.aevt_Clock, audio_structs.h:102). A Cue posted against
// AF_GLOBAL_CLOCK keeps the global timebase the pump already passes in.
static uint32_t gk_cue_due_time_locked(gk_item *cue, uint32_t frames,
                                       uint32_t global_time) {
    if (!cue || cue->cue_clock == 0u) return global_time;
    gk_item *clock = gk_live_item(cue->cue_clock);
    if (!clock || clock->ctype != GK_AUDIO_CLOCK_CTYPE) return global_time;
    return gk_audio_clock_time_from_frames(clock, frames);
}

// ReadAudioClock: swiReadAudioClock (audio_timer.c:1169-1196) validates the
// writable destination first, substitutes AF_GLOBAL_CLOCK for Item 0, writes
// AudioTime to *timePtr, and writes nothing at all when it fails.
int32_t m2_guest_audio_read_audio_clock(PPCContext *cpu, uint32_t clock,
                                        uint32_t time_ptr_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    // IsMemWritable(timePtr, sizeof(AudioTime)) is the source's first test.
    if (time_ptr_ea == 0u || time_ptr_ea > RECOMP_GUEST_MEM - 4u)
        return M2_AUDIO_ERR_SECURITY;
    const uint32_t frames =
        (uint32_t)gk_audio_clock_read(m2_host_audio_frame_count(), 0);
    pthread_mutex_lock(&g_audio_timer_lock);
    gk_item *clk = NULL;
    if (clock != 0u) {
        clk = gk_live_item(clock);
        if (!clk || clk->ctype != GK_AUDIO_CLOCK_CTYPE) {
            pthread_mutex_unlock(&g_audio_timer_lock);
            return M2_AUDIO_ERR_BAD_ITEM;
        }
    }
    const uint32_t now = gk_audio_clock_time_from_frames(clk, frames);
    pthread_mutex_unlock(&g_audio_timer_lock);
    wr32(cpu, time_ptr_ea, now);
    return M2K_OK;
}

// SetAudioClockRate: swiSetAudioClockRate (audio_timer.c:1056-1071) resolves
// the clock Item (no AF_GLOBAL_CLOCK substitution on this call), integerises
// sample-rate/hertz with +0.5 rounding, and hands the result to
// lowSetAudioDuration, which range-checks it and re-bases the clock before the
// new Duration takes effect.
int32_t m2_guest_audio_set_audio_clock_rate(PPCContext *cpu, uint32_t clock,
                                            float hertz) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *clk = gk_live_item(clock);
    if (!clk || clk->ctype != GK_AUDIO_CLOCK_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    const double ratio = GK_AUDIO_DSP_SAMPLE_RATE / (double)hertz;
    // A zero, negative, infinite or NaN hertz produces a ratio that cannot be
    // integerised into int32; that is the same out-of-range class the source
    // reaches through lowSetAudioDuration.
    if (!(ratio > -2147483648.0 && ratio < 2147483648.0))
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    const int32_t duration = (int32_t)(ratio + 0.5);
    if (duration < GK_AUDIO_MIN_DSP_DURATION ||
        duration > GK_AUDIO_MAX_DSP_DURATION)
        return M2_AUDIO_ERR_OUT_OF_RANGE;
    const uint32_t frames =
        (uint32_t)gk_audio_clock_read(m2_host_audio_frame_count(), 0);
    pthread_mutex_lock(&g_audio_timer_lock);
    (void)gk_audio_clock_time_from_frames(clk, frames); // lowSetAudioDuration
    clk->clock_duration = (uint32_t)duration;
    pthread_mutex_unlock(&g_audio_timer_lock);
    return M2K_OK;
}

// SleepUntilAudioTime: SleepUntilAudioTime (audio_timer.c:918-933) is
// SignalAtAudioTime + GetCueSignal + WaitSignal, returning 0 once the Cue
// signal arrives. The wait is a real block on the calling task's signal bit:
// the host frame/DSPP timer pump removes the due AudioEvent and raises that
// signal, which is what releases the task. It must therefore be called
// WITHOUT the audio graph lock held, or the pump that has to deliver the
// signal could never take that lock.
int32_t m2_guest_audio_sleep_until_audio_time(PPCContext *cpu, uint32_t clock,
                                              uint32_t cue_item,
                                              uint32_t time) {
    const int32_t posted =
        m2_guest_audio_signal_at_audio_time(cpu, clock, cue_item, time);
    if (posted < 0) return posted;
    const uint32_t mask = m2_guest_audio_get_cue_signal(cpu, cue_item);
    if (mask != 0u) (void)m2k_wait_signal(g_gk.kctx, mask);
    // The source returns 0 unconditionally after WaitSignal.
    return M2K_OK;
}

// StopAttachment: swiStopAttachment (audio_attachments.c:1331-1359) checks
// the Item is an AUDIO_ATTACHMENT_NODE, rejects any non-NULL tag list with
// AF_ERR_BADTAG, requires aatt_HostItem to be an Instrument, then dispatches on
// aatt_Type. Both leaves stop abruptly: no release phase is entered, and a
// stopped attachment never signals its Cue.
int32_t m2_guest_audio_stop_attachment(PPCContext *cpu, uint32_t attachment,
                                       uint32_t taglist_ea) {
    if (!gk_bound() || !cpu || cpu->mem != g_gk.cpu->mem)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_item *live = gk_live_item(attachment);
    if (!live || live->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (taglist_ea != 0u)
        return M2_AUDIO_ERR_BAD_TAG;
    gk_item *master = gk_live_item(live->attachment_master);
    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (live->attachment_type == 2u) {
        // DSPPStopEnvAttachment (audio_envelopes.c:1240-1251): activity level to
        // AF_STOPPED and the pending AudioEnvExtension event unposted, so no
        // further segment runs and the monitoring Cue cannot fire.
        pthread_mutex_lock(&g_audio_timer_lock);
        live->envelope_activity = 0u;
        live->envelope_event_posted = 0u;
        live->envelope_event_time = 0u;
        live->attachment_stopped = 1u;
        pthread_mutex_unlock(&g_audio_timer_lock);
        return M2K_OK;
    }
    if (live->attachment_type != 1u)
        return M2K_OK; // vendor switch has no default: Result stays 0
    // DSPPStopSampleAttachment (dspp_instr.c:1583-1611) returns 0 immediately
    // when the attachment is already at or below AF_STOPPED.
    if (live->attachment_stopped) return M2K_OK;
    gk_item *sample = gk_live_item(live->attachment_slave);
    if (!sample || sample->ctype != GK_AUDIO_SAMPLE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    if (live->attachment_voice < 0 && !live->attachment_delay_bound &&
        sample->sample_stream_placeholder)
        // The host stream adapters expose start/link/unlink but no abrupt
        // stop, so the vendor's dsphDisableDMA has no boundary to drive on
        // this route. Keep the refusal visible rather than reporting a stop
        // that never happened.
        return M2_AUDIO_ERR_UNIMPLEMENTED;
    pthread_mutex_lock(&g_audio_timer_lock);
    const int32_t voice = live->attachment_voice;
    live->attachment_voice = -1;
    // DisableAttachmentSignal: a completion already queued for this
    // attachment must not reach its Cue, and a linked successor must not be
    // promoted by it (audio_attachments.c:1386-1388).
    live->attachment_stopped = 1u;
    pthread_mutex_unlock(&g_audio_timer_lock);
    if (voice >= 0 && voice < 32) {
        // Another car may have reused the same slot for the same sample.
        // Match the attachment as well before sending the stop.
        const uint32_t owner = m2_host_audio_voice_attachment((uint32_t)voice);
        if ((owner == attachment || owner == UINT32_MAX) &&
            m2_host_audio_voice_sample((uint32_t)voice) == sample->host_sample_id) {
            (void)m2_host_audio_stop_voice((uint32_t)voice);
            const uint32_t bit = 1u << (uint32_t)voice;
            if (master->audio_voice_mask & bit) master->audio_voice_mask &= ~bit;
        }
    }
    // dsphDisableDMA + ClearDelayLineIfStopped for a bound physical FIFO.
    gk_unbind_delay_attachment(live);
    return M2K_OK;
}

// Attachment completion signals are generated by the host playback adapters,
// then consumed at the guest frame boundary so the guest task and its
// ssplProcessSignals/SpoolBufCompletionFunc path remain authoritative. CBD2
// segments and uploaded PCM voices share the host queue and therefore the
// drain below covers both route-specific platform adapters; raw DSPP DMA
// completions arrive through the shared-space poll queue in the second
// branch.
static void gk_pump_attachment_completions(void) {
    if (!gk_bound()) return;
    uint32_t attachment = 0;
    while (m2_host_audio_pop_attachment_completion(&attachment)) {
        uint32_t owner = M2K_ITEM_NONE;
        uint32_t signal_mask = 0;
        uint32_t terminal_stop = 0;
        pthread_mutex_lock(&g_audio_timer_lock);
        gk_item *a = gk_live_item(attachment);
        // DisableAttachmentSignal (dspp_instr.c:1602): an attachment stopped
        // before its DMA completion is drained never signals its Cue and never
        // promotes a linked successor. The event is consumed and dropped here
        // rather than left for a later pass, so the suppression is immediate.
        if (a && a->ctype == GK_AUDIO_ATTACHMENT_CTYPE && a->attachment_stopped) {
            pthread_mutex_unlock(&g_audio_timer_lock);
            continue;
        }
        if (a && a->ctype == GK_AUDIO_ATTACHMENT_CTYPE) {
            // The host PCM/CBD2 adapters are this bridge's DMA completion
            // source for uploaded samples and spooled byte streams, so
            // ProcessAttachmentDMA's terminal branch applies on this route
            // too: a FATLADYSINGS attachment stops its owning instrument
            // first, and a failed stop returns before SignalMonitoringCue.
            // Resolve the owner under the timer lock (graph -> timer order)
            // and perform the stop after releasing it.
            if ((a->attachment_flags &
                 M2_AUDIO_ATTACHMENT_FLAG_FATLADYSINGS) != 0u)
                terminal_stop = a->attachment_master;
            if (a->attachment_cue != 0u) {
                gk_item *cue = gk_live_item(a->attachment_cue);
                if (cue && cue->ctype == GK_AUDIO_CUE_CTYPE) {
                    owner = cue->cue_owner;
                    signal_mask = cue->cue_signal_mask;
                }
            }
        }
        pthread_mutex_unlock(&g_audio_timer_lock);
        if (terminal_stop != 0u &&
            m2_guest_audio_stop_instrument(g_gk.cpu, terminal_stop, 0u) < 0)
            continue;
        if (owner != M2K_ITEM_NONE && signal_mask != 0u)
            (void)m2k_send_signal(g_gk.kctx, owner,
                                  __builtin_ctz(signal_mask));
    }
    // ---- Physical/numeric DSPP DMA completion -> Cue delivery --------------
    // Vendor ground: folios/audio/audio_attachments.c ProcessAttachmentDMA
    // signals the monitored Cue when the final segment completes. Physical
    // finite delay-line attachments now record that edge against their exact
    // attachment identity; numeric descriptors retain the older bounded
    // channel-map compatibility path. Numeric events are delivered at this
    // frame boundary through attachment_cue -> Cue owner/signal_mask ->
    // m2k_send_signal. Physical delay attachments take the standard
    // DMANext/FIRQ/audio-daemon route below; their parallel low-level poll
    // record is drained as a stale compatibility record so it cannot signal a
    // Cue twice. The queue is per DSPP addressable space (shared across every
    // live sim like all DMA state), so it is drained once through the first
    // live instrument sim. Stale/unattached events are dropped.
    {
        dspp_sim *poll_sim = NULL;
        for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
            gk_item *inst = &g_gk.items[i];
            if (inst->used && inst->ctype == GK_AUDIO_INSTRUMENT_CTYPE &&
                inst->audio_dsp_sim) {
                poll_sim = (dspp_sim *)inst->audio_dsp_sim;
                break;
            }
            if (inst->used && inst->ctype == GK_AUDIO_INSTRUMENT_CTYPE &&
                inst->audio_patch_graph) {
                for (uint32_t b = 0;
                     b < inst->audio_patch_graph->block_count; ++b) {
                    if (inst->audio_patch_graph->block_sims[b]) {
                        poll_sim = inst->audio_patch_graph->block_sims[b];
                        break;
                    }
                }
                if (poll_sim) break;
            }
        }
        if (poll_sim != NULL) {
            uint32_t channel = 0;
            while (dspp_sim_dma_poll_completion(poll_sim, &channel)) {
                if (channel >= 32u /* DSPI_NUM_DMA_CHANNELS */)
                    continue; // loader never emits; defensive, never deliver
                const int physical =
                    dspp_sim_dma_delay_line_attached(poll_sim, channel);
                if (!physical &&
                    !dspp_sim_dma_numeric_attached(poll_sim, channel))
                    continue; // stale bind (owner deleted); drop silently
                if (physical)
                    continue; // physical delivery is the FIRQ/daemon event
                uint32_t matched[GK_MAX_ITEMS];
                uint32_t n_matched = 0;
                uint32_t physical_attachment = M2K_ITEM_NONE;
                pthread_mutex_lock(&g_audio_timer_lock);
                for (uint32_t k = 0; k < GK_MAX_ITEMS; ++k) {
                    gk_item *a = &g_gk.items[k];
                    if (!a->used || a->ctype != GK_AUDIO_ATTACHMENT_CTYPE)
                        continue;
                    gk_item *master = gk_live_item(a->attachment_master);
                    if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
                        continue;
                    if (physical) {
                        // A physical FIFO has one live delay binding. Match
                        // the exact owner/channel recorded at bind time;
                        // do not broadcast a delay completion to every
                        // attachment whose hook happens to resolve alike.
                        if (!a->attachment_delay_bound ||
                            a->attachment_delay_channel != channel ||
                            a->attachment_delay_sim != poll_sim)
                            continue;
                        if (physical_attachment == M2K_ITEM_NONE)
                            physical_attachment = gk_make_handle(
                                GK_TYPE_ITEM_VA, k, a->generation);
                        if (a->attachment_cue == 0u)
                            continue;
                    } else {
                        if (!master->audio_dsp_sim) continue;
                        if (a->attachment_cue == 0u)
                            continue;
                        const char *hook_arg = a->attachment_has_hook
                            ? a->attachment_hook
                            : NULL;
                        uint32_t ach = 0;
                        if (gk_resolve_fifo_channel(
                                (dspp_sim *)master->audio_dsp_sim, hook_arg,
                                &ach, NULL) != M2K_OK)
                            continue;
                        if (ach != channel) continue;
                    }
                    matched[n_matched++] =
                        gk_make_handle(GK_TYPE_ITEM_VA, k, a->generation);
                }
                pthread_mutex_unlock(&g_audio_timer_lock);
                for (uint32_t m = 0; m < n_matched; ++m) {
                    uint32_t owner = M2K_ITEM_NONE;
                    uint32_t signal_mask = 0;
                    pthread_mutex_lock(&g_audio_timer_lock);
                    gk_item *a = gk_live_item(matched[m]);
                    if (a && a->ctype == GK_AUDIO_ATTACHMENT_CTYPE &&
                        a->attachment_cue != 0u) {
                        gk_item *cue = gk_live_item(a->attachment_cue);
                        if (cue && cue->ctype == GK_AUDIO_CUE_CTYPE) {
                            owner = cue->cue_owner;
                            signal_mask = cue->cue_signal_mask;
                        }
                    }
                    pthread_mutex_unlock(&g_audio_timer_lock);
                    if (owner != M2K_ITEM_NONE && signal_mask != 0u)
                        (void)m2k_send_signal(g_gk.kctx, owner,
                                              __builtin_ctz(signal_mask));
                }
                if (physical_attachment != M2K_ITEM_NONE) {
                    gk_item *completed = gk_live_item(physical_attachment);
                    gk_promote_delay_attachment(completed);
                }
            }
        }
        // A finite unlinked physical attachment may have had resident FIFO
        // words when its completion Cue was delivered. Release the channel
        // only after those words drain; linked attachments were promoted
        // above and therefore no longer satisfy this cleanup predicate.
        gk_cleanup_finished_delay_attachments();
    }
}

// ---- Audio daemon frame-boundary service -----------------------------------
// Vendor audio_folio.c RunAudioDaemon: WaitSignal(timer|trigger|dma), then
// HandleDMASignal -> HandleTimerSignal -> HandleTriggerSignal. The host runs
// the same handlers synchronously: the trigger half immediately after the
// FIRQ (gk_audio_handle_trigger_signal), the DMA/timer halves here.
// HandleDMASignal's dsphGetCompletedDMAChannels reads and clears
// af_ChannelsComplete with the DSPP interrupt disabled; the host drains the
// mask the FIRQ accumulated. Physical finite delay attachments resolve their
// exact channel owner here, promote a linked successor, and signal its Cue;
// numeric descriptors remain on the separate consumed-record pump seam.
static void gk_audio_daemon_dma_signal(void) {
    if (!(g_gk.audio_daemon_signals & GK_AUDIO_DAEMON_DMA)) return;
    uint32_t channels = g_gk.audio_dma_completed;
    g_gk.audio_dma_completed = 0;
    g_gk.audio_daemon_signals &= ~GK_AUDIO_DAEMON_DMA;
    // HandleDMASignal uses the DMA control's AttachmentItem to identify the
    // attachment that just finished. The host physical delay channel keeps
    // the same ownership in the live attachment record; resolve it before
    // promoting a successor so current/next and Cue ordering match
    // ProcessAttachmentDMA.
    for (uint32_t channel = 0; channel < 32u; ++channel) {
        if ((channels & (1u << channel)) == 0u) continue;
        gk_item *completed = NULL;
        for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
            gk_item *candidate = &g_gk.items[i];
            if (!candidate->used ||
                candidate->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
                !candidate->attachment_delay_bound ||
                candidate->attachment_delay_channel != channel ||
                !candidate->attachment_delay_sim)
                continue;
            gk_item *master = gk_live_item(candidate->attachment_master);
            if (!master || master->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
                continue;
            completed = candidate;
            break;
        }
        if (!completed) continue; // numeric descriptor: queue seam owns it

        uint32_t owner = M2K_ITEM_NONE;
        uint32_t signal_mask = 0u;
        const uint32_t instrument = completed->attachment_master;
        const int stop_instrument =
            (completed->attachment_flags &
             M2_AUDIO_ATTACHMENT_FLAG_FATLADYSINGS) != 0u;
        pthread_mutex_lock(&g_audio_timer_lock);
        if (completed->attachment_cue != 0u) {
            gk_item *cue = gk_live_item(completed->attachment_cue);
            if (cue && cue->ctype == GK_AUDIO_CUE_CTYPE) {
                owner = cue->cue_owner;
                signal_mask = cue->cue_signal_mask;
            }
        }
        pthread_mutex_unlock(&g_audio_timer_lock);

        if (stop_instrument) {
            // Source ProcessAttachmentDMA gives FATLADYSINGS precedence
            // over a successor, calls swiStopInstrument, and returns its
            // error *before* SignalMonitoringCue. A failed terminal stop must
            // therefore not fabricate the completion Cue; a successful one
            // leaves the Cue record valid after the teardown.
            if (m2_guest_audio_stop_instrument(g_gk.cpu, instrument, 0u) < 0)
                continue;
        } else {
            gk_promote_delay_attachment(completed);
        }
        if (owner != M2K_ITEM_NONE && signal_mask != 0u)
            (void)m2k_send_signal(g_gk.kctx, owner,
                                  __builtin_ctz(signal_mask));
    }
    if (channels != 0u && gk_audio_start_diag_enabled()) {
        static uint32_t dma_signal_count;
        if (dma_signal_count < 64u) {
            ++dma_signal_count;
            fprintf(stderr, "[audio-firq] dma_ch_complete=%#x\n", channels);
        }
    }
}

// Vendor HandleTimerSignal: process every fast-list event due at the current
// sample-frame count, remove it, and run its callback (PerformCueSignal for a
// Cue event). The host keeps the same posted/trigger-time state on the Cue
// item and delivers through the task signal path. `frames` is the already
// sampled DSP frame count for this pass: a Cue posted against a custom
// AudioClock Item is due against that clock's own tick cadence
// (AudioEvent.aevt_Clock), while a global-clock Cue keeps `current_time`.
static void gk_audio_handle_timer_signal(uint32_t current_time, uint32_t frames) {
    uint32_t envelope_completed[GK_MAX_ITEMS];
    uint32_t envelope_stop[GK_MAX_ITEMS];
    uint32_t envelope_owner[GK_MAX_ITEMS];
    uint32_t envelope_signal[GK_MAX_ITEMS];
    uint32_t envelope_count = 0u;
    pthread_mutex_lock(&g_audio_timer_lock);
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *cue = &g_gk.items[i];
        if (!cue->used || cue->ctype != GK_AUDIO_CUE_CTYPE ||
            !cue->cue_posted)
            continue;
        if ((int32_t)(gk_cue_due_time_locked(cue, frames, current_time) -
                      cue->cue_trigger_time) < 0)
            continue;

        const uint32_t owner = cue->cue_owner;
        const uint32_t signal_mask = cue->cue_signal_mask;
        cue->cue_posted = 0;
        cue->cue_trigger_time = 0;

        // A host-only Cue has no source Task owner and therefore has no
        // legitimate guest recipient. Its event still completes/unposts, but
        // no compatibility broadcast is fabricated.
        if (owner != M2K_ITEM_NONE && signal_mask != 0u)
            (void)m2k_send_signal(g_gk.kctx, owner,
                                  __builtin_ctz(signal_mask));
    }

    // Vendor NextEnvSegment is the callback for an AudioEnvExtension event.
    // Remove the event before invoking the callback, then deliver the
    // attachment Cue after the callback's optional FATLADYSINGS stop. This is
    // intentionally kept separate from SignalAtAudioTime Cue processing:
    // envelope events are owned by attachments, not by caller-posted Cues.
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *attachment = &g_gk.items[i];
        if (!attachment->used ||
            attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            attachment->attachment_type != 2u ||
            !attachment->envelope_event_posted ||
            (int32_t)(current_time - attachment->envelope_event_time) < 0)
            continue;
        attachment->envelope_event_posted = 0u;
        attachment->envelope_event_time = 0u;
        const int32_t rc = gk_envelope_next_segment(attachment, current_time);
        if (rc != M2K_OK) {
            attachment->envelope_activity = 0u;
            continue;
        }
        if (attachment->envelope_activity != 0u) continue;
        if (envelope_count >= GK_MAX_ITEMS) continue;
        const uint32_t handle = gk_make_handle(
            GK_TYPE_ITEM_VA, i, attachment->generation);
        envelope_completed[envelope_count] = handle;
        envelope_stop[envelope_count] =
            (attachment->attachment_flags &
             M2_AUDIO_ATTACHMENT_FLAG_FATLADYSINGS) != 0u
                ? attachment->attachment_master
                : 0u;
        envelope_owner[envelope_count] = M2K_ITEM_NONE;
        envelope_signal[envelope_count] = 0u;
        if (attachment->attachment_cue != 0u) {
            gk_item *cue = gk_live_item(attachment->attachment_cue);
            if (cue && cue->ctype == GK_AUDIO_CUE_CTYPE) {
                envelope_owner[envelope_count] = cue->cue_owner;
                envelope_signal[envelope_count] = cue->cue_signal_mask;
            }
        }
        ++envelope_count;
    }
    pthread_mutex_unlock(&g_audio_timer_lock);

    for (uint32_t i = 0; i < envelope_count; ++i) {
        if (envelope_stop[i] != 0u &&
            m2_guest_audio_stop_instrument(g_gk.cpu, envelope_stop[i], 0u) <
                0)
            continue;
        if (envelope_owner[i] != M2K_ITEM_NONE &&
            envelope_signal[i] != 0u)
            (void)m2k_send_signal(g_gk.kctx, envelope_owner[i],
                                  __builtin_ctz(envelope_signal[i]));
        (void)envelope_completed[i];
    }
}

// Bounded audio-pump phase attribution (M2_FRAME_TIMING, diagnostic only).
// The per-iteration `audio_ms` in the host's `[frame-timing]` line is a single
// opaque number; this splits the pump into the phases that can each be moved or
// cached independently (MPEG completions, attachment completions, DSPP output,
// clock, DMA daemon, timer/FIRQ) so the next optimization is attributable
// instead of guessed. A monotonic clock comparable to the host's frame-timing
// log keeps the phase deltas summing to `audio_ms`.
//
// `GK_AUDIO_TIMING_MARK` advances a running mark and credits the elapsed time
// to the phase accumulator it is passed; it is a no-op unless timing is on, so
// production pacing is untouched.
static uint64_t gk_audio_timing_now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}
static int gk_audio_timing_enabled(void) {
    static int checked = 0, enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_FRAME_TIMING");
        enabled = e != NULL;
        checked = 1;
    }
    return enabled;
}
#define GK_AUDIO_TIMING_MARK(acc, mark)                                        \
    do {                                                                      \
        if (audio_timing) {                                                   \
            const uint64_t _gk_ns = gk_audio_timing_now_ns();                 \
            (acc) += _gk_ns - (mark);                                         \
            (mark) = _gk_ns;                                                  \
        }                                                                     \
    } while (0)

// Host frame hook for the recovered timer delivery prefix. The original DSP
// timer interrupt compares sample-frame time, removes due AudioEvents, and
// calls PerformCueSignal. This bounded equivalent uses the same published
// rendered-frame counter already exposed by GetAudioTime, with a 60 Hz host
// boundary clock when no mixer has published frames yet.
void m2_guest_audio_pump_timers_for_tick(int advance_idle_clock) {
    if (!gk_bound()) return;
    m2_guest_audio_graph_lock();
    const int audio_timing = gk_audio_timing_enabled();
    uint64_t at_mpeg_ns = 0, at_attach_ns = 0, at_dspp_ns = 0;
    uint64_t at_clock_ns = 0, at_dma_ns = 0, at_timer_ns = 0;
    const uint64_t at_start = audio_timing ? gk_audio_timing_now_ns() : 0;
    uint64_t at_mark = at_start;
    gk_mpeg_complete_ready_writes();
    gk_mpeg_complete_ready_reads();
    GK_AUDIO_TIMING_MARK(at_mpeg_ns, at_mark);
    gk_pump_attachment_completions();
    GK_AUDIO_TIMING_MARK(at_attach_ns, at_mark);
    // Tick started DSPP-backed instruments at the mixer's published 44.1 kHz
    // cadence and push their summed outputs into the SDL stream (deficit
    // since the last pump, bounded catch-up; observation-only without a
    // mixer). Sample/CBD2 voices mix on their own paths.
    if (!m2_guest_audio_async_dspp_enabled())
        m2_guest_audio_pump_dspp_output();
    GK_AUDIO_TIMING_MARK(at_dspp_ns, at_mark);
    const uint32_t rendered_frames = m2_host_audio_frame_count();
    const uint64_t clock_frames =
        gk_audio_clock_read(rendered_frames, advance_idle_clock != 0);
    const uint32_t current_time =
        (uint32_t)(clock_frames / GK_AUDIO_GLOBAL_CLOCK_DURATION);
    gk_log_audio_clock(g_gk.cpu, "pump", (uint32_t)clock_frames,
                       current_time);
    GK_AUDIO_TIMING_MARK(at_clock_ns, at_mark);
    gk_audio_daemon_dma_signal(); // HandleDMASignal
    GK_AUDIO_TIMING_MARK(at_dma_ns, at_mark);

    // Vendor timer wake: ScheduleNextAudioTimerSignal programs the DSP
    // Wakeup frame to the next event's time, and dspsCheckTimerInterrupt
    // raises DSPX_F_INT_TIMER once AudioTime reaches it. Raise here when an
    // event is actually due, then run the FIRQ pass so the register bank
    // observes the same raise/clear pair before the daemon processes.
    uint32_t due = 0;
    pthread_mutex_lock(&g_audio_timer_lock);
    for (uint32_t i = 0; i < GK_MAX_ITEMS && !due; ++i) {
        gk_item *item = &g_gk.items[i];
        if (!item->used) continue;
        if (item->ctype == GK_AUDIO_CUE_CTYPE && item->cue_posted &&
            (int32_t)(gk_cue_due_time_locked(item, (uint32_t)clock_frames,
                                            current_time) -
                      item->cue_trigger_time) >= 0)
            due = 1;
        if (item->ctype == GK_AUDIO_ATTACHMENT_CTYPE &&
            item->attachment_type == 2u && item->envelope_event_posted &&
            (int32_t)(current_time - item->envelope_event_time) >= 0)
            due = 1;
    }
    pthread_mutex_unlock(&g_audio_timer_lock);
    if (due) {
        dspp_sim *sim = gk_any_started_dsp_sim();
        if (sim) {
            // Vendor dspp_timer.c dsppSetWakeupFrame: clear the timer
            // interrupt, program the wakeup, then enable the timer bit. The
            // host derives the wake from the due-event scan, so only the
            // clear/enable pair applies before the FIRQ pass.
            dspp_sim_dma_raise_timer_interrupt(sim);
            dspp_sim_dma_register_write(sim, GK_DSPX_INTERRUPT_ENABLE,
                                        DSPP_MAIN_INT_TIMER);
            gk_audio_firq_dispatch(); // dsphHandleTimer clear + daemon wake
        }
    }
    gk_audio_handle_timer_signal(current_time,
                                 (uint32_t)clock_frames); // HandleTimerSignal
    g_gk.audio_daemon_signals &= ~GK_AUDIO_DAEMON_TIMER;
    GK_AUDIO_TIMING_MARK(at_timer_ns, at_mark);

    if (audio_timing) {
        static uint32_t audio_timing_lines = 0;
        if (audio_timing_lines < 2400u) {
            const uint64_t at_total_ns = gk_audio_timing_now_ns() - at_start;
            fprintf(stderr,
                    "[audio-timing] n=%u mpeg_ms=%.2f attach_ms=%.2f "
                    "dspp_ms=%.2f clock_ms=%.2f dma_ms=%.2f "
                    "timer_ms=%.2f total_ms=%.2f rendered=%u\n",
                    audio_timing_lines, at_mpeg_ns / 1e6,
                    at_attach_ns / 1e6, at_dspp_ns / 1e6, at_clock_ns / 1e6,
                    at_dma_ns / 1e6, at_timer_ns / 1e6, at_total_ns / 1e6,
                    rendered_frames);
            ++audio_timing_lines;
        }
    }
    m2_guest_audio_graph_unlock();
}

void m2_guest_audio_pump_timers(void) {
    // Standalone callers invoke this hook once per explicit emulated tick.
    // The interactive host supplies its field decision through the variant
    // above so extra monitor-refresh iterations cannot accelerate silence.
    m2_guest_audio_pump_timers_for_tick(1);
}

// Recovered attachment callers pass bounded guest tag lists. The live
// sound-3D path uses AF_TAG_NAME/AF_TAG_AUTO_DELETE_SLAVE, while the sound
// spooler uses AF_TAG_SET_FLAGS/AF_ATTF_NOAUTOSTART. Validate those exact
// source-backed forms; other attachment creation tags remain fail-closed
// until their call shape is recovered. The AF_TAG_NAME hook is additionally
// retained (vendor aatt_HookName) so the completion pump can map a DMA
// channel back to its attachments; acceptance is unchanged (overlong hooks
// still fail closed, value 0 keeps the vendor NULL default).
static int32_t gk_parse_attachment_taglist(uint32_t taglist_ea,
                                           uint32_t *flags_out,
                                           char hook_out[GK_MAX_NAME_LEN],
                                           uint8_t *has_hook_out,
                                           int32_t *start_at_out) {
    if (flags_out) *flags_out = 0;
    if (hook_out) hook_out[0] = '\0';
    if (has_hook_out) *has_hook_out = 0;
    if (start_at_out) *start_at_out = 0;
    if (taglist_ea == 0) return M2K_OK;
    if (!gk_bound() || !g_gk.cpu || !g_gk.cpu->mem ||
        taglist_ea >= RECOMP_GUEST_MEM)
        return M2_AUDIO_ERR_BAD_PTR;

    uint32_t flags = 0;
    for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
        const uint32_t offset = i * 8u;
        if (offset > RECOMP_GUEST_MEM - taglist_ea ||
            RECOMP_GUEST_MEM - taglist_ea - offset < 8u)
            return M2_AUDIO_ERR_BAD_PTR;
        const uint32_t ea = taglist_ea + offset;
        const uint32_t tag = rd32(g_gk.cpu, ea);
        const uint32_t value = rd32(g_gk.cpu, ea + 4u);
        if (tag == M2_TAG_END) {
            if (flags_out) *flags_out = flags;
            return M2K_OK;
        }
        if (tag == M2_AUDIO_TAG_SET_FLAGS) {
            if (value & ~M2_AUDIO_ATTACHMENT_FLAGS_LEGAL)
                return M2_AUDIO_ERR_BAD_TAG_VALUE;
            flags |= value;
            continue;
        }
        if (tag == M2_AUDIO_TAG_START_AT) {
            if ((int32_t)value < 0)
                return M2_AUDIO_ERR_BAD_TAG_VALUE;
            if (start_at_out) *start_at_out = (int32_t)value;
            continue;
        }
        if (tag == M2_AUDIO_TAG_NAME) {
            if (value != 0) {
                char hook_name[GK_MAX_NAME_LEN];
                if (m2m_copy_guest_string_ctx(g_gk.cpu, value, hook_name,
                                               sizeof(hook_name)) < 0)
                    return M2_AUDIO_ERR_BAD_PTR;
                if (hook_out) memcpy(hook_out, hook_name, sizeof(hook_name));
                if (has_hook_out) *has_hook_out = 1;
            }
            continue;
        }
        if (tag == M2_AUDIO_TAG_AUTO_DELETE_SLAVE)
            continue;
        return M2_AUDIO_ERR_BAD_TAG;
    }
    return M2_AUDIO_ERR_BAD_TAG;
}

// ---- CreateSample (.imsasound) bridge --------------------------------------
// Authentic path:
// imsasound_loadfile@0x2c6cc reads the file via filesystem selectors,
// imsasound_buffertosample@0x2c7c0 patches AF_TAG_ADDRESS to buffer+0x60,
// CreateSample@0x7396c calls kernel CreateItem(0x404 SAMPLE, taglist EA).
// The header is 12 TagArgs (0x60 bytes); AF_TAG_NUMBYTES is the exact payload
// length. Supported uploads use DecodeSQXD() from the original M2 DSP
// simulator: clear the low mode bit before signed square expansion, use the
// expanded value directly for even bytes or a quarter-scale predictor delta
// for odd bytes, and wrap the result to 16 bits per channel.
// Unknown compression/width/channel combos retain ADDRESS/NUMBYTES metadata
// but leave host_sample_id=0 (no fabricated audio). OOB addresses fail item
// creation. Headless/no-backend uploads also leave host_sample_id=0; the item
// and metadata remain valid so StartAttachment stays at its UNIMPLEMENTED
// boundary instead of cascading BAD_ITEM.
static int gk_sample_diag_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        const char *e = getenv("M2_AUDIO_SAMPLE_DIAG");
        enabled = e && *e && *e != '0';
        checked = 1;
    }
    return enabled;
}

static void gk_log_sample(const char *outcome, uint32_t item,
                          uint32_t comp_type, uint32_t channels,
                          uint32_t num_bytes, uint32_t frames,
                          uint32_t sid) {
    static uint32_t count = 0;
    if (!gk_sample_diag_enabled() || count >= 32u) return;
    ++count;
    fprintf(stderr,
            "[audio-sample] n=%u item=%#x outcome=%s comp=%#x ch=%u "
            "bytes=%u frames=%u sid=%u\n",
            count, item, outcome, comp_type, channels,
            num_bytes, frames, sid);
}

static void gk_log_sample_tag_window(PPCContext *cpu, uint32_t item,
                                     uint32_t taglist_ea) {
    static uint32_t count = 0;
    if (!gk_sample_diag_enabled() || count >= 32u) return;
    ++count;
    fprintf(stderr, "[audio-sample-tags] n=%u item=%#x list=%#x",
            count, item, taglist_ea);
    if (taglist_ea == 0u) {
        fprintf(stderr, " NULL\n");
        return;
    }
    if (!cpu || !cpu->mem || taglist_ea > RECOMP_GUEST_MEM - 8u) {
        fprintf(stderr, " OOB\n");
        return;
    }
    for (uint32_t i = 0; i < 12u; ++i) {
        const uint32_t ea = taglist_ea + i * 8u;
        if (ea > RECOMP_GUEST_MEM - 8u) {
            fprintf(stderr, " OOB");
            break;
        }
        const uint32_t tag = rd32(cpu, ea);
        const uint32_t value = rd32(cpu, ea + 4u);
        fprintf(stderr, " (%#x,%#x)", tag, value);
        if (tag == M2_TAG_END) break;
    }
    fprintf(stderr, "\n");
}

// Decode/upload one validated sample payload. Returns the host sample id
// (0 = no backend or unsupported, never a fabricated playable id). Sets
// *frames_out to the uploaded frame count on success.
static uint32_t gk_upload_sample_bytes(PPCContext *cpu, uint32_t addr,
                                       uint32_t num_bytes, uint32_t channels,
                                       uint32_t comp_type, uint32_t comp_ratio,
                                       uint32_t numbits, uint32_t *frames_out) {
    if (frames_out) *frames_out = 0;
    if (!cpu || !cpu->mem) return 0;
    if (addr >= RECOMP_GUEST_MEM || num_bytes == 0 ||
        num_bytes > RECOMP_GUEST_MEM - addr)
        return 0;
    if (channels != 1u && channels != 2u) return 0;

    if (comp_type == 0u) {
        // Vendor dspsServiceInputFDMA expands signed int8 by 8 bits; use
        // multiplication to avoid C's undefined negative left shift. The
        // original shooter M2_SetupInst converts unsigned S3M bytes first.
        if (numbits != 8u && numbits != 16u) return 0;
        const uint32_t width = numbits / 8u;
        const uint32_t frame_bytes = channels * width;
        if (num_bytes % frame_bytes != 0u) return 0;
        const uint32_t frames = num_bytes / frame_bytes;
        if (frames == 0u || frames > (16u << 20)) return 0;
        const size_t out_words = (size_t)frames * 2u;
        int16_t *pcm = (int16_t *)malloc(out_words * sizeof(int16_t));
        if (!pcm) return 0;
        for (uint32_t f = 0; f < frames; ++f) {
            for (uint32_t ch = 0; ch < 2u; ++ch) {
                const uint32_t source = addr + f * frame_bytes +
                                        (channels == 1u ? 0u : ch * width);
                const uint32_t byte = rd8(cpu, source);
                pcm[f * 2u + ch] = width == 1u
                    ? (int16_t)((byte < 128u ? (int32_t)byte : (int32_t)byte - 256) * 256)
                    : (int16_t)rd16(cpu, source);
            }
        }
        const uint32_t sid = m2_host_audio_add_sample(pcm, frames);
        free(pcm);
        if (sid != 0u && frames_out) *frames_out = frames;
        return sid;
    }

    if (comp_type == M2_AUDIO_COMPRESSION_SQS2) {
        if (numbits != 16u || comp_ratio != 2u) return 0;
        const uint32_t usable = num_bytes - (num_bytes % channels);
        if (usable == 0u) return 0;
        // One byte -> one s16; stereo pairs interleave L,R.
        const uint32_t samples = usable;
        if (samples > (16u << 20)) return 0;
        const uint32_t frames = (channels == 1u) ? samples : samples / 2u;
        if (frames == 0u) return 0;
        int16_t *decoded = (int16_t *)malloc((size_t)samples * sizeof(int16_t));
        if (!decoded) return 0;
        uint32_t pred[2] = {0, 0};
        for (uint32_t i = 0; i < usable; ++i) {
            const uint32_t ch = (channels == 1u) ? 0u : (i % 2u);
            const uint32_t coded = rd8(cpu, addr + i);
            int32_t magnitude = (int32_t)(coded & 0xfeu);
            if (magnitude >= 128) magnitude -= 256;
            const int32_t expanded = magnitude *
                                     ((magnitude < 0) ? -magnitude : magnitude) *
                                     2;
            const int32_t output = (coded & 1u)
                ? (int32_t)pred[ch] + (expanded / 4)
                : expanded;
            pred[ch] = (uint32_t)output & 0xffffu;
            decoded[i] = (int16_t)pred[ch];
        }
        uint32_t sid = 0;
        if (channels == 1u) {
            const size_t out_words = (size_t)frames * 2u;
            int16_t *pcm = (int16_t *)malloc(out_words * sizeof(int16_t));
            if (pcm) {
                for (uint32_t i = 0; i < frames; ++i) {
                    pcm[i * 2u] = decoded[i];
                    pcm[i * 2u + 1u] = decoded[i];
                }
                sid = m2_host_audio_add_sample(pcm, frames);
                free(pcm);
            }
        } else {
            sid = m2_host_audio_add_sample(decoded, frames);
        }
        free(decoded);
        if (sid != 0u && frames_out) *frames_out = frames;
        return sid;
    }

    return 0;
}

// Parsed CreateSample fields with .imsasound defaults (mono PCM).
typedef struct gk_sample_fields {
    uint32_t addr;
    uint32_t num_bytes;
    uint32_t width;
    uint32_t channels;
    uint32_t comp_ratio;
    uint32_t comp_type;
    uint32_t numbits;
    float sample_rate;
    int32_t sustain_begin;
    int32_t sustain_end;
    int32_t release_begin;
    int32_t release_end;
    uint32_t delay_kind;       // 1 = delay line, 2 = delay-line template
    uint32_t delay_num_bytes;  // AF_TAG_DELAY_LINE(_TEMPLATE) value
    uint32_t sample_flags;     // AF_SAMPF_* after SET/CLEAR_FLAGS
    uint8_t low_note;          // AF_TAG_LOWNOTE
    uint8_t high_note;         // AF_TAG_HIGHNOTE
    uint8_t low_velocity;      // AF_TAG_LOWVELOCITY
    uint8_t high_velocity;     // AF_TAG_HIGHVELOCITY
    int has_addr;
    int has_num_bytes;
    int has_width;
} gk_sample_fields;

static void gk_sample_fields_init(gk_sample_fields *f) {
    f->addr = 0;
    f->num_bytes = 0;
    f->width = 0;
    f->channels = 1u;
    f->comp_ratio = 1u;
    f->comp_type = 0u;
    f->numbits = 16u;
    f->sample_rate = 44100.0f;
    f->sustain_begin = -1;
    f->sustain_end = -1;
    f->release_begin = -1;
    f->release_end = -1;
    f->low_note = 0;
    f->high_note = 127;
    f->low_velocity = 0;
    f->high_velocity = 127;
    f->delay_kind = 0;
    f->delay_num_bytes = 0;
    f->sample_flags = 0;
    f->has_addr = 0;
    f->has_num_bytes = 0;
    f->has_width = 0;
}

// Returns 1 if the tag belongs to the authentic CreateSample header (or the
// generic TAG_ITEM_NAME), 0 for anything else. Loop/rate/legacy tags are
// accepted without affecting the upload.
static int gk_sample_tag_known(uint32_t tag) {
    switch (tag) {
    case 1u: // TAG_ITEM_NAME
    case M2_AUDIO_TAG_WIDTH:
    case M2_AUDIO_TAG_ADDRESS:
    case M2_AUDIO_TAG_NUMBYTES:
    case M2_AUDIO_TAG_CHANNELS:
    case M2_AUDIO_TAG_COMPRESSIONRATIO:
    case M2_AUDIO_TAG_COMPRESSIONTYPE:
    case M2_AUDIO_TAG_NUMBITS:
    case M2_AUDIO_TAG_SAMPLE_RATE_FP:
    case M2_AUDIO_TAG_LEGACY_0x50:
    case M2_AUDIO_TAG_SUSTAINBEGIN:
    case M2_AUDIO_TAG_SUSTAINEND:
    case M2_AUDIO_TAG_RELEASEBEGIN:
    case M2_AUDIO_TAG_RELEASEEND:
    case M2_AUDIO_TAG_LOWNOTE:
    case M2_AUDIO_TAG_HIGHNOTE:
    case M2_AUDIO_TAG_LOWVELOCITY:
    case M2_AUDIO_TAG_HIGHVELOCITY:
    case M2_AUDIO_TAG_SET_FLAGS:
    case M2_AUDIO_TAG_CLEAR_FLAGS:
    case M2_AUDIO_TAG_DELAY_LINE_TEMPLATE:
    case M2_AUDIO_TAG_DELAY_LINE:
        return 1;
    default:
        return 0;
    }
}

static void gk_sample_field_apply(gk_sample_fields *f, uint32_t tag,
                                  uint32_t val) {
    switch (tag) {
    case M2_AUDIO_TAG_WIDTH:
        f->width = val;
        f->numbits = val * 8u;
        f->has_width = 1;
        break;
    case M2_AUDIO_TAG_ADDRESS:
        f->addr = val;
        f->has_addr = 1;
        break;
    case M2_AUDIO_TAG_NUMBYTES:
        f->num_bytes = val;
        f->has_num_bytes = 1;
        break;
    case M2_AUDIO_TAG_CHANNELS:
        f->channels = val;
        break;
    case M2_AUDIO_TAG_COMPRESSIONRATIO:
        f->comp_ratio = val;
        break;
    case M2_AUDIO_TAG_COMPRESSIONTYPE:
        f->comp_type = val;
        break;
    case M2_AUDIO_TAG_NUMBITS:
        f->numbits = val;
        f->width = (val + 7u) / 8u;
        break;
    case M2_AUDIO_TAG_SAMPLE_RATE_FP:
        memcpy(&f->sample_rate, &val, sizeof(f->sample_rate));
        break;
    case M2_AUDIO_TAG_SUSTAINBEGIN:
        f->sustain_begin = (int32_t)val;
        break;
    case M2_AUDIO_TAG_SUSTAINEND:
        f->sustain_end = (int32_t)val;
        break;
    case M2_AUDIO_TAG_RELEASEBEGIN:
        f->release_begin = (int32_t)val;
        break;
    case M2_AUDIO_TAG_RELEASEEND:
        f->release_end = (int32_t)val;
        break;
    case M2_AUDIO_TAG_LOWNOTE:
        f->low_note = (uint8_t)(val > 127 ? 127 : val);
        break;
    case M2_AUDIO_TAG_HIGHNOTE:
        f->high_note = (uint8_t)(val > 127 ? 127 : val);
        break;
    case M2_AUDIO_TAG_LOWVELOCITY:
        f->low_velocity = (uint8_t)(val > 127 ? 127 : val);
        break;
    case M2_AUDIO_TAG_HIGHVELOCITY:
        f->high_velocity = (uint8_t)(val > 127 ? 127 : val);
        break;
    case M2_AUDIO_TAG_SET_FLAGS:
        f->sample_flags |= val;
        break;
    case M2_AUDIO_TAG_CLEAR_FLAGS:
        f->sample_flags &= ~val;
        break;
    case M2_AUDIO_TAG_DELAY_LINE_TEMPLATE:
        f->delay_kind = 2u;
        f->delay_num_bytes = val;
        break;
    case M2_AUDIO_TAG_DELAY_LINE:
        f->delay_kind = 1u;
        f->delay_num_bytes = val;
        break;
    default:
        break;
    }
}

// Configure a freshly minted sample item from parsed fields. Always retains
// ADDRESS/NUMBYTES when present and range-valid; uploads only supported
// combos. Returns 0 on success, -1 when the address range is OOB (caller
// deletes the item and returns ITEM_NONE).
static int gk_configure_sample_item(PPCContext *cpu, gk_item *live,
                                    uint32_t item_handle,
                                    const gk_sample_fields *f,
                                    int has_unknown_tag) {
    if (!live || !f) return 0;
    if (!(f->sample_rate >= 10.0f && f->sample_rate <= 1000000.0f))
        return -1;
    live->sample_sustain_begin = f->sustain_begin;
    live->sample_sustain_end = f->sustain_end;
    live->sample_release_begin = f->release_begin;
    live->sample_release_end = f->release_end;
    live->sample_low_note = f->low_note;
    live->sample_high_note = f->high_note;
    live->sample_low_velocity = f->low_velocity;
    live->sample_high_velocity = f->high_velocity;
    live->sample_rate = f->sample_rate;
    live->sample_channels = f->channels;
    live->sample_bits = f->numbits;
    live->sample_compression = f->comp_type;
    live->sample_compression_ratio = f->comp_ratio;
    live->sample_flags = f->sample_flags;
    live->sample_stream_placeholder = 0;

    // Delay lines are privileged Sample Items, not ordinary guest-backed PCM.
    // The Audio Folio allocates their storage from supervisor memory and the
    // DSPP attachment path consumes the Item as a FIFO buffer. Keep the exact
    // source metadata here without uploading or treating the numeric length as
    // a guest address. The source rejects ordinary data tags mixed with either
    // delay-line kind; fail closed on that conflict as well as on non-positive
    // or unreasonably large host metadata.
    if (f->delay_kind != 0u) {
        if (f->delay_num_bytes == 0u ||
            f->delay_num_bytes > (64u << 20) ||
            f->channels == 0u || f->channels > 255u ||
            (f->sample_flags & ~M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP) != 0u ||
            f->has_addr || f->has_num_bytes)
            return -1;
        live->sample_kind = (uint8_t)f->delay_kind;
        live->sample_num_bytes = f->delay_num_bytes;
        live->sample_address = 0u;
        live->host_sample_id = 0u;
        if (f->delay_kind == 1u) {
            live->sample_delay_line = dspp_delay_line_create(
                f->delay_num_bytes, f->channels, 0);
            if (!live->sample_delay_line)
                return -1;
            if (dspp_delay_line_set_sample_loops(
                    live->sample_delay_line, f->sustain_begin,
                    f->sustain_end, f->release_begin, f->release_end) != 0) {
                dspp_delay_line_destroy(live->sample_delay_line);
                live->sample_delay_line = NULL;
                return -1;
            }
            dspp_delay_line_set_clear_on_stop(
                live->sample_delay_line,
                (f->sample_flags & M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP) != 0u);
        }
        gk_log_sample(f->delay_kind == 1u ? "delay-line" :
                                              "delay-line-template",
                      item_handle, 0u, f->channels, f->delay_num_bytes, 0u,
                      0u);
        return 0;
    }
    if ((f->sample_flags & ~M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP) != 0u)
        return -1;
    if (f->sample_flags != 0u)
        return -1; // CLEARONSTOP is a privileged delay-line property
    live->sample_kind = 0u;
    if (!f->has_addr && !f->has_num_bytes) {
        live->sample_stream_placeholder =
            f->has_width && f->width == 1u;
        gk_log_sample("empty", item_handle, f->comp_type, f->channels,
                      0, 0, 0);
        return 0;
    }
    // A zero address with a nonzero length (or vice versa) is a placeholder,
    // not an uploadable payload; retain zeros without reading guest RAM.
    if (f->addr == 0u || f->num_bytes < 2u) {
        live->sample_address = 0;
        live->sample_num_bytes = 0;
        live->host_sample_id = 0;
        gk_log_sample("placeholder", item_handle, f->comp_type,
                      f->channels, f->num_bytes, 0, 0);
        return 0;
    }
    if (f->addr >= RECOMP_GUEST_MEM ||
        f->num_bytes > RECOMP_GUEST_MEM - f->addr)
        return -1;
    live->sample_address = f->addr;
    live->sample_num_bytes = f->num_bytes;
    live->host_sample_id = 0;
    if (has_unknown_tag) {
        gk_log_sample("unknown-tag", item_handle, f->comp_type,
                      f->channels, f->num_bytes, 0, 0);
        return 0;
    }
    uint32_t frames = 0;
    const uint32_t sid = gk_upload_sample_bytes(
        cpu, f->addr, f->num_bytes, f->channels, f->comp_type,
        f->comp_ratio, f->numbits, &frames);
    if (sid != 0u) {
        live->host_sample_id = sid;
        gk_log_sample("uploaded", item_handle, f->comp_type, f->channels,
                      f->num_bytes, frames, sid);
    } else if (f->comp_type != 0u &&
               f->comp_type != M2_AUDIO_COMPRESSION_SQS2) {
        gk_log_sample("unsupported-comp", item_handle, f->comp_type,
                      f->channels, f->num_bytes, 0, 0);
    } else if (f->channels != 1u && f->channels != 2u) {
        gk_log_sample("unsupported-ch", item_handle, f->comp_type,
                      f->channels, f->num_bytes, 0, 0);
    } else if (f->numbits != 16u) {
        gk_log_sample("unsupported-bits", item_handle, f->comp_type,
                      f->channels, f->num_bytes, 0, 0);
    } else {
        // Supported shape but no backend (headless/test weak stub): metadata
        // retained, audio stays silent without failing creation.
        gk_log_sample("no-backend", item_handle, f->comp_type,
                      f->channels, f->num_bytes, 0, 0);
    }
    return 0;
}

typedef struct gk_envelope_fields {
    uint32_t address;
    int32_t num_points;
    int32_t sustain_begin;
    int32_t sustain_end;
    float sustain_time;
    int32_t release_begin;
    int32_t release_end;
    float release_time;
    int32_t release_jump;
    uint32_t signal_type;
    uint32_t flags;
    uint8_t base_note;
    int8_t notes_per_double;
} gk_envelope_fields;

static int32_t gk_envelope_apply_tag(gk_envelope_fields *fields,
                                     uint32_t tag, uint32_t value) {
    if (!fields) return M2_AUDIO_ERR_BAD_PTR;
    switch (tag) {
    case 1u: // TAG_ITEM_NAME is handled by CreateItem before this helper.
    case M2_AUDIO_TAG_AUTO_DELETE_SLAVE:
        return M2K_OK;
    case M2_AUDIO_TAG_ADDRESS:
        fields->address = value;
        return M2K_OK;
    case M2_AUDIO_TAG_FRAMES:
        fields->num_points = (int32_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_TYPE:
        if (value > 5u) return M2_AUDIO_ERR_BAD_SIGNAL_TYPE;
        fields->signal_type = value;
        return M2K_OK;
    case M2_AUDIO_TAG_SUSTAINBEGIN:
        if ((int32_t)value < -1) return M2_AUDIO_ERR_OUT_OF_RANGE;
        fields->sustain_begin = (int32_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_SUSTAINEND:
        if ((int32_t)value < -1) return M2_AUDIO_ERR_OUT_OF_RANGE;
        fields->sustain_end = (int32_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_SUSTAINTIME_FP:
        memcpy(&fields->sustain_time, &value, sizeof(fields->sustain_time));
        return isfinite(fields->sustain_time) ? M2K_OK
                                              : M2_AUDIO_ERR_BAD_TAG_VALUE;
    case M2_AUDIO_TAG_RELEASEBEGIN:
        if ((int32_t)value < -1) return M2_AUDIO_ERR_OUT_OF_RANGE;
        fields->release_begin = (int32_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_RELEASEEND:
        if ((int32_t)value < -1) return M2_AUDIO_ERR_OUT_OF_RANGE;
        fields->release_end = (int32_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_RELEASETIME_FP:
        memcpy(&fields->release_time, &value, sizeof(fields->release_time));
        return isfinite(fields->release_time) ? M2K_OK
                                              : M2_AUDIO_ERR_BAD_TAG_VALUE;
    case M2_AUDIO_TAG_RELEASEJUMP:
        if ((int32_t)value < -1) return M2_AUDIO_ERR_OUT_OF_RANGE;
        fields->release_jump = (int32_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_BASENOTE:
        if (value > 127u) return M2_AUDIO_ERR_BAD_TAG_VALUE;
        fields->base_note = (uint8_t)value;
        return M2K_OK;
    case M2_AUDIO_TAG_NOTESPEROCTAVE: {
        const int32_t notes = (int32_t)value;
        if (notes < -128 || notes > 127)
            return M2_AUDIO_ERR_BAD_TAG_VALUE;
        fields->notes_per_double = (int8_t)notes;
        return M2K_OK;
    }
    case M2_AUDIO_TAG_SET_FLAGS:
        if ((value & ~M2_AUDIO_ENVELOPE_FLAGS_LEGAL) != 0u)
            return M2_AUDIO_ERR_BAD_TAG_VALUE;
        fields->flags |= value;
        return M2K_OK;
    case M2_AUDIO_TAG_CLEAR_FLAGS:
        if ((value & ~M2_AUDIO_ENVELOPE_FLAGS_LEGAL) != 0u)
            return M2_AUDIO_ERR_BAD_TAG_VALUE;
        fields->flags &= ~value;
        return M2K_OK;
    default:
        return M2_AUDIO_ERR_BAD_TAG;
    }
}

static int32_t gk_configure_envelope_item(PPCContext *cpu, gk_item *live,
                                           const uint32_t tags[][2],
                                           uint32_t tag_count,
                                           uint32_t taglist_ea) {
    if (!cpu || cpu->mem != g_gk.cpu->mem || !live ||
        live->ctype != GK_AUDIO_ENVELOPE_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;
    gk_envelope_fields fields = {
        .address = 0u,
        .num_points = 0,
        .sustain_begin = -1,
        .sustain_end = -1,
        .sustain_time = 0.0f,
        .release_begin = -1,
        .release_end = -1,
        .release_time = 0.0f,
        .release_jump = -1,
        .signal_type = 0u,
        .flags = 0u,
        .base_note = 0u,
        .notes_per_double = 0,
    };
    for (uint32_t i = 0; i < tag_count; ++i) {
        const uint32_t tag = tags[i][0];
        if (tag == M2_TAG_END || tag == M2_TAG_JUMP || tag == 0xFFFFFFFFu)
            continue;
        const int32_t rc = gk_envelope_apply_tag(&fields, tag, tags[i][1]);
        if (rc != M2K_OK) return rc;
    }
    if (taglist_ea != 0u) {
        uint32_t cur = taglist_ea;
        uint32_t jumps = 0u;
        for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
            if (cur > RECOMP_GUEST_MEM - 8u)
                return M2_AUDIO_ERR_BAD_PTR;
            const uint32_t tag = rd32(cpu, cur);
            const uint32_t value = rd32(cpu, cur + 4u);
            cur += 8u;
            if (tag == M2_TAG_END) break;
            if (tag == 0xFFFFFFFFu) continue;
            if (tag == M2_TAG_JUMP) {
                if (++jumps > 2u) return M2_AUDIO_ERR_BAD_TAG;
                if (value == 0u) return M2_AUDIO_ERR_BAD_PTR;
                cur = value;
                continue;
            }
            const int32_t rc = gk_envelope_apply_tag(&fields, tag, value);
            if (rc != M2K_OK) return rc;
        }
    }
    if (fields.num_points < 1 || fields.num_points > (int32_t)(RECOMP_GUEST_MEM / 8u))
        return M2_AUDIO_ERR_BAD_TAG_VALUE;
    if (fields.address == 0u ||
        (uint64_t)fields.address + (uint64_t)(uint32_t)fields.num_points * 8u >
            RECOMP_GUEST_MEM)
        return M2_AUDIO_ERR_BAD_PTR;
    if (fields.sustain_begin >= 0 &&
        (fields.sustain_end < fields.sustain_begin ||
         fields.sustain_end >= fields.num_points))
        return M2_AUDIO_ERR_BAD_TAG_VALUE;
    if (fields.release_begin >= 0 &&
        (fields.release_end < fields.release_begin ||
         fields.release_end >= fields.num_points))
        return M2_AUDIO_ERR_BAD_TAG_VALUE;
    if (fields.release_jump >= 0 &&
        fields.release_jump >= fields.num_points - 1)
        return M2_AUDIO_ERR_BAD_TAG_VALUE;

    live->envelope_address = fields.address;
    live->envelope_num_points = fields.num_points;
    live->envelope_sustain_begin = fields.sustain_begin;
    live->envelope_sustain_end = fields.sustain_end;
    live->envelope_sustain_time = fields.sustain_time;
    live->envelope_release_begin = fields.release_begin;
    live->envelope_release_end = fields.release_end;
    live->envelope_release_time = fields.release_time;
    live->envelope_release_jump = fields.release_jump;
    live->envelope_signal_type = fields.signal_type;
    live->envelope_flags = fields.flags;
    live->envelope_base_note = fields.base_note;
    live->envelope_notes_per_double = fields.notes_per_double;
    return M2K_OK;
}

static uint32_t gk_CreateItemVA(uint32_t ctype, uint32_t t1, uint32_t v1, uint32_t t2, uint32_t v2, uint32_t t3, uint32_t v3, uint32_t t4) {
    if (!gk_bound() || ctype == 0) return M2K_ITEM_NONE;
    PPCContext* call_cpu = gk_current_cpu();
    PPCContext* cpu = gk_current_memory_cpu();
    // Collect TagArg pairs from registers (r4..r10) plus stack spill at r1+8.
    // Portfolio CreateItemVA is Item CreateItemVA(int32 ctype, uint32 tags, ...) where tags is first tag.
    // Generated sites pass tags in r4..r10 and stack, terminated by TAG_END 0.
    // We collect up to 16 pairs bounded, validate string tags, mint distinct handle.
    // Note: dispatch passes t4 as last tag (expected TAG_END), val for t4 is on stack if needed.
    uint32_t tags[16][2];
    uint32_t tag_count = 0;
    uint32_t template_item = 0;
    uint32_t instrument_calc_rate_divider = 1u;
    uint32_t instrument_priority = 100u;
    uint32_t name_ea = 0;
    uint32_t instrument_item = 0;
    uint32_t attachment_master = 0;
    uint32_t attachment_slave = 0;
    uint32_t attachment_taglist = 0;
    int attachment_master_present = 0;
    int attachment_slave_present = 0;
    int knob_name_present = 0;
    int knob_tag_present = 0;
    int probe_name_present = 0;
    int reg_terminated = 0;
    uint32_t reg_tags[7] = {t1, v1, t2, v2, t3, v3, t4};
    for (int i = 0; i < 7 && tag_count < 16; i += 2) {
        uint32_t tag = reg_tags[i];
        uint32_t val = (i+1 < 7) ? reg_tags[i+1] : 0;
        if (i+1 >= 7) {
            // t4 is last tag, val is on stack at r1+8
            uint32_t sp = call_cpu ? call_cpu->gpr[1] : 0;
            if (sp + 8 + 4 <= RECOMP_GUEST_MEM) val = rd32(cpu, sp+8);
            else val = 0;
        }
        if (tag == M2_TAG_END) {
            reg_terminated = 1;
            break;
        }
        if (ctype == GK_AUDIO_KNOB_CTYPE || ctype == GK_AUDIO_PROBE_CTYPE) {
            if (tag == 12u /* AF_TAG_NAME */) {
                name_ea = val;
                if (ctype == GK_AUDIO_KNOB_CTYPE)
                    knob_name_present = 1;
                else
                    probe_name_present = 1;
                if (ctype == GK_AUDIO_KNOB_CTYPE)
                    knob_tag_present = 1;
            } else if (tag == 17u /* AF_TAG_INSTRUMENT */) {
                instrument_item = val;
                if (ctype == GK_AUDIO_KNOB_CTYPE)
                    knob_tag_present = 1;
            }
        }
        tags[tag_count][0] = tag;
        tags[tag_count][1] = val;
        tag_count++;
        if (tag == M2_TAG_END) {
            reg_terminated = 1;
            break;
        }
        // CreateInstrument/CreateKnob/CreateProbe use TAG_JUMP to append a caller-owned
        // TagArg list. The lifted production callers pass a NULL list, and
        // the direct tags before the jump contain the ownership-bearing
        // template/instrument Item. Do not inspect later stale registers as
        // if they were more varargs once the jump marker is reached.
        if (tag == M2_TAG_JUMP || tag == 0xFFFFFFFFu) {
            reg_terminated = 1;
            break;
        }
    }
    // Also pull from guest stack at r1+12 if TAG_END not yet seen and room remains.
    // After r10 (t4), stack at sp+8 holds v4, sp+12 holds t5, etc.
    if (!reg_terminated && tag_count < 16) {
        uint32_t sp = call_cpu ? call_cpu->gpr[1] : 0;
        for (int i = 0; i < 8 && tag_count < 16; ++i) {
            uint32_t ea = sp + 12 + (uint32_t)(i*8);
            if (ea + 8 > RECOMP_GUEST_MEM) break;
            uint32_t stag = rd32(cpu, ea);
            uint32_t sval = rd32(cpu, ea+4);
            if (stag == M2_TAG_END) break;
            // If we already have this tag in reg list, avoid duplicate, but still count.
            tags[tag_count][0] = stag;
            tags[tag_count][1] = sval;
            tag_count++;
            if (stag == M2_TAG_END) break;
            // Heuristic: if stag looks like small tag (<1000) and sval is plausible, continue.
            // Break if stag is 0xFFFFFFFF (-1) sentinel that some callers use as terminator?
            if (stag == 0xFFFFFFFFu) break;
        }
    }
    // CreateItemVA(MKNODEID(KERNELNODE, MESSAGENODE), ...) is the kernel
    // CreateMsg shape (kernel/msgport.h): CreateForwardMsg 0x65d30 uses tag 10
    // CREATEMSG_TAG_REPLYPORT. Mint a real Message item so LookupItem/ReplyMsg
    // operate on it.
    if (ctype == M2K_KERNEL_MESSAGE_CTYPE) {
        uint32_t reply_port = M2K_ITEM_NONE;
        uint32_t user_data = 0;
        for (uint32_t i = 0; i < tag_count; ++i) {
            if (tags[i][0] == M2K_TAG_IO_REPLYPORT /* == CREATEMSG_TAG_REPLYPORT */) {
                reply_port = tags[i][1];
            }
            if (tags[i][0] == 13u) // CREATEMSG_TAG_USERDATA, msgport.h
                user_data = tags[i][1];
        }
        const uint32_t message = m2k_create_msg(g_gk.kctx, reply_port);
        if (message != M2K_ITEM_NONE) {
            const uint32_t ea = gk_LookupItem(message);
            if (ea) wr32(cpu, ea + 0x3cu, user_data);
        }
        return message;
    }
    // CreateItemVA(MKNODEID(KERNELNODE, IOREQNODE), ...) is the kernel
    // CreateIOReq shape (kernel/io.h): FMVCreateIOReq mints its video
    // read/write requests with tags 11=DEVICE and 12=SIGNAL. Route those to
    // the kernel IOReq pool so DoIO/SendIO/WaitIO/DeleteItem operate on a real
    // request whose completion wakes the owner with the recorded signal
    // (SIGF_IODONE when the creator omitted the tag).
    if (ctype == M2K_KERNEL_IOREQ_CTYPE) {
        m2_tag_arg va_tags[17];
        uint32_t n = 0;
        int have_signal = 0;
        int have_replyport = 0;
        for (uint32_t i = 0; i < tag_count && n < 16u; ++i) {
            if (tags[i][0] == M2_TAG_END) break;
            va_tags[n].tag = tags[i][0];
            va_tags[n].value = tags[i][1];
            if (tags[i][0] == M2K_TAG_IO_SIGNAL) {
                have_signal = 1;
                if (va_tags[n].value == 0) va_tags[n].value = M2K_SIGF_IODONE;
            }
            if (tags[i][0] == M2K_TAG_IO_REPLYPORT && tags[i][1] > 0)
                have_replyport = 1;
            ++n;
        }
        if (!have_signal && !have_replyport && n < 16u) {
            va_tags[n].tag = M2K_TAG_IO_SIGNAL;
            va_tags[n].value = M2K_SIGF_IODONE;
            ++n;
        }
        va_tags[n].tag = M2_TAG_END;
        va_tags[n].value = 0;
        return m2k_create_ioreq_va(g_gk.kctx, va_tags, n + 1u);
    }
    // Bounded validation: ensure at least TAG_END or tag_count <16, and string tags have valid guest strings.
    for (uint32_t i = 0; i < tag_count; ++i) {
        uint32_t tag = tags[i][0];
        uint32_t val = tags[i][1];
        if (tag == 1 /* TAG_ITEM_NAME */) {
            name_ea = val;
            if (val != 0) {
                if (val + 4 > RECOMP_GUEST_MEM || !g_gk.cpu || !g_gk.cpu->mem) {
                    fprintf(stderr, "[gk] CreateItemVA fault: TAG_ITEM_NAME val=%#x OOB ctype=%#x\n", val, ctype);
                    return M2K_ITEM_NONE;
                }
                char tmp[GK_MAX_NAME_LEN];
                int32_t rc = m2m_copy_guest_string_ctx(g_gk.cpu, val, tmp, sizeof(tmp));
                if (rc == M2M_ERR_FAULT || rc < 0) {
                    fprintf(stderr, "[gk] CreateItemVA fault: TAG_ITEM_NAME val=%#x no NUL within %u ctype=%#x\n", val, (unsigned)GK_MAX_NAME_LEN, ctype);
                    return M2K_ITEM_NONE;
                }
            }
        }
        if (tag == 16u /* AF_TAG_TEMPLATE */) template_item = val;
        if (tag == 13u /* AF_TAG_MASTER */) {
            attachment_master = val;
            attachment_master_present = 1;
        }
        if (tag == 18u /* AF_TAG_SLAVE */) {
            attachment_slave = val;
            attachment_slave_present = 1;
        }
        if (tag == M2_TAG_JUMP || tag == 0xFFFFFFFFu)
            attachment_taglist = val;
        if (ctype == GK_AUDIO_INSTRUMENT_CTYPE) {
            if (tag == M2_AUDIO_TAG_CALCRATE_DIVIDE) {
                if (val != 1u && val != 2u && val != 8u)
                    return (uint32_t)M2_AUDIO_ERR_BAD_TAG_VALUE;
                instrument_calc_rate_divider = val;
            } else if (tag == M2_AUDIO_TAG_PRIORITY) {
                if (val > 200u)
                    return (uint32_t)M2_AUDIO_ERR_BAD_TAG_VALUE;
                instrument_priority = val;
            }
        }
        // For other tags that carry guest EAs (heuristic: val in guest RAM range and tag small), we could validate but skip for now.
        (void)tag; (void)val;
    }
    if (ctype == GK_AUDIO_INSTRUMENT_CTYPE) {
        gk_item *template_live = gk_live_item(template_item);
        if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE)
            return M2K_ITEM_NONE;
    }
    if (ctype == GK_AUDIO_ATTACHMENT_CTYPE) {
        uint32_t attachment_flags = 0;
        char attachment_hook[GK_MAX_NAME_LEN];
        uint8_t attachment_has_hook = 0;
        int32_t attachment_start_at = 0;
        attachment_hook[0] = '\0';
        const int32_t tag_result = gk_parse_attachment_taglist(
            attachment_taglist, &attachment_flags, attachment_hook,
            &attachment_has_hook, &attachment_start_at);
        if (tag_result < 0)
            return (uint32_t)tag_result;
        if (!attachment_master_present || !attachment_slave_present)
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
        gk_item *master = gk_live_item(attachment_master);
        if (!master || (master->ctype != GK_AUDIO_TEMPLATE_CTYPE &&
                        master->ctype != GK_AUDIO_INSTRUMENT_CTYPE))
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
        gk_item *slave = gk_live_item(attachment_slave);
        if (!slave || (slave->ctype != GK_AUDIO_SAMPLE_CTYPE &&
                       slave->ctype != GK_AUDIO_ENVELOPE_CTYPE))
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
        if (slave->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            slave->sample_kind == 1u) {
            if (!slave->sample_delay_line || slave->sample_channels == 0u)
                return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
            const uint64_t frame_count =
                (uint64_t)slave->sample_num_bytes /
                ((uint64_t)slave->sample_channels * 2u);
            if ((uint64_t)attachment_start_at >= frame_count)
                return (uint32_t)M2_AUDIO_ERR_OUT_OF_RANGE;
        }
        uint32_t attachment = gk_mint_item(
            "audio attachment", GK_AUDIO_ATTACHMENT_CTYPE, 0, tag_count, 1);
        if (attachment == M2K_ITEM_NONE)
            return (uint32_t)M2_AUDIO_ERR_NO_MEMORY;
        gk_item *live = gk_live_item(attachment);
        if (!live) {
            gk_DeleteItem(attachment);
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
        }
        live->attachment_master = attachment_master;
        live->attachment_slave = attachment_slave;
        live->attachment_next = 0;
        live->attachment_start_at = attachment_start_at;
        live->attachment_type =
            slave->ctype == GK_AUDIO_SAMPLE_CTYPE ? 1u : 2u;
        live->attachment_flags = attachment_flags;
        memcpy(live->attachment_hook, attachment_hook,
               sizeof(live->attachment_hook));
        live->attachment_has_hook = attachment_has_hook;
        live->attachment_voice = -1;
        live->attachment_stopped = 1u; // AF_STOPPED until StartAttachment
        return attachment;
    }
    if (ctype == GK_AUDIO_PROBE_CTYPE)
        return gk_create_audio_probe(instrument_item, name_ea,
                                     probe_name_present, attachment_taglist);
    if (ctype == GK_AUDIO_KNOB_CTYPE && knob_tag_present)
        return gk_create_audio_knob(instrument_item, name_ea,
                                    knob_name_present);
    uint32_t item = gk_mint_item("CreateItemVA", ctype, name_ea, tag_count, 1);
    if (item != M2K_ITEM_NONE && ctype == GK_GRAPHICS_BITMAP_CTYPE) {
        gk_item *bitmap = gk_live_item(item);
        if (!bitmap || !gk_configure_bitmap_item(bitmap, tags, tag_count)) {
            gk_DeleteItem(item);
            return M2K_ITEM_NONE;
        }
    }
    if (item != M2K_ITEM_NONE && ctype == GK_GRAPHICS_VIEW_CTYPE) {
        gk_item *view = gk_live_item(item);
        if (!view || !gk_configure_view_item(view, tags, tag_count)) {
            gk_DeleteItem(item);
            return M2K_ITEM_NONE;
        }
        if (!view->view_signal_task)
            view->view_signal_task = m2k_current_task_item(g_gk.kctx);
    }
    if (item != M2K_ITEM_NONE && ctype == GK_AUDIO_INSTRUMENT_CTYPE) {
        gk_item *live = gk_live_item(item);
        if (!live) {
            gk_DeleteItem(item);
            return M2K_ITEM_NONE;
        }
        live->template_item = template_item;
        live->calc_rate_divider = instrument_calc_rate_divider;
        live->priority = instrument_priority;
        const int32_t propagate_rc =
            gk_propagate_template_attachments(template_item, item);
        if (propagate_rc < 0) {
            gk_DeleteItem(item);
            return (uint32_t)propagate_rc;
        }
        if (gk_audio_calcrate_diag_enabled()) {
            const gk_item *template_live = gk_live_item(template_item);
            gk_log_audio_calcrate(
                item, template_live ? template_live->audio_name : "",
                instrument_calc_rate_divider, instrument_priority);
        }
    }
    if (item != M2K_ITEM_NONE && ctype == GK_AUDIO_SAMPLE_CTYPE) {
        gk_item *live = gk_live_item(item);
        if (!live) {
            gk_DeleteItem(item);
            return M2K_ITEM_NONE;
        }
        gk_sample_fields f;
        gk_sample_fields_init(&f);
        int has_unknown = 0;
        for (uint32_t i = 0; i < tag_count; ++i) {
            const uint32_t tag = tags[i][0];
            const uint32_t val = tags[i][1];
            if (tag == M2_TAG_JUMP || tag == 0xFFFFFFFFu) continue;
            if (!gk_sample_tag_known(tag)) has_unknown = 1;
            else gk_sample_field_apply(&f, tag, val);
        }
        // A VA sample list may append a caller-owned list behind TAG_JUMP.
        if (attachment_taglist != 0u && g_gk.cpu && g_gk.cpu->mem) {
            for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
                const uint32_t ea = attachment_taglist + i * 8u;
                if (ea + 8u > RECOMP_GUEST_MEM) break;
                const uint32_t tag = rd32(g_gk.cpu, ea);
                const uint32_t val = rd32(g_gk.cpu, ea + 4u);
                if (tag == M2_TAG_END) break;
                if (tag == M2_TAG_JUMP || tag == 0xFFFFFFFFu) continue;
                if (!gk_sample_tag_known(tag)) has_unknown = 1;
                else gk_sample_field_apply(&f, tag, val);
            }
        }
        if (gk_configure_sample_item(cpu ? cpu : g_gk.cpu, live, item,
                                     &f, has_unknown) != 0) {
            gk_DeleteItem(item);
            return M2K_ITEM_NONE;
        }
    }
    if (item != M2K_ITEM_NONE && ctype == GK_AUDIO_ENVELOPE_CTYPE &&
        (tag_count != 0u || attachment_taglist != 0u)) {
        gk_item *live = gk_live_item(item);
        const int32_t envelope_rc = gk_configure_envelope_item(
            cpu ? cpu : g_gk.cpu, live, tags, tag_count, attachment_taglist);
        if (envelope_rc != M2K_OK) {
            gk_DeleteItem(item);
            return (uint32_t)envelope_rc;
        }
    }
    return item;
}

static uint32_t gk_CreateItem(uint32_t ctype, uint32_t taglist_ea) {
    if (!gk_bound() || ctype == 0) return M2K_ITEM_NONE;
    // Portfolio CreateItem(int32 ctype, const TagArg* tags): r3=ctype, r4=EA of a
    // TagArg list ({tag,value} u32 pairs, TAG_END=0 terminated) or 0 for no tags.
    // Bounded, fail-closed on OOB list EA or malformed name string.
    uint32_t name_ea = 0;
    uint32_t tag_count = 0;
    uint32_t template_item = 0;
    uint32_t instrument_calc_rate_divider = 1u;
    uint32_t instrument_priority = 100u;
    if (taglist_ea != 0) {
        if (taglist_ea + 8 > RECOMP_GUEST_MEM || !g_gk.cpu || !g_gk.cpu->mem)
            return M2K_ITEM_NONE;
        for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
            uint32_t ea = taglist_ea + i*8u;
            if (ea + 8 > RECOMP_GUEST_MEM) return M2K_ITEM_NONE;
            uint32_t tag = rd32(g_gk.cpu, ea);
            uint32_t val = rd32(g_gk.cpu, ea+4);
            if (tag == M2_TAG_END) break;
            if (tag == 0xFFFFFFFFu) break; // -1 sentinel terminator
            if (tag == 1 /* TAG_ITEM_NAME */) {
                name_ea = val;
                if (val != 0) {
                    if (val + 4 > RECOMP_GUEST_MEM) {
                        fprintf(stderr, "[gk] CreateItem fault: TAG_ITEM_NAME val=%#x OOB ctype=%#x\n", val, ctype);
                        return M2K_ITEM_NONE;
                    }
                    char tmp[GK_MAX_NAME_LEN];
                    int32_t rc = m2m_copy_guest_string_ctx(g_gk.cpu, val, tmp, sizeof(tmp));
                    if (rc == M2M_ERR_FAULT || rc < 0) {
                        fprintf(stderr, "[gk] CreateItem fault: TAG_ITEM_NAME val=%#x no NUL within %u ctype=%#x\n", val, (unsigned)GK_MAX_NAME_LEN, ctype);
                        return M2K_ITEM_NONE;
                    }
                }
            }
            if (ctype == GK_AUDIO_INSTRUMENT_CTYPE) {
                if (tag == M2_AUDIO_TAG_TEMPLATE) {
                    template_item = val;
                } else if (tag == M2_AUDIO_TAG_CALCRATE_DIVIDE) {
                    if (val != 1u && val != 2u && val != 8u)
                        return (uint32_t)M2_AUDIO_ERR_BAD_TAG_VALUE;
                    instrument_calc_rate_divider = val;
                } else if (tag == M2_AUDIO_TAG_PRIORITY) {
                    if (val > 200u)
                        return (uint32_t)M2_AUDIO_ERR_BAD_TAG_VALUE;
                    instrument_priority = val;
                }
            }
            tag_count++;
        }
    }
    // A null TagArg list is also used by the bounded generic kernel-item
    // lifecycle path (including ctype 0x402) without an audio template. Keep
    // that established compatibility shape; enforce the Audio Folio
    // template contract when an instrument tag list is actually supplied.
    if (ctype == GK_AUDIO_INSTRUMENT_CTYPE && taglist_ea != 0u) {
        gk_item *template_live = gk_live_item(template_item);
        if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE)
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
    }
    uint32_t sample_item = gk_mint_item("CreateItem", ctype, name_ea,
                                        tag_count, 1);
    // A null TagArg list is retained as the generic CreateItem compatibility
    // shape above. Only a source-shaped Audio Instrument list carries the
    // template ownership contract and therefore propagates attachments.
    if (sample_item != M2K_ITEM_NONE &&
        ctype == GK_AUDIO_INSTRUMENT_CTYPE && taglist_ea != 0u) {
        gk_item *live = gk_live_item(sample_item);
        if (!live) {
            gk_DeleteItem(sample_item);
            return (uint32_t)M2_AUDIO_ERR_BAD_ITEM;
        }
        live->template_item = template_item;
        live->calc_rate_divider = instrument_calc_rate_divider;
        live->priority = instrument_priority;
        const int32_t propagate_rc =
            gk_propagate_template_attachments(template_item, sample_item);
        if (propagate_rc < 0) {
            gk_DeleteItem(sample_item);
            return (uint32_t)propagate_rc;
        }
        if (gk_audio_calcrate_diag_enabled()) {
            const gk_item *template_live = gk_live_item(template_item);
            gk_log_audio_calcrate(
                sample_item,
                template_live ? template_live->audio_name : "",
                instrument_calc_rate_divider, instrument_priority);
        }
    }
    if (sample_item != M2K_ITEM_NONE && ctype == GK_AUDIO_SAMPLE_CTYPE &&
        taglist_ea != 0u) {
        gk_item *live = gk_live_item(sample_item);
        if (!live) {
            gk_DeleteItem(sample_item);
            return M2K_ITEM_NONE;
        }
        gk_sample_fields f;
        gk_sample_fields_init(&f);
        int has_unknown = 0;
        gk_log_sample_tag_window(g_gk.cpu, sample_item, taglist_ea);
        for (uint32_t i = 0; i < GK_MAX_TAGS; ++i) {
            const uint32_t ea = taglist_ea + i * 8u;
            if (ea + 8u > RECOMP_GUEST_MEM) break;
            const uint32_t tag = rd32(g_gk.cpu, ea);
            const uint32_t val = rd32(g_gk.cpu, ea + 4u);
            if (tag == M2_TAG_END) break;
            if (tag == 0xFFFFFFFFu) break;
            if (tag == M2_TAG_JUMP) continue;
            if (!gk_sample_tag_known(tag)) has_unknown = 1;
            else gk_sample_field_apply(&f, tag, val);
        }
        if (gk_configure_sample_item(g_gk.cpu, live, sample_item, &f,
                                     has_unknown) != 0) {
            gk_DeleteItem(sample_item);
            return M2K_ITEM_NONE;
        }
    }
    if (sample_item != M2K_ITEM_NONE && ctype == GK_AUDIO_ENVELOPE_CTYPE &&
        taglist_ea != 0u) {
        gk_item *live = gk_live_item(sample_item);
        const int32_t envelope_rc = gk_configure_envelope_item(
            g_gk.cpu, live, NULL, 0u, taglist_ea);
        if (envelope_rc != M2K_OK) {
            gk_DeleteItem(sample_item);
            return (uint32_t)envelope_rc;
        }
    }
    return sample_item;
}

// Propagate the Audio Folio's template attachment list when an instrument is
// created. Ordinary Sample/Envelope slaves are shared; a delay-line template
// is promoted to a fresh delay-line Sample for this instrument, matching
// PropagateTemplateAttachments()/PromoteDelayLineTemplate in the vendor
// folio. This is ownership/state plumbing only: the DSPP delay FIFO and tap
// execution are handled separately.
static int32_t gk_propagate_template_attachments(uint32_t template_item,
                                                  uint32_t instrument_item) {
    gk_item *template_live = gk_live_item(template_item);
    gk_item *instrument_live = gk_live_item(instrument_item);
    if (!template_live || template_live->ctype != GK_AUDIO_TEMPLATE_CTYPE ||
        !instrument_live ||
        instrument_live->ctype != GK_AUDIO_INSTRUMENT_CTYPE)
        return M2_AUDIO_ERR_BAD_ITEM;

    // Promote each delay-line template once per CreateInstrument call. The
    // vendor keeps a local DelayLineTemplatePromotion list, so several
    // template attachments (Sound3D's Send/LeftTap/RightTap trio) share one
    // new physical delay line rather than receiving three independent
    // buffers.
    uint32_t promoted_template[GK_MAX_ITEMS];
    uint32_t promoted_delay[GK_MAX_ITEMS];
    uint32_t promoted_count = 0u;
    memset(promoted_template, 0, sizeof(promoted_template));
    memset(promoted_delay, 0, sizeof(promoted_delay));

    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) {
        gk_item *source_attachment = &g_gk.items[i];
        if (!source_attachment->used ||
            source_attachment->ctype != GK_AUDIO_ATTACHMENT_CTYPE ||
            source_attachment->attachment_master != template_item)
            continue;

        gk_item *source_slave =
            gk_live_item(source_attachment->attachment_slave);
        if (!source_slave ||
            (source_slave->ctype != GK_AUDIO_SAMPLE_CTYPE &&
             source_slave->ctype != GK_AUDIO_ENVELOPE_CTYPE))
            return M2_AUDIO_ERR_BAD_ITEM;

        uint32_t slave_item = source_attachment->attachment_slave;
        if (source_slave->ctype == GK_AUDIO_SAMPLE_CTYPE &&
            source_slave->sample_kind == 2u) {
            for (uint32_t p = 0; p < promoted_count; ++p) {
                if (promoted_template[p] == source_attachment->attachment_slave) {
                    slave_item = promoted_delay[p];
                    break;
                }
            }
            if (slave_item == source_attachment->attachment_slave) {
                slave_item = gk_mint_item("promoted delay line",
                                          GK_AUDIO_SAMPLE_CTYPE, 0u, 0u, 0);
                if (slave_item == M2K_ITEM_NONE)
                    return M2_AUDIO_ERR_NO_MEMORY;
                gk_item *promoted = gk_live_item(slave_item);
                if (!promoted) {
                    gk_DeleteItem(slave_item);
                    return M2_AUDIO_ERR_BAD_ITEM;
                }
                promoted->sample_kind = 1u;
                promoted->sample_delay_owned = 1u;
                promoted->sample_num_bytes = source_slave->sample_num_bytes;
                promoted->sample_channels = source_slave->sample_channels;
                promoted->sample_flags = source_slave->sample_flags;
                promoted->sample_rate = source_slave->sample_rate;
                promoted->sample_sustain_begin =
                    source_slave->sample_sustain_begin;
                promoted->sample_sustain_end = source_slave->sample_sustain_end;
                promoted->sample_release_begin =
                    source_slave->sample_release_begin;
                promoted->sample_release_end = source_slave->sample_release_end;
                promoted->sample_low_note = source_slave->sample_low_note;
                promoted->sample_high_note = source_slave->sample_high_note;
                promoted->sample_low_velocity = source_slave->sample_low_velocity;
                promoted->sample_high_velocity = source_slave->sample_high_velocity;
                promoted->sample_delay_line = dspp_delay_line_create(
                    promoted->sample_num_bytes, promoted->sample_channels, 0);
                if (!promoted->sample_delay_line) {
                    gk_DeleteItem(slave_item);
                    return M2_AUDIO_ERR_NO_MEMORY;
                }
                if (dspp_delay_line_set_sample_loops(
                        promoted->sample_delay_line,
                        promoted->sample_sustain_begin,
                        promoted->sample_sustain_end,
                        promoted->sample_release_begin,
                        promoted->sample_release_end) != 0) {
                    dspp_delay_line_destroy(promoted->sample_delay_line);
                    promoted->sample_delay_line = NULL;
                    gk_DeleteItem(slave_item);
                    return M2_AUDIO_ERR_UNIMPLEMENTED;
                }
                dspp_delay_line_set_clear_on_stop(
                    promoted->sample_delay_line,
                    (promoted->sample_flags &
                     M2_AUDIO_SAMPLE_FLAG_CLEAR_ON_STOP) != 0u);
                if (promoted_count >= GK_MAX_ITEMS) {
                    gk_DeleteItem(slave_item);
                    return M2_AUDIO_ERR_NO_MEMORY;
                }
                promoted_template[promoted_count] =
                    source_attachment->attachment_slave;
                promoted_delay[promoted_count] = slave_item;
                ++promoted_count;
            }
        }

        const uint32_t attachment = gk_mint_item(
            "propagated audio attachment", GK_AUDIO_ATTACHMENT_CTYPE,
            0u, 0u, 0);
        if (attachment == M2K_ITEM_NONE) {
            return M2_AUDIO_ERR_NO_MEMORY;
        }
        gk_item *copy = gk_live_item(attachment);
        if (!copy) {
            gk_DeleteItem(attachment);
            return M2_AUDIO_ERR_BAD_ITEM;
        }
        copy->attachment_master = instrument_item;
        copy->attachment_slave = slave_item;
        copy->attachment_next = 0u;
        copy->attachment_cue = 0u;
        copy->attachment_cue_at = 0;
        copy->attachment_start_at = source_attachment->attachment_start_at;
        copy->attachment_type = source_attachment->attachment_type;
        copy->attachment_flags = source_attachment->attachment_flags;
        memcpy(copy->attachment_hook, source_attachment->attachment_hook,
               sizeof(copy->attachment_hook));
        copy->attachment_has_hook = source_attachment->attachment_has_hook;
    }
    return M2K_OK;
}


// Standalone GState allocation exports follow M2 SDK src/folios/gstate/gstate.c.
// The driving library's allocators were replaced by its private racing arena;
// they cannot serve another application. Retain its nonallocating guest code
// and public 128-byte ABI, using kernel allocations at this folio boundary.
#define GK_GSTATE_NOMEM 0xd55ef206u
#define GK_GSTATE_BADPTR 0xd55ef209u
static int gk_gstate_call(PPCContext *c, uint32_t offset) {
    RecompFn fn = recomp_lookup(g_recomp_text_base + offset);
    if (!fn) return 0;
    fn(c);
    return 1;
}

static void gk_gstate_free_bitmap(uint32_t item) {
    gk_item *bm = gk_live_item(item);
    if (bm && bm->ctype == GK_GRAPHICS_BITMAP_CTYPE) {
        gk_FreeMem((void *)(uintptr_t)bm->bitmap_buffer,
                   (int32_t)bm->bitmap_buffer_size);
        gk_DeleteItem(item);
    }
}

static uint32_t gk_gstate_bitmap(PPCContext *c, uint32_t width, uint32_t height,
                                  uint32_t type, uint32_t coalign) {
    const uint32_t tags[][2] = {
        {GK_BMTAG_WIDTH, width}, {GK_BMTAG_HEIGHT, height},
        {GK_BMTAG_TYPE, type},
        {GK_BMTAG_DISPLAYABLE, type != GK_BMTYPE_16_ZBUFFER},
        {GK_BMTAG_RENDERABLE, 1u}, {GK_BMTAG_COALIGN, coalign}
    };
    const uint32_t item = gk_mint_item("GS_AllocBitmaps",
                                       GK_GRAPHICS_BITMAP_CTYPE, 0, 6, 1);
    if (!item) return GK_GSTATE_NOMEM;
    gk_item *bm = gk_live_item(item);
    if (!bm || !gk_configure_bitmap_item(bm, tags, 6)) {
        gk_DeleteItem(item);
        return 0xD55B9003u; // Graphics ER_BadTagArgVal
    }
    gk_publish_bitmap_object(item, bm);
    const uint32_t buffer = (uint32_t)(uintptr_t)gk_AllocMemMasked(
        (int32_t)bm->bitmap_buffer_size, bm->bitmap_buf_mem_type,
        bm->bitmap_buf_mem_care_bits | 0xfffu, bm->bitmap_buf_mem_state_bits);
    if (!buffer) {
        gk_DeleteItem(item);
        return GK_GSTATE_NOMEM;
    }
    // Publish through the normal Graphics ModifyGraphicsItem TagArg boundary.
    const uint32_t sp = c->gpr[1];
    if (sp < 16u || sp > RECOMP_GUEST_MEM) {
        gk_FreeMem((void *)(uintptr_t)buffer, (int32_t)bm->bitmap_buffer_size);
        gk_DeleteItem(item);
        return GK_GSTATE_BADPTR;
    }
    uint8_t saved_tags[16];
    memcpy(saved_tags, c->mem + sp - 16u, sizeof(saved_tags));
    wr32(c, sp - 16u, GK_BMTAG_BUFFER); wr32(c, sp - 12u, buffer);
    wr32(c, sp - 8u, M2_TAG_END); wr32(c, sp - 4u, 0u);
    c->gpr[3] = item; c->gpr[4] = sp - 16u;
    const int handled = recomp_call_graphics_dispatch(c, 1u, c->pc);
    memcpy(c->mem + sp - 16u, saved_tags, sizeof(saved_tags));
    if (!handled || (int32_t)c->gpr[3] < 0) {
        const uint32_t err = handled ? c->gpr[3] : GK_GSTATE_BADPTR;
        gk_FreeMem((void *)(uintptr_t)buffer, (int32_t)bm->bitmap_buffer_size);
        gk_DeleteItem(item);
        return err;
    }
    return item;
}

static void gk_gstate_free_lists(PPCContext *c, uint32_t gs) {
    const uint32_t lists = rd32(c, gs + 0x20u);
    const uint32_t count = rd32(c, gs + 0x18u);
    if (lists) {
        for (uint32_t i = 0; i < count; ++i) {
            gk_FreeMem((void *)(uintptr_t)rd32(c, lists + 8u*i + 4u), -1);
            const uint32_t io = rd32(c, lists + 8u*i);
            if (io) gk_DeleteItem(io);
        }
        for (uint32_t off = 0x40u; off <= 0x4cu; off += 4u) {
            if (off == 0x48u) continue; // speed, not an Item
            const uint32_t io = rd32(c, gs + off);
            if ((int32_t)io > 0) gk_DeleteItem(io);
        }
        gk_FreeMem((void *)(uintptr_t)lists, (int32_t)(count * 8u));
    }
    wr32(c, gs + 0x20u, 0u); wr32(c, gs + 0x18u, 0u);
    wr32(c, gs, g_recomp_text_base + 0x1b15cu); // GS_BustedSendList
}

static int gk_gstate_allocation_dispatch(PPCContext *c, uint32_t ord) {
    if (ord != 0u && ord != 2u && ord != 16u) return 0;
    if (!gk_bound() || c->mem != g_gk.cpu->mem) {
        c->gpr[3] = ord == 0u ? 0u : GK_GSTATE_BADPTR;
        return 1;
    }
    if (ord == 0u) {
        const uint32_t gs = (uint32_t)(uintptr_t)gk_AllocMemMasked(
            128, GK_MEMTYPE_FILL, 31u, 0u);
        if (!gs) { c->gpr[3] = 0; return 1; }
        c->gpr[3] = gs;
        if (!gk_gstate_call(c, 0x1b3c0u)) {
            gk_FreeMem((void *)(uintptr_t)gs, 128); c->gpr[3] = 0; return 1;
        }
        wr16(c, gs + 0x28u, 8192u); wr16(c, gs + 0x2au, 32u);
        if (!gk_gstate_call(c, 0x73ebcu) || (int32_t)c->gpr[3] < 0) {
            gk_FreeMem((void *)(uintptr_t)gs, 128); c->gpr[3] = 0; return 1;
        }
        wr32(c, gs + 0x3cu, c->gpr[3]);
        c->gpr[3] = gs;
        return 1;
    }
    if (ord == 16u) {
        const uint32_t out = c->gpr[3], width = c->gpr[4], height = c->gpr[5];
        const uint32_t type = c->gpr[6], count = c->gpr[7];
        const int depth = c->gpr[8] != 0u;
        if (!count) { c->gpr[3] = 23u; return 1; } // vendor ER_ParamError
        if (!out || count > GK_MAX_ITEMS - (uint32_t)depth ||
            out > RECOMP_GUEST_MEM - (count + depth)*4u) {
            c->gpr[3] = GK_GSTATE_BADPTR; return 1;
        }
        for (uint32_t i = 0; i < count + depth; ++i) {
            const uint32_t item = gk_gstate_bitmap(c, width, height,
                i == count ? GK_BMTYPE_16_ZBUFFER : type,
                i == count ? rd32(c, out) : 0u);
            wr32(c, out + i*4u, item);
            if ((int32_t)item < 0) {
                for (uint32_t j = 0; j < i; ++j)
                    gk_gstate_free_bitmap(rd32(c, out + j*4u));
                c->gpr[3] = item; return 1;
            }
        }
        c->gpr[3] = 0; return 1;
    }
    const uint32_t gs = c->gpr[3], count = c->gpr[4], words = c->gpr[5];
    if (!gs || gs > RECOMP_GUEST_MEM - 128u) {
        c->gpr[3] = GK_GSTATE_BADPTR; return 1;
    }
    if (!count) { c->gpr[3] = 0; return 1; }
    if (count > M2K_MAX_IOREQS || words > (INT32_MAX - 75u)/4u) {
        c->gpr[3] = GK_GSTATE_NOMEM; return 1;
    }
    const uint32_t lists = (uint32_t)(uintptr_t)gk_AllocMem(
        (int32_t)(count*8u), GK_MEMTYPE_FILL);
    if (!lists) { c->gpr[3] = GK_GSTATE_NOMEM; return 1; }
    wr32(c, gs + 0x20u, lists); wr32(c, gs + 0x18u, count);
    wr32(c, gs, g_recomp_text_base + 0x1c2a8u);
    wr32(c, gs + 0x24u, words);
    const uint32_t bytes = (words*4u + 44u + 31u) & ~31u;
    uint32_t result = 0;
    for (uint32_t i = 0; i < count; ++i) {
        const uint32_t buffer = (uint32_t)(uintptr_t)gk_AllocMemMasked(
            (int32_t)bytes, GK_MEMTYPE_TRACKSIZE, 31u, 0u);
        wr32(c, lists + i*8u + 4u, buffer);
        if (!buffer) { result = GK_GSTATE_NOMEM; break; }
        const uint32_t io = gk_CreateIOReq(0, 0, rd32(c, gs + 0x3cu),
                                           rd32(c, gs + 0x78u));
        wr32(c, lists + i*8u, io);
        if (!io || (int32_t)io < 0) {
            result = io ? io : GK_GSTATE_NOMEM; break;
        }
    }
    if (!result) {
        for (uint32_t off = 0x40u; off <= 0x4cu; off += 4u) {
            if (off == 0x48u) continue;
            const uint32_t io = gk_CreateIOReq(0, 0, rd32(c, gs + 0x3cu), 0);
            wr32(c, gs + off, io);
            if (!io || (int32_t)io < 0) {
                result = io ? io : GK_GSTATE_NOMEM; break;
            }
        }
    }
    if (!result) {
        c->gpr[3] = gs; c->gpr[4] = 0; // TE_FULLSPEED
        if (!gk_gstate_call(c, 0x1b7b8u)) result = GK_GSTATE_NOMEM;
        else result = c->gpr[3];
        if ((int32_t)result >= 0) {
            c->gpr[3] = gs; c->gpr[4] = 0;
            if (gk_gstate_call(c, 0x1b22cu)) { c->gpr[3] = 0; return 1; }
            result = GK_GSTATE_NOMEM;
        }
    }
    gk_gstate_free_lists(c, gs);
    c->gpr[3] = result;
    return 1;
}

static uint32_t gk_FindItem(uint32_t type_tag, uint32_t name_ea) {
    if (!gk_bound()) return M2K_ITEM_NONE;
    // MKNODEID(KERNELNODE,TASKNODE) is 0x105. With a NULL tag list the
    // original kernel returns CURRENTTASKITEM, which is the task whose
    // t_SigBits StateDriver reads immediately after LookupItem. Resolve this
    // from the m2k task-local context; do not use the generic CreateItem pool.
    if (type_tag == 0x105u && name_ea == 0) {
        uint32_t current = m2k_current_task_item(g_gk.kctx);
        if (current != M2K_ITEM_NONE) {
            if (gk_state2_input_diag_enabled()) {
                fprintf(stderr,
                        "[gk-input] FindItem pc=%#x type=%#x name=%#x "
                        "-> current-task %#x\n",
                        g_gk_selector_pc, type_tag, name_ea, current);
            }
            return current;
        }
        // A host-only caller has no CURRENTTASKITEM. Preserve the existing
        // deterministic compatibility result for those unit-test calls; the
        // guest path above is the only path that can publish a TaskNode EA.
    }
    // Fast path: check CreateItemVA pool first for name match (more faithful than minting).
    if (name_ea != 0) {
        for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i) if (g_gk.items[i].used && g_gk.items[i].ctype==type_tag && g_gk.items[i].name_ea==name_ea) {
            static int _find_item_hit = 0;
            if (_find_item_hit < 20) { fprintf(stderr, "[gk] FindItem type=%#x name_ea=%#x -> %#x (from CreateItemVA pool)\n", type_tag, name_ea, gk_make_handle(GK_TYPE_ITEM_VA, i, g_gk.items[i].generation)); _find_item_hit++; }
            return gk_make_handle(GK_TYPE_ITEM_VA, i, g_gk.items[i].generation);
        }
        for (int i=0;i<GK_FIND_REG;++i) if (g_find_reg[i].handle && g_find_reg[i].type==type_tag && g_find_reg[i].name==name_ea)
            return g_find_reg[i].handle;
        // Miss with name: mint deterministic handle and remember it so the
        // guest's subsequent OpenItem/FindItem for same name is stable.
        uint32_t h = 0x7000u | ((type_tag & 0xFFu)<<8) | (name_ea & 0xFFu);
        if (h==M2K_ITEM_NONE) h = 0x7001u;
        for (int i=0;i<GK_FIND_REG;++i) if (g_find_reg[i].handle==0) { g_find_reg[i]=(typeof(g_find_reg[0])){type_tag,name_ea,h}; break; }
        static int _find_cnt2 = 0;
        if (_find_cnt2 < 20) { fprintf(stderr, "[gk] FindItem type=%#x name_ea=%#x -> %#x (minted)\n", type_tag, name_ea, h); _find_cnt2++; }
        return h;
    }
    uint32_t ret = (g_last_generic_item != 0) ? g_last_generic_item : M2K_ITEM_NONE;
    if (gk_state2_input_diag_enabled()) {
        gk_item* live = gk_live_item(ret);
        fprintf(stderr,
                "[gk-input] FindItem pc=%#x type=%#x name=%#x -> %#x "
                "last=%#x live=%s ctype=%#x\n",
                g_gk_selector_pc, type_tag, name_ea, ret, g_last_generic_item,
                live ? "yes" : "no", live ? live->ctype : 0u);
    }
    // Throttled log for StateDriver diagnosis (first 20)
    static int _find_cnt = 0;
    if (_find_cnt < 20) {
        fprintf(stderr, "[gk] FindItem type=%#x name_ea=%#x -> %#x (last=%#x)\n",
                type_tag, name_ea, ret, g_last_generic_item);
        _find_cnt++;
    }
    return ret;
}

static uint32_t gk_CreateSemaphore(uint32_t name_ea, uint32_t pri) {
    (void)name_ea; (void)pri;
    if (!gk_bound()) return M2K_ITEM_NONE;
    const uint32_t h = m2k_create_semaphore(g_gk.kctx);
    static int _cs_cnt = 0;
    if (_cs_cnt < 10) { fprintf(stderr, "[gk] CreateSemaphore name=%#x pri=%u -> %#x\n", name_ea, pri, h); _cs_cnt++; }
    return h;
}

// The host may observe a complete down/up transition between two guest
// GetCPortData calls. Retain such rising edges until the guest releases the
// ControlPort descriptor semaphore after copying its sample.
static uint32_t g_cport_current_buttons;
static uint32_t g_cport_pending_pressed;
static uint8_t g_cport_current_stick_x = 128u;
static uint8_t g_cport_current_stick_y = 128u;
static int g_cport_edge_publish;
static m2_diagnostic_input_status g_diagnostic_input;
static int g_diagnostic_input_tap;
static uint8_t g_diagnostic_input_x = 128u;
static uint8_t g_diagnostic_input_y = 128u;

uint64_t m2_diagnostic_input_submit(uint32_t buttons, uint8_t x, uint8_t y, int tap) {
    if (!m2_diagnostic_enabled() || !m2_diagnostic_is_paused() ||
        !gk_bound() || g_diagnostic_input.phase) return 0;
    ++g_diagnostic_input.submitted;
    g_diagnostic_input.buttons = buttons;
    g_diagnostic_input.phase = 1;
    g_diagnostic_input_tap = tap;
    g_diagnostic_input_x = x;
    g_diagnostic_input_y = y;
    m2_guest_input_set_cport_edges(buttons, buttons & ~g_cport_current_buttons, x, y);
    return g_diagnostic_input.submitted;
}

void m2_diagnostic_input_publish(void) {
    if (!m2_diagnostic_enabled() || !gk_bound() || !g_diagnostic_input.phase)
        return;
    m2_guest_input_set_cport_edges(g_diagnostic_input.buttons,
                                   g_diagnostic_input.buttons &
                                       ~g_cport_current_buttons,
                                   g_diagnostic_input_x,
                                   g_diagnostic_input_y);
}

void m2_diagnostic_input_query(m2_diagnostic_input_status* out) {
    if (out) *out = g_diagnostic_input;
}

void m2_diagnostic_input_cancel(void) {
    if (!m2_diagnostic_enabled() || !m2_diagnostic_is_paused()) return;
    g_diagnostic_input.phase = 0;
    g_diagnostic_input.buttons = 0;
    g_diagnostic_input_x = 128u;
    g_diagnostic_input_y = 128u;
    g_cport_pending_pressed = 0;
    m2_guest_input_set_cport_edges(0, 0, 128, 128);
}

static void gk_diagnostic_input_consumed(void) {
    if (g_diagnostic_input.phase == 1) {
        g_diagnostic_input.consumed = g_diagnostic_input.submitted;
        if (g_diagnostic_input_tap) {
            // Release at the actual copy-completion boundary, before a fast
            // guest can poll/repeat a held press while the client is idle.
            g_diagnostic_input.phase = 2;
            g_diagnostic_input.buttons = 0;
            g_diagnostic_input_x = 128u;
            g_diagnostic_input_y = 128u;
            m2_guest_input_set_cport_edges(0, 0, 128, 128);
            return;
        }
    } else if (g_diagnostic_input.phase != 2) {
        return;
    }
    g_diagnostic_input.completed = g_diagnostic_input.submitted;
    g_diagnostic_input.phase = 0;
}

static void gk_consume_cport_edges(void) {
    if (g_cport_pending_pressed == 0u) return;
    g_cport_pending_pressed = 0u;
    g_cport_edge_publish = 1;
    m2_guest_input_set_cport(g_cport_current_buttons,
                             g_cport_current_stick_x,
                             g_cport_current_stick_y);
    g_cport_edge_publish = 0;
}

static int32_t gk_LockSemaphore(uint32_t sema, uint32_t flags){
    if(!gk_bound() || sema==0) return M2K_ERR_BAD_ITEM;
    if (gk_state2_input_diag_enabled() || getenv("M2_SECRET_INPUT_PROBE")) {
        static uint32_t _input_lock_diag_n;
        PPCContext* cpu = gk_current_cpu();
        if (_input_lock_diag_n < 128u && cpu && cpu->mem &&
            rd32(cpu, 0x1877d8u) == 3u &&
            (rd32(cpu, 0x1877dcu) == 17u || rd32(cpu, 0x1877dcu) == 18u) &&
            cpu->gpr[30] <= RECOMP_GUEST_MEM - 0x10u &&
            (cpu->gpr[31] == 0x181580u || cpu->gpr[31] == 0x1812b8u)) {
            uint32_t caller_lr = 0;
            if (cpu->gpr[1] <= RECOMP_GUEST_MEM - 0x58u)
                caller_lr = rd32(cpu, cpu->gpr[1] + 0x54u);
            fprintf(stderr,
                    "[gk-input] LockSemaphore pc=%#x sema=%#x args=(%#x,%#x,%#x) "
                    "lr=%#x sp=%#x r30=%#x out=%#x desc=(%#x,%#x,%#x,%#x) "
                    "raw=(%#x,%#x,%#x)\n",
                    g_gk_selector_pc, sema, cpu->gpr[3], cpu->gpr[4],
                    cpu->gpr[5], caller_lr, cpu->gpr[1], cpu->gpr[30],
                    cpu->gpr[31],
                    rd32(cpu, cpu->gpr[30] + 0x00u),
                    rd32(cpu, cpu->gpr[30] + 0x04u),
                    rd32(cpu, cpu->gpr[30] + 0x08u),
                    rd32(cpu, cpu->gpr[30] + 0x0cu),
                    rd32(cpu, GK_BROKER_INPUT_DATA_EA + 0x0cu),
                    rd32(cpu, GK_BROKER_INPUT_DATA_EA + 0x10u),
                    rd32(cpu, GK_BROKER_INPUT_DATA_EA + 0x14u));
            ++_input_lock_diag_n;
        }
    }
    const int32_t rc = m2k_lock_semaphore(g_gk.kctx, sema, flags);
    static int _ls_cnt=0;
    if(_ls_cnt<8){ fprintf(stderr, "[gk] LockSemaphore sema=%#x -> %d\n", sema, rc); _ls_cnt++; }
    return rc;
}
static int32_t gk_UnlockSemaphore(uint32_t sema){
    if(!gk_bound() || sema==0) return M2K_ERR_BAD_ITEM;
    const int32_t rc = m2k_unlock_semaphore(g_gk.kctx, sema);
    if (rc == M2K_OK && g_gk.cpu && g_gk.cpu->mem &&
        sema == rd32(g_gk.cpu, GK_BROKER_DESCRIPTOR_EA + 0x00u)) {
        gk_consume_cport_edges();
        gk_diagnostic_input_consumed();
    }
    static int _us_cnt=0;
    if(_us_cnt<8){ fprintf(stderr, "[gk] UnlockSemaphore sema=%#x -> %d\n", sema, rc); _us_cnt++; }
    return rc;
}

static int32_t gk_printf(uint32_t fmt_ea, uint32_t a1, uint32_t a2, uint32_t a3, uint32_t a4, uint32_t a5, uint32_t a6, uint32_t a7) {
    if (!gk_bound() || fmt_ea == 0 || fmt_ea + 4 > RECOMP_GUEST_MEM) {
        fprintf(stderr, "[gk] printf fault: fmt_ea=%#x OOB\n", fmt_ea);
        return -1;
    }
    PPCContext* call_cpu = gk_current_cpu();
    PPCContext* cpu = gk_current_memory_cpu();
    char fmt[256];
    int32_t rc = m2m_copy_guest_string_ctx(cpu, fmt_ea, fmt, sizeof(fmt));
    if (rc < 0) {
        fprintf(stderr, "[gk] printf fault: fmt_ea=%#x no NUL within %zu\n", fmt_ea, sizeof(fmt));
        return -1;
    }
    // Collect varargs: regs a1..a7 plus stack spill at r1+8, +12, ...
    uint32_t args[16];
    args[0]=a1; args[1]=a2; args[2]=a3; args[3]=a4; args[4]=a5; args[5]=a6; args[6]=a7;
    int arg_count = 7;
    // Fill remaining from stack (up to 9 more)
    uint32_t sp = call_cpu ? call_cpu->gpr[1] : 0;
    for (int i=0; i<9 && arg_count < 16; ++i) {
        uint32_t ea = sp + 8 + (uint32_t)(i*4);
        // printf stack args are 4-byte words (EABI)
        if (ea + 4 > RECOMP_GUEST_MEM) break;
        args[arg_count++] = rd32(cpu, ea);
    }
    char out[1024];
    size_t out_pos = 0;
    int arg_idx = 0;
    for (size_t i=0; fmt[i] && out_pos + 1 < sizeof(out); ++i) {
        if (fmt[i] != '%') {
            out[out_pos++] = fmt[i];
            continue;
        }
        // %%
        if (fmt[i+1] == '%') { out[out_pos++] = '%'; ++i; continue; }
        // Parse flags/width/precision/length (skip, not needed for value)
        size_t j = i+1;
        while (fmt[j] && strchr("-+ #0", fmt[j])) ++j;
        while (fmt[j] && fmt[j]>='0' && fmt[j]<='9') ++j;
        if (fmt[j]=='.') { ++j; while (fmt[j] && fmt[j]>='0' && fmt[j]<='9') ++j; }
        while (fmt[j] && strchr("hlLzjt", fmt[j])) ++j;
        char spec = fmt[j];
        if (!spec) break;
        i = j; // advance
        if (arg_idx >= arg_count) {
            // Not enough args: emit placeholder
            const char *ph = "<missing>";
            for (size_t k=0; ph[k] && out_pos+1 < sizeof(out); ++k) out[out_pos++] = ph[k];
            continue;
        }
        uint32_t v = args[arg_idx++];
        char tmp[256] = {0};
        switch (spec) {
            case 's': {
                if (v==0) { snprintf(tmp,sizeof(tmp),"(null)"); }
                else if (v + 4 > RECOMP_GUEST_MEM) { snprintf(tmp,sizeof(tmp),"<OOB:%#x>", v); }
                else {
                    char sbuf[256];
                    int32_t sr = m2m_copy_guest_string_ctx(g_gk.cpu, v, sbuf, sizeof(sbuf));
                    if (sr < 0) snprintf(tmp,sizeof(tmp),"<fault:%#x>", v);
                    else {
                        // Escape for clean log
                        for (size_t k=0; sbuf[k] && k < sizeof(tmp)-1; ++k) {
                            if (sbuf[k]=='\n' || sbuf[k]=='\r') break;
                        }
                        snprintf(tmp,sizeof(tmp),"%s", sbuf);
                    }
                }
                break;
            }
            case 'd': case 'i':
                snprintf(tmp,sizeof(tmp),"%d", (int32_t)v);
                break;
            case 'u':
                snprintf(tmp,sizeof(tmp),"%u", v);
                break;
            case 'x':
                snprintf(tmp,sizeof(tmp),"%x", v);
                break;
            case 'X':
                snprintf(tmp,sizeof(tmp),"%X", v);
                break;
            case 'o':
                snprintf(tmp,sizeof(tmp),"%o", v);
                break;
            case 'p':
                snprintf(tmp,sizeof(tmp),"%#x", v);
                break;
            case 'c':
                tmp[0]=(char)(v & 0xFF); tmp[1]=0;
                break;
            case 'f': case 'F': case 'g': case 'G': case 'e': case 'E': case 'a': case 'A':
                // Float: try to read from fpr if available? For now print as float from bits
                {
                    float fv; uint32_t bits=v; memcpy(&fv,&bits,4);
                    // If bits looks like integer small, also try gpr as int
                    snprintf(tmp,sizeof(tmp),"%f", (double)fv);
                }
                break;
            default:
                snprintf(tmp,sizeof(tmp),"%%%c", spec);
                break;
        }
        for (size_t k=0; tmp[k] && out_pos+1 < sizeof(out); ++k) out[out_pos++] = tmp[k];
    }
    out[out_pos]=0;
    // Throttled log (first 20)
    {
        static int _pf_cnt = 0;
        if (_pf_cnt < 20) {
            fprintf(stderr, "[gk] printf fmt=\"%s\" -> \"%s\" (%zu)\n", fmt, out, out_pos);
            _pf_cnt++;
            if (_pf_cnt==20) fprintf(stderr, "[gk] (further printf suppressed)\n");
        }
    }
    // Also emit to host stdout for diagnostics (like original printf would go to console)
    // Use fputs to avoid extra formatting
    fputs(out, stdout);
    // Return chars printed (as original printf)
    return (int32_t)out_pos;
}

// Guest vcprintf (kernel:24): vcprintf(fmt, OutputFunc, userData, va_list).
// The format and va_list are guest EAs; callback and userData remain guest
// words. We read each argument on demand via gk_va_arg(), format to a bounded
// host buffer, emit to stdout, and return the character count. The guest
// callback/FILE sink is not yet reconstructed, so the callback is accepted but
// not invoked as a host function pointer.
static uint32_t gk_va_arg(uint32_t va_ea, uint32_t type_class);  // defined below
static int32_t gk_vcprintf(uint32_t fmt_ea, uint32_t output_func_ea,
                           uint32_t user_data_ea, uint32_t va_ea) {
    (void)output_func_ea;
    (void)user_data_ea;
    if (!gk_bound() || fmt_ea == 0 || fmt_ea + 4 > RECOMP_GUEST_MEM) {
        fprintf(stderr, "[gk] vcprintf fault: fmt_ea=%#x OOB\n", fmt_ea);
        return -1;
    }
    char fmt[256];
    int32_t rc = m2m_copy_guest_string_ctx(g_gk.cpu, fmt_ea, fmt, sizeof(fmt));
    if (rc < 0) {
        fprintf(stderr, "[gk] vcprintf fault: fmt_ea=%#x no NUL within %zu\n", fmt_ea, sizeof(fmt));
        return -1;
    }
    char out[1024];
    size_t out_pos = 0;
    for (size_t i = 0; fmt[i] && out_pos + 1 < sizeof(out); ++i) {
        if (fmt[i] != '%') {
            out[out_pos++] = fmt[i];
            continue;
        }
        if (fmt[i+1] == '%') { out[out_pos++] = '%'; ++i; continue; }
        size_t j = i+1;
        while (fmt[j] && strchr("-+ #0", fmt[j])) ++j;
        while (fmt[j] && fmt[j]>='0' && fmt[j]<='9') ++j;
        if (fmt[j]=='.') { ++j; while (fmt[j] && fmt[j]>='0' && fmt[j]<='9') ++j; }
        while (fmt[j] && strchr("hlLzjt", fmt[j])) ++j;
        char spec = fmt[j];
        if (!spec) break;
        i = j;
        uint32_t slot = gk_va_arg(va_ea, 1);
        uint32_t v = slot ? rd32(g_gk.cpu, slot) : 0u;
        char tmp[256] = {0};
        switch (spec) {
            case 's': {
                if (v==0) snprintf(tmp,sizeof(tmp),"(null)");
                else if (v + 4 > RECOMP_GUEST_MEM) snprintf(tmp,sizeof(tmp),"<OOB:%#x>", v);
                else {
                    char sbuf[256];
                    int32_t sr = m2m_copy_guest_string_ctx(g_gk.cpu, v, sbuf, sizeof(sbuf));
                    if (sr < 0) snprintf(tmp,sizeof(tmp),"<fault:%#x>", v);
                    else snprintf(tmp,sizeof(tmp),"%s", sbuf);
                }
                break;
            }
            case 'd': case 'i': snprintf(tmp,sizeof(tmp),"%d", (int32_t)v); break;
            case 'u': snprintf(tmp,sizeof(tmp),"%u", v); break;
            case 'x': snprintf(tmp,sizeof(tmp),"%x", v); break;
            case 'X': snprintf(tmp,sizeof(tmp),"%X", v); break;
            case 'o': snprintf(tmp,sizeof(tmp),"%o", v); break;
            case 'p': snprintf(tmp,sizeof(tmp),"%#x", v); break;
            case 'c': tmp[0]=(char)(v & 0xFF); tmp[1]=0; break;
            case 'f': case 'F': case 'g': case 'G': case 'e': case 'E': case 'a': case 'A': {
                float fv; uint32_t bits=v; memcpy(&fv,&bits,4);
                snprintf(tmp,sizeof(tmp),"%f", (double)fv);
                break;
            }
            default: snprintf(tmp,sizeof(tmp),"%%%c", spec); break;
        }
        for (size_t k=0; tmp[k] && out_pos+1 < sizeof(out); ++k) out[out_pos++] = tmp[k];
    }
    out[out_pos] = 0;
    {
        static int _vpf_cnt = 0;
        if (_vpf_cnt < 20) {
            fprintf(stderr, "[gk] vcprintf fmt=\"%s\" -> \"%s\" (%zu)\n", fmt, out, out_pos);
            _vpf_cnt++;
            if (_vpf_cnt == 20) fprintf(stderr, "[gk] (further vcprintf suppressed)\n");
        }
    }
    fputs(out, stdout);
    return (int32_t)out_pos;
}

static float gk_itof(int32_t v) { return (float)v; }
static float gk_utof(uint32_t v) { return (float)v; }

// ---- Diab PPC varargs helper (kernel 267 __va_arg) -------------------------
// va_list layout proven from the two consumers' inlined va_start
// (CreateDeviceStackListVA 0x73478; fscanf 0x74c20 -> __vfscanf 0x74cc4):
//   +0 u8  gpr index  (named-arg count at va_start: 1 or 2 observed)
//   +1 u8  fpr index  (0; never consumed through 267 in this image)
//   +4 u32 overflow_arg_area (incoming stack-args area = frame+8)
//   +8 u32 reg_save_area (saved r3..r10 words, prologue stores)
// All 15 ELF-verified sites (REL24 sym (1<<16)|267 == generated lift ==
// the selector table) pass r3=va_list EA, r4=1 class and consume the result as
// `lwz rX, 0(r3)` — one 4-byte word. While gpr<8 the slot is
// reg_save_area+gpr*4 and the byte increments; at >=8 the slot is the
// overflow area and advances by 4 (counter saturation variants are
// observationally equivalent: only __va_arg reads the byte and both route
// to the overflow path). Fail-closed EA 0, no write: unbound kernel, va_list
// outside the [0x10000, RECOMP_GUEST_MEM-12] window the discovery scaffold
// used, or type class != 1 (no site passes any other class; unproven classes
// stay visibly broken rather than guessed).
static uint32_t gk_va_arg(uint32_t va_ea, uint32_t type_class) {
    if (!gk_bound() || type_class != 1) return 0;
    if (va_ea < 0x10000 || va_ea + 12 > RECOMP_GUEST_MEM) return 0;
    PPCContext* cpu = g_gk.cpu;
    uint32_t gpr = rd8(cpu, va_ea);
    uint32_t res;
    if (gpr < 8) {
        uint32_t reg_save = rd32(cpu, va_ea + 8);
        res = reg_save + gpr * 4u;
        wr8(cpu, va_ea, gpr + 1);
    } else {
        uint32_t input_area = rd32(cpu, va_ea + 4);
        res = input_area;
        wr32(cpu, va_ea + 4, input_area + 4u);
    }
    return res;
}


// ---- guest threads -------------------------------------------------------------------

// Guest main argc/argv delivery. The original Portfolio OS launches the game
// task with r3=argc / r4=argv (guest main forwards both to Parse_Args, whose
// -V/-T cases drive GDP+0x5c / GDP+0x54 boot config). CreateThread has no
// body argument, so the launcher stages the words here before CreateThread;
// the first created task consumes them once. The argv strings are copied into
// a fixed guest-visible block in the image/stack gap so guest code can read
// them through normal guest loads.
static uint32_t g_gk_main_argc = 0;
static uint32_t g_gk_main_argv_ea = 0;

// Fixed scratch block: guest images end at 0x18B198 and guest task stacks
// start at GK_TASK_STACK_BASE (0x200000), so 0x1C0000 sits in dead space.
#define GK_MAIN_ARGS_EA 0x001C0000u
#define GK_MAIN_ARGS_BYTES 0x4000u

void m2_guest_set_main_args(int argc, char* const* argv) {
    g_gk_main_argc = 0;
    g_gk_main_argv_ea = 0;
    if (!g_gk.cpu || !g_gk.cpu->mem) return;
    if (argc <= 0 || !argv) return;
    if (argc > 64) argc = 64;
    uint8_t* mem = g_gk.cpu->mem;
    memset(mem + GK_MAIN_ARGS_EA, 0, GK_MAIN_ARGS_BYTES);
    uint32_t cursor = GK_MAIN_ARGS_EA + 64 * 4; // string pool after 64 pointer slots
    uint32_t limit = GK_MAIN_ARGS_EA + GK_MAIN_ARGS_BYTES;
    int n = 0;
    for (int i = 0; i < argc; ++i) {
        const char* s = argv[i] ? argv[i] : "";
        size_t len = strlen(s) + 1;
        if ((uint64_t)cursor + len > limit) break;
        memcpy(mem + cursor, s, len);
        // Guest memory is big-endian: store argv[n] as a BE word.
        uint32_t pe = GK_MAIN_ARGS_EA + (uint32_t)n * 4u;
        mem[pe + 0] = (uint8_t)(cursor >> 24);
        mem[pe + 1] = (uint8_t)(cursor >> 16);
        mem[pe + 2] = (uint8_t)(cursor >> 8);
        mem[pe + 3] = (uint8_t)(cursor);
        cursor += (uint32_t)((len + 3u) & ~3u);
        ++n;
    }
    g_gk_main_argc = (uint32_t)n;
    g_gk_main_argv_ea = GK_MAIN_ARGS_EA;
    printf("[recomp] guest main args staged: argc=%u argv_ea=%#x\n",
           g_gk_main_argc, g_gk_main_argv_ea);
}

uint32_t m2_guest_main_args_peek(uint32_t* argv_ea) {
    if (argv_ea) *argv_ea = g_gk_main_argv_ea;
    return g_gk_main_argc;
}

void m2_guest_main_args_consume(void) { g_gk_main_argv_ea = 0; }

// Return the original lifted function that owns a proven checkpoint park
// point.  c->pc is a last-translated-PC tag, so only PCs established at an
// explicit blocking/parking boundary may be used to recreate a host task.
// Values are module-relative guest EAs, matching the generated emitter's
// function addresses.  An entrypoint restart is never a fallback.
static uint32_t gk_image_entry_offset(uint32_t slot, uint32_t entry_ea);
static uint32_t gk_task_resume_function_ea(uint32_t module_slot,
                                           uint32_t entry_ea, uint32_t pc) {
    const uint32_t entry = gk_image_entry_offset(module_slot, entry_ea);
    if (entry == 0x1ef6cu && pc == 0x2fb88u) return 0x2fa4cu; // StateDriver frame park
    if (entry == 0x28108u && pc == 0x28758u) return 0x28108u; // WaitSignal
    if (entry == 0x1fe9cu && pc == 0x1ff90u) return 0x1fe9cu; // WaitPort
    if (entry == 0x692a0u && pc == 0x692f8u) return 0x692a0u; // DataStream WaitSignal
    if (entry == 0x1726cu && (pc == 0x18d0cu || pc == 0x18ea4u))
        return 0x1726cu; // track-init waits
    if (entry == 0x0b054u && pc == 0x0b7c8u) return 0x0b054u; // timer wait
    return 0;
}

// Guarded callback: the guard frame in m2_guest_exit_guard_run stays live
// while the lifted entry runs, so a guest exit#8 can unwind to it.
typedef struct gk_guest_call {
    RecompFn fn;
} gk_guest_call;

static int32_t gk_guest_call_run(PPCContext* c, void* user) {
    gk_guest_call* call = (gk_guest_call*)user;
    call->fn(c);
    return 0;
}

static uint32_t gk_image_text_base(uint32_t slot) {
    if (slot == GK_MODULE_SHOOTER2D) return g_shooter2d_recomp_text_base;
    if (slot == GK_MODULE_SHELL) return g_launchme_recomp_text_base;
    return g_recomp_text_base;
}

static uint32_t gk_image_text_size(uint32_t slot) {
    if (slot == GK_MODULE_SHOOTER2D) return g_shooter2d_recomp_text_size;
    if (slot == GK_MODULE_SHELL) return g_launchme_recomp_text_size;
    return g_recomp_text_size;
}

static RecompFn gk_image_lookup(uint32_t slot, uint32_t guest_ea) {
    if (slot == GK_MODULE_SHOOTER2D)
        return recomp_lookup_shooter2d(guest_ea);
    if (slot == GK_MODULE_SHELL)
        return recomp_lookup_launchme(guest_ea);
    if (slot == GK_MODULE_GAME)
        return recomp_lookup(guest_ea);
    return NULL;
}

static uint32_t gk_image_entry_offset(uint32_t slot, uint32_t entry_ea) {
    const uint32_t base = gk_image_text_base(slot);
    const uint32_t size = gk_image_text_size(slot);
    if (entry_ea >= base && entry_ea - base < size)
        return entry_ea - base;
    if (entry_ea < size) return entry_ea;
    return entry_ea;
}

static RecompFn gk_resolve_entry(uint32_t entry_ea, uint32_t preferred_slot,
                                 uint32_t* resolved_slot_out) {
    if (entry_ea == 0) return NULL;
    for (uint32_t slot = 0; slot < GK_MODULE_COUNT; ++slot) {
        const uint32_t base = gk_image_text_base(slot);
        const uint32_t size = gk_image_text_size(slot);
        if (entry_ea >= base && entry_ea - base < size) {
            RecompFn fn = gk_image_lookup(slot, entry_ea);
            if (fn) {
                if (resolved_slot_out) *resolved_slot_out = slot;
                return fn;
            }
        }
    }
    if (preferred_slot < GK_MODULE_COUNT) {
        RecompFn fn = gk_image_lookup(preferred_slot, entry_ea);
        if (fn) {
            if (resolved_slot_out) *resolved_slot_out = preferred_slot;
            return fn;
        }
    }
    for (uint32_t slot = 0; slot < GK_MODULE_COUNT; ++slot) {
        if (slot == preferred_slot) continue;
        RecompFn fn = gk_image_lookup(slot, entry_ea);
        if (fn) {
            if (resolved_slot_out) *resolved_slot_out = slot;
            return fn;
        }
    }
    return NULL;
}

// Callback addresses are linked guest EAs. Relative continuation PCs use
// the current task image; an absolute EA always selects its owning image.
static RecompFn gk_lookup_callback(uint32_t guest_ea) {
    return gk_resolve_entry(guest_ea, gk_current_module_slot(), NULL);
}

static uint32_t gk_image_main_entry(uint32_t slot) {
    if (slot == GK_MODULE_GAME) return g_recomp_text_base + 0x1ef6cu;
    if (slot == GK_MODULE_SHOOTER2D) return g_shooter2d_recomp_text_base + 0x2a0u;
    // imsa_shell.c::main, the first function in LaunchMe.m2's .text at the
    // image link base (generated/launchme_recomp.h FN_launchme_main__00000).
    if (slot == GK_MODULE_SHELL) return g_launchme_recomp_text_base + 0x0u;
    return 0;
}

// Task body (extended entrypoint): fresh PPCContext sharing the bound guest
// RAM, deterministic stack carve, guest payload words in r3/r4. The body's r3
// classifies the task (>=0 completed, <0 failed) via the standard m2k join
// path; a guest exit#8 returns its status through the same terminal path.
static int32_t gk_task_body(m2k_context* kctx, void* user_data) {
    (void)kctx;
    gk_thread_spec* spec = (gk_thread_spec*)user_data;
    if (!gk_bound() || !spec || !spec->fn) return -1;
    uint32_t slot = (uint32_t)(spec - g_gk.specs);
    const int32_t previous_module_slot = gk_tls_module_slot;
    if (spec->module_slot >= GK_MODULE_COUNT) return -1;
    gk_tls_module_slot = (int32_t)spec->module_slot;
    RecompFn fn = spec->fn;
    const uint32_t entry = gk_image_entry_offset(spec->module_slot,
                                                  spec->entry_ea);
    const int video_task = entry == 0x64b88u;
    const int resumed = spec->resume_ea != 0;
    if (resumed) {
        fn = gk_resolve_entry(spec->resume_ea, spec->module_slot, NULL);
        if (!fn) {
            gk_tls_module_slot = previous_module_slot;
            gk_module_task_release(spec->module_slot, spec->module_item);
            return -1;
        }
        printf("[guest] task slot=%u resuming entry=%#x at pc=%#x\n",
               slot, spec->entry_ea, spec->ctx.pc);
        spec->ctx.mem = g_gk.cpu->mem;
        m2_guest_resume_begin(&spec->ctx, spec->resume_ea);
    } else {
        snprintf(gk_cwd_slot_for_current_task(), GK_CWD_MAX, "%s", spec->initial_cwd);
        printf("[guest] task slot=%u entry=%p starting (arg=%#x)\n",
               slot, (void*)spec->fn, spec->arg);
        memset(&spec->ctx, 0, sizeof(spec->ctx));
        spec->ctx.mem = g_gk.cpu->mem;
        spec->ctx.gpr[13] = 0;   // flat small-data model, same as the boot context
        spec->ctx.gpr[1] = GK_TASK_STACK_BASE +
                    (slot + 1) * GK_TASK_STACK_SIZE;
        spec->ctx.gpr[3] = spec->arg;
        spec->ctx.gpr[4] = spec->argp;
        spec->has_ctx = 1;
    }
    if (entry == 0x60d6cu)
        gk_mpeg_wait_for_stream_startup();
    gk_guest_call call = { fn };
    int32_t exit_status = 0;
    const int guest_exit = m2_guest_exit_guard_run(gk_guest_call_run, &spec->ctx,
                                                   &call, &exit_status);
    if (video_task) gk_mpeg_video_startup_abort();
    int32_t ret;
    if (guest_exit) {
        spec->ctx.gpr[3] = (uint32_t)exit_status;
        printf("[guest] task slot=%u exit#8 status=%d\n", slot, exit_status);
        ret = exit_status;   // m2k classifies <0 as FAILED, else COMPLETED
    } else {
        printf("[guest] task slot=%u completed r3=%#x\n", slot, spec->ctx.gpr[3]);
        ret = (int32_t)spec->ctx.gpr[3];
    }
    // Portfolio deletes Items owned by a task before publishing its death to
    // the parent.  Apply that platform boundary only to lifted guest tasks;
    // host compatibility tests intentionally retain their own fixtures.  A
    // guest exit#8 crosses the same boundary as a normal return, so both
    // terminal paths must reclaim before the status message reaches the
    // parent.
    const int32_t reclaimed = m2k_reclaim_current_task_items(kctx);
    if (reclaimed < 0)
        fprintf(stderr, "[guest] task slot=%u item reclaim rc=%d\n",
                slot, reclaimed);
    gk_tls_module_slot = previous_module_slot;
    gk_module_task_release(spec->module_slot, spec->module_item);
    // keep ctx for savestate, but mark not busy? The task will be joined and deleted, so keep has_ctx for now
    return ret;
}

static int gk_free_spec_slot(void) {
    // A spec is pinned from create until its task handle stops resolving
    // (delete refuses live threads), so a recycled slot can never alias a
    // running body's state.
    for (uint32_t i = 0; i < M2K_MAX_TASKS; ++i) {
        gk_thread_spec* s = &g_gk.specs[i];
        if (!s->busy) return (int)i;
        if (s->task != M2K_ITEM_NONE && gk_task_terminal(s->task)) {
            gk_reclaim_terminal_task(s->task);
            return (int)i;
        }
    }
    return -1;
}

// Portfolio's CreateThread passes TAG_NOP when pri is zero. Task creation
// then inherits the current task's priority; the initial operator task starts
// at 200 (M2 SDK kernel/task.c). Preserve that value before publishing the
// TaskNode, since guest code reads n_Priority to derive worker priorities.
static uint8_t gk_thread_priority(uint32_t requested) {
    if (requested != 0) return (uint8_t)requested;
    uint8_t inherited = 200;
    const m2k_item_t creator = m2k_current_task_item(g_gk.kctx);
    if (creator != M2K_ITEM_NONE)
        (void)m2k_task_priority(g_gk.kctx, creator, &inherited);
    return inherited;
}

typedef struct gk_task_tags {
    uint32_t argc;
    uint32_t argv;
    uint32_t cmdstr;
    uint8_t has_argc;
    uint8_t has_argv;
    uint8_t has_cmdstr;
    uint32_t msgfromchild;   // creator's message port (tag 19)
    uint8_t has_msgfromchild;
} gk_task_tags;

static int gk_task_tag_add(gk_task_tags* tags, uint32_t tag, uint32_t value) {
    if (tag == 0 || tag == 1) return 1;  // TAG_END / TAG_NOP
    if (tag == GK_TAG_ARGC) {
        tags->argc = value;
        tags->has_argc = 1;
        return 1;
    }
    if (tag == GK_TAG_ARGP) {
        tags->argv = value;
        tags->has_argv = 1;
        return 1;
    }
    if (tag == GK_TAG_CMDSTR) {
        tags->cmdstr = value;
        tags->has_cmdstr = 1;
        return 1;
    }
    // CREATETASK_TAG_MSGFROMCHILD: the kernel sends this task's exit status to
    // the named port when it terminates. imsa_shell.c's own main passes it as
    // the only CreateTaskVA tag, so it is the whole parent/child contract of
    // the disc's launcher.
    if (tag == GK_TAG_MSGFROMCHILD) {
        tags->msgfromchild = value;
        tags->has_msgfromchild = 1;
        return 1;
    }
    // Portfolio ignores application-defined tags above TAG_USER; small
    // unknown tags are malformed for this bounded task-creation surface.
    return tag >= 0x10000u;
}

static int gk_task_tags_from_list(uint32_t tags_ea, gk_task_tags* out) {
    memset(out, 0, sizeof(*out));
    if (tags_ea == 0) return 1;
    if (!gk_bound()) return 0;
    for (uint32_t i = 0; i < 32u; ++i) {
        const uint32_t at = tags_ea + i * 8u;
        if (at < tags_ea || at > RECOMP_GUEST_MEM - 8u) return 0;
        const uint32_t tag = rd32(g_gk.cpu, at);
        if (tag == 0) return 1;
        const uint32_t value = rd32(g_gk.cpu, at + 4u);
        if (!gk_task_tag_add(out, tag, value)) return 0;
    }
    return 0;  // no TAG_END within the fixed bound
}

static int gk_task_cmdline_args(uint32_t task_slot, uint32_t cmdstr_ea,
                                uint32_t* argc_out, uint32_t* argv_out) {
    // Task stacks are carved at GK_TASK_STACK_BASE + (slot + 1) * 0x10000, so
    // the twelfth slot's stack occupies 0x2b0000..0x2c0000. The argv staging
    // sits above that run and below the guest object carves at 0x300400.
    enum { CMD_CAP = 1024u, ARG_CAP = 64u,
           ARG_BASE = 0x002c0000u, ARG_STRIDE = 0x1000u };
    if (!gk_bound() || task_slot >= M2K_MAX_TASKS || cmdstr_ea == 0)
        return 0;
    char command[CMD_CAP];
    const int32_t copied = m2m_copy_guest_string_ctx(
        g_gk.cpu, cmdstr_ea, command, sizeof(command));
    if (copied < 0) return 0;
    const uint32_t base = ARG_BASE + task_slot * ARG_STRIDE;
    const uint32_t string_bytes = (uint32_t)copied + 1u;
    const uint32_t argv_ea = base + ((string_bytes + 7u) & ~7u);
    if (base > RECOMP_GUEST_MEM ||
        ARG_STRIDE > RECOMP_GUEST_MEM - base ||
        argv_ea + (ARG_CAP + 1u) * 4u > base + ARG_STRIDE)
        return 0;
    memcpy(g_gk.cpu->mem + base, command, string_bytes);
    uint32_t argc = 0;
    uint32_t offset = 0;
    for (;;) {
        while (offset < string_bytes && g_gk.cpu->mem[base + offset] == ' ')
            ++offset;
        if (offset >= string_bytes || g_gk.cpu->mem[base + offset] == 0) break;
        if (argc == ARG_CAP) return 0;
        uint8_t terminator = ' ';
        if (g_gk.cpu->mem[base + offset] == '"') {
            ++offset;
            terminator = '"';
        }
        wr32(g_gk.cpu, argv_ea + argc * 4u, base + offset);
        ++argc;
        while (offset < string_bytes && g_gk.cpu->mem[base + offset] != 0 &&
               g_gk.cpu->mem[base + offset] != terminator)
            ++offset;
        if (offset < string_bytes && g_gk.cpu->mem[base + offset] == terminator)
            g_gk.cpu->mem[base + offset++] = 0;
    }
    wr32(g_gk.cpu, argv_ea + argc * 4u, 0);
    gk_record_guest_host_write(base, argv_ea + (argc + 1u) * 4u - base,
                               g_gk_selector_pc);
    *argc_out = argc;
    *argv_out = argv_ea;
    return 1;
}

static uint32_t gk_spawn_task(uint32_t code_ea, uint32_t name_ea,
                              uint32_t pri, uint32_t stack_size,
                              uint32_t preferred_module_slot,
                              uint32_t required_module_item,
                              uint32_t arg, uint32_t argp,
                              uint32_t cmdstr_ea, int use_staged_args,
                              uint32_t msgfromchild_port,
                              const char* call_name) {
    (void)name_ea;
    (void)stack_size;
    if (!gk_bound() || code_ea == 0) return M2K_ITEM_NONE;
    uint32_t module_slot = preferred_module_slot;
    RecompFn fn = gk_resolve_entry(code_ea, preferred_module_slot,
                                   &module_slot);
    if (!fn) {
        fprintf(stderr, "[m2k] %s fail: unresolved entry=%#x preferred-module=%u\n",
                call_name, code_ea, preferred_module_slot);
        return M2K_ITEM_NONE;
    }
    const int slot = gk_free_spec_slot();
    if (slot < 0) {
        fprintf(stderr, "[m2k] %s fail: no task slot\n", call_name);
        return M2K_ITEM_NONE;
    }
    if (cmdstr_ea != 0) {
        if (!gk_task_cmdline_args((uint32_t)slot, cmdstr_ea, &arg, &argp)) {
            fprintf(stderr, "[m2k] %s fail: invalid CREATETASK_TAG_CMDSTR\n",
                    call_name);
            return M2K_ITEM_NONE;
        }
    } else if (use_staged_args && g_gk_main_argv_ea != 0) {
        arg = g_gk_main_argc;
        argp = g_gk_main_argv_ea;
        g_gk_main_argv_ea = 0;
    }
    uint32_t module_item = 0;
    if (!gk_module_task_acquire(module_slot, required_module_item,
                                &module_item)) {
        fprintf(stderr, "[m2k] %s fail: stale module Item %#x\n",
                call_name, required_module_item);
        return M2K_ITEM_NONE;
    }
    const uint32_t entry = gk_image_entry_offset(module_slot, code_ea);
    if (module_slot == GK_MODULE_GAME && entry == 0x692a0u)
        gk_mpeg_startup_reset();
    else if (module_slot == GK_MODULE_GAME && entry == 0x64b88u)
        gk_mpeg_startup_arm_video_gate();

    gk_thread_spec* spec = &g_gk.specs[slot];
    memset(spec, 0, sizeof(*spec));
    spec->busy = 1;
    spec->fn = fn;
    spec->arg = arg;
    spec->argp = argp;
    spec->entry_ea = code_ea;
    spec->module_slot = module_slot;
    spec->module_item = module_item;
    spec->has_ctx = 0;
    // Snapshot before the child starts; recycled slots must not retain an old cwd.
    snprintf(spec->initial_cwd, sizeof(spec->initial_cwd), "%s",
             gk_cwd_slot_for_current_task());
    const m2k_item_t task = m2k_create_task_ex_notify_priority(
        g_gk.kctx, gk_task_body, spec, gk_thread_priority(pri),
        msgfromchild_port, M2K_ITEM_NONE);
    if (task == M2K_ITEM_NONE) {
        gk_module_task_release(module_slot, module_item);
        memset(spec, 0, sizeof(*spec));
        fprintf(stderr, "[m2k] %s fail: task creation returned NONE\n",
                call_name);
        return M2K_ITEM_NONE;
    }
    spec->task = task;
    printf("[m2k] %s task created slot=%u image=%u entry=%#x\n",
           call_name, m2k_handle_slot(task), module_slot, code_ea);
    return task;
}

static uint32_t gk_CreateThread(uint32_t code_ea, uint32_t name_ea,
                                uint32_t pri, uint32_t stack_size,
                                uint32_t tags_ea) {
    if (gk_state2_input_diag_enabled()) {
        fprintf(stderr,
                "[gk-input] CreateThread pc=%#x code=%#x name=%#x pri=%#x stack=%#x tags=%#x\n",
                g_gk_selector_pc, code_ea, name_ea, pri, stack_size, tags_ea);
    }
    return gk_spawn_task(code_ea, name_ea, pri, stack_size,
                         gk_current_module_slot(), 0, 0, 0, 0, 1, 0,
                         "CreateThread");
}

// CreateThreadVA (kernel 84) per the Portfolio prototype (portfolio_os_m2
// kernel/task.h):
//   Item CreateThreadVA(void (*code)(), const char *name, uint8 pri,
//                       int32 stackSize, uint32 tag, ...);
// Sole generated caller NewThread (guest 0x6ac14 -> selector site 0x6ac4c)
// shuffles its args into exactly this window before trapping: r3 passes
// through untouched and both sites pass lifted thread-body starts
// (FN_DataStreamThread__692a0 / FN_DataAcqThread__6a388), old-r6 lands in
// r4 (name), (old-r4+7)&~7 rounds the stack into r6, tags
// 14=CREATETASK_TAG_ARGC / 15=CREATETASK_TAG_ARGP carry old-r7/old-r8, and a
// TAG_END word is stored at 8(sp). The code EA resolves against the caller's
// image first; every other operand stays a fixed-width guest value.
//
// Generated bl sites resolve lifted functions with image-space keys:
// key = GK_RELOC_TEXT_BASE | module-relative guest EA (transpile.py
// TEXT_BASE; e.g. NewThread itself looks up 0x16ac14 for guest 0x6ac14).
static uint32_t gk_CreateThreadVA(uint32_t code_ea, uint32_t name_ea,
                                   uint32_t pri, uint32_t stack_size,
                                   uint32_t tag_a, uint32_t val_a,
                                   uint32_t tag_b, uint32_t val_b) {
    uint32_t module_slot = gk_current_module_slot();
    uint32_t arg = 0;
    uint32_t argp = 0;
    uint32_t resolved_slot = module_slot;
    (void)name_ea; (void)stack_size;   // recorded operands only
    printf("[m2k] CreateThreadVA attempt code=%#x pri=%u stack=%#x tags=%u:%#x %u:%#x\n",
           code_ea, pri, stack_size, tag_a, val_a, tag_b, val_b);
    if (!gk_bound()) {
        printf("[m2k] CreateThreadVA fail: not bound\n");
        return M2K_ITEM_NONE;
    }
    RecompFn fn = gk_resolve_entry(code_ea, module_slot, &resolved_slot);
    if (!fn) {
        printf("[m2k] CreateThreadVA fail: unknown entry %#x module=%u\n",
               code_ea, module_slot);
        return M2K_ITEM_NONE;
    }
    (void)fn;
    if (tag_a == GK_TAG_ARGC) arg = val_a;
    else if (tag_a == GK_TAG_ARGP) argp = val_a;
    if (tag_b == GK_TAG_ARGC) arg = val_b;
    else if (tag_b == GK_TAG_ARGP) argp = val_b;
    return gk_spawn_task(code_ea, name_ea, pri, stack_size, resolved_slot,
                         0, arg, argp, 0, 0, 0, "CreateThreadVA");
}

static uint32_t gk_CreateTaskCommon(uint32_t module_item, uint32_t name_ea,
                                    const gk_task_tags* tags) {
    const int module_slot = gk_module_slot_for_item(module_item, 1);
    if (module_slot < 0) return (uint32_t)M2M_ERR_BAD_ITEM;
    if (name_ea != 0) {
        char name[GK_MAX_NAME_LEN];
        const int32_t rc = m2m_copy_guest_string_ctx(
            g_gk.cpu, name_ea, name, sizeof(name));
        if (rc < 0) return (uint32_t)M2M_ERR_RANGE;
    }
    uint32_t argc = tags->argc;
    uint32_t argv = tags->argv;
    const int use_staged = !tags->has_argc && !tags->has_argv &&
                           !tags->has_cmdstr;
    const uint32_t entry_ea = gk_image_main_entry((uint32_t)module_slot);
    // CREATETASK_TAG_MSGFROMCHILD names a real message port; an Item-less or
    // non-port value is a malformed tag for this bounded surface, exactly as
    // an unusable module Item is refused above.
    uint32_t msgfromchild = 0;
    if (tags->has_msgfromchild) {
        if (tags->msgfromchild == 0 ||
            m2k_handle_type(tags->msgfromchild) != M2K_TYPE_MSGPORT)
            return (uint32_t)M2M_ERR_BAD_ITEM;
        msgfromchild = tags->msgfromchild;
    }
    const uint32_t task = gk_spawn_task(entry_ea, name_ea, 0, 0,
                                        (uint32_t)module_slot, module_item,
                                        argc, argv,
                                        tags->has_cmdstr ? tags->cmdstr : 0,
                                        use_staged, msgfromchild, "CreateTask");
    // The host frame pump follows the guest's own application task. Under the
    // imsa_shell boot that task is created by the launcher's CreateTaskVA /
    // CreateTask, not by the host, so publication happens here rather than in
    // m2_game_entry. imsa_shell itself never publishes: it is the launcher,
    // not an application.
    if (task != M2K_ITEM_NONE && module_slot != GK_MODULE_SHELL)
        m2_guest_publish_main_task((uint32_t)module_slot, task, module_item);
    return task;
}

static uint32_t gk_CreateTask(uint32_t module_item, uint32_t name_ea,
                              uint32_t tags_ea) {
    gk_task_tags tags;
    if (!gk_task_tags_from_list(tags_ea, &tags))
        return (uint32_t)M2M_ERR_RANGE;
    return gk_CreateTaskCommon(module_item, name_ea, &tags);
}

static uint32_t gk_CreateTaskVA(uint32_t module_item, uint32_t name_ea,
                                uint32_t tag_a, uint32_t val_a,
                                uint32_t tag_b, uint32_t val_b,
                                uint32_t tag_c, uint32_t val_c) {
    gk_task_tags tags;
    memset(&tags, 0, sizeof(tags));
    const uint32_t pair[][2] = {{tag_a, val_a}, {tag_b, val_b},
                                {tag_c, val_c}};
    int ended = 0;
    for (uint32_t i = 0; i < sizeof(pair) / sizeof(pair[0]); ++i) {
        if (pair[i][0] == 0) { ended = 1; break; }
        if (!gk_task_tag_add(&tags, pair[i][0], pair[i][1]))
            return (uint32_t)M2M_ERR_RANGE;
    }
    if (!ended) return (uint32_t)M2M_ERR_RANGE;
    return gk_CreateTaskCommon(module_item, name_ea, &tags);
}

// ---- binding + template -------------------------------------------------------------

static void gk_reset_pools(void) {
    gk_display_clear(0);
    gk_gstate_vbl_reset();
    gk_audio_clock_reset();
    gk_mpeg_startup_reset();
    pthread_mutex_lock(&g_mpeg_lock);
    memset(g_mpeg_pending_reads, 0, sizeof(g_mpeg_pending_reads));
    memset(g_mpeg_pending_writes, 0, sizeof(g_mpeg_pending_writes));
    g_mpeg_pending_read_count = 0;
    g_mpeg_pending_write_count = 0;
    g_mpeg_strip_buffer_io = M2K_ITEM_NONE;
    g_mpeg_reference_buffer_io = M2K_ITEM_NONE;
    g_mpeg_dest_bitmap_item = 0;
    g_mpeg_bitstream_len = 0;
    g_mpeg_ref_capacity = 0u;
    g_mpeg_strip_capacity = 0u;
    g_mpeg_ref_client_control = 0;
    g_mpeg_strip_client_control = 0;
    pthread_mutex_unlock(&g_mpeg_lock);
    (void)gk_mpeg_configure_buffer_limits();
    // DSPP resource addresses live in one M2-wide data-memory allocator. Tear
    // down live sims before clearing Item records so their ranges are
    // released before the shared image is discarded.
    for (uint32_t i = 0; i < GK_MAX_ITEMS; ++i)
        gk_dsp_sim_destroy_for(&g_gk.items[i]);
    dspp_sim_space_destroy(g_gk.audio_dsp_space);
    g_gk.audio_dsp_space = NULL;
    // Mixer-output carrier reservations die with the space; clear the host
    // table too or stale handles would consume slots across rebinds.
    memset(gk_mixnode_word_res, 0, sizeof(gk_mixnode_word_res));
    memset(g_gk.small, 0, sizeof(g_gk.small));
    memset(g_gk.items, 0, sizeof(g_gk.items));
    memset(g_gk.connections, 0, sizeof(g_gk.connections));
    gk_mix_graph_touch();
    memset(g_gk_patches, 0, sizeof(g_gk_patches));
    memset(g_gk.specs, 0, sizeof(g_gk.specs));
    memset(g_iff_states, 0, sizeof(g_iff_states));
    memset(g_gk.broker_used, 0, sizeof(g_gk.broker_used));
    gk_close_all_files();
    memset(g_dir_slots, 0, sizeof(g_dir_slots));
    g_dir_gen = 0;
    memset(g_cwd_slots, 0, sizeof(g_cwd_slots));
    g_cwd_gen = 0;
    // Every task's current directory starts at the volume root, which is what
    // a fresh FileFolioTaskData gets from SetupFileFolioTaskData.
    memset(g_cwd_paths, 0, sizeof(g_cwd_paths));
    m2_guest_exit_pending_clear();   // no stale unguarded exit#8 across rebinds
    m2m_init(&g_gk.m2m);
    pthread_mutex_lock(&gk_module_lock);
    memset(gk_modules, 0, sizeof(gk_modules));
    for (uint32_t i = 0; i < GK_MODULE_COUNT; ++i)
        gk_modules[i].generation = 1;
    pthread_mutex_unlock(&gk_module_lock);
    gk_tls_module_slot = -1;
    gk_boot_module_slot = GK_MODULE_GAME;
    gk_boot_module_item = 0;
    g_gk.small_gen = 0;
    g_gk.item_gen = 0;
    memset(g_find_reg, 0, sizeof(g_find_reg));
    g_last_generic_item = 0;
    g_gk.te_write = 0;
    g_gk.te_read = 0;
    g_gk.te_view_item = 0;
    g_gk.te_framebuffer_item = 0;
    g_gk.te_zbuffer_item = 0;
    g_gk.te_z_fill_word = 0u;
    g_gk.te_fb_clear_red_word = 0u;
    g_gk.te_fb_clear_green_word = 0u;
    g_gk.te_fb_clear_blue_word = 0u;
    g_gk.te_fb_clear_alpha_word = 0u;
    g_gk.audio_frame_low = 0;
    g_gk.audio_mixer_half[0] = 0;
    g_gk.audio_mixer_half[1] = 0;
    g_gk.audio_knob_set_serial = 0;
    // Trigger -> Cue map is per-space state: a rebind starts disarmed so a
    // recycled slot/generation can never deliver a stale armed cue.
    memset(gk_trigger_cue, 0, sizeof(gk_trigger_cue));
    gk_trigger_armed = 0;
    g_gk.audio_daemon_signals = 0;
    g_gk.audio_dma_completed = 0;
    gk_gmixer[0] = 0;
    gk_gmixer[1] = 0;
    pthread_mutex_lock(&gk_heap_lock);
    free(g_gk.heap_blocks);
    g_gk.heap_blocks = NULL;
    g_gk.heap_block_count = 0;
    g_gk.heap_block_capacity = 0;
    g_gk.heap_next = GK_HEAP_BASE;
    memset(g_gk.heap_owned_pages, 0, sizeof(g_gk.heap_owned_pages));
    pthread_mutex_unlock(&gk_heap_lock);
    if (g_gk.cpu) {
        gk_init_broker_memory(g_gk.cpu);
        gk_install_kernel_ctype(g_gk.cpu);
        if (GK_TASK_OBJECT_BASE + M2K_MAX_TASKS * GK_TASK_OBJECT_STRIDE <=
            RECOMP_GUEST_MEM) {
            memset(g_gk.cpu->mem + GK_TASK_OBJECT_BASE, 0,
                   M2K_MAX_TASKS * GK_TASK_OBJECT_STRIDE);
            gk_record_guest_host_write(
                GK_TASK_OBJECT_BASE,
                M2K_MAX_TASKS * GK_TASK_OBJECT_STRIDE, g_gk_selector_pc);
        }
        if (GK_IOREQ_OBJECT_BASE + M2K_MAX_IOREQS * GK_IOREQ_OBJECT_STRIDE <=
            RECOMP_GUEST_MEM) {
            memset(g_gk.cpu->mem + GK_IOREQ_OBJECT_BASE, 0,
                   M2K_MAX_IOREQS * GK_IOREQ_OBJECT_STRIDE);
            gk_record_guest_host_write(
                GK_IOREQ_OBJECT_BASE,
                M2K_MAX_IOREQS * GK_IOREQ_OBJECT_STRIDE, g_gk_selector_pc);
        }
        if (GK_BITMAP_OBJECT_BASE + GK_MAX_ITEMS * GK_BITMAP_OBJECT_STRIDE <=
            RECOMP_GUEST_MEM) {
            memset(g_gk.cpu->mem + GK_BITMAP_OBJECT_BASE, 0,
                   GK_MAX_ITEMS * GK_BITMAP_OBJECT_STRIDE);
            gk_record_guest_host_write(
                GK_BITMAP_OBJECT_BASE,
                GK_MAX_ITEMS * GK_BITMAP_OBJECT_STRIDE, g_gk_selector_pc);
        }
        if (GK_VIEW_OBJECT_BASE + GK_MAX_ITEMS * GK_VIEW_OBJECT_STRIDE <=
            RECOMP_GUEST_MEM) {
            memset(g_gk.cpu->mem + GK_VIEW_OBJECT_BASE, 0,
                   GK_MAX_ITEMS * GK_VIEW_OBJECT_STRIDE);
            gk_record_guest_host_write(
                GK_VIEW_OBJECT_BASE,
                GK_MAX_ITEMS * GK_VIEW_OBJECT_STRIDE, g_gk_selector_pc);
        }
    }
}

// Raw control-port bit masks live in ../include/m2_cport_bits.h. The guest's map tables at those EAs are
// SHIPPED .data content, passed by guest code (StateDriver@0x02fa4c); the host
// must not author or repair them. A previous host-authored seeding routine was
// removed because it targeted .bss addresses the guest never references
// (`guest_xref.py data 0x1866a8` -> none), was gated on an all-zero test the
// shipped image never satisfies, and disagreed with the shipped values at the
// .data EAs it also wrote. See the guest core structure notes.

void m2_guest_input_set_cport(uint32_t buttons, uint8_t stick_x, uint8_t stick_y) {
    // This bridge intentionally exposes the raw host ControlPort sample to
    // the guest. Edge interpretation belongs to the lifted controls/state
    // code; do not synthesize menu transitions here.
    if (!g_gk.cpu || !g_gk.cpu->mem) return;
    if (!g_cport_edge_publish) {
        // Raw callers (including frozen regression drivers) request an exact
        // immediate level and therefore supersede any live pending edge.
        g_cport_current_buttons = buttons;
        g_cport_pending_pressed = 0u;
        g_cport_current_stick_x = stick_x;
        g_cport_current_stick_y = stick_y;
    }

    // Map modern/host CportBits for digital ControlPad (dev_type == 0, offset 0x0c)
    uint32_t raw_pad = 0;
    if (buttons & (1u << 0)) raw_pad |= M2_CPORT_A;
    if (buttons & (1u << 1)) raw_pad |= M2_CPORT_B;
    if (buttons & (1u << 2)) raw_pad |= M2_CPORT_C;
    if (buttons & (1u << 3)) raw_pad |= M2_CPORT_START;
    if (buttons & (1u << 4)) raw_pad |= M2_CPORT_L;
    if (buttons & (1u << 5)) raw_pad |= M2_CPORT_R;
    if (buttons & (1u << 6)) raw_pad |= M2_CPORT_X;
    if (buttons & (1u << 12)) raw_pad |= M2_CPORT_D;
    if (buttons & (1u << 13)) raw_pad |= M2_CPORT_E;
    if (buttons & (1u << 14)) raw_pad |= M2_CPORT_F;
    if (buttons & M2_HOST_DPAD_UP) raw_pad |= M2_CPORT_UP;
    if (buttons & M2_HOST_DPAD_DOWN) raw_pad |= M2_CPORT_DOWN;
    if (buttons & M2_HOST_DPAD_LEFT) raw_pad |= M2_CPORT_LEFT;
    if (buttons & M2_HOST_DPAD_RIGHT) raw_pad |= M2_CPORT_RIGHT;

    // Analog StickEventData button word. The guest's Joy_TranslateInput tests
    // these left-justified bits; the physical binding that produced the action
    // is irrelevant, exactly as for the ControlPad word above.
    uint32_t raw_stick = 0;
    if (buttons & (1u << 0)) raw_stick |= M2_STICK_A;
    if (buttons & (1u << 1)) raw_stick |= M2_STICK_B;
    if (buttons & (1u << 2)) raw_stick |= M2_STICK_C;
    if (buttons & (1u << 3)) raw_stick |= M2_STICK_PLAY;
    if (buttons & (1u << 4)) raw_stick |= M2_STICK_LEFTSHIFT;
    if (buttons & (1u << 5)) raw_stick |= M2_STICK_RIGHTSHIFT;
    if (buttons & (1u << 6)) raw_stick |= M2_STICK_FIRE;
    if (buttons & M2_HOST_DPAD_UP) raw_stick |= M2_STICK_UP;
    if (buttons & M2_HOST_DPAD_DOWN) raw_stick |= M2_STICK_DOWN;
    if (buttons & M2_HOST_DPAD_LEFT) raw_stick |= M2_STICK_LEFT;
    if (buttons & M2_HOST_DPAD_RIGHT) raw_stick |= M2_STICK_RIGHT;

    // Ensure primary device pointer in devlist points to GK_BROKER_DESCRIPTOR_EA
    if (0x184cf4u + 4 <= RECOMP_GUEST_MEM) {
        uint32_t devlist = rd32(g_gk.cpu, 0x184cf4u);
        if (devlist != 0 && devlist + 0x6c <= RECOMP_GUEST_MEM) {
            uint32_t cur_dev = rd32(g_gk.cpu, devlist + 0x68);
            if (cur_dev < 0x10000 || cur_dev == GK_BROKER_STR_EA) {
                wr32(g_gk.cpu, devlist + 0x68, GK_BROKER_DESCRIPTOR_EA);
            }
        }
    }

    // Publish the raw left-justified ControlPad level, exactly as the vendor
    // pod driver does (ControlPadDriver.c:285 writes pod_PrivateData[0], the
    // decoded bits masked 0xFFFC0000, into cped_ButtonBits). Both games
    // consume this word unchanged: racing's Cpad_TranslateInput indexes its
    // shipped .data table by raw bit position (31..18), and shooter2d's
    // dispatch tests the same raw bits directly (rlwinm mb=me masks at
    // 0xc28/0xd14 = 0x08000000 A, 0xd24 = 0x20000000 RIGHT,
    // 0xd34 = 0x10000000 LEFT, 0xd44 = 0x40000000 UP, 0xd54 = 0x80000000
    // DOWN — decoded from the original image bytes with PPC's MSB-first
    // mask numbering, not LSB bit indices).
    wr32(g_gk.cpu, GK_BROKER_INPUT_DATA_EA + 0x0c, raw_pad);
    wr32(g_gk.cpu, GK_BROKER_INPUT_DATA_EA + 0x10, 0);
    wr32(g_gk.cpu, GK_BROKER_INPUT_DATA_EA + 0x14, 0);
    wr32(g_gk.cpu, GK_BROKER_TABLE_PAD_EA + 0x0c, raw_pad);
    wr32(g_gk.cpu, GK_BROKER_TABLE_PAD_EA + 0x10, 0u);
    wr32(g_gk.cpu, GK_BROKER_TABLE_PAD_EA + 0x14, 0u);
    wr32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x10, raw_stick);
    if (gk_cport_word_axes_enabled()) {
        wr32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x14,
             (uint32_t)stick_x * 4u);
        wr32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x18,
             (uint32_t)stick_y * 4u);
        wr32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x1c, 0u);
    } else {
        wr8(g_gk.cpu,  GK_BROKER_STICK_DATA_EA + 0x14, stick_x);
        wr8(g_gk.cpu,  GK_BROKER_STICK_DATA_EA + 0x15, stick_y);
    }
    // Reserved word after the stick record; GetCPortData never consumes it.
    wr32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x20, 0u);

    // After-write diagnostic: axes values above reflect the sample just
    // written. The guest-side [secret-process-input] trace remains the
    // stronger observation (it reads the record at ProcessInput entry).
    if (getenv("M2_SECRET_INPUT_PROBE") && g_gk.cpu &&
        rd32(g_gk.cpu, 0x1877d8u) == 3u &&
        (rd32(g_gk.cpu, 0x1877dcu) == 17u ||
         rd32(g_gk.cpu, 0x1877dcu) == 18u)) {
        static uint32_t input_set_diag_n;
        if (input_set_diag_n < 32u) {
            fprintf(stderr,
                    "[gk-input] set_cport n=%u frame=%u buttons=%#x "
                    "stick=(%u,%u) raw=%#x axes=(%#x,%#x,%#x)\n",
                    input_set_diag_n + 1u,
                    rd32(g_gk.cpu, M2_GUEST_FRAME_COUNTER_EA), buttons,
                    stick_x, stick_y, raw_pad,
                    rd32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x14u),
                    rd32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x18u),
                    rd32(g_gk.cpu, GK_BROKER_STICK_DATA_EA + 0x1cu));
            ++input_set_diag_n;
        }
    }
}

void m2_guest_input_set_cport_edges(uint32_t buttons, uint32_t pressed,
                                    uint8_t stick_x, uint8_t stick_y) {
    g_cport_current_buttons = buttons;
    g_cport_pending_pressed |= pressed;
    g_cport_current_stick_x = stick_x;
    g_cport_current_stick_y = stick_y;
    g_cport_edge_publish = 1;
    m2_guest_input_set_cport(buttons | g_cport_pending_pressed,
                             stick_x, stick_y);
    g_cport_edge_publish = 0;
}

int m2_guest_kernel_bind(m2k_context* kctx, PPCContext* cpu) {
    if (!kctx || !cpu || !cpu->mem) return -1;
    g_gk.kctx = kctx;
    g_gk.cpu = cpu;
    g_cport_current_buttons = 0u;
    g_cport_pending_pressed = 0u;
    g_cport_current_stick_x = 128u;
    g_cport_current_stick_y = 128u;
    g_cport_edge_publish = 0;
    gk_reset_pools();
    return 0;
}

m2k_context* m2_guest_kernel_context(void) {
    return g_gk.kctx;
}

void m2_guest_kernel_unbind(void) {
    gk_reset_pools();
    g_gk.kctx = NULL;
    g_gk.cpu = NULL;
    g_cport_current_buttons = 0u;
    g_cport_pending_pressed = 0u;
    g_cport_current_stick_x = 128u;
    g_cport_current_stick_y = 128u;
    g_cport_edge_publish = 0;
}

// ---- Promoted handlers (call shapes proven from generated-lift windows) --
// 3DO Portfolio List (16-byte anchor, matches CreateDeviceStackList#67):
//   List { MinNode l_Anchor@0; MinNode* l_Head@4; MinNode* l_Tail@8;
//          MinNode* l_TailPred@12 }
// Empty: l_Head == &l_Tail (list+8), l_Tail == NULL, l_TailPred == &l_Head
// (list+4). The compiled empty check `*(list+4) == list+8` evaluates true.
// Node link = {n_Succ@0, n_Pred@4}; the anchors &l_Head / &l_Tail are valid
// "nodes" for the link pointers, so RemNode's generic unlink is self-consistent.
// All EAs bounds-checked against guest RAM; invalid EAs fail closed.

// kernel:37 PrepList — initialize a 16-byte List anchor in place. Return ignored.
static void gk_PrepList(uint32_t list_ea) {
    if (!gk_bound() || list_ea == 0 || list_ea + 16 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    wr32(cpu, list_ea + 0,  0);            // l_Anchor
    wr32(cpu, list_ea + 4,  list_ea + 8);  // l_Head = &l_Tail
    wr32(cpu, list_ea + 8,  0);            // l_Tail = NULL
    wr32(cpu, list_ea + 12, list_ea + 4);  // l_TailPred = &l_Head
}

// kernel:40 RemNode — unlink node r3 from whatever list it is in. Return ignored.
static void gk_RemNode(uint32_t node_ea) {
    if (!gk_bound() || node_ea == 0 || node_ea + 8 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    uint32_t succ = rd32(cpu, node_ea + 0);
    uint32_t pred = rd32(cpu, node_ea + 4);
    if (pred != 0 && pred + 8 <= RECOMP_GUEST_MEM) wr32(cpu, pred + 0, succ);
    if (succ != 0 && succ + 8 <= RECOMP_GUEST_MEM) wr32(cpu, succ + 4, pred);
    wr32(cpu, node_ea + 0, 0);
    wr32(cpu, node_ea + 4, 0);
}

// kernel:42 AddTail — link node r4 as the last element of list r3. Return ignored.
static void gk_AddTail(uint32_t list_ea, uint32_t node_ea) {
    if (!gk_bound() || list_ea == 0 || list_ea + 16 > RECOMP_GUEST_MEM ||
        node_ea == 0 || node_ea + 8 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    uint32_t pred = rd32(cpu, list_ea + 12);   // old l_TailPred
    wr32(cpu, node_ea + 0, list_ea + 8);        // n.succ = &l_Tail
    wr32(cpu, node_ea + 4, pred);               // n.pred = old l_TailPred
    if (pred == list_ea + 4)                    // was empty (pred == &l_Head)
        wr32(cpu, list_ea + 4, node_ea);        // l_Head = n
    else if (pred != 0 && pred + 8 <= RECOMP_GUEST_MEM)
        wr32(cpu, pred + 0, node_ea);           // old last.succ = n
    wr32(cpu, list_ea + 12, node_ea);           // l_TailPred = n
}

// kernel:43 RemTail — unlink + return the last node of list r3, or 0 when empty.
static uint32_t gk_RemTail(uint32_t list_ea) {
    if (!gk_bound() || list_ea == 0 || list_ea + 16 > RECOMP_GUEST_MEM) return 0;
    PPCContext* cpu = g_gk.cpu;
    uint32_t n = rd32(cpu, list_ea + 12);        // l_TailPred
    if (n == list_ea + 4) return 0;              // empty (n == &l_Head)
    if (n == 0 || n + 8 > RECOMP_GUEST_MEM) return 0;
    uint32_t prev = rd32(cpu, n + 4);
    wr32(cpu, list_ea + 12, prev);               // l_TailPred = prev
    if (prev != 0 && prev + 8 <= RECOMP_GUEST_MEM)
        wr32(cpu, prev + 0, list_ea + 8);        // prev.succ = &l_Tail
    wr32(cpu, n + 0, 0);
    wr32(cpu, n + 4, 0);
    return n;
}

// kernel:44 AddHead — link node r4 as the first element of list r3. Return ignored.
static void gk_AddHead(uint32_t list_ea, uint32_t node_ea) {
    if (!gk_bound() || list_ea == 0 || list_ea + 16 > RECOMP_GUEST_MEM ||
        node_ea == 0 || node_ea + 8 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    uint32_t succ = rd32(cpu, list_ea + 4);      // old l_Head
    wr32(cpu, node_ea + 0, succ);                // n.succ = old l_Head
    wr32(cpu, node_ea + 4, list_ea + 4);          // n.pred = &l_Head
    if (succ == list_ea + 8)                     // was empty (l_Head == &l_Tail)
        wr32(cpu, list_ea + 12, node_ea);        // l_TailPred = n
    else if (succ != 0 && succ + 8 <= RECOMP_GUEST_MEM)
        wr32(cpu, succ + 4, node_ea);            // old first.pred = n
    wr32(cpu, list_ea + 4, node_ea);              // l_Head = n
}

// kernel:45 RemHead — unlink + return the first node of list r3, or 0 when empty.
static uint32_t gk_RemHead(uint32_t list_ea) {
    if (!gk_bound() || list_ea == 0 || list_ea + 16 > RECOMP_GUEST_MEM) return 0;
    PPCContext* cpu = g_gk.cpu;
    uint32_t n = rd32(cpu, list_ea + 4);         // l_Head
    if (n == list_ea + 8) return 0;              // empty (n == &l_Tail)
    if (n == 0 || n + 8 > RECOMP_GUEST_MEM) return 0;
    uint32_t next = rd32(cpu, n + 0);
    wr32(cpu, list_ea + 4, next);                // l_Head = next
    if (next != 0 && next + 8 <= RECOMP_GUEST_MEM)
        wr32(cpu, next + 4, list_ea + 4);        // next.pred = &l_Head
    wr32(cpu, n + 0, 0);
    wr32(cpu, n + 4, 0);
    return n;
}

// ---- M2 time base (kernel 21/27) -------------------------------------------
// SampleSystemTimeTT samples the PowerPC time base.  Vendor source
// (`folios/kernel/timer.s`): read TBU (`mftbu`) and TBL (`mftb`), re-read TBU
// and retry while it changed (carry), then store TBU at +0 and TBL at +4.  The
// 8-byte record is the guest's `TimerTicks {uint32 tt_Hi; uint32 tt_Lo;}`
// (`includes/kernel/time.h`), a free-running 64-bit counter.  The host owns
// this clock (platform timing), so it is sourced from the host monotonic clock.
//
// ConvertTimerTicksToTimeVal converts that hardware-dependent count into a
// TimeVal using the kernel's own divisor (`folios/kernel/timer.c`):
//   tv_Seconds      = ticks / _ticksPerSecond
//   tv_Microseconds = ((ticks % _ticksPerSecond) * 1000000) / _ticksPerSecond
//
// `_ticksPerSecond` is the M2 time-base rate: `kernel.init/timer.c` seeds it
// from `si.si_TicksPerSec`; `others/bootcode/romsysinfo.c` publishes
// `BootGlobals.bg_TicksPerSec`; and `others/bootcode/bootvideo.c` derives the
// bus clock from the NTSC field count, rounds it to the nearest MHz, snaps to
// the preset table `{33333333, 66666667}` (33.333 MHz bus / 66.667 MHz CPU),
// and sets `bg_TicksPerSec = bg_BusClock / 4` ("1 tick per 4 bus cycles").
// 33333333 / 4 = 8333333 (integer, exactly as that source computes it).
//
// The absolute epoch is meaningless to the guest (the vendor header warns that
// the representation is hardware-dependent and only differences are usable), so
// the host clock's own epoch is used and only monotonic advance matters. The
// TimerDriver SETTIME_USEC command adds a guest-visible offset to that clock;
// this preserves the released SuperSetSystemTimeTT contract without changing
// the host monotonic source itself.
static _Atomic uint64_t gk_time_base_offset_ticks = ATOMIC_VAR_INIT(0);

static uint64_t gk_raw_monotonic_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

static uint64_t gk_raw_time_base_ticks(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    // Split the multiply so a long uptime cannot overflow the 64-bit tick
    // count: seconds * rate is exact, and the sub-second part is scaled at
    // nanosecond resolution before the divide.
    uint64_t ticks = (uint64_t)ts.tv_sec * M2_TIME_BASE_TICKS_PER_SECOND;
    ticks += ((uint64_t)ts.tv_nsec * M2_TIME_BASE_TICKS_PER_SECOND) / 1000000000ull;
    return ticks;
}

static void gk_timer_set_system_time(int32_t seconds, int32_t microseconds) {
    // ConvertTimeValToTimerTicks in the released kernel performs these
    // operations in uint64 arithmetic, including its deliberate acceptance of
    // negative fields. Mirror that modulo-2^64 representation exactly.
    const uint64_t sec = (uint64_t)(int64_t)seconds;
    const uint64_t usec = (uint64_t)(int64_t)microseconds;
    const uint64_t desired =
        sec * M2_TIME_BASE_TICKS_PER_SECOND +
        (usec * M2_TIME_BASE_TICKS_PER_SECOND) / 1000000ull;
    const uint64_t raw = gk_raw_time_base_ticks();
    atomic_store_explicit(&gk_time_base_offset_ticks, desired - raw,
                          memory_order_release);
}

static uint64_t gk_time_base_ticks(void) {
    return gk_raw_time_base_ticks() +
           atomic_load_explicit(&gk_time_base_offset_ticks,
                                memory_order_acquire);
}

// kernel:21 SampleSystemTimeTT — write the 8-byte TimerTicks (BE) to out ptr r3.
static void gk_SampleSystemTimeTT(uint32_t out_ea) {
    if (!gk_bound() || out_ea == 0 || out_ea + 8 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    const uint64_t ticks = gk_time_base_ticks();
    wr32(cpu, out_ea + 0, (uint32_t)(ticks >> 32));          // TBU (tt_Hi)
    wr32(cpu, out_ea + 4, (uint32_t)(ticks & 0xffffffffu));  // TBL (tt_Lo)
}

// kernel:27 ConvertTimerTicksToTimeVal — convert the 8-byte TimerTicks (r3)
// into the TimeVal {int32 tv_sec@0; int32 tv_usec@4} (r4) with the kernel's
// `_ticksPerSecond` divisor (see above).
static void gk_ConvertTimerTicksToTimeVal(uint32_t ticks_ea, uint32_t tv_ea) {
    if (!gk_bound() || ticks_ea == 0 || ticks_ea + 8 > RECOMP_GUEST_MEM ||
        tv_ea == 0 || tv_ea + 8 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    const uint64_t ticks = ((uint64_t)rd32(cpu, ticks_ea + 0) << 32) |
                            (uint64_t)rd32(cpu, ticks_ea + 4);
    const uint64_t remainder = ticks % M2_TIME_BASE_TICKS_PER_SECOND;
    wr32(cpu, tv_ea + 0,
         (uint32_t)(ticks / M2_TIME_BASE_TICKS_PER_SECOND));
    wr32(cpu, tv_ea + 4,
         (uint32_t)((remainder * 1000000ull) / M2_TIME_BASE_TICKS_PER_SECOND));
}

// kernel:48 SubTimerTicks(tt1 r3, tt2 r4, result r5) — vendor
// folios/kernel/timer.s:185-197:
//
//   lwz r7,4(r3); lwz r8,4(r4); subfco. r6,r7,r8   /* low word, sets carry */
//   lwz r7,0(r3); lwz r8,0(r4); subfe.  r7,r7,r8   /* high word, -= carry */
//   bge 0$                                         /* signed accept/reject */
//   li r6,0; mr r7,r6                              /* else zero both words */
//   0$: stw r6,4(r5); stw r7,0(r5)
//
// Word order: the routine's inline comments label `4(r)` "[32-63]" and `0(r)`
// "[0-31]", but those comments are wrong. `TimerTicks` is
// `struct { uint32 tt_Hi; uint32 tt_Lo; }` (M2 SDK kernel/time.h), so +0 is
// the high word and +4 the low word; `AddTimerTicks` in the same file confirms
// it by adding the `+4` word FIRST and propagating that carry into the `+0`
// word. This host models the same layout (gk_SampleSystemTimeTT above).
//
// Arithmetic: `subfco.` computes r6 = tt2_Lo - tt1_Lo with CA = 1 exactly when
// no borrow occurred; `subfe.` then computes r7 = tt2_Hi - tt1_Hi - (1 - CA).
// The source's guard is the signed 32-bit `bge` on the HIGH word, so a
// difference is kept only when its high word reads non-negative as int32.
// That is reproduced exactly, because the guest feeds the result straight into
// ConvertTimerTicksToTimeVal and the original clamping is observable.
// `result` may alias tt1 or tt2 (timer.s:161-163), so both operands are read
// before either word is written.
static void gk_SubTimerTicks(uint32_t tt1_ea, uint32_t tt2_ea,
                             uint32_t result_ea) {
    if (!gk_bound()) return;
    if (tt1_ea == 0 || tt1_ea + 8 > RECOMP_GUEST_MEM ||
        tt2_ea == 0 || tt2_ea + 8 > RECOMP_GUEST_MEM ||
        result_ea == 0 || result_ea + 8 > RECOMP_GUEST_MEM) return;
    PPCContext* cpu = g_gk.cpu;
    const uint32_t a_hi = rd32(cpu, tt1_ea + 0), a_lo = rd32(cpu, tt1_ea + 4);
    const uint32_t b_hi = rd32(cpu, tt2_ea + 0), b_lo = rd32(cpu, tt2_ea + 4);
    // subfco. sets the carry when the low subtraction did NOT borrow, and
    // subfe. subtracts the borrow (1 - carry) from the high word only.
    const uint32_t borrow = (b_lo < a_lo) ? 1u : 0u;
    const uint32_t r_lo = b_lo - a_lo;
    const uint32_t r_hi = b_hi - a_hi - borrow;
    if ((int32_t)r_hi >= 0) {
        wr32(cpu, result_ea + 0, r_hi);
        wr32(cpu, result_ea + 4, r_lo);
    } else {
        wr32(cpu, result_ea + 0, 0u);
        wr32(cpu, result_ea + 4, 0u);
    }
}

// kernel:149 ReadHardwareRandomNumber — M2 SDK src/folios/kernel/random.c:
//
//   dsppNoiseReg = (vuint32 *)0x61ffc;  /* DSPX_DATA_MEMORY_LOW[DSPI_NOISE] */
//   lrand = *dsppNoiseReg;  *dsppNoiseReg;  *dsppNoiseReg;  rrand = *dsppNoiseReg;
//   return (lrand << 16) | rrand;
//
// 0x61ffc is an M2 audio-DSP hardware register this platform boundary does
// not model, so the word comes from the host CSPRNG. The vendor's documented
// contract is only "an unsigned 32-bit random number, any value in
// [0, 2^32-1] ... useful for providing a seed to the software random-number
// generator" (random.c AUTODOC); that contract is what the host satisfies. No
// claim is made that the value matches any M2 noise sequence, and the value
// is never a constant.
static uint32_t gk_ReadHardwareRandomNumber(void) {
    (void)gk_bound();
    uint32_t word = 0;
    // The kernel CSPRNG device is the host entropy boundary. fopen/fread keep
    // this free of the feature-test macros that hide getentropy(3) under this
    // build's strict C standard; the call is once per boot in the recovered
    // image (main@0x364), so the open/read/close is not a hot path.
    FILE *f = fopen("/dev/urandom", "rb");
    if (f) {
        const size_t got = fread(&word, 1u, sizeof(word), f);
        fclose(f);
        if (got == sizeof(word)) return word;
    }
    // Reached only where the OS entropy device is unavailable. Clock and
    // stack-address mixing is weaker than the primary path; it is not a fixed
    // seed, so the guest's srand() still receives a varying word.
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t z = (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
    z ^= (uint64_t)(uintptr_t)&ts;
    z ^= (uint64_t)(uintptr_t)&word;
    z *= 0x9E3779B97F4A7C15ull;
    z ^= z >> 31;
    z *= 0xBF58476D1CE4E5B9ull;
    z ^= z >> 29;
    return (uint32_t)z;
}

// kernel:157 SetItemPri(Item r3, uint8 newpri r4) — vendor item.c
// internalSetItemPriority (item.c:943) -> internalSetPriorityKernelItem
// (item.c:1460) -> task.c internalChangeTaskPri (task.c:533). Returns the
// previous priority, or a negative Err.
static int32_t gk_SetItemPri(uint32_t item, uint8_t newpri) {
    if (!gk_bound() || item == M2K_ITEM_NONE) return M2K_ERR_BAD_ITEM;
    // The kernel folio installs internalSetPriorityKernelItem for every
    // kernel item (folio.c:784); that routine answers TASKNODE with
    // internalChangeTaskPri and every other kernel node type with
    // BADSUBTYPE (item.c:1466-1468). A non-kernel folio's item would report
    // NOSUPPORT here, which this host does not model as a separate class.
    if (m2k_handle_type(item) != M2K_TYPE_TASK) return M2K_ERR_BAD_SUBTYPE;
    // Privileged = 1: every task in this pool is kernel-created (recomp_entry
    // boot task, and gk_spawn_task for guest CreateThread/CreateTask), and all
    // carry the modeled default priority 200 (GK_TASK_PRIORITY_DEFAULT,
    // from vendor task.c:385). internalChangeTaskPri forbids any priority
    // above 199 for a task without ITEMNODE_PRIVILEGED, so a modeled task
    // sitting at 200 cannot be an unprivileged one under the source's own
    // invariant. The shooter's own call shape (main@0x73c raises the task's
    // published n_Priority by 0x14 and main@0x758 restores it) requires that
    // both words be accepted, which the band would otherwise refuse.
    return m2k_set_task_priority(g_gk.kctx, item, newpri, 1, NULL);
}

// kernel:136 FlushDCacheAll — whole-D-cache flush; host is coherent, so a no-op.
static void gk_FlushDCacheAll(void) {
    (void)gk_bound();
}

static void gk_PrintfSysErr(int32_t err);

static void gk_copy_error_name(uint32_t ea, char *out, size_t cap) {
    if (cap == 0) return;
    if (ea == 0) {
        snprintf(out, cap, "<null>");
        return;
    }
    if (ea >= RECOMP_GUEST_MEM) {
        snprintf(out, cap, "<OOB:%#x>", ea);
        return;
    }
    if (m2m_copy_guest_string_ctx(g_gk.cpu, ea, out, cap) < 0)
        snprintf(out, cap, "<fault:%#x>", ea);
}

// kernel:310 clib_PrintError — clib_PrintError(who, what, whom, Err).
// The source function is void; the host keeps the guest strings bounded and
// emits a diagnostic, then preserves the source's negative-error reporting
// relationship through the PrintfSysErr boundary.
static void gk_clib_PrintError(uint32_t who_ea, uint32_t what_ea,
                               uint32_t whom_ea, int32_t err) {
    if (!gk_bound()) return;
    char who[128], what[128], whom[128];
    gk_copy_error_name(who_ea, who, sizeof(who));
    gk_copy_error_name(what_ea, what, sizeof(what));
    gk_copy_error_name(whom_ea, whom, sizeof(whom));
    fprintf(stderr, "[gk] clib_PrintError who=%s what=%s whom=%s err=%d\n",
            who, what, whom, (int)err);
    if (err < 0) gk_PrintfSysErr(err);
}

// kernel:311 PrintfSysErr — print the system-error text for error code r3 to the
// console. No format string is passed by the guest; emit a faithful placeholder.
static void gk_PrintfSysErr(int32_t err) {
    if (!gk_bound()) return;
    fprintf(stderr, "[gk] PrintfSysErr pc=%#x err=%d\n",
            g_gk_selector_pc, (int)err);
}

// kernel:324 sprintf — format the guest format string at r4 into the guest RAM
// buffer at r3, return the char count. Mirrors the printf formatter but writes
// into guest memory instead of the console; %s reads guest strings. Floating
// conversions take the PPC EABI variadic FPR arguments f1..f8 in order (the
// caller sets CR1[EQ] when it passes any), keeping the guest's flags, width
// and precision; UI_DrawBestTimes formats its average speed this way
// (`%6.2f`, f1). Floating arguments past f8 would be on the stack and remain
// unmodelled; they format as "<missing>".
static int32_t gk_sprintf(uint32_t buf_ea, uint32_t fmt_ea, uint32_t a1,
                          uint32_t a2, uint32_t a3, uint32_t a4, uint32_t a5,
                          uint32_t a6, uint32_t a7) {
    if (!gk_bound()) return -1;
    PPCContext* call_cpu = gk_current_cpu();
    PPCContext* cpu = gk_current_memory_cpu();
    if (fmt_ea == 0 || fmt_ea + 4 > RECOMP_GUEST_MEM) return -1;
    if (buf_ea == 0 || buf_ea + 4 > RECOMP_GUEST_MEM) return -1;
    char fmt[256];
    int32_t rc = m2m_copy_guest_string_ctx(cpu, fmt_ea, fmt, sizeof(fmt));
    if (rc < 0) {
        fprintf(stderr, "[gk] sprintf fault: fmt_ea=%#x no NUL within %zu\n", fmt_ea, sizeof(fmt));
        return -1;
    }
    uint32_t args[16];
    args[0]=a1; args[1]=a2; args[2]=a3; args[3]=a4; args[4]=a5; args[5]=a6; args[6]=a7;
    int arg_count = 7;
    uint32_t sp = call_cpu ? call_cpu->gpr[1] : 0;
    for (int i=0; i<9 && arg_count < 16; ++i) {
        uint32_t ea = sp + 8 + (uint32_t)(i*4);
        if (ea + 4 > RECOMP_GUEST_MEM) break;
        args[arg_count++] = rd32(cpu, ea);
    }
    char out[1024];
    size_t out_pos = 0;
    int arg_idx = 0;
    int fpr_idx = 1;
    for (size_t i=0; fmt[i] && out_pos + 1 < sizeof(out); ++i) {
        if (fmt[i] != '%') { out[out_pos++] = fmt[i]; continue; }
        if (fmt[i+1] == '%') { out[out_pos++] = '%'; ++i; continue; }
        size_t conversion_start = i;
        size_t j = i+1;
        while (fmt[j] && strchr("-+ #0", fmt[j])) ++j;
        while (fmt[j] && fmt[j]>='0' && fmt[j]<='9') ++j;
        if (fmt[j]=='.') { ++j; while (fmt[j] && fmt[j]>='0' && fmt[j]<='9') ++j; }
        size_t length_start = j;
        while (fmt[j] && strchr("hlLzjt", fmt[j])) ++j;
        char spec = fmt[j];
        if (!spec) break;
        i = j;
        // Preserve the guest's flags, width, and precision. Its variadic
        // integer slots are 32-bit even where host long is 64-bit.
        char conversion[64] = {0};
        size_t conversion_length = length_start - conversion_start;
        if (conversion_length + 2 >= sizeof(conversion)) return -1;
        memcpy(conversion, fmt + conversion_start, conversion_length);
        conversion[conversion_length] = spec;
        conversion[conversion_length + 1] = 0;
        if (strchr("fFgGeEaA", spec)) {
            char tmp[256] = {0};
            if (call_cpu && fpr_idx <= 8)
                snprintf(tmp, sizeof(tmp), conversion, (double)call_cpu->fpr[fpr_idx++]);
            else
                snprintf(tmp, sizeof(tmp), "<missing>");
            for (size_t k=0; tmp[k] && out_pos+1 < sizeof(out); ++k) out[out_pos++] = tmp[k];
            continue;
        }
        if (arg_idx >= arg_count) {
            const char *ph = "<missing>";
            for (size_t k=0; ph[k] && out_pos+1 < sizeof(out); ++k) out[out_pos++] = ph[k];
            continue;
        }
        uint32_t v = args[arg_idx++];
        char tmp[256] = {0};
        switch (spec) {
            case 's': {
                if (v==0) snprintf(tmp,sizeof(tmp),"(null)");
                else if (v + 4 > RECOMP_GUEST_MEM) snprintf(tmp,sizeof(tmp),"<OOB:%#x>", v);
                else {
                    char sbuf[256];
                    int32_t sr = m2m_copy_guest_string_ctx(cpu, v, sbuf, sizeof(sbuf));
                    if (sr < 0) snprintf(tmp,sizeof(tmp),"<fault:%#x>", v);
                    else snprintf(tmp,sizeof(tmp),"%s", sbuf);
                }
                break;
            }
            case 'd': case 'i': snprintf(tmp,sizeof(tmp),conversion, (int32_t)v); break;
            case 'u': case 'x': case 'X': case 'o':
                snprintf(tmp,sizeof(tmp),conversion, v); break;
            case 'p': snprintf(tmp,sizeof(tmp),"%#x", v); break;
            case 'c': tmp[0]=(char)(v & 0xFF); tmp[1]=0; break;
            default: snprintf(tmp,sizeof(tmp),"%%%c", spec); break;
        }
        for (size_t k=0; tmp[k] && out_pos+1 < sizeof(out); ++k) out[out_pos++] = tmp[k];
    }
    out[out_pos]=0;
    // Bounded write into the guest buffer (NUL-terminated).
    for (size_t k=0; k <= out_pos && buf_ea + k < RECOMP_GUEST_MEM; ++k)
        wr8(cpu, buf_ea + k, out[k]);
    return (int32_t)out_pos;
}

